-- NEET UG previous-year questions (official NTA papers), 2016, 2018, 2019.
-- Question text is the exam's; answers are solved and cross-checked independently by UG Prep
-- (not the official key); one-liners and explanations are original. Idempotent by id.
INSERT INTO public.questions (id, exam, subject, topic, stem, options, correct_option_id, one_liner,
  explanation, distractors, high_yield, difficulty, is_pyq, pyq_year, repeat_count, source, image_url)
VALUES
('c8e9a1b2-27ee-5102-ad54-7525885736a2', 'neet_ug', 'Physics', 'Units and Measurements', 'Planck''s constant (h), speed of light in vacuum (c) and Newton''s gravitational constant (G) are three fundamental constants. Which of the following combinations of these has the dimension of length?', '[{"id": "a", "text": "√(hG)/c^(3/2)"}, {"id": "b", "text": "√(hG)/c^(5/2)"}, {"id": "c", "text": "√(hc/G)"}, {"id": "d", "text": "√(Gc)/h^(3/2)"}]'::jsonb, 'a', '√(hG/c³) is the Planck length, so √(hG)/c^(3/2) has the dimension of length.', 'Take [h] = ML²T⁻¹, [G] = M⁻¹L³T⁻² and [c] = LT⁻¹. Then hG = L⁵T⁻³, and dividing by c³ = L³T⁻³ gives L². So √(hG/c³) = √(hG)/c^(3/2) has the dimension L.', '{"b": "√(hG)/c^(5/2) has the dimension of time (the Planck time).", "c": "√(hc/G) has the dimension of mass (the Planck mass).", "d": "The masses do not cancel, so this is not a pure length."}'::jsonb, 'Dimensions: [G] = M⁻¹L³T⁻², [h] = ML²T⁻¹.', 'med', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('f8c3aeb5-8c0a-5729-b49c-e7977f977eec', 'neet_ug', 'Physics', 'Motion in a Straight Line', 'Two cars P and Q start from a point at the same time in a straight line and their positions are represented by xP(t) = at + bt² and xQ(t) = ft − t². At what time do the cars have the same velocity?', '[{"id": "a", "text": "(a − f)/(1 + b)"}, {"id": "b", "text": "(a + f)/(2(b − 1))"}, {"id": "c", "text": "(a + f)/(2(1 + b))"}, {"id": "d", "text": "(f − a)/(2(1 + b))"}]'::jsonb, 'd', 'Set the derivatives equal: a + 2bt = f − 2t, so t = (f − a)/(2(1 + b)).', 'Velocity is dx/dt: vP = a + 2bt and vQ = f − 2t. Setting them equal gives 2t(b + 1) = f − a, so t = (f − a)/[2(1 + b)].', '{"a": "This drops the factor 2 and has the wrong sign.", "b": "This uses wrong signs for both a and the t² term.", "c": "This has the sign of a wrong."}'::jsonb, 'Instantaneous velocity v = dx/dt.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('be6c0e09-5cda-55b1-b3a9-f2f98c3841a2', 'neet_ug', 'Physics', 'Motion in a Plane', 'In the given figure, a = 15 m/s² represents the total acceleration of a particle moving in the clockwise direction in a circle of radius R = 2.5 m at a given instant of time. The speed of the particle is', '[{"id": "a", "text": "4.5 m/s"}, {"id": "b", "text": "5.0 m/s"}, {"id": "c", "text": "5.7 m/s"}, {"id": "d", "text": "6.2 m/s"}]'::jsonb, 'c', 'The centripetal part of a is a cos30° = v²/R, which gives v ≈ 5.7 m/s.', 'The total acceleration makes 30° with the radius, so the radial component is a_c = 15 × cos30° = 15 × 0.866 ≈ 13 m/s². Then v² = a_c R = 13 × 2.5 ≈ 32.5, so v ≈ 5.7 m/s.', '{"a": "Too small: this does not match a_c R.", "b": "This uses a_c = 10 m/s², which is the wrong component.", "d": "This uses the full 15 m/s² as centripetal (v ≈ 6.1)."}'::jsonb, 'Only the radial component of acceleration equals v²/R.', 'med', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', '/pyq/ug/2016/3.webp'),
('61274872-0424-551e-91ac-271df05bcab3', 'neet_ug', 'Physics', 'Laws of Motion', 'A rigid ball of mass m strikes a rigid wall at 60° and gets reflected without loss of speed as shown in the figure below. The value of impulse imparted by the wall on the ball will be', '[{"id": "a", "text": "mV"}, {"id": "b", "text": "2mV"}, {"id": "c", "text": "mV/2"}, {"id": "d", "text": "mV/3"}]'::jsonb, 'a', 'Only the component normal to the wall reverses, so the impulse is 2mV cos60° = mV.', 'The angle with the normal (the dashed horizontal) is 60°. The normal component V cos60° reverses while the parallel component stays the same. So the impulse is 2mV cos60° = mV, directed away from the wall.', '{"b": "This would be true only for head-on (normal) incidence.", "c": "This takes a single component without doubling it.", "d": "No resolution of the velocity gives this value."}'::jsonb, 'Impulse = change in momentum, and only the normal component changes.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', '/pyq/ug/2016/4.webp'),
('6eb306d8-4182-5d90-b8c8-d75d00125025', 'neet_ug', 'Physics', 'Work, Energy and Power', 'A bullet of mass 10 g moving horizontally with a velocity of 400 m s⁻¹ strikes a wooden block of mass 2 kg which is suspended by a light inextensible string of length 5 m. As a result, the centre of gravity of the block is found to rise a vertical distance of 10 cm. The speed of the bullet after it emerges out horizontally from the block will be', '[{"id": "a", "text": "100 m s⁻¹"}, {"id": "b", "text": "80 m s⁻¹"}, {"id": "c", "text": "120 m s⁻¹"}, {"id": "d", "text": "160 m s⁻¹"}]'::jsonb, 'c', 'The block''s speed is √(2gh) = √2 m/s, and momentum conservation then gives the bullet about 120 m/s.', 'The block''s speed just after impact is V = √(2gh) = √(2 × 10 × 0.1) = √2 ≈ 1.41 m/s. Momentum conservation gives 0.01 × 400 = 2 × 1.41 + 0.01v, so v = (4 − 2.83)/0.01 ≈ 117 ≈ 120 m/s.', '{"a": "This underestimates: it takes the block''s momentum as about 3 kg m/s.", "b": "This is not consistent with conservation of momentum.", "d": "This takes the block''s speed as about 1.2 m/s."}'::jsonb, 'In collisions momentum is conserved; after the collision use energy conservation for the swing.', 'med', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('968d6e19-c177-5c9c-8ca1-fd721d18e922', 'neet_ug', 'Physics', 'Work, Energy and Power', 'Two identical balls A and B having velocities of 0.5 m/s and −0.3 m/s, respectively collide elastically in one dimension. The velocities of B and A after the collision respectively will be', '[{"id": "a", "text": "−0.5 m/s and 0.3 m/s"}, {"id": "b", "text": "0.5 m/s and −0.3 m/s"}, {"id": "c", "text": "−0.3 m/s and 0.5 m/s"}, {"id": "d", "text": "0.3 m/s and 0.5 m/s"}]'::jsonb, 'b', 'Equal masses in a 1-D elastic collision exchange velocities, so B moves at 0.5 m/s and A at −0.3 m/s.', 'For equal masses in an elastic head-on collision, v₁'' = u₂ and v₂'' = u₁. So A takes −0.3 m/s and B takes 0.5 m/s. In the order asked (B, A), this is 0.5 m/s and −0.3 m/s.', '{"a": "The signs are reversed.", "c": "This gives the order A, B rather than B, A.", "d": "The sign of A''s velocity is wrong and the order is mixed up."}'::jsonb, 'Equal masses in a 1-D elastic collision exchange velocities.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('099e7aed-155c-5171-8d6e-bcc9a465c1e3', 'neet_ug', 'Physics', 'Work, Energy and Power', 'A particle moves from a point (−2î + 5ĵ) to (4ĵ + 3k̂) when a force of (4î + 3ĵ) N is applied. How much work has been done by the force?', '[{"id": "a", "text": "8 J"}, {"id": "b", "text": "11 J"}, {"id": "c", "text": "5 J"}, {"id": "d", "text": "2 J"}]'::jsonb, 'c', 'W = F·d, with d = 2î − ĵ + 3k̂, gives 8 − 3 = 5 J.', 'The displacement is d = (4ĵ + 3k̂) − (−2î + 5ĵ) = 2î − ĵ + 3k̂. Then W = F·d = 4(2) + 3(−1) + 0(3) = 5 J.', '{"a": "This counts only the x-term.", "b": "This adds the y-term instead of subtracting it.", "d": "This comes from the wrong displacement vector."}'::jsonb, 'Work = F·d, the dot product of force and displacement.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('a59b2686-4627-5fae-ae0c-7427e07713c5', 'neet_ug', 'Physics', 'System of Particles and Rotational Motion', 'Two rotating bodies A and B of masses m and 2m with moments of inertia I_A and I_B (I_B > I_A) have equal kinetic energy of rotation. If L_A and L_B be their angular momenta respectively, then', '[{"id": "a", "text": "L_A = L_B/2"}, {"id": "b", "text": "L_A = 2L_B"}, {"id": "c", "text": "L_B > L_A"}, {"id": "d", "text": "L_A > L_B"}]'::jsonb, 'c', 'L = √(2IK), so at equal K the body with the larger I has the larger L.', 'Rotational KE is K = L²/2I, so L = √(2IK). With K equal and I_B > I_A, it follows that L_B > L_A. The masses do not matter here.', '{"a": "An exact ratio would need I_B = 4I_A, which is not given.", "b": "This is the wrong direction of inequality.", "d": "This contradicts L ∝ √I."}'::jsonb, 'K_rot = L²/(2I).', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('91a320ce-cb62-5abf-a6e5-c41148e5fc10', 'neet_ug', 'Physics', 'System of Particles and Rotational Motion', 'A solid sphere of mass m and radius R is rotating about its diameter. A solid cylinder of the same mass and same radius is also rotating about its geometrical axis with an angular speed twice that of the sphere. The ratio of their kinetic energies of rotation (E_sphere / E_cylinder) will be', '[{"id": "a", "text": "2 : 3"}, {"id": "b", "text": "1 : 5"}, {"id": "c", "text": "1 : 4"}, {"id": "d", "text": "3 : 1"}]'::jsonb, 'b', '(½·⅖mR²ω²) : (½·½mR²·4ω²) = 0.2 : 1 = 1 : 5.', 'E_sphere = ½(2/5 mR²)ω² = (1/5)mR²ω². E_cyl = ½(½mR²)(2ω)² = mR²ω². The ratio is 1 : 5.', '{"a": "This ignores the doubled angular speed of the cylinder.", "c": "This is wrong for the given values.", "d": "The ratio is inverted and wrong."}'::jsonb, 'I(solid sphere) = ⅖MR², I(solid cylinder about its axis) = ½MR².', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('64ec6a02-7410-59b2-8c4c-476b2955bf8c', 'neet_ug', 'Physics', 'System of Particles and Rotational Motion', 'A light rod of length l has two masses m₁ and m₂ attached to its two ends. The moment of inertia of the system about an axis perpendicular to the rod and passing through the centre of mass is', '[{"id": "a", "text": "(m₁m₂/(m₁ + m₂)) l²"}, {"id": "b", "text": "((m₁ + m₂)/(m₁m₂)) l²"}, {"id": "c", "text": "(m₁ + m₂) l²"}, {"id": "d", "text": "√(m₁m₂) l²"}]'::jsonb, 'a', 'I about the CM = μl², where μ = m₁m₂/(m₁ + m₂).', 'The distances from the CM are r₁ = m₂l/(m₁ + m₂) and r₂ = m₁l/(m₁ + m₂). Then I = m₁r₁² + m₂r₂² = m₁m₂l²(m₂ + m₁)/(m₁ + m₂)² = m₁m₂l²/(m₁ + m₂).', '{"b": "This is the reciprocal of the reduced mass and has the wrong dimension.", "c": "This is the moment of inertia about one end as if both masses were at distance l.", "d": "This is not derived from the CM distances."}'::jsonb, 'Reduced mass μ = m₁m₂/(m₁ + m₂).', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('0d482d1e-f77a-5797-8168-4440d2e68d0f', 'neet_ug', 'Physics', 'Gravitation', 'Starting from the centre of the Earth having radius R, the variation of g (acceleration due to gravity) is shown by', '[{"id": "a", "text": "Option (1) in figure"}, {"id": "b", "text": "Option (2) in figure"}, {"id": "c", "text": "Option (3) in figure"}, {"id": "d", "text": "Option (4) in figure"}]'::jsonb, 'b', 'g rises linearly from 0 at the centre to g₀ at r = R and then falls as 1/r² outside.', 'Inside a uniform Earth, g = g₀r/R, a straight line through the origin. Outside, g = g₀R²/r², a decreasing curve. Graph (2) shows this linear rise followed by the inverse-square fall.', '{"a": "This shows a linear fall outside, but the true fall is 1/r².", "c": "This shows a curved (non-linear) rise inside.", "d": "This shows g constant inside, which is wrong."}'::jsonb, 'g at depth d is g₀(1 − d/R), and g at height h is g₀R²/(R + h)².', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', '/pyq/ug/2016/11.webp'),
('7fc1e4ed-9db4-5b42-8374-8b27c65a1d3b', 'neet_ug', 'Physics', 'Gravitation', 'A satellite of mass m is orbiting the Earth (of radius R) at a height h from its surface. The total energy of the satellite in terms of g₀, the value of acceleration due to gravity at the Earth''s surface, is', '[{"id": "a", "text": "mg₀R²/(2(R + h))"}, {"id": "b", "text": "−mg₀R²/(2(R + h))"}, {"id": "c", "text": "2mg₀R²/(R + h)"}, {"id": "d", "text": "−2mg₀R²/(R + h)"}]'::jsonb, 'b', 'E = −GMm/2r = −mg₀R²/(2(R + h)).', 'For a circular orbit of radius r = R + h, the total energy is E = −GMm/(2r). Using GM = g₀R² gives E = −mg₀R²/[2(R + h)]. It is negative because the satellite is bound.', '{"a": "This is the kinetic energy; the total energy is negative.", "c": "The factor is wrong and the sign is positive.", "d": "The factor is wrong; this is not PE or KE."}'::jsonb, 'For a satellite, E = −K = U/2.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('3d45be82-1ea1-5bfe-ba4f-d03c94dcf9e8', 'neet_ug', 'Physics', 'Mechanical Properties of Fluids', 'A rectangular film of liquid is extended from (4 cm × 2 cm) to (5 cm × 4 cm). If the work done is 3 × 10⁻⁴ J, the value of the surface tension of the liquid is', '[{"id": "a", "text": "0.250 N m⁻¹"}, {"id": "b", "text": "0.125 N m⁻¹"}, {"id": "c", "text": "0.2 N m⁻¹"}, {"id": "d", "text": "8.0 N m⁻¹"}]'::jsonb, 'b', 'W = T × 2ΔA, with ΔA = 12 cm², gives T = 3×10⁻⁴/(24×10⁻⁴) = 0.125 N/m.', 'ΔA = 20 − 8 = 12 cm² per face. A film has two surfaces, so the total increase is 24 × 10⁻⁴ m². Then T = W/ΔA_total = 3 × 10⁻⁴ / 24 × 10⁻⁴ = 0.125 N m⁻¹.', '{"a": "This forgets that the film has two surfaces.", "c": "This is an arithmetic slip.", "d": "This inverts the ratio."}'::jsonb, 'A liquid film has two free surfaces: W = 2TΔA.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('92580757-197a-544f-a71c-4a30b34ef00e', 'neet_ug', 'Physics', 'Mechanical Properties of Fluids', 'Three liquids of densities ρ₁, ρ₂ and ρ₃ (with ρ₁ > ρ₂ > ρ₃), having the same value of surface tension T, rise to the same height in three identical capillaries. The angles of contact θ₁, θ₂ and θ₃ obey', '[{"id": "a", "text": "π/2 > θ₁ > θ₂ > θ₃ ≥ 0"}, {"id": "b", "text": "0 ≤ θ₁ < θ₂ < θ₃ < π/2"}, {"id": "c", "text": "π/2 < θ₁ < θ₂ < θ₃ < π"}, {"id": "d", "text": "π > θ₁ > θ₂ > θ₃ > π/2"}]'::jsonb, 'b', 'h = 2T cosθ/(ρrg) is the same for all three, so cosθ ∝ ρ, and the densest liquid has the smallest θ.', 'With h, T and r fixed, cosθ ∝ ρ. Because ρ₁ > ρ₂ > ρ₃, cosθ₁ > cosθ₂ > cosθ₃, so θ₁ < θ₂ < θ₃. All the liquids rise, so every θ is acute.', '{"a": "This reverses the order of the angles.", "c": "Obtuse angles would give a capillary fall, not a rise.", "d": "Obtuse angles would give a capillary fall."}'::jsonb, 'Capillary rise: h = 2T cosθ/(ρrg).', 'med', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('c0e1ee03-87e3-55ef-ade0-75184d91a595', 'neet_ug', 'Physics', 'Thermal Properties of Matter', 'Two identical bodies are made of a material for which the heat capacity increases with temperature. One of these is at 100 °C, while the other one is at 0 °C. If the two bodies are brought into contact, then, assuming no heat loss, the final common temperature is', '[{"id": "a", "text": "50 °C"}, {"id": "b", "text": "More than 50 °C"}, {"id": "c", "text": "Less than 50 °C but greater than 0 °C"}, {"id": "d", "text": "0 °C"}]'::jsonb, 'b', 'The hot body gives out more heat per degree than the cold body absorbs, so the final temperature lies above 50 °C.', 'Heat lost equals heat gained: ∫C dT from T_f to 100 = ∫C dT from 0 to T_f. Because C is larger at higher temperatures, the hot body releases more heat per degree of cooling. So the cold body must warm by more degrees than the hot body cools, which puts T_f above 50 °C.', '{"a": "This holds only for a constant heat capacity.", "c": "This would require C to decrease with temperature.", "d": "This is impossible because heat flows from hot to cold."}'::jsonb, 'Heat exchanged Q = ∫C dT.', 'med', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('d84a22ea-fbb0-57ed-8541-d0e6a7cc8c98', 'neet_ug', 'Physics', 'Thermal Properties of Matter', 'A body cools from a temperature 3T to 2T in 10 minutes. The room temperature is T. Assume that Newton''s law of cooling is applicable. The temperature of the body at the end of next 10 minutes will be', '[{"id": "a", "text": "7T/4"}, {"id": "b", "text": "3T/2"}, {"id": "c", "text": "4T/3"}, {"id": "d", "text": "T"}]'::jsonb, 'b', 'The excess over the surroundings falls from 2T to T in 10 min, so it halves again to T/2, giving a temperature of 3T/2.', 'Under Newton''s law the excess temperature decays exponentially. In the first 10 min it goes 2T → T (halved), so in the next 10 min it goes T → T/2, and the body is at T + T/2 = 3T/2. The average-temperature method gives the same: k = 1/15 per min, and (2T − θ)/10 = (1/15)(θ/2) gives θ = 3T/2.', '{"a": "This assumes the cooling becomes slower than the law predicts.", "c": "This assumes the cooling is too fast.", "d": "The body reaches room temperature only asymptotically."}'::jsonb, 'Newton''s law of cooling: dθ/dt = −k(θ − θ₀).', 'med', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('019c9ee5-d685-5382-b391-473d61752f0f', 'neet_ug', 'Physics', 'Thermodynamics', 'One mole of an ideal monatomic gas undergoes a process described by the equation PV³ = constant. The heat capacity of the gas during this process is', '[{"id": "a", "text": "3R/2"}, {"id": "b", "text": "5R/2"}, {"id": "c", "text": "2R"}, {"id": "d", "text": "R"}]'::jsonb, 'd', 'For a polytropic process C = C_V + R/(1 − x); with x = 3 this is 3R/2 − R/2 = R.', 'For PVˣ = constant, the molar heat capacity is C = C_V + R/(1 − x). For a monatomic gas C_V = 3R/2, and with x = 3, C = 3R/2 − R/2 = R.', '{"a": "This is C_V (the isochoric value).", "b": "This is C_P (the isobaric value).", "c": "This uses the wrong sign in the formula."}'::jsonb, 'Polytropic heat capacity: C = C_V + R/(1 − n).', 'med', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('7c95501d-33e9-527c-8d45-f553f3f45ec6', 'neet_ug', 'Physics', 'Thermodynamics', 'The temperature inside a refrigerator is t₂ °C and the room temperature is t₁ °C. The amount of heat delivered to the room for each joule of electrical energy consumed ideally will be', '[{"id": "a", "text": "t₁/(t₁ − t₂)"}, {"id": "b", "text": "(t₁ + 273)/(t₁ − t₂)"}, {"id": "c", "text": "(t₂ + 273)/(t₁ − t₂)"}, {"id": "d", "text": "(t₁ + t₂)/(t₁ + 273)"}]'::jsonb, 'b', 'For an ideal refrigerator Q₁/W = T₁/(T₁ − T₂) = (t₁ + 273)/(t₁ − t₂).', 'Heat delivered to the hot side is Q₁ = Q₂ + W. For a Carnot device Q₁/W = T₁/(T₁ − T₂). In kelvin, T₁ = t₁ + 273 and T₁ − T₂ = t₁ − t₂.', '{"a": "This uses Celsius temperature in the numerator.", "c": "This is the coefficient of performance (heat removed from inside), not the heat delivered.", "d": "This expression has no thermodynamic basis."}'::jsonb, 'Refrigerator COP β = T₂/(T₁ − T₂).', 'med', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('a0124273-70e2-5cfb-b01d-2543b305e903', 'neet_ug', 'Physics', 'Kinetic Theory', 'A given sample of an ideal gas occupies a volume V at a pressure P and absolute temperature T. The mass of each molecule of the gas is m. Which of the following gives the density of the gas?', '[{"id": "a", "text": "P/(kT)"}, {"id": "b", "text": "Pm/(kT)"}, {"id": "c", "text": "P/(kTV)"}, {"id": "d", "text": "mkT"}]'::jsonb, 'b', 'Number density n = P/kT, so ρ = nm = Pm/kT.', 'From P = nkT, the number of molecules per unit volume is P/(kT). Multiplying by the mass per molecule gives ρ = Pm/(kT).', '{"a": "This is the number density, not the mass density.", "c": "This has the wrong dimension.", "d": "This has no physical basis."}'::jsonb, 'P = nkT, where n is the number density.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('0b6c4908-afb9-5dc7-8ad7-4e002e466fcc', 'neet_ug', 'Physics', 'Oscillations', 'A body of mass m is attached to the lower end of a spring whose upper end is fixed. The spring has negligible mass. When the mass m is slightly pulled down and released, it oscillates with a time period of 3 s. When the mass m is increased by 1 kg, the time period of oscillations becomes 5 s. The value of m in kg is:', '[{"id": "a", "text": "3/4"}, {"id": "b", "text": "4/3"}, {"id": "c", "text": "16/9"}, {"id": "d", "text": "9/16"}]'::jsonb, 'd', 'T² ∝ m, so 9/25 = m/(m + 1), which gives m = 9/16 kg.', 'T = 2π√(m/k), so (3/5)² = m/(m + 1). Then 25m = 9m + 9, so m = 9/16 kg.', '{"a": "This takes T ∝ m instead of √m.", "b": "This is wrong from the ratio.", "c": "This inverts the correct ratio."}'::jsonb, 'Spring-mass system: T = 2π√(m/k).', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('3b3fb3fc-7b76-51f2-ad96-f1b381c86300', 'neet_ug', 'Physics', 'Waves', 'The second overtone of an open organ pipe has the same frequency as the first overtone of a closed pipe L meter long. The length of the open pipe will be', '[{"id": "a", "text": "L"}, {"id": "b", "text": "2L"}, {"id": "c", "text": "L/2"}, {"id": "d", "text": "4L"}]'::jsonb, 'b', '3v/(2L₀) = 3v/(4L), so L₀ = 2L.', 'For an open pipe the second overtone is the third harmonic, 3v/(2L₀). For a closed pipe the first overtone is the third harmonic, 3v/(4L). Equating them gives L₀ = 2L.', '{"a": "This would need equal fundamental relations.", "c": "The ratio is inverted.", "d": "This is wrong by a factor of 2."}'::jsonb, 'A closed pipe has only odd harmonics.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('89da01bb-4138-5061-a725-68ee6593016f', 'neet_ug', 'Physics', 'Waves', 'Three sound waves of equal amplitudes have frequencies (n − 1), n, (n + 1). They superimpose to give beats. The number of beats produced per second will be', '[{"id": "a", "text": "1"}, {"id": "b", "text": "4"}, {"id": "c", "text": "3"}, {"id": "d", "text": "2"}]'::jsonb, 'd', 'The beat envelope A(1 + 2cos2πt) has a period of 1 s, but the intensity peaks twice each second, giving 2 beats per second.', 'The sum is A sin2πnt [1 + 2cos2πt]. The amplitude |1 + 2cos2πt| reaches a maximum at cos2πt = 1 (3A) and again at cos2πt = −1 (A), with zeros in between. So two loudness maxima occur every second: 2 beats/s, the largest frequency difference.', '{"a": "This counts only the main maxima of the envelope.", "b": "This double-counts.", "c": "This adds the frequency differences incorrectly."}'::jsonb, 'Beat frequency = |ν₁ − ν₂|.', 'hard', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('7b36ca69-e867-5e4b-8b8b-0ab08e9817af', 'neet_ug', 'Physics', 'Electric Charges and Fields', 'An electric dipole is placed at an angle of 30° with an electric field intensity 2 × 10⁵ N/C. It experiences a torque equal to 4 N m. The charge on the dipole, if the dipole length is 2 cm, is', '[{"id": "a", "text": "8 mC"}, {"id": "b", "text": "2 mC"}, {"id": "c", "text": "5 mC"}, {"id": "d", "text": "7 μC"}]'::jsonb, 'b', 'τ = q(2a)E sinθ, so q = 4/(0.02 × 2×10⁵ × 0.5) = 2 × 10⁻³ C.', 'p = τ/(E sinθ) = 4/(2 × 10⁵ × 0.5) = 4 × 10⁻⁵ C m. Then q = p/l = 4 × 10⁻⁵/0.02 = 2 × 10⁻³ C = 2 mC.', '{"a": "This drops the sin30° factor in the wrong way.", "c": "This is an arithmetic error.", "d": "This is wrong by orders of magnitude."}'::jsonb, 'Torque on a dipole: τ = pE sinθ.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('3798b0f3-5143-55d8-8465-bb6a29fa19ea', 'neet_ug', 'Physics', 'Electrostatic Potential and Capacitance', 'A parallel-plate capacitor of area A, plate separation d and capacitance C is filled with four dielectric materials having dielectric constant k₁, k₂, k₃ and k₄ as shown in the figure below. If a single dielectric material is to be used to have the same capacitance C in this capacitor, then its dielectric constant k is given by', '[{"id": "a", "text": "k = k₁ + k₂ + k₃ + 3k₄"}, {"id": "b", "text": "k = (2/3)(k₁ + k₂ + k₃) + 2k₄"}, {"id": "c", "text": "2/k = 3/(k₁ + k₂ + k₃) + 1/k₄"}, {"id": "d", "text": "1/k = 1/k₁ + 1/k₂ + 1/k₃ + 3/(2k₄)"}]'::jsonb, 'c', 'The three upper strips (each A/3, thickness d/2) are in parallel, and together they are in series with the lower slab k₄ (area A, thickness d/2).', 'Take the upper strips as k₁, k₂, k₃ and the lower slab as k₄. Then C_top = ε₀(A/3)(k₁ + k₂ + k₃)/(d/2) and C_bottom = 2ε₀Ak₄/d. In series, d/(kε₀A) = 3d/[2ε₀A(k₁ + k₂ + k₃)] + d/(2ε₀Ak₄). Multiplying by 2ε₀A/d gives 2/k = 3/(k₁ + k₂ + k₃) + 1/k₄.', '{"a": "This treats everything as in parallel.", "b": "This adds the series parts as if they were in parallel.", "d": "This treats everything as in series."}'::jsonb, 'Side-by-side dielectrics act in parallel; stacked layers act in series.', 'hard', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', '/pyq/ug/2016/24.webp'),
('60491200-9972-5725-bd38-2f492435279e', 'neet_ug', 'Physics', 'Current Electricity', 'The potential difference (V_A − V_B) between the points A and B in the given figure is', '[{"id": "a", "text": "−3 V"}, {"id": "b", "text": "+3 V"}, {"id": "c", "text": "+6 V"}, {"id": "d", "text": "+9 V"}]'::jsonb, 'd', 'Going from A to B along the current: drop 4 V (2 Ω), drop 3 V (+ to − of the cell), drop 2 V (1 Ω), so V_A − V_B = 9 V.', 'V_A − 2×2 − 3 − 2×1 = V_B, so V_A − V_B = 4 + 3 + 2 = 9 V. Crossing the cell from its + terminal to its − terminal lowers the potential by 3 V.', '{"a": "The sign is wrong and the resistors are ignored.", "b": "This counts only the cell.", "c": "This counts only the resistor drops."}'::jsonb, 'Kirchhoff''s loop rule: sum the potential changes along a path.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', '/pyq/ug/2016/25.webp'),
('d3d15029-9324-5248-8ea9-61ffe4a30434', 'neet_ug', 'Physics', 'Current Electricity', 'A filament bulb (500 W, 100 V) is to be used in a 230 V main supply. When a resistance R is connected in series, it works perfectly and the bulb consumes 500 W. The value of R is', '[{"id": "a", "text": "230 Ω"}, {"id": "b", "text": "46 Ω"}, {"id": "c", "text": "26 Ω"}, {"id": "d", "text": "13 Ω"}]'::jsonb, 'c', 'The bulb needs I = 5 A and has resistance 20 Ω, so the total resistance is 230/5 = 46 Ω and R = 26 Ω.', 'The rated current is I = P/V = 500/100 = 5 A, and R_bulb = V²/P = 20 Ω. At 230 V the total resistance must be 230/5 = 46 Ω, so the series resistor is R = 46 − 20 = 26 Ω.', '{"a": "This uses the supply voltage directly.", "b": "This is the total resistance, not the added resistor.", "d": "This is half of the correct value."}'::jsonb, 'Bulb resistance R = V²/P.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('efac6ede-0247-517f-bb41-ce9459b504ca', 'neet_ug', 'Physics', 'Moving Charges and Magnetism', 'A long wire carrying a steady current is bent into a circular loop of one turn. The magnetic field at the centre of the loop is B. It is then bent into a circular coil of n turns. The magnetic field at the centre of this coil of n turns will be', '[{"id": "a", "text": "nB"}, {"id": "b", "text": "n²B"}, {"id": "c", "text": "2nB"}, {"id": "d", "text": "2n²B"}]'::jsonb, 'b', 'The radius becomes R/n and there are n turns, so B'' = μ₀nI/(2R/n) = n²B.', 'With the same wire length, 2πR = n·2πr, so r = R/n. Then B'' = nμ₀I/(2r) = n²μ₀I/(2R) = n²B.', '{"a": "This ignores the reduced radius.", "c": "This has a spurious factor of 2.", "d": "This has a spurious factor of 2."}'::jsonb, 'Field at the centre of a coil: B = μ₀NI/(2R).', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('6da56660-8850-5447-8d40-01deb34eb42e', 'neet_ug', 'Physics', 'Magnetism and Matter', 'A bar magnet is hung by a thin cotton thread in a uniform horizontal magnetic field and is in equilibrium state. The energy required to rotate it by 60° is W. Now the torque required to keep the magnet in this new position is', '[{"id": "a", "text": "W/√3"}, {"id": "b", "text": "√3W"}, {"id": "c", "text": "(√3/2)W"}, {"id": "d", "text": "2W/√3"}]'::jsonb, 'b', 'W = MB(1 − cos60°) = MB/2, so τ = MB sin60° = √3W.', 'The work done in rotating from 0° to 60° is W = MB(1 − cos60°) = MB/2, so MB = 2W. The torque at 60° is τ = MB sin60° = 2W × √3/2 = √3W.', '{"a": "This inverts the trigonometric ratio.", "c": "This takes MB = W.", "d": "This uses the wrong relation for the energy."}'::jsonb, 'Work to rotate a dipole: W = MB(cosθ₁ − cosθ₂).', 'med', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('f7148e4a-f01e-5b54-bcc3-d7f068390043', 'neet_ug', 'Physics', 'Moving Charges and Magnetism', 'An electron is moving in a circular path under the influence of a transverse magnetic field of 3.57 × 10⁻² T. If the value of e/m is 1.76 × 10¹¹ C/kg, the frequency of revolution of the electron is', '[{"id": "a", "text": "1 GHz"}, {"id": "b", "text": "100 MHz"}, {"id": "c", "text": "62.8 MHz"}, {"id": "d", "text": "6.28 MHz"}]'::jsonb, 'a', 'f = (e/m)B/(2π) = 1.76×10¹¹ × 3.57×10⁻²/6.28 ≈ 10⁹ Hz.', 'The cyclotron frequency is f = qB/(2πm). Here (e/m)B = 1.76 × 10¹¹ × 3.57 × 10⁻² ≈ 6.28 × 10⁹ s⁻¹. Dividing by 2π gives f ≈ 1 × 10⁹ Hz = 1 GHz.', '{"b": "This is off by a factor of 10.", "c": "This is off by orders of magnitude.", "d": "This is ω/10³, a units slip."}'::jsonb, 'Frequency of circular motion in a magnetic field: f = qB/(2πm), independent of speed.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('b8c484d9-3aed-5503-8a3a-f1554d36609a', 'neet_ug', 'Physics', 'Alternating Current', 'Which of the following combinations should be selected for better tuning of an L-C-R circuit used for communication?', '[{"id": "a", "text": "R = 20 Ω, L = 1.5 H, C = 35 μF"}, {"id": "b", "text": "R = 25 Ω, L = 2.5 H, C = 45 μF"}, {"id": "c", "text": "R = 15 Ω, L = 3.5 H, C = 30 μF"}, {"id": "d", "text": "R = 25 Ω, L = 1.5 H, C = 45 μF"}]'::jsonb, 'c', 'Sharper tuning needs the highest Q = (1/R)√(L/C), which is option (3).', 'Q = (1/R)√(L/C): option (1) gives √(1.5/35×10⁻⁶)/20 ≈ 10.4, option (2) ≈ 9.4, option (3) √(3.5/30×10⁻⁶)/15 ≈ 22.8, and option (4) ≈ 7.3. The highest Q gives the sharpest resonance.', '{"a": "Q ≈ 10, which is lower.", "b": "Q ≈ 9.4, which is lower.", "d": "Q ≈ 7.3, the lowest."}'::jsonb, 'Quality factor Q = (1/R)√(L/C); a higher Q means a sharper resonance.', 'med', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('0cd03ee2-f761-5af2-aaf6-24c34e69a6c7', 'neet_ug', 'Physics', 'Electromagnetic Induction', 'A uniform magnetic field is restricted within a region of radius r. The magnetic field changes with time at a rate dB/dt. Loop 1 of radius R > r encloses the region r and loop 2 of radius R is outside the region of magnetic field as shown in the figure below. Then the e.m.f. generated is', '[{"id": "a", "text": "Zero in loop 1 and zero in loop 2"}, {"id": "b", "text": "−(dB/dt)(πr²) in loop 1 and −(dB/dt)(πr²) in loop 2"}, {"id": "c", "text": "−(dB/dt)(πR²) in loop 1 and zero in loop 2"}, {"id": "d", "text": "−(dB/dt)(πr²) in loop 1 and zero in loop 2"}]'::jsonb, 'd', 'Flux exists only over the area πr², which loop 1 encloses; loop 2 encloses no flux.', 'ε = −dΦ/dt. For loop 1 the flux is Bπr², because the field exists only within radius r, so ε₁ = −πr² dB/dt. Loop 2 links no flux, so ε₂ = 0.', '{"a": "Loop 1 does link a changing flux.", "b": "Loop 2 encloses no field.", "c": "The field does not fill the whole area πR²."}'::jsonb, 'Faraday''s law: ε = −dΦ/dt, where Φ counts only the area that carries the field.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', '/pyq/ug/2016/31.webp'),
('34f027d4-5aae-51be-950a-57df5b3cd0b1', 'neet_ug', 'Physics', 'Alternating Current', 'The potential differences across the resistance, capacitance and inductance are 80 V, 40 V and 100 V respectively in an L-C-R circuit. The power factor of this circuit is', '[{"id": "a", "text": "0.4"}, {"id": "b", "text": "0.5"}, {"id": "c", "text": "0.8"}, {"id": "d", "text": "1.0"}]'::jsonb, 'c', 'V = √(80² + 60²) = 100 V, so cosφ = V_R/V = 0.8.', 'The net reactive voltage is V_L − V_C = 60 V. The supply voltage is V = √(80² + 60²) = 100 V, so the power factor is cosφ = 80/100 = 0.8.', '{"a": "This is V_C/V.", "b": "This has no basis.", "d": "This would hold only at resonance (V_L = V_C)."}'::jsonb, 'Power factor cosφ = R/Z = V_R/V.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('a45cbb33-990b-5f82-aad7-c6b4eee438bd', 'neet_ug', 'Physics', 'Electromagnetic Waves', 'A 100 Ω resistance and a capacitor of 100 Ω reactance are connected in series across a 220 V source. When the capacitor is 50% charged, the peak value of the displacement current is', '[{"id": "a", "text": "2.2 A"}, {"id": "b", "text": "11 A"}, {"id": "c", "text": "4.4 A"}, {"id": "d", "text": "11√2 A"}]'::jsonb, 'a', 'The displacement current equals the conduction current, whose peak is √2 × 220/(100√2) = 2.2 A.', 'Z = √(100² + 100²) = 100√2 Ω. I_rms = 220/(100√2), so I₀ = √2 × I_rms = 2.2 A. Inside the capacitor the displacement current equals the conduction current, so its peak is 2.2 A whatever the state of charge.', '{"b": "This is off by a factor of 5.", "c": "This doubles the correct value.", "d": "This ignores the impedance."}'::jsonb, 'Displacement current between the plates equals the conduction current in the leads.', 'med', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('b72d0169-a031-5f14-a4a5-b5b5cd607f29', 'neet_ug', 'Physics', 'Ray Optics and Optical Instruments', 'Two identical glass (μg = 3/2) equiconvex lenses of focal length f each are kept in contact. The space between the two lenses is filled with water (μw = 4/3). The focal length of the combination is', '[{"id": "a", "text": "f/3"}, {"id": "b", "text": "f"}, {"id": "c", "text": "4f/3"}, {"id": "d", "text": "3f/4"}]'::jsonb, 'd', 'Two glass lenses give 2/f; the concave water lens gives −2/(3f); the net 4/(3f) gives F = 3f/4.', 'For each glass lens, 1/f = (1.5 − 1)(2/R), so R = f. The water between them forms a biconcave lens with 1/f_w = (4/3 − 1)(−2/R) = −2/(3f). The total power is 2/f − 2/(3f) = 4/(3f), so F = 3f/4.', '{"a": "This adds the powers incorrectly.", "b": "This ignores the water lens.", "c": "This inverts the result."}'::jsonb, 'Lens maker''s formula: 1/f = (μ − 1)(1/R₁ − 1/R₂).', 'med', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('c38d252f-0919-5fcd-94fd-9e54f0c26c19', 'neet_ug', 'Physics', 'Ray Optics and Optical Instruments', 'An air bubble in a glass slab with refractive index 1.5 (near normal incidence) is 5 cm deep when viewed from one surface and 3 cm deep when viewed from the opposite face. The thickness (in cm) of the slab is', '[{"id": "a", "text": "8"}, {"id": "b", "text": "10"}, {"id": "c", "text": "12"}, {"id": "d", "text": "16"}]'::jsonb, 'c', 'Real depth = μ × apparent depth from each face; add both real depths.', 'Real depth from first face = 1.5 × 5 = 7.5 cm and from the opposite face = 1.5 × 3 = 4.5 cm. The bubble lies between the faces, so thickness = 7.5 + 4.5 = 12 cm.', '{"a": "Simply adds the apparent depths 5 + 3, forgetting the refraction factor.", "b": "No consistent combination of μ and the depths gives 10 cm.", "d": "Overestimates; would need μ = 2."}'::jsonb, 'Apparent depth = real depth / μ for near-normal viewing from a denser medium into air.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('cb9cc638-9ba2-5d07-a3c4-0270658bf769', 'neet_ug', 'Physics', 'Wave Optics', 'The interference pattern is obtained with two coherent light sources of intensity ratio n. In the interference pattern, the ratio (Imax − Imin)/(Imax + Imin) will be', '[{"id": "a", "text": "√n/(n + 1)"}, {"id": "b", "text": "2√n/(n + 1)"}, {"id": "c", "text": "√n/(n + 1)²"}, {"id": "d", "text": "2√n/(n + 1)²"}]'::jsonb, 'b', 'The fringe-visibility ratio equals 2√(I₁I₂)/(I₁ + I₂).', 'Imax = (√I₁ + √I₂)², Imin = (√I₁ − √I₂)². Their difference is 4√(I₁I₂) and their sum is 2(I₁ + I₂), so the ratio is 2√(I₁I₂)/(I₁ + I₂). With I₁ = nI₂ this becomes 2√n/(n + 1).', '{"a": "Misses the factor 2 from the cross term.", "c": "Wrong power of (n + 1) and missing factor 2.", "d": "Squares the denominator incorrectly."}'::jsonb, 'For coherent sources, I = I₁ + I₂ + 2√(I₁I₂)cosφ.', 'med', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('e303df88-80b9-5ec8-aad9-60c7bae68fb0', 'neet_ug', 'Physics', 'Ray Optics and Optical Instruments', 'A person can see clearly objects only when they lie between 50 cm and 400 cm from his eyes. In order to increase the maximum distance of distinct vision to infinity, the type and power of the correcting lens, the person has to use, will be', '[{"id": "a", "text": "Convex, + 2.25 diopter"}, {"id": "b", "text": "Concave, – 0.25 diopter"}, {"id": "c", "text": "Concave, – 0.2 diopter"}, {"id": "d", "text": "Convex, + 0.15 diopter"}]'::jsonb, 'b', 'Myopia (far point 400 cm) is corrected by a concave lens of f = −400 cm.', 'The lens must form a virtual image at the far point (400 cm) of an object at infinity, so f = −400 cm = −4 m. Power P = 1/f = −0.25 D, a concave (diverging) lens.', '{"a": "A convex lens corrects hypermetropia (near point), not the far point.", "c": "−0.2 D corresponds to f = −500 cm, not the 400 cm far point.", "d": "Convex lens would worsen distant vision."}'::jsonb, 'Myopia: far point closer than infinity; corrected by a concave lens with f = −(far point).', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('07527893-500b-5475-84f8-6c1c37ca2f6e', 'neet_ug', 'Physics', 'Wave Optics', 'A linear aperture whose width is 0.02 cm is placed immediately in front of a lens of focal length 60 cm. The aperture is illuminated normally by a parallel beam of wavelength 5 × 10⁻⁵ cm. The distance of the first dark band of the diffraction pattern from the centre of the screen is', '[{"id": "a", "text": "0.10 cm"}, {"id": "b", "text": "0.25 cm"}, {"id": "c", "text": "0.20 cm"}, {"id": "d", "text": "0.15 cm"}]'::jsonb, 'd', 'First minimum of single-slit diffraction: a sinθ = λ, so y = fλ/a.', 'For the first dark band, sinθ ≈ θ = λ/a. On the focal plane y = fθ = (60 × 5 × 10⁻⁵)/0.02 = 0.15 cm.', '{"a": "Corresponds to using 2/3 of the correct value; arithmetic slip.", "b": "No standard formula gives this value.", "c": "Would need a = 0.015 cm."}'::jsonb, 'Single slit: minima at a sinθ = nλ; central maximum width = 2fλ/a.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('dca73bed-8f68-5c89-808a-4e407ca83cf1', 'neet_ug', 'Physics', 'Dual Nature of Radiation and Matter', 'Electrons of mass m with de-Broglie wavelength λ fall on the target in an X-ray tube. The cutoff wavelength (λ₀) of the emitted X-ray is :-', '[{"id": "a", "text": "λ₀ = 2mcλ²/h"}, {"id": "b", "text": "λ₀ = 2h/(mc)"}, {"id": "c", "text": "λ₀ = 2m²c²λ³/h²"}, {"id": "d", "text": "λ₀ = λ"}]'::jsonb, 'a', 'The whole electron KE goes into the shortest-wavelength photon: hc/λ₀ = h²/(2mλ²).', 'Electron momentum p = h/λ, so KE = p²/2m = h²/(2mλ²). The cutoff photon carries all this energy: hc/λ₀ = h²/(2mλ²), giving λ₀ = 2mcλ²/h.', '{"b": "Dimensionally a length but ignores λ entirely.", "c": "Wrong dimensions; mixes powers incorrectly.", "d": "Photon and electron of the same energy have different wavelengths."}'::jsonb, 'de Broglie wavelength λ = h/p = h/√(2mK).', 'med', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('316c4e8c-465b-5608-854f-18458d9d3c77', 'neet_ug', 'Physics', 'Dual Nature of Radiation and Matter', 'Photons with energy 5 eV are incident on a cathode C in a photoelectric cell. The maximum energy of emitted photoelectrons is 2 eV. When photons of energy 6 eV are incident on C, no photoelectrons will reach the anode A, if the stopping potential of A relative to C is:-', '[{"id": "a", "text": "+3 V"}, {"id": "b", "text": "+4 V"}, {"id": "c", "text": "-1 V"}, {"id": "d", "text": "-3 V"}]'::jsonb, 'd', 'Work function = 3 eV, so 6 eV photons give Kmax = 3 eV, needing −3 V on the anode.', 'φ = 5 − 2 = 3 eV. With 6 eV photons Kmax = 6 − 3 = 3 eV. To stop these electrons, the anode must be at −3 V relative to the cathode.', '{"a": "A positive anode attracts electrons, increasing current.", "b": "Positive and wrong magnitude.", "c": "−1 V cannot stop electrons of 3 eV."}'::jsonb, 'Einstein''s equation: Kmax = hν − φ = eV₀.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('aa63ceb0-f762-5cce-8f74-dbba0f177cdf', 'neet_ug', 'Physics', 'Atoms', 'If an electron in a hydrogen atom jumps from the 3rd orbit to the 2nd orbit, it emits a photon of wavelength λ. When it jumps from the 4th orbit to the 3rd orbit, the corresponding wavelength of the photon will be :-', '[{"id": "a", "text": "(16/25)λ"}, {"id": "b", "text": "(9/16)λ"}, {"id": "c", "text": "(20/7)λ"}, {"id": "d", "text": "(20/13)λ"}]'::jsonb, 'c', 'Ratio of wavelengths is the inverse ratio of (1/n₁² − 1/n₂²) terms.', '1/λ ∝ (1/4 − 1/9) = 5/36 and 1/λ′ ∝ (1/9 − 1/16) = 7/144. So λ′/λ = (5/36)/(7/144) = 20/7, i.e. λ′ = 20λ/7.', '{"a": "Uses ratio of n² values, not the Rydberg difference.", "b": "Ratio 9/16 is just n² values, ignoring the formula.", "d": "Arithmetic error in the 4→3 term."}'::jsonb, 'Rydberg formula: 1/λ = R(1/n₁² − 1/n₂²).', 'med', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('c0606646-3db6-5c9a-a159-82b821531d4a', 'neet_ug', 'Physics', 'Semiconductor Electronics: Materials, Devices and Simple Circuits', 'The given circuit has two ideal diodes connected as shown in the figure below. The current flowing through the resistance R₁ will be', '[{"id": "a", "text": "2.5 A"}, {"id": "b", "text": "10.0 A"}, {"id": "c", "text": "1.43 A"}, {"id": "d", "text": "3.13 A"}]'::jsonb, 'a', 'D₁ is reverse biased and D₂ forward biased, so only R₁ and R₃ carry current.', 'The battery''s positive terminal drives the top rail. D₁ points against this current direction (reverse biased, open), while D₂ conducts (ideal, zero resistance). Current = 10/(R₁ + R₃) = 10/(2 + 2) = 2.5 A.', '{"b": "Treats the circuit as having zero resistance beyond R₁ partially; ignores R₃.", "c": "Assumes both branches conduct in parallel incorrectly with wrong grouping.", "d": "Assumes both diodes conduct: 10/(2 + 3∥2) = 3.13 A."}'::jsonb, 'An ideal diode is a short circuit in forward bias and an open circuit in reverse bias.', 'med', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', '/pyq/ug/2016/44.webp'),
('409e6145-4a5e-50eb-b396-bb95a563a444', 'neet_ug', 'Physics', 'Semiconductor Electronics: Materials, Devices and Simple Circuits', 'What is the output Y in the following circuit, when all the three inputs A, B, C are first 0 and then 1?', '[{"id": "a", "text": "0, 1"}, {"id": "b", "text": "0, 0"}, {"id": "c", "text": "1, 0"}, {"id": "d", "text": "1, 1"}]'::jsonb, 'c', 'P is AND, Q is NAND: Y = NOT((A·B)·C).', 'Gate P is AND, Q is NAND. With A = B = C = 0, P = 0 and Y = NOT(0·0) = 1. With all inputs 1, P = 1 and Y = NOT(1·1) = 0. So Y is 1, then 0.', '{"a": "Reverses the order (AND-type output).", "b": "Would require output stuck low.", "d": "Would require output stuck high."}'::jsonb, 'A NAND gate gives 0 only when all inputs are 1.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', '/pyq/ug/2016/45.webp'),
('728bfe07-a16e-5660-8a18-190ad0ec035c', 'neet_ug', 'Chemistry', 'Chemical Bonding and Molecular Structure', 'Which one of the following compounds shows the presence of intramolecular hydrogen bond?', '[{"id": "a", "text": "H₂O₂"}, {"id": "b", "text": "HCN"}, {"id": "c", "text": "Cellulose"}, {"id": "d", "text": "Concentrated acetic acid"}]'::jsonb, 'c', 'Cellulose has many –OH groups that H-bond within the same macromolecule.', 'In cellulose, hydroxyl groups on adjacent glucose units of the same chain H-bond with each other, i.e. intramolecular H-bonding. H₂O₂ and acetic acid (dimerising) show intermolecular H-bonding, and HCN only weak intermolecular association.', '{"a": "H₂O₂ H-bonds between molecules.", "b": "HCN associates intermolecularly (C–H···N), not within one molecule.", "d": "Acetic acid forms intermolecular cyclic dimers."}'::jsonb, 'o-Nitrophenol is NCERT''s classic example of intramolecular H-bonding.', 'med', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('582e2e45-c414-532b-9684-3da9ba3ead07', 'neet_ug', 'Chemistry', 'Electrochemistry', 'The molar conductivity of a 0.5 mol/dm³ solution of AgNO₃ with electrolytic conductivity of 5.76 × 10⁻³ S cm⁻¹ at 298 K is', '[{"id": "a", "text": "2.88 S cm²/mol"}, {"id": "b", "text": "11.52 S cm²/mol"}, {"id": "c", "text": "0.086 S cm²/mol"}, {"id": "d", "text": "28.8 S cm²/mol"}]'::jsonb, 'b', 'Λm = κ × 1000 / C (C in mol L⁻¹).', 'Λm = (5.76 × 10⁻³ S cm⁻¹ × 1000 cm³ L⁻¹)/(0.5 mol L⁻¹) = 11.52 S cm² mol⁻¹.', '{"a": "Multiplies by C instead of dividing.", "c": "Unit-conversion error.", "d": "Arithmetic error in the factor."}'::jsonb, 'Λm = κ/c; conversion factor 1000 when c is in mol L⁻¹ and κ in S cm⁻¹.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('acb7cfd2-ea53-530a-8a49-de8ffa8eacfd', 'neet_ug', 'Chemistry', 'Chemical Kinetics', 'The decomposition of phosphine (PH₃) on tungsten at low pressure is a first-order reaction. It is because the', '[{"id": "a", "text": "rate is proportional to the surface coverage"}, {"id": "b", "text": "rate is inversely proportional to the surface coverage"}, {"id": "c", "text": "rate is independent of the surface coverage"}, {"id": "d", "text": "rate of decomposition is very slow"}]'::jsonb, 'a', 'At low pressure, surface coverage ∝ pressure, so rate ∝ p (first order).', 'At low pressure only a small fraction of the surface is covered, and the coverage is proportional to the gas pressure. Since the rate depends on the adsorbed amount, rate ∝ coverage ∝ p, giving first order. At high pressure the surface saturates and the reaction becomes zero order.', '{"b": "Higher coverage gives more reacting molecules, not fewer.", "c": "That describes the high-pressure, zero-order regime.", "d": "Speed alone does not determine order."}'::jsonb, 'Decomposition of NH₃ on hot Pt at high pressure is zero order.', 'med', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('8a44f953-a187-5611-8d1c-19e93e8558f8', 'neet_ug', 'Chemistry', 'Electrochemistry', 'During the electrolysis of molten sodium chloride, the time required to produce 0.10 mol of chlorine gas using a current of 3 amperes is', '[{"id": "a", "text": "55 minutes"}, {"id": "b", "text": "110 minutes"}, {"id": "c", "text": "220 minutes"}, {"id": "d", "text": "330 minutes"}]'::jsonb, 'b', '2Cl⁻ → Cl₂ + 2e⁻: 0.1 mol Cl₂ needs 0.2 F.', 'Charge Q = 0.2 × 96500 = 19300 C. Time t = Q/I = 19300/3 ≈ 6433 s ≈ 107 min ≈ 110 minutes.', '{"a": "Uses 1 electron per Cl₂ (0.1 F).", "c": "Uses 4 electrons per Cl₂.", "d": "Uses 6 electrons per Cl₂."}'::jsonb, 'Faraday''s first law: m = ZIt; 1 F = 96500 C mol⁻¹ of electrons.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('ae18cc2e-7f68-579b-b28a-da45977b5f0e', 'neet_ug', 'Chemistry', 'Structure of Atom', 'How many electrons can fit in the orbital for which n = 3 and l = 1?', '[{"id": "a", "text": "2"}, {"id": "b", "text": "6"}, {"id": "c", "text": "10"}, {"id": "d", "text": "14"}]'::jsonb, 'a', 'Any single orbital holds at most 2 electrons (Pauli principle).', 'n = 3, l = 1 is a 3p orbital. A single orbital holds a maximum of two electrons with opposite spins. (The whole 3p subshell would hold 6, but the question asks about the orbital.)', '{"b": "6 is the capacity of the entire 3p subshell, not one orbital.", "c": "Capacity of a d subshell.", "d": "Capacity of an f subshell."}'::jsonb, 'Pauli exclusion: no two electrons share all four quantum numbers.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('c0c6ac3d-24dc-5e32-861b-7b59972fe563', 'neet_ug', 'Chemistry', 'Thermodynamics', 'For a sample of perfect gas when its pressure is changed isothermally from pᵢ to p_f, the entropy change is given by', '[{"id": "a", "text": "ΔS = nR ln(p_f/pᵢ)"}, {"id": "b", "text": "ΔS = nR ln(pᵢ/p_f)"}, {"id": "c", "text": "ΔS = nRT ln(p_f/pᵢ)"}, {"id": "d", "text": "ΔS = RT ln(pᵢ/p_f)"}]'::jsonb, 'b', 'Isothermal ideal gas: ΔS = nR ln(V_f/Vᵢ) = nR ln(pᵢ/p_f).', 'For a reversible isothermal ideal-gas process, q_rev = nRT ln(V_f/Vᵢ), so ΔS = q_rev/T = nR ln(V_f/Vᵢ). Using Boyle''s law V_f/Vᵢ = pᵢ/p_f, ΔS = nR ln(pᵢ/p_f).', '{"a": "Inverts the pressure ratio; compression would wrongly increase entropy.", "c": "Includes T, giving units of energy (that is work), not entropy.", "d": "Includes T and omits n."}'::jsonb, 'ΔS = q_rev/T; entropy of a gas increases on expansion.', 'med', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('812df1b8-be69-57a0-b84f-3e1ff918c640', 'neet_ug', 'Chemistry', 'Solutions', 'The van''t Hoff factor (i) for a dilute aqueous solution of the strong electrolyte barium hydroxide is', '[{"id": "a", "text": "0"}, {"id": "b", "text": "1"}, {"id": "c", "text": "2"}, {"id": "d", "text": "3"}]'::jsonb, 'd', 'Ba(OH)₂ → Ba²⁺ + 2OH⁻ gives 3 ions.', 'A strong electrolyte dissociates completely in dilute solution. Each Ba(OH)₂ unit gives one Ba²⁺ and two OH⁻, so i = 3.', '{"a": "i cannot be zero.", "b": "i = 1 is for non-electrolytes.", "c": "Counts only two ions."}'::jsonb, 'i = (observed colligative property)/(calculated value).', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('4c7f1580-ebe3-57bf-b78d-ec154ecaab9b', 'neet_ug', 'Chemistry', 'Equilibrium', 'The percentage of pyridine (C₅H₅N) that forms pyridinium ion (C₅H₅N⁺H) in a 0.10 M aqueous pyridine solution (K_b for C₅H₅N = 1.7 × 10⁻⁹) is', '[{"id": "a", "text": "0.0060%"}, {"id": "b", "text": "0.013%"}, {"id": "c", "text": "0.77%"}, {"id": "d", "text": "1.6%"}]'::jsonb, 'b', 'Weak base: α = √(K_b/C).', 'α = √(1.7 × 10⁻⁹/0.10) = √(1.7 × 10⁻⁸) ≈ 1.3 × 10⁻⁴. Percentage = 1.3 × 10⁻⁴ × 100 ≈ 0.013%.', '{"a": "Arithmetic error in the square root.", "c": "Square-root/power-of-ten error.", "d": "Far too high for such a small K_b."}'::jsonb, 'Ostwald dilution law: α = √(K/C) for weak electrolytes.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('8629c23e-0125-51bd-9e88-8d97e35e1fce', 'neet_ug', 'Chemistry', 'The Solid State', 'In calcium fluoride, having the fluorite structure, the coordination numbers for calcium ion (Ca²⁺) and fluoride ion (F⁻) are', '[{"id": "a", "text": "4 and 2"}, {"id": "b", "text": "6 and 6"}, {"id": "c", "text": "8 and 4"}, {"id": "d", "text": "4 and 8"}]'::jsonb, 'c', 'In fluorite, Ca²⁺ is 8-coordinate (fcc) and F⁻ in tetrahedral voids is 4-coordinate.', 'Ca²⁺ ions form an fcc lattice and F⁻ occupy all tetrahedral voids. Each F⁻ is surrounded by 4 Ca²⁺, and since there are twice as many F⁻, each Ca²⁺ has 8 F⁻ neighbours: 8:4.', '{"a": "Wrong values for both ions.", "b": "That is the NaCl (rock-salt) structure.", "d": "Reversed: that is the antifluorite (Na₂O) type."}'::jsonb, 'Coordination numbers are in the inverse ratio of the ion counts in the formula.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('95d1ad24-05b7-5c96-8910-4aff86772419', 'neet_ug', 'Chemistry', 'Electrochemistry', 'If the E°cell for a given reaction has a negative value which of the following gives the correct relationships for the values of ΔG° and K_eq?', '[{"id": "a", "text": "ΔG° > 0; K_eq < 1"}, {"id": "b", "text": "ΔG° > 0; K_eq > 1"}, {"id": "c", "text": "ΔG° < 0; K_eq > 1"}, {"id": "d", "text": "ΔG° < 0; K_eq < 1"}]'::jsonb, 'a', 'ΔG° = −nFE° and ΔG° = −RT ln K.', 'If E° < 0, then ΔG° = −nFE° is positive. Since ΔG° = −RT ln K, a positive ΔG° means ln K < 0, i.e. K < 1.', '{"b": "Positive ΔG° cannot give K > 1.", "c": "That is the case for E° > 0.", "d": "Negative ΔG° always gives K > 1."}'::jsonb, 'E° > 0 ⇔ ΔG° < 0 ⇔ K > 1.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('be0246cb-c33b-5b52-8737-34788e92f7a4', 'neet_ug', 'Chemistry', 'Solutions', 'Which one of the following is incorrect for ideal solution?', '[{"id": "a", "text": "ΔH_mix = 0"}, {"id": "b", "text": "ΔU_mix = 0"}, {"id": "c", "text": "ΔP = P_obs − P_calculated by Raoult''s law = 0"}, {"id": "d", "text": "ΔG_mix = 0"}]'::jsonb, 'd', 'Mixing is spontaneous, so ΔG_mix < 0 even for ideal solutions.', 'For an ideal solution ΔH_mix = 0, ΔV_mix = 0 (hence ΔU_mix = 0), and Raoult''s law is obeyed exactly. Mixing increases entropy, so ΔG_mix = −TΔS_mix < 0, not zero.', '{"a": "True: no heat change on ideal mixing.", "b": "True: with ΔH = 0 and ΔV = 0, ΔU = 0.", "c": "True: ideal solutions obey Raoult''s law at all compositions."}'::jsonb, 'Ideal solution: ΔH_mix = 0, ΔV_mix = 0, obeys Raoult''s law.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('4916f537-a7b8-5788-a1ca-6d6ea28c08d1', 'neet_ug', 'Chemistry', 'Equilibrium', 'The solubility of AgCl(s) with solubility product 1.6 × 10⁻¹⁰ in 0.1 M NaCl solution would be', '[{"id": "a", "text": "1.25 × 10⁻⁵ M"}, {"id": "b", "text": "1.6 × 10⁻⁹ M"}, {"id": "c", "text": "1.6 × 10⁻¹¹ M"}, {"id": "d", "text": "zero"}]'::jsonb, 'b', 'Common-ion effect: s = K_sp/[Cl⁻].', 'In 0.1 M NaCl, [Cl⁻] ≈ 0.1 M. K_sp = s × 0.1, so s = 1.6 × 10⁻¹⁰/0.1 = 1.6 × 10⁻⁹ M.', '{"a": "Solubility in pure water (√K_sp).", "c": "Divides by 10 twice.", "d": "Solubility is reduced, never zero."}'::jsonb, 'A common ion suppresses the solubility of a sparingly soluble salt.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('b0e581a0-ecc6-5f8e-916f-3bc469b15948', 'neet_ug', 'Chemistry', 'Some Basic Concepts of Chemistry', 'Suppose the elements X and Y combine to form two compounds XY₂ and X₃Y₂. When 0.1 mole of XY₂ weighs 10 g and 0.05 mole of X₃Y₂ weighs 9 g, the atomic weights of X and Y are', '[{"id": "a", "text": "40, 30"}, {"id": "b", "text": "60, 40"}, {"id": "c", "text": "20, 30"}, {"id": "d", "text": "30, 20"}]'::jsonb, 'a', 'Molar masses 100 and 180 give two simultaneous equations.', 'M(XY₂) = 10/0.1 = 100, so X + 2Y = 100. M(X₃Y₂) = 9/0.05 = 180, so 3X + 2Y = 180. Subtracting, 2X = 80, X = 40 and Y = 30.', '{"b": "60 + 80 = 140 ≠ 100.", "c": "20 + 60 = 80 ≠ 100.", "d": "30 + 40 = 70 ≠ 100."}'::jsonb, 'Molar mass = mass/moles.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('72f1fc65-1ce7-5b69-b94e-f078a7ff4c5f', 'neet_ug', 'Chemistry', 'Electrochemistry', 'The number of electrons delivered at the cathode during electrolysis by a current of 1 ampere in 60 seconds is (charge on electron = 1.60 × 10⁻¹⁹ C)', '[{"id": "a", "text": "6 × 10²³"}, {"id": "b", "text": "6 × 10²⁰"}, {"id": "c", "text": "3.75 × 10²⁰"}, {"id": "d", "text": "7.48 × 10²³"}]'::jsonb, 'c', 'Number of electrons = It/e.', 'Q = It = 1 × 60 = 60 C. Number of electrons = 60/(1.60 × 10⁻¹⁹) = 3.75 × 10²⁰.', '{"a": "Avogadro''s number; that would be 1 F of charge.", "b": "Arbitrary power-of-ten guess.", "d": "No valid calculation gives this."}'::jsonb, 'Q = It = ne.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('494243db-20f3-5b69-8e8e-c3a39ebb794a', 'neet_ug', 'Chemistry', 'Electrochemistry', 'Zinc can be coated on iron to produce galvanized iron but the reverse is not possible. It is because', '[{"id": "a", "text": "zinc is lighter than iron"}, {"id": "b", "text": "zinc has lower melting point than iron"}, {"id": "c", "text": "zinc has lower negative electrode potential than iron"}, {"id": "d", "text": "zinc has higher negative electrode potential than iron"}]'::jsonb, 'd', 'Zn (E° = −0.76 V) is more easily oxidised than Fe (E° = −0.44 V), so it protects iron sacrificially.', 'Zinc''s reduction potential is more negative than iron''s, so zinc corrodes preferentially and protects iron even if the coating is scratched. Iron on zinc would offer no such protection.', '{"a": "Density has no bearing on corrosion protection.", "b": "Melting point helps hot-dipping but isn''t the reason.", "c": "Reverses the actual electrode potentials."}'::jsonb, 'Sacrificial protection: a more reactive metal corrodes in place of iron.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('58c1f811-86a9-5469-8f3d-765c8012b051', 'neet_ug', 'Chemistry', 'Chemical Bonding and Molecular Structure', 'The hybridizations of atomic orbitals of nitrogen in NO₂⁺, NO₃⁻ and NH₄⁺ respectively are', '[{"id": "a", "text": "sp, sp³ and sp²"}, {"id": "b", "text": "sp², sp³ and sp"}, {"id": "c", "text": "sp, sp² and sp³"}, {"id": "d", "text": "sp², sp and sp³"}]'::jsonb, 'c', 'Steric numbers of N are 2, 3 and 4.', 'NO₂⁺ is linear (O=N⁺=O, 2 σ-pairs): sp. NO₃⁻ is trigonal planar (3 σ-pairs): sp². NH₄⁺ is tetrahedral (4 σ-pairs): sp³.', '{"a": "Swaps NO₃⁻ and NH₄⁺.", "b": "Wrong for all three.", "d": "Swaps NO₂⁺ and NO₃⁻."}'::jsonb, 'Hybridisation = number of σ-bonds + lone pairs on the central atom.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('abd124dc-98f2-528c-ba38-336f06ee7657', 'neet_ug', 'Chemistry', 'Chemical Bonding and Molecular Structure', 'Which of the following fluoro-compounds is most likely to behave as a Lewis base?', '[{"id": "a", "text": "BF₃"}, {"id": "b", "text": "PF₃"}, {"id": "c", "text": "CF₄"}, {"id": "d", "text": "SiF₄"}]'::jsonb, 'b', 'PF₃ has a lone pair on phosphorus to donate.', 'A Lewis base donates an electron pair. In PF₃, phosphorus carries a lone pair (as in PF₃ metal complexes). BF₃ and SiF₄ are electron acceptors, and CF₄ has no donor lone pair on carbon and no vacant orbitals.', '{"a": "BF₃ is a classic Lewis acid (incomplete octet).", "c": "CF₄ is inert, with no lone pair on C.", "d": "SiF₄ can accept F⁻ (forms SiF₆²⁻), so it acts as a Lewis acid."}'::jsonb, 'Lewis acid = electron-pair acceptor; Lewis base = electron-pair donor.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('2dc01e14-084b-5552-9301-941132ac069b', 'neet_ug', 'Chemistry', 'The p-Block Elements', 'Hot concentrated sulphuric acid is a moderately strong oxidizing agent. Which of the following reactions does not show oxidizing behavior?', '[{"id": "a", "text": "Cu + 2H₂SO₄ → CuSO₄ + SO₂ + 2H₂O"}, {"id": "b", "text": "3S + 2H₂SO₄ → 3SO₂ + 2H₂O"}, {"id": "c", "text": "C + 2H₂SO₄ → CO₂ + 2SO₂ + 2H₂O"}, {"id": "d", "text": "CaF₂ + H₂SO₄ → CaSO₄ + 2HF"}]'::jsonb, 'd', 'In CaF₂ + H₂SO₄ no oxidation states change; it''s an acid–salt displacement.', 'In (1)–(3), sulphur is reduced from +6 to +4 (SO₂) while Cu, S or C is oxidised. In CaF₂ + H₂SO₄ → CaSO₄ + 2HF, S stays +6 and F stays −1: H₂SO₄ acts only as a non-volatile acid.', '{"a": "Cu is oxidised to Cu²⁺; S(+6) → S(+4).", "b": "S(0) is oxidised to S(+4).", "c": "C is oxidised to CO₂."}'::jsonb, 'Conc. H₂SO₄ acts as an acid, a dehydrating agent and an oxidising agent.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('502500d9-911e-52bc-9ec3-4dac5b8d4269', 'neet_ug', 'Chemistry', 'Coordination Compounds', 'Which of the following pairs of d-orbitals will have electron density along the axes?', '[{"id": "a", "text": "d_z², d_xz"}, {"id": "b", "text": "d_xz, d_yz"}, {"id": "c", "text": "d_z², d_x²−y²"}, {"id": "d", "text": "d_xy, d_x²−y²"}]'::jsonb, 'c', 'The e_g set (d_z², d_x²−y²) points along the axes.', 'd_x²−y² has lobes along the x and y axes, and d_z² along the z axis. d_xy, d_yz and d_xz have lobes between the axes.', '{"a": "d_xz lies between the axes.", "b": "Both lie between the axes.", "d": "d_xy lies between the axes."}'::jsonb, 'In an octahedral field, e_g orbitals point at ligands and rise in energy.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('3fe91048-70f7-5fa6-9cbf-3b00126e5ff6', 'neet_ug', 'Chemistry', 'Chemical Bonding and Molecular Structure', 'The correct geometry and hybridization for XeF₄ are :', '[{"id": "a", "text": "Octahedral, sp³d²"}, {"id": "b", "text": "Trigonal bipyramidal, sp³d"}, {"id": "c", "text": "Planar triangle, sp³d³"}, {"id": "d", "text": "Square planar, sp³d²"}]'::jsonb, 'd', 'Xe has 4 bond pairs + 2 lone pairs: sp³d², square planar shape.', 'Xe has 8 valence electrons; 4 form bonds with F, leaving 2 lone pairs. Six electron domains give sp³d² (octahedral arrangement), and with the lone pairs trans the molecular shape is square planar.', '{"a": "Octahedral is the electron-domain geometry, not the molecular shape.", "b": "Wrong number of domains (that is 5).", "c": "Impossible combination."}'::jsonb, 'Shape ignores lone pairs; hybridisation counts them.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('8b38d6ff-3c8b-52d7-965c-912ab75b7fbd', 'neet_ug', 'Chemistry', 'Chemical Bonding and Molecular Structure', 'Among the following which one is a wrong statement?', '[{"id": "a", "text": "PH₅ and BiCl₅ do not exist"}, {"id": "b", "text": "pπ–dπ bonds are present in SO₂"}, {"id": "c", "text": "SeF₄ and CH₄ have same shape"}, {"id": "d", "text": "I₃⁺ has bent geometry"}]'::jsonb, 'c', 'SeF₄ is see-saw (one lone pair) while CH₄ is tetrahedral.', 'SeF₄ has 4 bond pairs and 1 lone pair (sp³d), giving a see-saw shape; CH₄ is tetrahedral. The other statements hold: PH₅ (high-energy P–H/d mismatch) and BiCl₅ (inert pair effect) do not exist, SO₂ has pπ–dπ bonding, and I₃⁺ (2 bp + 2 lp) is bent.', '{"a": "True: neither compound exists.", "b": "True: S uses d-orbitals in one of its π bonds.", "d": "True: two lone pairs on the central I make it bent."}'::jsonb, 'VSEPR: AB₄E is see-saw; AB₄ is tetrahedral.', 'med', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('de422dc4-cacd-52c8-87b4-2969bc15ba68', 'neet_ug', 'Chemistry', 'The d- and f-Block Elements', 'Which one of the following statements related to lanthanons is incorrect?', '[{"id": "a", "text": "Europium shows +2 oxidation state."}, {"id": "b", "text": "The basicity decreases as the ionic radius decreases from Pr to Lu."}, {"id": "c", "text": "All the lanthanons are much more reactive than aluminium"}, {"id": "d", "text": "Ce(+4) solutions are widely used as oxidizing agent in volumetric analysis"}]'::jsonb, 'c', 'Later lanthanoids behave more like aluminium; not all are much more reactive.', 'Early lanthanoids are about as reactive as calcium, but as atomic number increases their behaviour approaches that of aluminium, so ''all much more reactive than Al'' is wrong. Eu²⁺ (4f⁷) exists, basicity of Ln(OH)₃ falls with lanthanoid contraction, and Ce⁴⁺ is a common volumetric oxidant.', '{"a": "Correct: Eu²⁺ has a stable half-filled 4f⁷ configuration.", "b": "Correct: smaller Ln³⁺ means more covalent, less basic hydroxide.", "d": "Correct: Ce⁴⁺ is a strong oxidant used in titrations."}'::jsonb, 'Lanthanoid contraction lowers basicity from La(OH)₃ to Lu(OH)₃.', 'med', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('a879fa78-7c4b-5ebb-828d-a009f9727b3d', 'neet_ug', 'Chemistry', 'Haloalkanes and Haloarenes', 'Which of the following can be used as halide component for Friedel-Crafts reaction?', '[{"id": "a", "text": "Chlorobenzene"}, {"id": "b", "text": "Bromobenzene"}, {"id": "c", "text": "Chloroethene"}, {"id": "d", "text": "Isopropyl chloride"}]'::jsonb, 'd', 'An alkyl halide easily forms a carbocation with AlCl₃; aryl/vinyl halides do not.', 'Friedel–Crafts alkylation needs a carbocation generated from the halide by AlCl₃. Isopropyl chloride readily gives the secondary isopropyl cation. In chlorobenzene, bromobenzene and chloroethene, the C–X bond has partial double-bond character from resonance, and aryl/vinyl cations are very unstable.', '{"a": "Aryl C–X is strengthened by resonance; no aryl cation forms.", "b": "Same reason as chlorobenzene.", "c": "Vinyl halide has partial double-bond character; vinyl cation is unstable."}'::jsonb, 'Aryl and vinyl halides are much less reactive towards ionisation than alkyl halides.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('5039f8fb-fea1-5933-8cc4-401048def73d', 'neet_ug', 'Chemistry', 'Haloalkanes and Haloarenes', 'Which of the following compounds shall not produce propene by reaction with HBr followed by elimination or direct only elimination reaction?', '[{"id": "a", "text": "Option (1) in figure"}, {"id": "b", "text": "Option (2) in figure"}, {"id": "c", "text": "Option (3) in figure"}, {"id": "d", "text": "Option (4) in figure"}]'::jsonb, 'c', 'Ketene (H₂C=C=O) has only two carbons and cannot give propene.', 'Cyclopropane opens with HBr to 1-bromopropane, which on dehydrohalogenation gives propene. Propan-1-ol dehydrates to propene, and 1-bromopropane eliminates HBr to give propene. Ketene H₂C=C=O is a C₂ compound, so it cannot form propene.', '{"a": "Cyclopropane + HBr → CH₃CH₂CH₂Br → propene.", "b": "Acid-catalysed dehydration of propan-1-ol gives propene.", "d": "Alcoholic KOH removes HBr to give propene."}'::jsonb, 'β-Elimination (dehydrohalogenation) of alkyl halides follows Saytzeff''s rule.', 'med', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', '/pyq/ug/2016/80.webp'),
('0f57f657-4cba-534e-8b37-1f77e2200168', 'neet_ug', 'Chemistry', 'Biomolecules', 'The central dogma of molecular genetics states that the genetic information flows from', '[{"id": "a", "text": "Amino acids → Proteins → DNA"}, {"id": "b", "text": "DNA → Carbohydrates → Proteins"}, {"id": "c", "text": "DNA → RNA → Proteins"}, {"id": "d", "text": "DNA → RNA → Carbohydrates"}]'::jsonb, 'c', 'Information flows DNA → (transcription) RNA → (translation) protein.', 'DNA is transcribed into mRNA, which is translated into protein on ribosomes. Carbohydrates are not part of the genetic information flow, and proteins do not encode DNA.', '{"a": "Reverses the direction; proteins do not code for DNA.", "b": "Carbohydrates carry no genetic information.", "d": "RNA is translated into proteins, not carbohydrates."}'::jsonb, 'Central dogma (Crick): DNA → RNA → Protein.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('b59b33af-b4dc-58b9-85b7-4718fa962f4d', 'neet_ug', 'Chemistry', 'Biomolecules', 'The correct corresponding order of names of following aldoses with configuration given below
[four Fischer projections in figure]
respectively, is', '[{"id": "a", "text": "L-erythrose, L-threose, L-erythrose, D-threose"}, {"id": "b", "text": "D-threose, D-erythrose, L-threose, L-erythrose"}, {"id": "c", "text": "L-erythrose, L-threose, D-erythrose, D-threose"}, {"id": "d", "text": "D-erythrose, D-threose, L-erythrose, L-threose"}]'::jsonb, 'd', 'OH on the same side = erythrose; D/L set by the OH on the lowest chiral carbon.', 'Structure 1 has both OH on the right: D-erythrose. Structure 2 has OH left then right: the OHs are on opposite sides (threose) and the lower OH is right, so D-threose. Structure 3 has both OH left: L-erythrose. Structure 4 has OH right then left: L-threose.', '{"a": "Wrong D/L assignment for structures 1 and 2 and wrong name for 4.", "b": "Swaps erythrose and threose throughout.", "c": "Assigns L to D structures and vice versa."}'::jsonb, 'D/L is decided by the –OH on the chiral carbon farthest from the carbonyl in the Fischer projection.', 'med', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', '/pyq/ug/2016/83.webp'),
('6da57b9f-84fb-53f7-8c7f-4aa75da67c67', 'neet_ug', 'Chemistry', 'Amines', 'A given nitrogen containing aromatic compound A reacts with Sn/HCl, followed by HNO₂ to give an unstable compound B. B, on treatment with phenol, forms a beautiful coloured compound C with the molecular formula C₁₂H₁₀N₂O. The structure of the compound A is', '[{"id": "a", "text": "Option (1) in figure"}, {"id": "b", "text": "Option (2) in figure"}, {"id": "c", "text": "Option (3) in figure"}, {"id": "d", "text": "Option (4) in figure"}]'::jsonb, 'b', 'Nitrobenzene → (Sn/HCl) aniline → (HNO₂) benzenediazonium chloride → (phenol) p-hydroxyazobenzene, C₁₂H₁₀N₂O.', 'Sn/HCl reduces –NO₂ to –NH₂, giving aniline. HNO₂ at 0–5 °C converts aniline into the unstable benzenediazonium salt (B). Coupling with phenol gives orange p-hydroxyazobenzene, C₆H₅–N=N–C₆H₄–OH = C₁₂H₁₀N₂O. So A is nitrobenzene, which needs the reduction step first.', '{"a": "Aniline would not need Sn/HCl reduction; the sequence implies a reducible nitro group.", "c": "Benzonitrile is reduced to benzylamine, which does not give a stable diazonium/azo dye.", "d": "Benzamide is not reduced by Sn/HCl to an aromatic amine."}'::jsonb, 'Arenediazonium salts couple with phenol (alkaline medium) at the para position to give azo dyes.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', '/pyq/ug/2016/85.webp'),
('79eec290-a5d0-58b0-97bc-75d503605255', 'neet_ug', 'Chemistry', 'Haloalkanes and Haloarenes', 'Consider the reaction
CH₃–CH₂–CH₂–Br + NaCN → CH₃–CH₂–CH₂–CN + NaBr
The reaction will be the fastest in', '[{"id": "a", "text": "ethanol"}, {"id": "b", "text": "methanol"}, {"id": "c", "text": "N, N′-dimethylformamide (DMF)"}, {"id": "d", "text": "water"}]'::jsonb, 'c', 'SN2 reactions of a primary bromide with CN⁻ are fastest in a polar aprotic solvent like DMF.', 'This is an SN2 substitution on a primary alkyl bromide. Protic solvents (water, methanol, ethanol) hydrogen-bond to CN⁻ and blunt its nucleophilicity. DMF is polar aprotic: it dissolves the salt by solvating Na⁺ but leaves CN⁻ ''naked'' and highly reactive, so the rate is greatest.', '{"a": "Ethanol is protic and solvates the cyanide ion.", "b": "Methanol is protic; H-bonding lowers CN⁻ reactivity.", "d": "Water strongly solvates CN⁻ by H-bonding, slowing SN2."}'::jsonb, 'Polar aprotic solvents (DMF, DMSO, acetone) accelerate SN2; polar protic solvents favour SN1.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('45ccd49d-25dd-51b0-9d8b-bc00d3e19fb1', 'neet_ug', 'Chemistry', 'Aldehydes, Ketones and Carboxylic Acids', 'The correct structure of the product A formed in the reaction
[cyclohex-2-en-1-one —H₂ (gas, 1 atmosphere), Pd/carbon, ethanol→ A]', '[{"id": "a", "text": "Option (1) in figure"}, {"id": "b", "text": "Option (2) in figure"}, {"id": "c", "text": "Option (3) in figure"}, {"id": "d", "text": "Option (4) in figure"}]'::jsonb, 'b', 'H₂ over Pd/C at 1 atm reduces the conjugated C=C but leaves the C=O intact, giving cyclohexanone.', 'Catalytic hydrogenation with Pd/C under mild conditions (1 atm, room temperature) readily saturates alkene C=C bonds, while the ketone C=O is much harder to hydrogenate. Cyclohex-2-en-1-one therefore gives cyclohexanone. Allylic alcohols (options 1, 3) would need hydride reduction of C=O, and a carbocation (option 4) is not a product of hydrogenation.', '{"a": "Reducing C=O while keeping C=C needs a selective hydride (e.g. NaBH₄/CeCl₃), not H₂/Pd.", "c": "Shifts the double bond and reduces C=O; not consistent with hydrogenation.", "d": "A carbocation is not a stable isolable product of catalytic hydrogenation."}'::jsonb, 'Under mild H₂/Pd–C conditions, C=C is reduced in preference to C=O.', 'med', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', '/pyq/ug/2016/87.webp'),
('f0219319-bee9-5111-81c8-cef8c60aebc1', 'neet_ug', 'Chemistry', 'Organic Chemistry – Some Basic Principles and Techniques', 'Which among the given molecules can exhibit tautomerism?
[structures I, II and III in figure]', '[{"id": "a", "text": "III only"}, {"id": "b", "text": "Both I and III"}, {"id": "c", "text": "Both I and II"}, {"id": "d", "text": "Both II and III"}]'::jsonb, 'a', 'Only III has an enolisable α-H; in I and II the only α-H atoms are at bridgeheads (Bredt''s rule) or absent.', 'Keto–enol tautomerism needs an α-hydrogen that can form a C=C to the carbonyl carbon. In I (7-norbornanone) both α-carbons are bridgeheads, and an enol would place a double bond at a bridgehead, forbidden by Bredt''s rule. In II, one α-carbon is a bridgehead and the other carries two phenyls (no H). In III (2-norbornanone), C-3 is a CH₂ group, so it can enolise.', '{"b": "I''s α-hydrogens are bridgehead; the enol would violate Bredt''s rule.", "c": "Neither I nor II has a usable α-H.", "d": "II has no enolisable α-H (gem-diphenyl carbon and a bridgehead)."}'::jsonb, 'Tautomerism requires an α-H; bridgehead α-H cannot enolise in small bicyclic systems (Bredt''s rule).', 'hard', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', '/pyq/ug/2016/88.webp'),
('c80cceff-9ae4-5783-bb8f-56e1ee5e4f68', 'neet_ug', 'Chemistry', 'Aldehydes, Ketones and Carboxylic Acids', 'The correct order of the strengths of the carboxylic acids
[I: cyclohexanecarboxylic acid; II: COOH at C-3 of tetrahydropyran; III: COOH at C-4 of tetrahydropyran – see figure]', '[{"id": "a", "text": "I > II > III"}, {"id": "b", "text": "II > III > I"}, {"id": "c", "text": "III > II > I"}, {"id": "d", "text": "II > I > III"}]'::jsonb, 'b', 'The ring oxygen''s –I effect stabilises the carboxylate; it is strongest when O is closest (II), weaker in III and absent in I.', 'Electron-withdrawing groups increase acidity by stabilising the conjugate base, and the –I effect decays with distance. In II the ring O is two bonds from the carbon bearing COOH, in III it is three bonds away, and I has no heteroatom. Hence acidity II > III > I.', '{"a": "Reverses the order; I has no electron-withdrawing oxygen.", "c": "III''s oxygen is farther away, so its –I effect is weaker than in II.", "d": "I is the weakest acid, not intermediate."}'::jsonb, 'Inductive (–I) effect falls off rapidly with distance from the –COOH group.', 'med', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', '/pyq/ug/2016/89.webp'),
('b29f403e-d260-503f-a9a7-69e3d9d39436', 'neet_ug', 'Chemistry', 'Hydrocarbons', 'The compound that will react most readily with gaseous bromine has the formula?', '[{"id": "a", "text": "C₃H₆"}, {"id": "b", "text": "C₂H₂"}, {"id": "c", "text": "C₄H₁₀"}, {"id": "d", "text": "C₂H₄"}]'::jsonb, 'a', 'Propene reacts fastest with gaseous Br₂ because it can undergo allylic (free-radical) substitution through a resonance-stabilised allyl radical.', 'In the gas phase bromine reacts by a free-radical pathway. Propene (CH₂=CH–CH₃) has allylic C–H bonds that are weak because the resulting allyl radical is resonance stabilised, so it reacts most readily (giving allyl bromide). Ethene and ethyne have no such allylic hydrogens and butane forms only ordinary alkyl radicals.', '{"b": "Ethyne''s sp-carbon π-electrons are held tightly and it has no allylic H; it is less reactive towards Br₂.", "c": "Butane (alkane) reacts only by slow radical substitution of ordinary C–H bonds.", "d": "Ethene lacks allylic hydrogens and has no stabilised radical pathway."}'::jsonb, 'Allylic C–H bonds are weak because the allyl radical is resonance stabilised.', 'hard', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('3d62bb06-0988-5889-bd87-280514d6c5b9', 'neet_ug', 'Botany', 'Biological Classification', 'Which one of the following is wrong for fungi?', '[{"id": "a", "text": "They are eukaryotic."}, {"id": "b", "text": "All fungi possess a purely cellulosic cell wall."}, {"id": "c", "text": "They are heterotrophic."}, {"id": "d", "text": "They are both unicellular and multicellular."}]'::jsonb, 'b', 'Fungal cell walls are made mainly of chitin and polysaccharides, not purely cellulose.', 'Fungi are eukaryotic, heterotrophic organisms that may be unicellular (yeast) or filamentous. Their cell walls are composed of chitin and polysaccharides, so the claim that all fungi have a purely cellulosic wall is wrong.', '{"a": "True; fungi have a membrane-bound nucleus.", "c": "True; they are saprophytes, parasites or symbionts.", "d": "True; yeast is unicellular, most others are filamentous."}'::jsonb, 'Fungal cell wall = chitin + polysaccharides.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('92d2c3b5-4c36-522f-bb6e-389892e68478', 'neet_ug', 'Botany', 'Biological Classification', 'Methanogens belong to', '[{"id": "a", "text": "Eubacteria"}, {"id": "b", "text": "Archaebacteria"}, {"id": "c", "text": "Dinoflagellates"}, {"id": "d", "text": "Slime moulds"}]'::jsonb, 'b', 'Methanogens are archaebacteria living in marshy areas and the rumen of cattle, producing methane.', 'Archaebacteria include halophiles, thermoacidophiles and methanogens. Methanogens live in marshes and the rumen of ruminants and generate methane (biogas). Their distinct cell wall structure separates them from eubacteria.', '{"a": "Eubacteria are ''true bacteria'' with peptidoglycan walls; methanogens are not among them.", "c": "Dinoflagellates are protists (Kingdom Protista).", "d": "Slime moulds are saprophytic protists."}'::jsonb, 'Archaebacteria: halophiles, thermoacidophiles, methanogens.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('36de53fe-81bd-5848-a79c-7ded03018365', 'neet_ug', 'Botany', 'Biological Classification', 'Select the wrong statement.', '[{"id": "a", "text": "The walls of diatoms are easily destructible."}, {"id": "b", "text": "''Diatomaceous earth'' is formed by the cell wall of diatoms."}, {"id": "c", "text": "Diatoms are chief producers in the ocean."}, {"id": "d", "text": "Diatoms are microscopic and float passively in water."}]'::jsonb, 'a', 'Diatom walls are silica-embedded and practically indestructible, which is why they accumulate as diatomaceous earth.', 'Diatoms have cell walls impregnated with silica that form two overlapping halves like a soap box. These walls are indestructible and pile up as diatomaceous earth. Diatoms are planktonic and are the chief producers in the oceans, so only statement 1 is wrong.', '{"b": "Correct statement: diatomaceous earth is the deposit of their silica walls.", "c": "Correct statement: diatoms are major oceanic producers.", "d": "Correct statement: they are microscopic plankton."}'::jsonb, 'Diatoms (chrysophytes) have silica walls; their deposit is diatomaceous earth used in polishing and filtration.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('b6ab5406-abdb-5211-a3ae-dca66cd0bad4', 'neet_ug', 'Botany', 'The Living World', 'The label of a herbarium sheet does not carry information on', '[{"id": "a", "text": "date of collection"}, {"id": "b", "text": "name of collector"}, {"id": "c", "text": "local names"}, {"id": "d", "text": "height of the plant"}]'::jsonb, 'd', 'Herbarium labels record collection date, collector, locality, local, botanical and family names, but not plant height.', 'A herbarium sheet bears a label with the date and place of collection, English, local and botanical names, family and the collector''s name. The height of the plant is not a standard label entry.', '{"a": "Date of collection is recorded on the label.", "b": "The collector''s name is recorded.", "c": "Local names are recorded."}'::jsonb, 'Herbarium label: date, place, English/local/botanical names, family, collector''s name.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('4c2ce6a3-fe70-565e-9b53-e7052eaa4b3d', 'neet_ug', 'Botany', 'Plant Kingdom', 'Conifers are adapted to tolerate extreme environmental conditions because of', '[{"id": "a", "text": "broad hardy leaves"}, {"id": "b", "text": "superficial stomata"}, {"id": "c", "text": "thick cuticle"}, {"id": "d", "text": "presence of vessels"}]'::jsonb, 'c', 'Conifer needles have a thick cuticle and sunken stomata that cut water loss.', 'Gymnosperm (conifer) leaves are needle-like with reduced surface area, a thick cuticle and sunken stomata. These features reduce transpiration and help them withstand extreme temperature, humidity and wind.', '{"a": "Conifer leaves are needle-like, not broad.", "b": "Their stomata are sunken, not superficial.", "d": "Gymnosperms generally lack vessels in xylem."}'::jsonb, 'Conifer needles: reduced area, thick cuticle, sunken stomata.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('c6f7d337-f9ef-5b75-a257-7bb2a8d60e80', 'neet_ug', 'Botany', 'Plant Kingdom', 'Which one of the following statements is wrong?', '[{"id": "a", "text": "Algae increase the level of dissolved oxygen in the immediate environment."}, {"id": "b", "text": "Algin is obtained from red algae, and carrageenan from brown algae."}, {"id": "c", "text": "Agar-agar is obtained from Gelidium and Gracilaria."}, {"id": "d", "text": "Laminaria and Sargassum are used as food."}]'::jsonb, 'b', 'The sources are swapped: algin comes from brown algae and carrageenan from red algae.', 'Brown algae (Phaeophyceae) yield algin, and red algae (Rhodophyceae) yield carrageenan; both are hydrocolloids. Statement 2 reverses this, so it is wrong. The other statements are correct.', '{"a": "True; algal photosynthesis releases O₂ into the water.", "c": "True; agar is from Gelidium and Gracilaria (red algae).", "d": "True; Laminaria and Sargassum are among the edible marine algae."}'::jsonb, 'Algin – brown algae; carrageenan and agar – red algae.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('d48a8787-b768-53ec-acb3-f5a7130e859b', 'neet_ug', 'Botany', 'Morphology of Flowering Plants', 'The term ''polyadelphous'' is related to', '[{"id": "a", "text": "gynoecium"}, {"id": "b", "text": "androecium"}, {"id": "c", "text": "corolla"}, {"id": "d", "text": "calyx"}]'::jsonb, 'b', 'Polyadelphous describes stamens united by filaments into more than two bundles, as in citrus.', 'Fusion of stamen filaments gives monadelphous (one bundle), diadelphous (two bundles) or polyadelphous (more than two bundles) conditions. Since this concerns stamens, the term relates to the androecium.', '{"a": "Gynoecium terms are apocarpous/syncarpous.", "c": "Corolla terms include polypetalous/gamopetalous.", "d": "Calyx terms include polysepalous/gamosepalous."}'::jsonb, 'Monadelphous – China rose; diadelphous – pea; polyadelphous – citrus.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('450b1042-0942-503c-83dc-243cf3527403', 'neet_ug', 'Botany', 'Morphology of Flowering Plants', 'How many plants among Indigofera, Sesbania, Salvia, Allium, Aloe, mustard, groundnut, radish, gram and turnip have stamens with different lengths in their flowers?', '[{"id": "a", "text": "Three"}, {"id": "b", "text": "Four"}, {"id": "c", "text": "Five"}, {"id": "d", "text": "Six"}]'::jsonb, 'b', 'Salvia (didynamous) and mustard, radish and turnip (tetradynamous, Brassicaceae) have stamens of unequal length: four plants.', 'Salvia (Lamiaceae) has didynamous stamens, two long and two short. Mustard, radish and turnip belong to Brassicaceae, with tetradynamous stamens, four long and two short. The legumes (Indigofera, Sesbania, groundnut, gram) and lilies (Allium, Aloe) are not counted as having stamens of different lengths. Total = 4.', '{"a": "Misses one of the Brassicaceae members or Salvia.", "c": "Wrongly includes a legume or liliaceous plant.", "d": "Overcounts; only four have didynamous/tetradynamous stamens."}'::jsonb, 'Didynamous – Lamiaceae (Salvia); tetradynamous – Brassicaceae (mustard).', 'med', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('4519eb63-d942-5b42-a215-d5c09938f9ac', 'neet_ug', 'Botany', 'Morphology of Flowering Plants', 'Radial symmetry is found in the flowers of', '[{"id": "a", "text": "Brassica"}, {"id": "b", "text": "Trifolium"}, {"id": "c", "text": "Pisum"}, {"id": "d", "text": "Cassia"}]'::jsonb, 'a', 'Brassica flowers are actinomorphic; Trifolium, Pisum and Cassia (legumes) have zygomorphic flowers.', 'A flower is actinomorphic (radially symmetrical) when it can be divided into two equal halves along any radial plane through the centre, as in mustard (Brassica). Members of Fabaceae such as pea, Trifolium and Cassia have zygomorphic flowers that divide into equal halves in only one plane.', '{"b": "Trifolium (Fabaceae) has zygomorphic papilionaceous flowers.", "c": "Pisum (pea) flowers are zygomorphic.", "d": "Cassia flowers are zygomorphic."}'::jsonb, 'Actinomorphic: mustard, datura, chilli; zygomorphic: pea, gulmohur, bean, Cassia.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('4cdf1aef-317c-599d-9657-d7d8ca47bdf5', 'neet_ug', 'Botany', 'Morphology of Flowering Plants', 'Free-central placentation is found in', '[{"id": "a", "text": "Dianthus"}, {"id": "b", "text": "Argemone"}, {"id": "c", "text": "Brassica"}, {"id": "d", "text": "Citrus"}]'::jsonb, 'a', 'Dianthus and Primrose show free-central placentation: ovules on a central axis without septa.', 'In free-central placentation ovules are borne on a central axis and septa are absent, as in Dianthus and Primrose. Argemone and Brassica have parietal placentation, and Citrus has axile placentation.', '{"b": "Argemone has parietal placentation.", "c": "Brassica has parietal placentation (with a false septum).", "d": "Citrus has axile placentation."}'::jsonb, 'Placentation: marginal–pea, axile–china rose/tomato/lemon, parietal–mustard/Argemone, free central–Dianthus/Primrose, basal–sunflower/marigold.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('b62a3a5a-7cf9-51cd-ae83-2e08277a5769', 'neet_ug', 'Botany', 'Anatomy of Flowering Plants', 'Cortex is the region found between', '[{"id": "a", "text": "epidermis and stele"}, {"id": "b", "text": "pericycle and endodermis"}, {"id": "c", "text": "endodermis and pith"}, {"id": "d", "text": "endodermis and vascular bundle"}]'::jsonb, 'a', 'The cortex is the ground tissue lying between the epidermis and the stele.', 'In roots and dicot stems, the cortex consists of several layers of parenchyma below the epidermis and outside the stele; endodermis is its innermost layer. So the cortex lies between epidermis and stele.', '{"b": "Pericycle and endodermis are adjacent layers; no cortex lies between them.", "c": "Between endodermis and pith lie pericycle and vascular tissues, i.e. the stele.", "d": "This region belongs to the stele, not the cortex."}'::jsonb, 'Stele = all tissues inside the endodermis (pericycle, vascular bundles, pith).', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('ddd7038c-b69a-5315-b0a6-4c7bd8585cbb', 'neet_ug', 'Botany', 'Cell: The Unit of Life', 'Select the mismatch.', '[{"id": "a", "text": "Gas vacuoles - Green bacteria"}, {"id": "b", "text": "Large central vacuoles - Animal cells"}, {"id": "c", "text": "Protists - Eukaryotes"}, {"id": "d", "text": "Methanogens - Prokaryotes"}]'::jsonb, 'b', 'Large central vacuoles are typical of plant cells; animal cells have small vacuoles.', 'A mature plant cell has a large central vacuole that can occupy up to 90% of the cell volume, whereas animal cells have small, often temporary vacuoles. Gas vacuoles do occur in blue-green, purple and green photosynthetic bacteria, protists are eukaryotes, and methanogens are prokaryotes, so option 2 is the mismatch.', '{"a": "Correct pair: green photosynthetic bacteria have gas vacuoles.", "c": "Correct pair: protists are unicellular eukaryotes.", "d": "Correct pair: methanogens are archaebacteria (prokaryotes)."}'::jsonb, 'Gas vacuoles occur in blue-green, purple and green photosynthetic bacteria.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('22a6fe5c-6ff8-56bb-bcf2-b33b4f24c230', 'neet_ug', 'Botany', 'Cell: The Unit of Life', 'Select the wrong statement.', '[{"id": "a", "text": "Bacterial cell wall is made up of peptidoglycan."}, {"id": "b", "text": "Pili and fimbriae are mainly involved in motility of bacterial cells."}, {"id": "c", "text": "Cyanobacteria lack flagellated cells."}, {"id": "d", "text": "Mycoplasma is a wall-less microorganism."}]'::jsonb, 'b', 'Pili and fimbriae help in attachment, not motility; bacterial motility is due to flagella.', 'Bacterial flagella provide motility. Pili are elongated tubular protein structures and fimbriae are small bristle-like fibres; both help bacteria attach to surfaces and host tissues and do not play a role in motility. The other statements are correct.', '{"a": "True; bacterial walls contain peptidoglycan (murein).", "c": "True; cyanobacteria have no flagellated stages.", "d": "True; Mycoplasma lacks a cell wall."}'::jsonb, 'Flagellum – motility; pili/fimbriae – attachment.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('7afd0f51-bf2e-5eb1-96fc-5c89018bf6d8', 'neet_ug', 'Botany', 'Cell: The Unit of Life', 'A cell organelle containing hydrolytic enzymes is', '[{"id": "a", "text": "lysosome"}, {"id": "b", "text": "microsome"}, {"id": "c", "text": "ribosome"}, {"id": "d", "text": "mesosome"}]'::jsonb, 'a', 'Lysosomes are membrane-bound vesicles rich in acid hydrolases (lipases, proteases, carbohydrases).', 'Lysosomes bud off from the Golgi apparatus and contain hydrolytic enzymes active at acidic pH that can digest carbohydrates, proteins, lipids and nucleic acids. Microsomes are ER fragments, ribosomes make proteins and mesosomes are infoldings of the bacterial membrane.', '{"b": "Microsomes are artefactual ER vesicles formed during cell fractionation.", "c": "Ribosomes are non-membranous sites of protein synthesis.", "d": "Mesosomes are membrane infoldings in bacteria aiding wall formation and respiration."}'::jsonb, 'Lysosomal hydrolases work optimally at acidic pH.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('ab9b0021-5992-5529-8a0c-6b19103b71ef', 'neet_ug', 'Botany', 'Cell Cycle and Cell Division', 'During cell growth, DNA synthesis takes place in', '[{"id": "a", "text": "S Phase"}, {"id": "b", "text": "G₁ phase"}, {"id": "c", "text": "G₂ phase"}, {"id": "d", "text": "M phase"}]'::jsonb, 'a', 'DNA replicates during the S (synthesis) phase of interphase.', 'Interphase consists of G₁, S and G₂. In S phase the DNA content doubles (2C → 4C) while the chromosome number stays the same. G₁ and G₂ are growth phases and M is division.', '{"b": "G₁ is active growth without DNA replication.", "c": "G₂ is preparation for mitosis; DNA is already replicated.", "d": "M phase is division, not DNA synthesis."}'::jsonb, 'In S phase DNA doubles from 2C to 4C, but the chromosome number does not change.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('619d6b00-80af-5ed3-8515-1e5468a6b567', 'neet_ug', 'Botany', 'Respiration in Plants', 'Which of the following biomolecules is common to respiration-mediated breakdown of fats, carbohydrates and proteins?', '[{"id": "a", "text": "Glucose-6-phosphate"}, {"id": "b", "text": "Fructose 1,6-bisphosphate"}, {"id": "c", "text": "Pyruvic acid"}, {"id": "d", "text": "Acetyl CoA"}]'::jsonb, 'd', 'Acetyl CoA is the common entry molecule into the Krebs cycle from carbohydrates, fats and proteins.', 'Carbohydrates give pyruvate, which forms acetyl CoA. Fatty acids undergo β-oxidation directly to acetyl CoA, and many amino acids are deaminated to acetyl CoA or Krebs-cycle intermediates. So acetyl CoA is the common intermediate, linking all three to the TCA cycle (the amphibolic pathway).', '{"a": "Glucose-6-phosphate is specific to carbohydrate breakdown.", "b": "Fructose 1,6-bisphosphate is a glycolytic intermediate only.", "c": "Fatty acids are not converted to pyruvic acid; they form acetyl CoA directly."}'::jsonb, 'Respiration is an amphibolic pathway; acetyl CoA is its central hub.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('2702eeff-8f1c-57fc-90be-40ae834dec63', 'neet_ug', 'Botany', 'Plant Growth and Development', 'You are given a tissue with its potential for differentiation in an artificial culture. Which of the following pairs of hormones would you add to the medium to secure shoots as well as roots?', '[{"id": "a", "text": "IAA and gibberellins"}, {"id": "b", "text": "Auxin and cytokinin"}, {"id": "c", "text": "Auxin and abscisic acid"}, {"id": "d", "text": "Gibberellin and abscisic acid"}]'::jsonb, 'b', 'The auxin:cytokinin ratio controls root versus shoot differentiation in tissue culture.', 'In callus culture a high auxin to cytokinin ratio favours root formation, while a high cytokinin to auxin ratio favours shoot formation. Supplying both hormones in suitable proportions gives both shoots and roots.', '{"a": "Gibberellins promote elongation, not organ differentiation in culture.", "c": "ABA is a growth inhibitor and does not induce shoots.", "d": "Neither hormone induces root and shoot organogenesis."}'::jsonb, 'High auxin → roots; high cytokinin → shoots (Skoog and Miller).', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('e1b59e6e-9a29-5dc3-8b59-461c951dbdc8', 'neet_ug', 'Botany', 'Photosynthesis in Higher Plants', 'The process which makes major difference between C₃ and C₄ plants is', '[{"id": "a", "text": "glycolysis"}, {"id": "b", "text": "Calvin cycle"}, {"id": "c", "text": "photorespiration"}, {"id": "d", "text": "respiration"}]'::jsonb, 'c', 'Photorespiration occurs in C₃ plants but is practically absent in C₄ plants.', 'In C₃ plants RuBisCO also binds O₂, causing photorespiration and loss of fixed carbon. C₄ plants concentrate CO₂ in bundle sheath cells, so RuBisCO acts as a carboxylase and photorespiration is negligible. Glycolysis, respiration and the Calvin cycle occur in both groups.', '{"a": "Glycolysis occurs in all plants.", "b": "Calvin cycle runs in both C₃ and C₄ plants (in bundle sheath of C₄).", "d": "Respiration is common to all plants."}'::jsonb, 'C₄ plants have Kranz anatomy and negligible photorespiration.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('432681f0-7098-5393-a5a9-c023e0d7caf6', 'neet_ug', 'Zoology', 'Evolution', 'Which one of the following generates new genetic combinations leading to variation?', '[{"id": "a", "text": "Vegetative reproduction"}, {"id": "b", "text": "Parthenogenesis"}, {"id": "c", "text": "Sexual reproduction"}, {"id": "d", "text": "Nucellar polyembryony"}]'::jsonb, 'c', 'Meiotic recombination and random fusion of gametes in sexual reproduction create new gene combinations.', 'Sexual reproduction involves meiosis (with crossing over and independent assortment) followed by fertilisation of gametes from two parents, producing new combinations of genes. Vegetative reproduction, parthenogenesis and nucellar polyembryony produce offspring genetically similar to the parent.', '{"a": "Vegetative propagation gives clones.", "b": "Parthenogenesis develops an embryo from an unfertilised egg; no recombination between parents.", "d": "Nucellar embryos are derived from maternal diploid tissue, so they are clones."}'::jsonb, 'Crossing over, independent assortment and fertilisation are the sources of variation in sexual reproduction.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('80eedd16-ab1a-5c9d-86ba-877e5268cd5c', 'neet_ug', 'Botany', 'Sexual Reproduction in Flowering Plants', 'Match Column-I with Column-II and select the correct option using the codes given below:
Column-I | Column-II
a. Pistils fused together | (i) Gametogenesis
b. Formation of gametes | (ii) Pistillate
c. Hyphae of higher ascomycetes | (iii) Syncarpous
d. Unisexual female flower | (iv) Dikaryotic', '[{"id": "a", "text": "a-(iv), b-(iii), c-(i), d-(ii)"}, {"id": "b", "text": "a-(ii), b-(i), c-(iv), d-(iii)"}, {"id": "c", "text": "a-(i), b-(ii), c-(iv), d-(iii)"}, {"id": "d", "text": "a-(iii), b-(i), c-(iv), d-(ii)"}]'::jsonb, 'd', 'Fused pistils = syncarpous; gamete formation = gametogenesis; ascomycete hyphae = dikaryotic; female flower = pistillate.', 'A gynoecium with fused carpels/pistils is syncarpous. Formation of gametes is gametogenesis. Higher ascomycetes and basidiomycetes form dikaryotic (n + n) hyphae before karyogamy. A unisexual flower bearing only pistils is pistillate. This matches a-(iii), b-(i), c-(iv), d-(ii).', '{"a": "Matches fused pistils with ''dikaryotic'' and gametes with ''syncarpous''.", "b": "Swaps pistillate and syncarpous.", "c": "Pairs fused pistils with gametogenesis."}'::jsonb, 'Dikaryophase (n + n) is characteristic of ascomycetes and basidiomycetes.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('874cbf9b-96ef-52e7-a9c1-90c9c571940b', 'neet_ug', 'Botany', 'Sexual Reproduction in Flowering Plants', 'In majority of angiosperms', '[{"id": "a", "text": "egg has a filiform apparatus"}, {"id": "b", "text": "there are numerous antipodal cells"}, {"id": "c", "text": "reduction division occurs in the megaspore mother cells"}, {"id": "d", "text": "a small central cell is present in the embryo sac"}]'::jsonb, 'c', 'The diploid megaspore mother cell undergoes meiosis to form four haploid megaspores.', 'In the ovule, the megaspore mother cell (2n) divides meiotically to give a linear tetrad of megaspores; one becomes functional (monosporic development). The filiform apparatus is in synergids, there are only three antipodals, and the central cell is the largest cell of the embryo sac.', '{"a": "Filiform apparatus is present on synergids, not the egg.", "b": "A typical 7-celled, 8-nucleate embryo sac has three antipodal cells.", "d": "The central cell is large, containing two polar nuclei."}'::jsonb, 'Typical embryo sac: 7 cells, 8 nuclei (egg apparatus 3, antipodals 3, central cell 1).', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('6d8beee8-9415-52ad-959a-cf523b5007f2', 'neet_ug', 'Botany', 'Sexual Reproduction in Flowering Plants', 'Pollination in water hyacinth and water lily is brought about by the agency of', '[{"id": "a", "text": "water"}, {"id": "b", "text": "insects or wind"}, {"id": "c", "text": "birds"}, {"id": "d", "text": "bats"}]'::jsonb, 'b', 'Their flowers project above the water surface and are pollinated by insects or wind.', 'Although water hyacinth and water lily are aquatic plants, their flowers emerge above the water level. Pollination is therefore by insects or wind, as in most land plants; true water pollination is seen in Vallisneria, Hydrilla and Zostera.', '{"a": "Hydrophily occurs in only a few genera (Vallisneria, Zostera), not these.", "c": "Bird pollination is not reported for these plants.", "d": "Bat pollination is not involved."}'::jsonb, 'Not all aquatic plants are water-pollinated; water hyacinth and water lily use insects or wind.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('7c8459c3-2042-59b2-b6fa-882fd4572b20', 'neet_ug', 'Botany', 'Sexual Reproduction in Flowering Plants', 'The ovule of an angiosperm is technically equivalent to', '[{"id": "a", "text": "megasporangium"}, {"id": "b", "text": "megasporophyll"}, {"id": "c", "text": "megaspore mother cell"}, {"id": "d", "text": "megaspore"}]'::jsonb, 'a', 'The ovule (nucellus with integuments) is the megasporangium.', 'Within the ovule the nucellus forms the megaspore mother cell, which produces megaspores; thus the ovule is the structure that bears megaspores, i.e. the megasporangium. The carpel (pistil) is the megasporophyll.', '{"b": "The carpel is the megasporophyll.", "c": "The MMC is a single cell inside the nucellus.", "d": "The megaspore is the product of meiosis that forms the embryo sac."}'::jsonb, 'Anther = microsporangia; ovule = megasporangium; carpel = megasporophyll.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('fe0a68b5-7d38-5223-a5e6-85b02f589e63', 'neet_ug', 'Botany', 'Molecular Basis of Inheritance', 'Taylor conducted the experiments to prove semiconservative mode of chromosome replication on', '[{"id": "a", "text": "Vinca rosea"}, {"id": "b", "text": "Vicia faba"}, {"id": "c", "text": "Drosophila melanogaster"}, {"id": "d", "text": "E. coli"}]'::jsonb, 'b', 'Taylor and colleagues used radioactive thymidine in Vicia faba (faba bean) root tips.', 'In 1958 Taylor and co-workers labelled Vicia faba root-tip chromosomes with radioactive thymidine and showed that chromosomes too replicate semiconservatively. Meselson and Stahl had shown semiconservative DNA replication in E. coli.', '{"a": "Vinca rosea is a medicinal plant, not used in this experiment.", "c": "Drosophila was used by Morgan for linkage studies.", "d": "E. coli was used by Meselson and Stahl for DNA, not chromosome replication."}'::jsonb, 'Meselson–Stahl: E. coli with ¹⁵N; Taylor: Vicia faba with ³H-thymidine.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('d3a28a72-d624-54f4-afaa-a3c4a6718b36', 'neet_ug', 'Botany', 'Principles of Inheritance and Variation', 'The mechanism that causes a gene to move from one linkage group to another is called', '[{"id": "a", "text": "Inversion"}, {"id": "b", "text": "Duplication"}, {"id": "c", "text": "Translocation"}, {"id": "d", "text": "Crossing over"}]'::jsonb, 'c', 'Translocation moves a chromosome segment to a non-homologous chromosome, i.e. a different linkage group.', 'Each linkage group corresponds to one chromosome pair. Translocation transfers a segment between non-homologous chromosomes, shifting genes to a new linkage group. Crossing over exchanges segments between homologues of the same linkage group, and inversion or duplication rearrange genes within a chromosome.', '{"a": "Inversion reverses gene order within the same chromosome.", "b": "Duplication repeats a segment on the same chromosome.", "d": "Crossing over is between homologous chromosomes of the same linkage group."}'::jsonb, 'Number of linkage groups = haploid chromosome number.', 'med', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('286e1c0b-7227-57d3-93a4-5ae1cc31c40d', 'neet_ug', 'Botany', 'Molecular Basis of Inheritance', 'The equivalent of a structural gene is', '[{"id": "a", "text": "Mutation"}, {"id": "b", "text": "Cistron"}, {"id": "c", "text": "Operon"}, {"id": "d", "text": "Recon"}]'::jsonb, 'b', 'A cistron is a DNA segment coding for one polypeptide, i.e. a structural gene.', 'A structural gene in a transcription unit codes for a polypeptide and is defined as a cistron. An operon is a cluster of structural genes with regulatory elements, a recon is the smallest unit of recombination and a muton the smallest unit of mutation.', '{"a": "Mutation is a change in DNA, not a gene unit.", "c": "An operon contains several structural genes plus promoter and operator.", "d": "Recon is the unit of recombination, not function."}'::jsonb, 'Monocistronic genes are typical of eukaryotes; polycistronic genes of bacteria.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('7b390166-654e-5473-8268-c3a52b4ede77', 'neet_ug', 'Botany', 'Principles of Inheritance and Variation', 'A true breeding plant is', '[{"id": "a", "text": "One that is able to breed on its own"}, {"id": "b", "text": "Produced due to cross pollination among unrelated plants"}, {"id": "c", "text": "Near homozygous and produces offspring of its own kind"}, {"id": "d", "text": "Always homozygous recessive in its genetic constitution"}]'::jsonb, 'c', 'True-breeding lines, from continuous self-pollination, are nearly homozygous and breed true for a trait.', 'Mendel used true-breeding lines that had undergone continuous self-pollination for several generations and showed stable trait inheritance. Such plants are (near) homozygous, dominant or recessive, and produce offspring like themselves.', '{"a": "Self-pollination ability alone does not make a plant true-breeding.", "b": "Cross pollination between unrelated plants increases heterozygosity.", "d": "True-breeding plants may be homozygous dominant too."}'::jsonb, 'True-breeding line = stable trait inheritance over generations by selfing.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('183a5401-ec27-590a-8280-f18c22f268ec', 'neet_ug', 'Botany', 'Molecular Basis of Inheritance', 'Which of the following rRNAs acts as structural RNA as well as ribozyme in bacteria?', '[{"id": "a", "text": "5S rRNA"}, {"id": "b", "text": "18S rRNA"}, {"id": "c", "text": "23S rRNA"}, {"id": "d", "text": "5.8S rRNA"}]'::jsonb, 'c', '23S rRNA of the bacterial 50S subunit is both structural and catalyses peptide bond formation (peptidyl transferase).', 'The bacterial ribosome (70S) has 23S and 5S rRNA in its 50S subunit and 16S rRNA in its 30S subunit. The 23S rRNA forms the peptidyl transferase centre, acting as a ribozyme for peptide bond formation, while also being a structural component. 18S and 5.8S are eukaryotic rRNAs.', '{"a": "5S rRNA is structural but not the catalytic ribozyme.", "b": "18S rRNA is found in eukaryotic 40S subunits.", "d": "5.8S rRNA occurs in eukaryotic 60S subunits."}'::jsonb, 'Peptidyl transferase activity of the bacterial ribosome resides in 23S rRNA.', 'med', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('604622b2-c61b-59d7-ae03-be289003a40c', 'neet_ug', 'Zoology', 'Biotechnology: Principles and Processes', 'Stirred tank bioreactors have been designed for', '[{"id": "a", "text": "Purification of product"}, {"id": "b", "text": "Addition of preservatives to the product"}, {"id": "c", "text": "Availability of oxygen throughout the process"}, {"id": "d", "text": "Ensuring anaerobic conditions in the culture vessel"}]'::jsonb, 'c', 'The stirrer and sparger ensure even mixing and oxygen availability throughout the bioreactor.', 'A stirred-tank bioreactor is a cylindrical vessel with a curved base and a stirrer that mixes contents uniformly. Sterile air bubbled through a sparger, together with stirring, makes oxygen available throughout the culture. Purification and preservative addition are downstream steps.', '{"a": "Purification is part of downstream processing.", "b": "Preservatives are added during downstream processing.", "d": "They are designed to supply oxygen, not maintain anaerobiosis."}'::jsonb, 'Bioreactor control: temperature, pH, foam, O₂ delivery, sampling ports.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('87067022-e872-54f6-b613-c223376fe471', 'neet_ug', 'Zoology', 'Biotechnology: Principles and Processes', 'A foreign DNA and plasmid cut by the same restriction endonuclease can be joined to form a recombinant plasmid using', '[{"id": "a", "text": "Eco R1"}, {"id": "b", "text": "Taq Polymerase"}, {"id": "c", "text": "Polymerase III"}, {"id": "d", "text": "ligase"}]'::jsonb, 'd', 'DNA ligase seals the sticky ends of vector and insert to form recombinant DNA.', 'Cutting both vector and foreign DNA with the same restriction enzyme leaves complementary sticky ends that base-pair. DNA ligase then forms phosphodiester bonds to seal the joint, producing the recombinant plasmid.', '{"a": "EcoRI cuts DNA; it does not join it.", "b": "Taq polymerase amplifies DNA in PCR.", "c": "DNA polymerase III replicates DNA; it does not join fragments into a vector."}'::jsonb, 'Restriction enzymes = molecular scissors; ligase = molecular glue.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('4b3afa27-9736-52c3-b785-3651a2b0ec90', 'neet_ug', 'Zoology', 'Biotechnology: Principles and Processes', 'Which of the following is not a component of downstream processing?', '[{"id": "a", "text": "Separation"}, {"id": "b", "text": "Purification"}, {"id": "c", "text": "Preservation"}, {"id": "d", "text": "Expression"}]'::jsonb, 'd', 'Gene expression happens during the culture (upstream); downstream processing covers separation, purification, formulation and preservation.', 'After biosynthesis in the bioreactor, the product undergoes downstream processing: separation, purification, formulation with preservatives, and quality testing. Expression of the gene product occurs earlier, inside the host cells.', '{"a": "Separation is the first downstream step.", "b": "Purification is a key downstream step.", "c": "Formulation with preservatives is part of downstream processing."}'::jsonb, 'Downstream processing = separation + purification + formulation + quality control.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('0112070c-d36c-5ca5-b521-760f9a1847b2', 'neet_ug', 'Zoology', 'Biotechnology: Principles and Processes', 'Which of the following restriction enzymes produce blunt ends?', '[{"id": "a", "text": "Sal I"}, {"id": "b", "text": "Eco RV"}, {"id": "c", "text": "Xho I"}, {"id": "d", "text": "Hind III"}]'::jsonb, 'b', 'EcoRV cuts both strands at the same position (GAT↓ATC), giving blunt ends.', 'Blunt ends arise when a restriction enzyme cuts both strands at the centre of its palindrome. EcoRV recognises GATATC and cuts between T and A on both strands. SalI, XhoI and HindIII make staggered cuts that leave sticky ends.', '{"a": "SalI (G↓TCGAC) gives sticky ends.", "c": "XhoI (C↓TCGAG) gives sticky ends.", "d": "HindIII (A↓AGCTT) gives sticky ends."}'::jsonb, 'Restriction enzyme naming: first letter genus, next two species, then strain and order of isolation.', 'med', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('ad20f8dd-7c66-5f57-8bc7-d56087c5206c', 'neet_ug', 'Zoology', 'Biotechnology and its Applications', 'Which kind of therapy was given in 1990 to a four year old girl with adenosine deaminase (ADA) deficiency?', '[{"id": "a", "text": "Gene therapy"}, {"id": "b", "text": "Chemotherapy"}, {"id": "c", "text": "Immunotherapy"}, {"id": "d", "text": "Radiation therapy"}]'::jsonb, 'a', 'The first clinical gene therapy (1990) introduced a functional ADA gene into the lymphocytes of a 4-year-old girl.', 'Lymphocytes from the patient were grown in culture, a functional ADA cDNA was introduced using a retroviral vector, and the cells were returned to the patient. This was the first gene therapy. Because lymphocytes are not immortal, periodic infusions were needed.', '{"b": "Chemotherapy uses drugs, mainly against cancer.", "c": "Immunotherapy modulates immune response; enzyme replacement is different from gene therapy here.", "d": "Radiation therapy is for tumours."}'::jsonb, 'A permanent cure for ADA deficiency would need the ADA gene introduced into early embryonic cells (bone-marrow stem cells).', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('e1e1f018-a5fd-5743-a550-76ec6cab46b3', 'neet_ug', 'Botany', 'Biodiversity and Conservation', 'How many hot spots of biodiversity in the world have been identified till date by Norman Myers?', '[{"id": "a", "text": "17"}, {"id": "b", "text": "25"}, {"id": "c", "text": "34"}, {"id": "d", "text": "43"}]'::jsonb, 'c', 'NCERT states that 34 biodiversity hotspots have been identified worldwide.', 'Norman Myers introduced the hotspot concept for regions with very high species richness, high endemism and severe habitat loss. Initially 25 hotspots were identified; the number was later raised to 34. Three of them (Western Ghats–Sri Lanka, Indo-Burma, Himalaya) cover India.', '{"a": "17 is the number of megadiverse countries, not hotspots.", "b": "25 was the earlier count before 9 more were added.", "d": "No such count has been designated."}'::jsonb, 'Hotspots cover <2% of land area yet hold a very large share of species.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('ac6993ce-4bd3-52ed-ac71-2ba83f8135bb', 'neet_ug', 'Botany', 'Ecosystem', 'The primary producers of deep-sea hydrothermal vent ecosystem are', '[{"id": "a", "text": "Green algae"}, {"id": "b", "text": "Chemosynthetic bacteria"}, {"id": "c", "text": "Blue green algae"}, {"id": "d", "text": "Coral reefs"}]'::jsonb, 'b', 'No sunlight reaches the deep sea, so chemosynthetic bacteria that oxidise H₂S form the producer base.', 'Deep-sea hydrothermal vents lack light, so photosynthesis is impossible. Bacteria oxidise reduced inorganic compounds such as H₂S released from the vents and use the energy to fix CO₂. These chemoautotrophs are the primary producers that support tube worms, clams and other fauna.', '{"a": "Green algae need sunlight and cannot live in the aphotic zone.", "c": "Cyanobacteria are photosynthetic and need light.", "d": "Coral reefs are shallow-water ecosystems dependent on photosynthetic zooxanthellae."}'::jsonb, 'Chemosynthetic bacteria oxidise inorganic substances (e.g. H₂S, NH₃) for energy.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('55f5e333-fb75-5180-83eb-b4319ae2076f', 'neet_ug', 'Botany', 'Organisms and Populations', 'Which of the following is corrent for r-selected species?', '[{"id": "a", "text": "Large number of progeny with small size"}, {"id": "b", "text": "Large number of progeny with large size"}, {"id": "c", "text": "Small number of progeny with small size"}, {"id": "d", "text": "Small number of progeny with large size"}]'::jsonb, 'a', 'r-strategists produce many small offspring with little parental care.', 'r-selected species favour a high intrinsic growth rate: they reproduce early and produce a large number of small offspring (e.g. oysters, many insects). K-selected species produce few, large offspring with extensive parental care (e.g. mammals, birds).', '{"b": "Many large offspring is energetically impossible; not a life-history strategy.", "c": "Few small offspring would not maximise r.", "d": "Few large offspring describes K-selected species."}'::jsonb, 'Pacific salmon and bamboo breed once; oysters and pelagic fishes produce many small eggs.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('36bd4293-a247-5502-9904-0726ab66e187', 'neet_ug', 'Botany', 'Organisms and Populations', 'If ''+'' sign is assigned to beneficial interactions, ''–'' sign to detrimental and ''0'' sign to neutral interactions, then the population interaction represented by ''+'' ''–'' refers to', '[{"id": "a", "text": "Mutualism"}, {"id": "b", "text": "Amensalism"}, {"id": "c", "text": "Commensalism"}, {"id": "d", "text": "Parasitism"}]'::jsonb, 'd', 'In parasitism one species benefits (+) and the host is harmed (–).', 'Interactions are coded by their effect on each species: mutualism (+,+), competition (–,–), predation and parasitism (+,–), commensalism (+,0) and amensalism (–,0). Among the options only parasitism is (+,–).', '{"a": "Mutualism is (+,+).", "b": "Amensalism is (–,0).", "c": "Commensalism is (+,0)."}'::jsonb, 'Predation and parasitism are both (+,–) interactions.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('318d7c3e-de12-511f-9ae7-7ad665f79f0c', 'neet_ug', 'Botany', 'Biodiversity and Conservation', 'Which of the following is correctly matched?', '[{"id": "a", "text": "Aerenchyma – Opuntia"}, {"id": "b", "text": "Age pyramid – Biome"}, {"id": "c", "text": "Parthenium hysterophorus – Threat to biodiversity"}, {"id": "d", "text": "Stratification – population"}]'::jsonb, 'c', 'Parthenium (carrot grass) is an invasive alien weed that threatens native biodiversity.', 'Alien species invasions are one of the ''evil quartet'' causes of biodiversity loss, and Parthenium, Lantana and Eichhornia are the classic Indian examples. Aerenchyma is typical of hydrophytes, not of the xerophyte Opuntia. Age pyramids describe populations and stratification describes communities.', '{"a": "Opuntia is a xerophyte; aerenchyma occurs in aquatic plants like Hydrilla.", "b": "Age pyramids are a population attribute, not a biome attribute.", "d": "Vertical stratification is a feature of communities/ecosystems, not populations."}'::jsonb, 'Evil quartet: habitat loss, over-exploitation, alien species invasion and co-extinctions.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('c166258b-6768-51f2-aa92-ba7674c4fa05', 'neet_ug', 'Botany', 'Biodiversity and Conservation', 'Red list contains data or information on', '[{"id": "a", "text": "all economically important plants"}, {"id": "b", "text": "Plants whose products are in international trade"}, {"id": "c", "text": "threatened species"}, {"id": "d", "text": "marine vertebrates only"}]'::jsonb, 'c', 'The IUCN Red List documents threatened species.', 'The IUCN Red List (Red Data Book) catalogues species assessed for extinction risk, such as critically endangered, endangered and vulnerable taxa. It is not restricted to economic plants, traded plants or marine animals.', '{"a": "Economic importance is not the criterion for listing.", "b": "International trade in species is regulated by CITES, not the Red List.", "d": "It covers all groups of organisms, not only marine vertebrates."}'::jsonb, 'IUCN Red List (2004) recorded 784 extinctions in the last 500 years.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('6d64f7c5-f323-5988-af8e-f3332f0ee297', 'neet_ug', 'Zoology', 'Human Health and Disease', 'Which of the following sets of diseases is caused by bacteria?', '[{"id": "a", "text": "Cholera and tetanus"}, {"id": "b", "text": "Typhoid and smallpox"}, {"id": "c", "text": "Tetanus and mumps"}, {"id": "d", "text": "Herpes and influenza"}]'::jsonb, 'a', 'Cholera (Vibrio cholerae) and tetanus (Clostridium tetani) are both bacterial.', 'Cholera is caused by Vibrio cholerae and tetanus by Clostridium tetani, so both are bacterial. Every other option pairs a bacterial or viral disease with at least one viral disease.', '{"b": "Smallpox is viral (Variola virus).", "c": "Mumps is viral.", "d": "Herpes and influenza are both viral."}'::jsonb, 'Typhoid is caused by Salmonella typhi and is confirmed by the Widal test.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('5a0ffc18-d03c-58aa-b497-b0f1e42101fc', 'neet_ug', 'Zoology', 'Animal Kingdom', 'Match Column-I with Column-II for housefly classification and select the correct option using the codes given below:
Column I | Column II
a. Family | (i) Diptera
b. Order | (ii) Arthropoda
c. Class | (iii) Muscidae
d. Phylum | (iv) Insecta', '[{"id": "a", "text": "a-(iii), b-(i), c-(iv), d-(ii)"}, {"id": "b", "text": "a-(iii), b-(ii), c-(iv), d-(i)"}, {"id": "c", "text": "a-(iv), b-(iii), c-(ii), d-(i)"}, {"id": "d", "text": "a-(iv), b-(ii), c-(i), d-(iii)"}]'::jsonb, 'a', 'Musca domestica: Family Muscidae, Order Diptera, Class Insecta, Phylum Arthropoda.', 'The housefly belongs to family Muscidae, order Diptera (two-winged flies), class Insecta and phylum Arthropoda. That gives a-(iii), b-(i), c-(iv), d-(ii).', '{"b": "Arthropoda is a phylum, not an order.", "c": "Insecta is a class, not a family.", "d": "Muscidae is a family, not a phylum."}'::jsonb, 'Housefly taxonomy: Muscidae → Diptera → Insecta → Arthropoda (NCERT Table 1.1).', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('a189a850-42ff-568e-84b4-4bec63f7756d', 'neet_ug', 'Zoology', 'Animal Kingdom', 'Choose the correct statement', '[{"id": "a", "text": "All mammals are viviparous"}, {"id": "b", "text": "All cyclostomes do not possess jaws and paired fins"}, {"id": "c", "text": "All reptiles have a three chambered heart"}, {"id": "d", "text": "All Pisces have gills covered by an operculum"}]'::jsonb, 'b', 'Cyclostomes are jawless and lack paired fins.', 'Cyclostomes such as lamprey and hagfish are agnathans with a sucking circular mouth, no jaws and no paired fins. Monotremes like the platypus lay eggs, crocodiles have a four-chambered heart, and cartilaginous fishes have gill slits without an operculum.', '{"a": "Ornithorhynchus (platypus) is oviparous.", "c": "Crocodiles have a four-chambered heart.", "d": "Chondrichthyes have uncovered gill slits."}'::jsonb, 'Cyclostomes are marine but migrate to fresh water to spawn and die soon after.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('7a298903-0287-51c9-9a2c-2ccb367d2166', 'neet_ug', 'Botany', 'The Living World', 'Study the four statements (A-D) given below and select the two correct ones out of them:
A. Definition of biological species was given by Ernst Mayr
B. Photoperiod does not affect reproduction in plants
C. Binomial nomenclature system was given by R. H. Whittaker
D. In unicellular organisms, reproduction is synonymous with growth
The two correct statements are', '[{"id": "a", "text": "B and C"}, {"id": "b", "text": "C and D"}, {"id": "c", "text": "A and D"}, {"id": "d", "text": "A and B"}]'::jsonb, 'c', 'Mayr defined the biological species, and in unicellular organisms growth and reproduction coincide.', 'Ernst Mayr gave the biological species concept, so A is true. In unicellular organisms cell division increases both cell number and the population, so D is true. Photoperiod does control flowering (B is false), and binomial nomenclature was given by Linnaeus, not Whittaker (C is false).', '{"a": "B and C are both false.", "b": "C is false: Linnaeus gave binomial nomenclature.", "d": "B is false: photoperiod regulates flowering."}'::jsonb, 'Whittaker proposed the five-kingdom classification (1969); Linnaeus proposed binomial nomenclature.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('546e1b43-c83f-590f-aa09-ea779aa5bc73', 'neet_ug', 'Zoology', 'Structural Organisation in Animals', 'In male cockroaches, sperms are stored in which part of the reproductive system?', '[{"id": "a", "text": "Seminal vesicles"}, {"id": "b", "text": "Mushroom glands"}, {"id": "c", "text": "Testes"}, {"id": "d", "text": "Vas deferens"}]'::jsonb, 'a', 'Sperms are stored in seminal vesicles and glued into spermatophores.', 'In male Periplaneta, sperms produced in the testes pass through the vasa deferentia and are stored in the seminal vesicles. They are then packed into spermatophores that are discharged during copulation.', '{"b": "Mushroom-shaped glands are accessory glands, not storage sites.", "c": "Testes produce sperms but do not store them.", "d": "Vasa deferentia only conduct sperms."}'::jsonb, 'Cockroach testes lie in abdominal segments 4–6; the phallic gland is also an accessory gland.', 'med', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('3de08798-804f-545c-803a-a7bb3343cdca', 'neet_ug', 'Zoology', 'Structural Organisation in Animals', 'Smooth muscles are', '[{"id": "a", "text": "Involuntary, fusiform, non-striated"}, {"id": "b", "text": "Voluntary, multinucleate, cylindrical"}, {"id": "c", "text": "Involuntary, cylindrical, striated"}, {"id": "d", "text": "Voluntary, spindle shaped, uninucleate"}]'::jsonb, 'a', 'Smooth muscle fibres are involuntary, spindle-shaped (fusiform) and unstriated.', 'Smooth muscle fibres taper at both ends, have no striations and are not under voluntary control. They are found in the walls of the gut, blood vessels and other visceral organs.', '{"b": "This describes skeletal muscle.", "c": "Smooth muscle lacks striations and is not cylindrical.", "d": "Smooth muscle is involuntary."}'::jsonb, 'Cardiac muscle is striated, involuntary and branched, with intercalated discs.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('4ef304e0-9599-5c93-8927-db70c88ad513', 'neet_ug', 'Botany', 'Respiration in Plants', 'Oxidative phosphorylation is', '[{"id": "a", "text": "Formation of ATP by transfer of phosphate group from a substrate to ADP"}, {"id": "b", "text": "Oxidation of phosphate group in ATP"}, {"id": "c", "text": "Addition of phosphate group to ATP"}, {"id": "d", "text": "Formation of ATP by energy released from electrons removed during substrate oxidation"}]'::jsonb, 'd', 'Oxidative phosphorylation makes ATP using energy from electrons passed down the ETS.', 'Electrons removed from substrates as NADH and FADH₂ pass through the electron transport system. The energy released pumps protons, and the resulting proton gradient drives ATP synthase to make ATP from ADP and Pi.', '{"a": "This is substrate-level phosphorylation.", "b": "Phosphate is not oxidised.", "c": "Phosphate is added to ADP, not ATP."}'::jsonb, 'Oxygen is the terminal electron acceptor in the ETS, and its reduction forms water.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('896b53dd-406d-5d0d-b183-9a537a338e04', 'neet_ug', 'Botany', 'Biomolecules', 'Which of the following is the least likely to be involved in stabilizing the three dimensional folding of most proteins?', '[{"id": "a", "text": "Hydrogen bonds"}, {"id": "b", "text": "Electrostatic interaction"}, {"id": "c", "text": "Hydrophobic interaction"}, {"id": "d", "text": "Ester bonds"}]'::jsonb, 'd', 'Ester bonds are not involved in protein folding.', 'The tertiary structure of proteins is stabilised by hydrogen bonds, ionic (electrostatic) interactions, hydrophobic interactions and disulphide bridges. Ester bonds link fatty acids to glycerol in lipids and are not a feature of polypeptide folding.', '{"a": "Hydrogen bonds stabilise helices, sheets and tertiary folds.", "b": "Ionic interactions between charged side chains help hold the fold.", "c": "Hydrophobic side chains cluster in the core to drive folding."}'::jsonb, 'Peptide bonds join amino acids, glycosidic bonds join sugars, and ester bonds occur in lipids.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('d2b9a37e-4f53-598b-8035-e953a4ad517a', 'neet_ug', 'Botany', 'Biomolecules', 'Which of the following describes the given graph correctly?', '[{"id": "a", "text": "Endothermic reaction with energy A in presence of enzyme and B in absence of enzyme"}, {"id": "b", "text": "Exothermic reaction with energy A in presence of enzyme and B in absence of enzyme"}, {"id": "c", "text": "Endothermic reaction with energy A in absence of enzyme and B in presence of enzyme"}, {"id": "d", "text": "Exothermic reaction with energy A in absence of enzyme and B in presence of enzyme"}]'::jsonb, 'b', 'Product lies below substrate (exothermic), and the enzyme lowers the activation energy (A < B).', 'The product''s potential energy is lower than the substrate''s, so energy is released and the reaction is exothermic. Enzymes lower the activation energy barrier, so the smaller hump A is with the enzyme and the taller hump B is without it.', '{"a": "The product is lower in energy, so the reaction is not endothermic.", "c": "Wrong on both counts: the reaction is exothermic and the enzyme gives the lower barrier.", "d": "The enzyme-catalysed path has the lower barrier A, not B."}'::jsonb, 'Enzymes lower activation energy but do not change the ΔG of the reaction.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', '/pyq/ug/2016/144.webp'),
('440d579d-3efe-5418-8441-f85271fc4288', 'neet_ug', 'Botany', 'Cell Cycle and Cell Division', 'When cell has stalled DNA replication fork, which checkpoint should be predominantly activated?', '[{"id": "a", "text": "G₁/S"}, {"id": "b", "text": "G₂/M"}, {"id": "c", "text": "M"}, {"id": "d", "text": "Both G₂/M and M"}]'::jsonb, 'b', 'Incomplete or stalled replication arrests the cell at the G₂/M checkpoint.', 'The G₂/M checkpoint checks that DNA replication is complete and the DNA is undamaged before the cell enters mitosis. A stalled replication fork leaves DNA unreplicated, so this checkpoint blocks mitotic entry. The G₁/S checkpoint acts before replication begins, and the M (spindle) checkpoint monitors kinetochore attachment.', '{"a": "G₁/S acts before replication starts, so it cannot sense a stalled fork.", "c": "The M checkpoint monitors spindle attachment, not replication.", "d": "The M checkpoint has no role in sensing replication."}'::jsonb, 'DNA replication occurs in the S phase, while centriole duplication in animal cells also occurs in S phase.', 'hard', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('989b0f88-00af-5c9b-a2cc-071aba7d77ec', 'neet_ug', 'Botany', 'Cell Cycle and Cell Division', 'Match the stages of meiosis in column I to their characteristic feature in column II and select the correct option using the codes given below:
Column I | Column II
a. Pachytene | i. Pairing of homologous chromosomes
b. Metaphase I | ii. Termination of chiasmata
c. Diakinesis | iii. Crossing over takes place
d. Zygotene | iv. Chromosomes align at equatorial plate', '[{"id": "a", "text": "a-(iii), b-(iv), c-(ii), d-(i)"}, {"id": "b", "text": "a-(i), b-(iv), c-(ii), d-(iii)"}, {"id": "c", "text": "a-(ii), b-(iv), c-(iii), d-(i)"}, {"id": "d", "text": "a-(iv), b-(iii), c-(ii), d-(i)"}]'::jsonb, 'a', 'Zygotene: synapsis. Pachytene: crossing over. Diakinesis: terminalisation of chiasmata. Metaphase I: alignment at the equator.', 'Homologous chromosomes pair (synapsis) in zygotene, and crossing over occurs in pachytene. Chiasmata terminalise in diakinesis, and bivalents align at the equatorial plate in metaphase I. That gives a-(iii), b-(iv), c-(ii), d-(i).', '{"b": "Pachytene is not pairing, and zygotene is not crossing over.", "c": "Pachytene is crossing over, not terminalisation.", "d": "Metaphase I is alignment, not crossing over."}'::jsonb, 'Recombination nodules appear in pachytene, and chiasmata become visible in diplotene.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('c3eb69d7-b895-5f18-bee3-a6a7c0df74f9', 'neet_ug', 'Zoology', 'Chemical Coordination and Integration', 'Which hormones do stimulate the production of pancreatic juice and bicarbonate?', '[{"id": "a", "text": "Angiotensin and epinephrine"}, {"id": "b", "text": "Gastrin and insulin"}, {"id": "c", "text": "Cholecystokinin and secretin"}, {"id": "d", "text": "Insulin and Glucagon"}]'::jsonb, 'c', 'Secretin stimulates the release of bicarbonate-rich juice and CCK stimulates pancreatic enzyme secretion.', 'The GI hormones secretin and cholecystokinin (CCK) act on the exocrine pancreas. Secretin stimulates the secretion of water and bicarbonate, and CCK stimulates the secretion of pancreatic enzymes and bile.', '{"a": "These regulate blood pressure and the stress response.", "b": "Gastrin acts on gastric glands, and insulin controls blood glucose.", "d": "Both are pancreatic islet hormones that regulate glucose."}'::jsonb, 'The four major GI hormones are gastrin, secretin, CCK and GIP.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('d11e291f-2f6f-5877-834b-d146d8e273cb', 'neet_ug', 'Zoology', 'Breathing and Exchange of Gases', 'The partial pressure of oxygen in the alveoli of the lungs is', '[{"id": "a", "text": "equal to that in the blood"}, {"id": "b", "text": "more than that in the blood"}, {"id": "c", "text": "less than that in the blood"}, {"id": "d", "text": "less than that of the carbon dioxide"}]'::jsonb, 'b', 'Alveolar pO₂ (104 mm Hg) is higher than in deoxygenated blood (40 mm Hg), so O₂ diffuses into the blood.', 'The pO₂ is about 104 mm Hg in the alveoli and about 40 mm Hg in deoxygenated blood arriving at the lungs. This gradient drives O₂ diffusion from the alveoli into the blood. Alveolar pCO₂ (40 mm Hg) is lower than alveolar pO₂.', '{"a": "Equal pressures would stop net diffusion.", "c": "O₂ would then diffuse out of the blood.", "d": "Alveolar pCO₂ is 40 mm Hg, far below pO₂ of 104 mm Hg."}'::jsonb, 'pO₂ in mm Hg: atmosphere 159, alveoli 104, deoxygenated blood 40, oxygenated blood 95, tissues 40.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('4ee89d16-1d33-5f6f-90fb-089898eef67a', 'neet_ug', 'Zoology', 'Neural Control and Coordination', 'Choose the correct statement.', '[{"id": "a", "text": "Nociceptors respond to changes in pressure"}, {"id": "b", "text": "Meissner''s corpuscles are thermoreceptors"}, {"id": "c", "text": "Photoreceptors in the human eye are depolarized during darkness and become hyperpolarized in response to the light stimulus"}, {"id": "d", "text": "Receptors do not produce graded potentials"}]'::jsonb, 'c', 'Rods and cones are depolarised in the dark and hyperpolarise when light falls on them.', 'In darkness, open cGMP-gated Na⁺ channels keep photoreceptors depolarised. Light activates rhodopsin, which closes these channels and hyperpolarises the cell. Nociceptors sense pain, Meissner''s corpuscles sense touch, and receptors generate graded receptor potentials.', '{"a": "Nociceptors detect painful stimuli, not pressure.", "b": "Meissner''s corpuscles are touch receptors.", "d": "Receptor (generator) potentials are graded."}'::jsonb, 'Light causes dissociation of retinal from opsin, which generates the visual impulse.', 'med', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('989b16cd-6b1a-583d-902e-3cc0e51fd262', 'neet_ug', 'Zoology', 'Chemical Coordination and Integration', 'Grave''s disease is caused due to', '[{"id": "a", "text": "hyposecretion of thyroid gland"}, {"id": "b", "text": "hypersecretion of thyroid gland"}, {"id": "c", "text": "hyposecretion of adrenal gland"}, {"id": "d", "text": "hypersecretion of adrenal gland"}]'::jsonb, 'b', 'Graves'' disease (exophthalmic goitre) is a form of hyperthyroidism.', 'Graves'' disease is an autoimmune hyperthyroidism in which excess thyroid hormone is secreted. It causes an enlarged thyroid, protruding eyeballs, a raised BMR and weight loss.', '{"a": "Hypothyroidism causes cretinism or myxoedema.", "c": "Adrenal cortex hyposecretion causes Addison''s disease.", "d": "Adrenal cortex hypersecretion causes Cushing''s syndrome."}'::jsonb, 'Exophthalmic goitre is a form of hyperthyroidism marked by protruding eyeballs.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('fbbb59d0-7c2e-5e51-bcd4-6459ac10f887', 'neet_ug', 'Zoology', 'Locomotion and Movement', 'Name the ion responsible for unmasking of active sites for myosin for cross-bridge activity during muscle contraction.', '[{"id": "a", "text": "Calcium"}, {"id": "b", "text": "Magnesium"}, {"id": "c", "text": "Sodium"}, {"id": "d", "text": "Potassium"}]'::jsonb, 'a', 'Ca²⁺ binds troponin and unmasks myosin-binding sites on actin.', 'A neural signal releases Ca²⁺ from the sarcoplasmic reticulum. Ca²⁺ binds troponin C, which shifts tropomyosin and exposes the active sites on F-actin so that myosin heads can form cross-bridges.', '{"b": "Mg²⁺ assists ATP binding but does not unmask actin sites.", "c": "Na⁺ mainly depolarises the sarcolemma.", "d": "K⁺ is involved in repolarisation."}'::jsonb, 'The sarcoplasmic reticulum is the Ca²⁺ store of a muscle fibre.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('0ca6e43a-a093-5db7-a1b4-55a04afcd885', 'neet_ug', 'Zoology', 'Body Fluids and Circulation', 'Name the blood cells, whose reduction in number can cause clotting disorder, leading to excessive loss of blood from the body.', '[{"id": "a", "text": "Erythrocytes"}, {"id": "b", "text": "Leucocytes"}, {"id": "c", "text": "Neutrophils"}, {"id": "d", "text": "Thrombocytes"}]'::jsonb, 'd', 'Platelets (thrombocytes) are needed for clotting, so a low count causes excessive bleeding.', 'Platelets are fragments of megakaryocytes that release factors to start the coagulation cascade. A reduced platelet count therefore impairs clotting and leads to excessive blood loss.', '{"a": "RBCs carry O₂; a low count causes anaemia.", "b": "WBCs provide immunity, not clotting.", "c": "Neutrophils are phagocytes."}'::jsonb, 'The normal platelet count is 1.5–3.5 lakh per mm³ of blood.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('eadc0534-376e-55ba-a3e8-0352a81813cd', 'neet_ug', 'Zoology', 'Chemical Coordination and Integration', 'Name a peptide hormone which acts mainly on hepatocytes, adipocytes and enhances cellular glucose uptake and utilization.', '[{"id": "a", "text": "Insulin"}, {"id": "b", "text": "Glucagon"}, {"id": "c", "text": "Secretin"}, {"id": "d", "text": "Gastrin"}]'::jsonb, 'a', 'Insulin promotes glucose uptake by liver and fat cells.', 'Insulin, a peptide hormone from β-cells, acts mainly on hepatocytes and adipocytes. It increases glucose uptake and utilisation and stimulates glycogenesis, which lowers blood glucose.', '{"b": "Glucagon raises blood glucose through glycogenolysis.", "c": "Secretin acts on the exocrine pancreas.", "d": "Gastrin stimulates gastric secretion."}'::jsonb, 'Prolonged hyperglycaemia leads to diabetes mellitus.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('7a2bae9c-a4d1-5d1b-9623-43884a16fea9', 'neet_ug', 'Zoology', 'Locomotion and Movement', 'Osteoporosis, age-related disease of skeletal system, may occur due to', '[{"id": "a", "text": "immune disorder affecting neuro-muscular junction leading to fatigue"}, {"id": "b", "text": "high concentration of Ca²⁺ and Na⁺"}, {"id": "c", "text": "decreased level of estrogen"}, {"id": "d", "text": "accumulation of uric acid leading to inflammation of joints"}]'::jsonb, 'c', 'Low oestrogen reduces bone mass and makes bones brittle.', 'Osteoporosis is an age-related reduction in bone mass that increases the chance of fractures. Decreased oestrogen, as after menopause, is a common cause.', '{"a": "This describes myasthenia gravis.", "b": "High Ca²⁺ does not cause bone loss.", "d": "This describes gout."}'::jsonb, 'Gout is caused by uric acid crystals in joints, and myasthenia gravis is an autoimmune disorder of the neuromuscular junction.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('f2d0fce3-6816-5e46-924f-33f9dd76fa65', 'neet_ug', 'Zoology', 'Body Fluids and Circulation', 'Serum differs from blood in', '[{"id": "a", "text": "lacking globulins"}, {"id": "b", "text": "lacking albumins"}, {"id": "c", "text": "lacking clotting factors"}, {"id": "d", "text": "lacking antibodies"}]'::jsonb, 'c', 'Serum is plasma without clotting factors (and of course without cells).', 'When blood clots, fibrinogen and other clotting factors are used up in the clot. The fluid left behind is serum, which still contains albumins, globulins and antibodies.', '{"a": "Serum retains globulins.", "b": "Serum retains albumins.", "d": "Antibodies (γ-globulins) remain in serum."}'::jsonb, 'Plasma proteins: fibrinogen (clotting), globulins (defence), albumins (osmotic balance).', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('70ae06da-b967-5861-9be1-3e275b36db67', 'neet_ug', 'Zoology', 'Breathing and Exchange of Gases', 'Lungs do not collapse between breaths and some air always remains in the lungs which can never be expelled because', '[{"id": "a", "text": "there is a negative pressure in the lungs"}, {"id": "b", "text": "there is negative intrapleural pressure pulling at the lung walls"}, {"id": "c", "text": "there is a positive intrapleural pressure"}, {"id": "d", "text": "pressure in the lungs is higher than the atmospheric pressure"}]'::jsonb, 'b', 'Sub-atmospheric intrapleural pressure keeps the lungs stretched open.', 'The pressure in the pleural cavity is always below the intrapulmonary pressure. This negative intrapleural pressure pulls on the lung walls and keeps the alveoli from collapsing, so a residual volume of air always remains.', '{"a": "Intrapulmonary pressure equals atmospheric pressure between breaths.", "c": "Positive intrapleural pressure would collapse the lungs.", "d": "Pressure in the lungs exceeds atmospheric pressure only during expiration."}'::jsonb, 'Residual volume is about 1100–1200 mL and cannot be exhaled even forcibly.', 'med', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('a0b6b456-760e-56c7-b142-2a9788984ae3', 'neet_ug', 'Zoology', 'Chemical Coordination and Integration', 'The posterior pituitary gland is not a ''true'' endocrine gland because', '[{"id": "a", "text": "it is provided with a duct"}, {"id": "b", "text": "it only stores and release hormones"}, {"id": "c", "text": "it is under the regulation of hypothalamus"}, {"id": "d", "text": "it secretes enzymes"}]'::jsonb, 'b', 'The neurohypophysis stores and releases oxytocin and vasopressin made by the hypothalamus.', 'Oxytocin and ADH are synthesised by hypothalamic neurosecretory cells and carried down axons to the posterior pituitary. The posterior pituitary only stores and releases these hormones and makes none of its own.', '{"a": "It is ductless like all endocrine glands.", "c": "Hypothalamic regulation also applies to the anterior pituitary, which is a true gland.", "d": "It does not secrete enzymes."}'::jsonb, 'The neurohypophysis (pars nervosa) releases oxytocin and vasopressin.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('bcf35568-92ee-51aa-97da-bae00f5abca4', 'neet_ug', 'Zoology', 'Excretory Products and their Elimination', 'The part of nephron involved in active reabsorption of sodium is', '[{"id": "a", "text": "distal convoluted tubule"}, {"id": "b", "text": "proximal convoluted tubule"}, {"id": "c", "text": "Bowman''s capsule"}, {"id": "d", "text": "descending limb of Henle''s loop"}]'::jsonb, 'b', 'The PCT actively reabsorbs most of the filtered Na⁺.', 'The PCT reabsorbs nearly all nutrients and 70–80% of electrolytes and water, and Na⁺ is actively transported there. The DCT performs only conditional Na⁺ reabsorption. Bowman''s capsule filters, and the descending limb is permeable mainly to water.', '{"a": "The DCT reabsorbs Na⁺ conditionally (under aldosterone), but the major active site is the PCT.", "c": "Bowman''s capsule is the site of filtration.", "d": "The descending limb is permeable to water but almost impermeable to electrolytes."}'::jsonb, 'The ascending limb of Henle''s loop is impermeable to water.', 'med', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('14bf30a1-eccc-53eb-8692-f82e1ae564a1', 'neet_ug', 'Zoology', 'Reproductive Health', 'Which of the following is hormone-releasing IUD?', '[{"id": "a", "text": "LNG-20"}, {"id": "b", "text": "Multiload 375"}, {"id": "c", "text": "Lippes loop"}, {"id": "d", "text": "Cu7"}]'::jsonb, 'a', 'LNG-20 releases the progestogen levonorgestrel.', 'IUDs are of three kinds: non-medicated (Lippes loop), copper-releasing (CuT, Cu7, Multiload 375) and hormone-releasing (Progestasert, LNG-20). LNG-20 makes the uterus unsuitable for implantation and the cervix hostile to sperm.', '{"b": "Multiload 375 is a copper-releasing IUD.", "c": "Lippes loop is non-medicated.", "d": "Cu7 is a copper-releasing IUD."}'::jsonb, 'Copper ions suppress sperm motility and fertilising capacity.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('055a97b5-09c5-53d4-80ef-03388c6c4f50', 'neet_ug', 'Zoology', 'Reproductive Health', 'Which of following incorrect regarding vasectomy?', '[{"id": "a", "text": "No sperm occurs in seminal fluid"}, {"id": "b", "text": "No sperms occurs in epididymis"}, {"id": "c", "text": "Vasa deferentia is cut and tied"}, {"id": "d", "text": "Irreversible sterility"}]'::jsonb, 'b', 'Vasectomy blocks the vas deferens beyond the epididymis, so sperms are still present in the epididymis.', 'In vasectomy a small part of the vas deferens is cut and tied through a small incision in the scrotum. Sperms are still produced in the testes and stored in the epididymis, but they cannot reach the semen. The statement that no sperms occur in the epididymis is therefore incorrect.', '{"a": "This is correct: sperms cannot reach the seminal fluid.", "c": "This is the procedure itself (the paper misprints ''tied'' as ''died'').", "d": "This is correct: it is a terminal method with very poor reversibility."}'::jsonb, 'Tubectomy is the female counterpart, in which a part of the fallopian tube is removed or tied.', 'med', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('d2407525-f0d5-510f-9879-19e484f58e0a', 'neet_ug', 'Zoology', 'Reproductive Health', 'Embryo with more than 16 blastomeres formed due to in vitro fertilization is transferred into', '[{"id": "a", "text": "uterus"}, {"id": "b", "text": "fallopian tube"}, {"id": "c", "text": "fimbriae"}, {"id": "d", "text": "cervix"}]'::jsonb, 'a', 'Embryos with more than 8 blastomeres are transferred into the uterus (IUT).', 'In ART, a zygote or an early embryo of up to 8 blastomeres is transferred into the fallopian tube (ZIFT). An embryo with more than 8 blastomeres, as here with more than 16, is transferred into the uterus (IUT).', '{"b": "The fallopian tube receives embryos of up to 8 blastomeres (ZIFT).", "c": "Fimbriae are not a site of embryo transfer.", "d": "The cervix is not a site of embryo transfer."}'::jsonb, 'GIFT transfers an ovum, and ICSI injects a sperm directly into an ovum.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('3b5d5af6-cca1-52d4-a310-8816a937e230', 'neet_ug', 'Zoology', 'Human Reproduction', 'Which of the following depicts the correct pathway of transport of sperms?', '[{"id": "a", "text": "Rete testis → Efferent ductules → Epididymis → Vas deferens"}, {"id": "b", "text": "Rete testis → Epididymis → Efferent ductules → Vas deferens"}, {"id": "c", "text": "Rete testis → Vas deferens → Efferent ductules → Epididymis"}, {"id": "d", "text": "Efferent ductules → Rete testis → Vas deferens → Epididymis"}]'::jsonb, 'a', 'Seminiferous tubules → rete testis → vasa efferentia → epididymis → vas deferens.', 'Sperms leave the seminiferous tubules through the rete testis and pass into the vasa efferentia. From there they enter the epididymis and then the vas deferens, which leads to the ejaculatory duct.', '{"b": "The efferent ductules come before the epididymis.", "c": "The vas deferens is distal to the epididymis.", "d": "The rete testis precedes the efferent ductules."}'::jsonb, 'The vas deferens joins the duct of the seminal vesicle to form the ejaculatory duct.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('82e205bf-a8d8-5d5e-a8d0-6f5510767ed6', 'neet_ug', 'Zoology', 'Human Reproduction', 'Match Column-I with Column-II and select the correct option using the codes given below:
Column I | Column II
a. Mons pubis | (i) Embryo formation
b. Antrum | (ii) Sperm
c. Trophectoderm | (iii) Female external genitalia
d. Nebenkern | (iv) Graafian follicle', '[{"id": "a", "text": "a-(iii), b-(iv), c-(ii), d-(i)"}, {"id": "b", "text": "a-(iii), b-(iv), c-(i), d-(ii)"}, {"id": "c", "text": "a-(iii), b-(i), c-(iv), d-(ii)"}, {"id": "d", "text": "a-(i), b-(iv), c-(iii), d-(iii)"}]'::jsonb, 'b', 'Mons pubis: external genitalia. Antrum: Graafian follicle. Trophectoderm: embryo formation. Nebenkern: sperm.', 'The mons pubis is part of the vulva, and the antrum is the fluid-filled cavity of the Graafian follicle. The trophectoderm (trophoblast) of the blastocyst helps form the embryo by attaching to the endometrium and forming the placenta. The nebenkern is the mitochondrial spiral in the sperm middle piece, giving a-(iii), b-(iv), c-(i), d-(ii).', '{"a": "Trophectoderm and nebenkern are swapped.", "c": "The antrum belongs to the Graafian follicle, not embryo formation.", "d": "The mons pubis is not embryo formation, and (iii) is repeated."}'::jsonb, 'The blastocyst has an outer trophoblast and an inner cell mass that becomes the embryo.', 'med', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('a86379fc-591c-5845-81c8-1421ba8c0f3c', 'neet_ug', 'Zoology', 'Human Reproduction', 'Several hormones likes hCG, hPL, estrogen, progesterone are produced by', '[{"id": "a", "text": "Ovary"}, {"id": "b", "text": "Placenta"}, {"id": "c", "text": "Fallopian tube"}, {"id": "d", "text": "Pituitary"}]'::jsonb, 'b', 'The placenta acts as an endocrine organ secreting hCG, hPL, oestrogens and progestogens.', 'During pregnancy the placenta secretes hCG, hPL, oestrogens and progestogens. Of these, hCG and hPL are produced only by the placenta. The ovary does not make hCG or hPL, and relaxin is secreted by the ovary in later pregnancy.', '{"a": "The ovary does not produce hCG or hPL.", "c": "The fallopian tube is not endocrine.", "d": "The pituitary produces gonadotropins, not hCG or hPL."}'::jsonb, 'Relaxin is secreted by the ovary during later stages of pregnancy.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('f50ce781-9305-55d9-bdee-37431d6463c7', 'neet_ug', 'Botany', 'Principles of Inheritance and Variation', 'If a colour-blind man marries a woman who is homozygous for normal vision, the probability of their son being colour blind is', '[{"id": "a", "text": "0"}, {"id": "b", "text": "0.5"}, {"id": "c", "text": "0.75"}, {"id": "d", "text": "1"}]'::jsonb, 'a', 'Sons inherit their X from the mother, who here carries only normal alleles.', 'The cross is XᶜY × XX. Every son receives the Y from his father and a normal X from his homozygous normal mother, so all sons are XY with normal vision. The probability is 0, while all daughters are carriers (XᶜX).', '{"b": "This would apply if the mother were a carrier.", "c": "No monohybrid cross here gives 0.75 for sons.", "d": "This would apply only if the mother were colour blind."}'::jsonb, 'Colour blindness is an X-linked recessive trait, so a son inherits it from his mother.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('77a6a6d3-c56e-5322-84f2-47d4145c9123', 'neet_ug', 'Zoology', 'Evolution', 'Genetic drift operates in:', '[{"id": "a", "text": "Small isolated population"}, {"id": "b", "text": "Large isolated population"}, {"id": "c", "text": "Non-reproductive population"}, {"id": "d", "text": "Slow reproductive population"}]'::jsonb, 'a', 'Chance changes in allele frequency are significant only in small populations.', 'Genetic drift is a random change in allele frequency due to chance. Its effect is pronounced in small, isolated populations, for example after a founder event or a bottleneck. In large populations random fluctuations average out.', '{"b": "Drift is negligible in large populations.", "c": "A non-reproducing population passes no alleles on.", "d": "Reproductive rate is not the determining factor; population size is."}'::jsonb, 'The founder effect is a form of genetic drift.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('7f76e443-156b-505f-9290-b5631cb27656', 'neet_ug', 'Zoology', 'Evolution', 'In Hardy-Weinberg equation, the frequency of heterozygous individuals is represented by', '[{"id": "a", "text": "p²"}, {"id": "b", "text": "2pq"}, {"id": "c", "text": "pq"}, {"id": "d", "text": "q²"}]'::jsonb, 'b', 'In p² + 2pq + q² = 1, the term 2pq is the heterozygote frequency.', 'With allele frequencies p (A) and q (a), the genotype frequencies are p² for AA, 2pq for Aa and q² for aa. The term 2pq counts both Aa and aA combinations.', '{"a": "p² is the frequency of homozygous dominant individuals.", "c": "pq is only half the heterozygote frequency.", "d": "q² is the frequency of homozygous recessive individuals."}'::jsonb, 'Five factors disturb Hardy-Weinberg equilibrium: gene migration, genetic drift, mutation, recombination and natural selection.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('263bbe2a-8abb-5b5f-86b1-0cadff9764d4', 'neet_ug', 'Zoology', 'Evolution', 'The chronological order of human evolution from early to the recent is', '[{"id": "a", "text": "Australopithecus → Ramapithecus → Homo habilis → Homo erectus"}, {"id": "b", "text": "Ramapithecus → Australopithecus → Homo habilis → Homo erectus"}, {"id": "c", "text": "Ramapithecus → Homo habilis → Australopithecus → Homo erectus"}, {"id": "d", "text": "Australopithecus → Homo habilis → Ramapithecus → Homo erectus"}]'::jsonb, 'b', 'Ramapithecus (~15 mya) → Australopithecus (~2 mya) → Homo habilis → Homo erectus (~1.5 mya).', 'Dryopithecus and Ramapithecus lived about 15 million years ago, and Australopithecines lived in East Africa about 2 million years ago. They were followed by Homo habilis and then Homo erectus, about 1.5 million years ago.', '{"a": "Ramapithecus is older than Australopithecus.", "c": "Australopithecus preceded Homo habilis.", "d": "Ramapithecus is the oldest of the four."}'::jsonb, 'Homo habilis had a cranial capacity of 650–800 cc and Homo erectus about 900 cc.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('4dd4f9dc-0f8c-5c41-b65b-ec902c1cfd62', 'neet_ug', 'Zoology', 'Evolution', 'Which of the following is the correct sequence of events in the origin of life?
I. Formation of protobionts
II. Synthesis of organic monomers
III. Synthesis of organic polymers
IV. Formation of DNA-based genetic systems', '[{"id": "a", "text": "I, II, III, IV"}, {"id": "b", "text": "I, III, II, IV"}, {"id": "c", "text": "II, III, I, IV"}, {"id": "d", "text": "II, III, IV, I"}]'::jsonb, 'c', 'Monomers → polymers → protobionts → DNA-based genetic systems.', 'Chemical evolution first produced simple organic monomers, as in Miller''s experiment, and these then joined into polymers. Polymers aggregated into protobionts such as coacervates, and the DNA-based genetic system evolved later, after an RNA world.', '{"a": "Protobionts cannot form before monomers and polymers.", "b": "Monomers must come before both polymers and protobionts.", "d": "DNA-based systems arose after protobionts."}'::jsonb, 'Miller (1953) produced amino acids from CH₄, NH₃, H₂ and water vapour using electric discharge at 800 °C.', 'med', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('b1514cd0-96d0-53b8-a964-f3a6d264fee1', 'neet_ug', 'Botany', 'Molecular Basis of Inheritance', 'A molecule that can act as a genetic material must fulfill the traits given below, except', '[{"id": "a", "text": "It should be able to express itself in the form of ''Mendelian characters''"}, {"id": "b", "text": "It should be able to generate its replica"}, {"id": "c", "text": "It should be unstable structurally and chemically"}, {"id": "d", "text": "It should provide the scope for slow changes that are required for evolution"}]'::jsonb, 'c', 'Genetic material must be stable, not unstable.', 'A genetic material must be able to replicate, be chemically and structurally stable, allow slow mutation for evolution, and express itself as Mendelian characters. Instability is not a requirement, which is why DNA is a better genetic material than RNA.', '{"a": "Expression as Mendelian characters is a required trait.", "b": "Self-replication is a required trait.", "d": "Scope for slow change is a required trait."}'::jsonb, 'The 2''-OH group makes RNA labile, and thymine in place of uracil adds stability to DNA.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('b78ee474-8471-57eb-9d32-e8891fe3c42d', 'neet_ug', 'Botany', 'Molecular Basis of Inheritance', 'DNA-dependent RNA polymerase catalyzes transcription on one strand of the DNA which is called the', '[{"id": "a", "text": "template strand"}, {"id": "b", "text": "coding strand"}, {"id": "c", "text": "alpha strand"}, {"id": "d", "text": "antistrand"}]'::jsonb, 'a', 'RNA polymerase reads the 3''→5'' template strand.', 'RNA polymerase uses the template strand, which has 3''→5'' polarity, to synthesise mRNA in the 5''→3'' direction. The other strand is the coding strand, whose sequence matches the RNA except that it has T in place of U.', '{"b": "The coding strand is not transcribed; its sequence matches the RNA.", "c": "There is no ''alpha strand'' in the transcription unit.", "d": "''Antistrand'' is not a standard term."}'::jsonb, 'A transcription unit has a promoter, a structural gene and a terminator.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('e5094dd2-afda-5998-9fb8-d90103fef164', 'neet_ug', 'Zoology', 'Human Health and Disease', 'Which of the following is correct regarding AIDS causative agent HIV?', '[{"id": "a", "text": "HIV is enveloped virus containing one molecule of single-stranded RNA and one molecule of reverse transcriptase"}, {"id": "b", "text": "HIV is enveloped virus that contains two identical molecules of single-stranded RNA and two molecules of reverse transcriptase"}, {"id": "c", "text": "HIV is unenveloped virus"}, {"id": "d", "text": "HIV does not escape but attacks the acquired immune response"}]'::jsonb, 'b', 'HIV is an enveloped retrovirus carrying two copies of ssRNA plus reverse transcriptase.', 'HIV is an enveloped retrovirus whose capsid contains two identical single-stranded RNA molecules together with reverse transcriptase. The reverse transcriptase copies the RNA into DNA, which integrates into the helper T-cell genome. It both evades and destroys acquired immunity.', '{"a": "The genome is diploid, with two RNA copies, not one.", "c": "HIV has a lipid envelope.", "d": "HIV does evade immune responses."}'::jsonb, 'ELISA is the diagnostic test for HIV, and macrophages act as an HIV factory.', 'med', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('e57c797d-fdf4-5334-ae9f-7f35db8a7133', 'neet_ug', 'Botany', 'Microbes in Human Welfare', 'Match Column-I with Column-II and select the correct option using the codes given below:
Column I | Column II
a. Citric acid | (i) Trichoderma
b. Cyclosporin A | (ii) Clostridium
c. Statins | (iii) Aspergillus
d. Butyric acid | (iv) Monascus', '[{"id": "a", "text": "a-(iii), b-(i), c-(ii), d-(iv)"}, {"id": "b", "text": "a-(iii), b-(i), c-(iv), d-(ii)"}, {"id": "c", "text": "a-(i), b-(iv), c-(ii), d-(iii)"}, {"id": "d", "text": "a-(iii), b-(iv), c-(i), d-(ii)"}]'::jsonb, 'b', 'Citric acid: Aspergillus. Cyclosporin A: Trichoderma. Statins: Monascus. Butyric acid: Clostridium.', 'Aspergillus niger produces citric acid and Clostridium butylicum produces butyric acid. Cyclosporin A, an immunosuppressant, comes from Trichoderma polysporum. Statins, which lower cholesterol, come from the yeast Monascus purpureus. That gives a-(iii), b-(i), c-(iv), d-(ii).', '{"a": "Statins come from Monascus and butyric acid from Clostridium, not the reverse.", "c": "Citric acid comes from Aspergillus, not Trichoderma.", "d": "Cyclosporin comes from Trichoderma, not Monascus."}'::jsonb, 'Acetobacter aceti produces acetic acid and Lactobacillus produces lactic acid.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('be85a6cb-1712-5766-ad90-ee3b449c6693', 'neet_ug', 'Botany', 'Microbes in Human Welfare', 'Biochemical Oxygen Demand (BOD) may not be a good index for pollution for water bodies receiving effluents from', '[{"id": "a", "text": "Domestic sewage"}, {"id": "b", "text": "Dairy industry"}, {"id": "c", "text": "Petroleum industry"}, {"id": "d", "text": "Sugar industry"}]'::jsonb, 'c', 'BOD measures biodegradable organic matter, and petroleum wastes are largely non-biodegradable.', 'BOD is the oxygen consumed by microbes in oxidising the organic matter in one litre of water. Sewage, dairy and sugar effluents are rich in biodegradable organics, so BOD reflects their pollution well. Petroleum effluents contain hydrocarbons that microbes do not readily degrade, so BOD underestimates that pollution.', '{"a": "Sewage is mainly biodegradable organic matter, so BOD indexes it well.", "b": "Dairy waste is biodegradable organic matter.", "d": "Sugar-industry waste is biodegradable organic matter."}'::jsonb, 'The greater the BOD of waste water, the greater its polluting potential.', 'med', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('4d3bcc46-5003-5d7f-8458-5ab6e45eebf6', 'neet_ug', 'Botany', 'Organisms and Populations', 'The principle of competitive exclusion was stated by', '[{"id": "a", "text": "C. Darwin"}, {"id": "b", "text": "G. F. Gause"}, {"id": "c", "text": "MacArthur"}, {"id": "d", "text": "Verhulst and Pearl"}]'::jsonb, 'b', 'Gause''s principle: two closely related species competing for the same resources cannot coexist indefinitely.', 'G. F. Gause stated the competitive exclusion principle, under which the competitively inferior species is eventually eliminated. MacArthur showed resource partitioning among warblers, and Verhulst–Pearl gave the logistic growth model.', '{"a": "Darwin gave natural selection, not this principle.", "c": "MacArthur demonstrated resource partitioning in warblers.", "d": "Verhulst and Pearl gave the logistic growth model."}'::jsonb, 'Logistic growth: dN/dt = rN(K − N)/K.', 'easy', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('414d4ccb-60dd-5516-bc83-9097722ee410', 'neet_ug', 'Botany', 'Biodiversity and Conservation', 'Which of the following National Parks is home to the famous musk deer or hangul?', '[{"id": "a", "text": "Keibul Lamjao National Park, Manipur"}, {"id": "b", "text": "Bandhavgarh National Park, Madhya Pradesh"}, {"id": "c", "text": "Eaglenest Wildlife Sanctuary, Arunachal Pradesh"}, {"id": "d", "text": "Dachigam National Park, Jammu & Kashmir"}]'::jsonb, 'd', 'Dachigam National Park in Kashmir protects the hangul (Kashmir stag).', 'The hangul (Kashmir stag) survives mainly in Dachigam National Park near Srinagar, which also shelters musk deer. Keibul Lamjao is the floating park of the sangai deer, Bandhavgarh is known for tigers, and Eaglenest for birds.', '{"a": "Keibul Lamjao protects the brow-antlered (sangai) deer.", "b": "Bandhavgarh is famous for tigers.", "c": "Eaglenest is known for birds such as the Bugun liocichla."}'::jsonb, 'India has about 90 national parks and 448 wildlife sanctuaries (in situ conservation).', 'med', true, 2016, NULL, 'NEET UG 2016 (NTA) · answer verified by UG Prep', NULL),
('1b848c13-a478-5574-b684-e98fa1f5a195', 'neet_ug', 'Physics', 'Thermodynamics', 'The volume (V) of a monatomic gas varies with its temperature (T), as shown in the graph. The ratio of work done by the gas, to the heat absorbed by it, when it undergoes a change from state A to state B, is', '[{"id": "a", "text": "1/3"}, {"id": "b", "text": "2/3"}, {"id": "c", "text": "2/5"}, {"id": "d", "text": "2/7"}]'::jsonb, 'c', 'A straight V–T line through the origin means an isobaric process, so W/Q = R/Cp = 2/5 for a monatomic gas.', 'V ∝ T means pressure is constant. W = nRΔT and Q = nCpΔT = (5/2)nRΔT for a monatomic gas, so W/Q = 1/(5/2) = 2/5.', '{"a": "This mixes up the ratio with other heat-capacity fractions; it is not R/Cp.", "b": "2/3 is ΔU/Q for an isobaric monatomic process, not W/Q.", "d": "2/7 is R/Cp for a diatomic gas (Cp = 7R/2)."}'::jsonb, 'In an isobaric process W/Q = 1 − 1/γ; ΔU/Q = 1/γ.', 'med', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', '/pyq/ug/2018/1.webp'),
('4746ef4b-92aa-5436-88ff-5ea75d19d95c', 'neet_ug', 'Physics', 'Waves', 'The fundamental frequency in an open organ pipe is equal to the third harmonic of a closed organ pipe. If the length of the closed organ pipe is 20 cm, the length of the open organ pipe is', '[{"id": "a", "text": "12·5 cm"}, {"id": "b", "text": "8 cm"}, {"id": "c", "text": "13·2 cm"}, {"id": "d", "text": "16 cm"}]'::jsonb, 'c', 'Equate v/2L₀ with 3v/4L_c to get L₀ = 2L_c/3 ≈ 13·3 cm.', 'Third harmonic of the closed pipe = 3v/(4×20) = 3v/80. Open-pipe fundamental = v/2L₀. Setting them equal gives L₀ = 80/6 ≈ 13·3 cm, which matches 13·2 cm most closely.', '{"a": "12·5 cm would need L₀ = 5L_c/8, which no harmonic relation here gives.", "b": "8 cm does not satisfy v/2L₀ = 3v/80.", "d": "16 cm would correspond to the open pipe matching the fifth-harmonic ratio, not the third."}'::jsonb, 'A closed pipe has only odd harmonics: f = (2n−1)v/4L; an open pipe has all harmonics: f = nv/2L.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('20477276-f2f3-5479-bd79-636dc3bb2acf', 'neet_ug', 'Physics', 'Kinetic Theory', 'At what temperature will the rms speed of oxygen molecules become just sufficient for escaping from the Earth''s atmosphere ?
(Given :
Mass of oxygen molecule (m) = 2·76 × 10⁻²⁶ kg
Boltzmann''s constant k_B = 1·38 × 10⁻²³ J K⁻¹)', '[{"id": "a", "text": "5·016 × 10⁴ K"}, {"id": "b", "text": "8·360 × 10⁴ K"}, {"id": "c", "text": "2·508 × 10⁴ K"}, {"id": "d", "text": "1·254 × 10⁴ K"}]'::jsonb, 'b', 'Set v_rms = √(3kT/m) equal to the escape speed 11·2 km/s and solve for T.', 'T = m v_e²/(3k_B) = 2·76×10⁻²⁶ × (1·12×10⁴)² / (3 × 1·38×10⁻²³) = 3·462×10⁻¹⁸ / 4·14×10⁻²³ ≈ 8·36×10⁴ K.', '{"a": "This is twice the correct value, as if 3k were replaced by 1·5k.", "c": "Half the correct value; the factor of 3 in v_rms is mishandled.", "d": "One-sixth too small a factor is used in the calculation."}'::jsonb, 'v_rms = √(3k_BT/m); Earth''s escape speed ≈ 11·2 km/s.', 'med', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('3d5ee0eb-c3ba-5598-8a57-fbe52157d539', 'neet_ug', 'Physics', 'Thermodynamics', 'The efficiency of an ideal heat engine working between the freezing point and boiling point of water, is', '[{"id": "a", "text": "6·25%"}, {"id": "b", "text": "20%"}, {"id": "c", "text": "26·8%"}, {"id": "d", "text": "12·5%"}]'::jsonb, 'c', 'Carnot efficiency = 1 − 273/373 ≈ 26·8%.', 'Use absolute temperatures: T_c = 273 K, T_h = 373 K. η = 1 − T_c/T_h = 100/373 ≈ 0·268 = 26·8%.', '{"a": "6·25% does not follow from 273 K and 373 K.", "b": "20% would need T_c/T_h = 0·8.", "d": "12·5% would need T_c/T_h = 0·875."}'::jsonb, 'Carnot efficiency η = 1 − T₂/T₁, with temperatures in kelvin.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('a9ba488d-c951-5eae-9063-8bdeec54a9f1', 'neet_ug', 'Physics', 'Current Electricity', 'A carbon resistor of (47 ± 4·7) kΩ is to be marked with rings of different colours for its identification. The colour code sequence will be', '[{"id": "a", "text": "Yellow – Green – Violet – Gold"}, {"id": "b", "text": "Yellow – Violet – Orange – Silver"}, {"id": "c", "text": "Violet – Yellow – Orange – Silver"}, {"id": "d", "text": "Green – Orange – Violet – Gold"}]'::jsonb, 'b', '47 × 10³ Ω with ±10% tolerance is Yellow(4) Violet(7) Orange(10³) Silver.', '47 kΩ = 47 × 10³ Ω, so the bands are 4 = yellow, 7 = violet and multiplier 10³ = orange. 4·7 kΩ is 10% of 47 kΩ, and ±10% is silver.', '{"a": "Yellow–Green gives 45, and violet as multiplier is 10⁷; gold means 5%.", "c": "Violet–Yellow reads 74, the digits are reversed.", "d": "Green–Orange gives 53, and the tolerance is gold (5%)."}'::jsonb, 'Colour code digits: Black 0, Brown 1, Red 2, Orange 3, Yellow 4, Green 5, Blue 6, Violet 7, Grey 8, White 9; gold 5%, silver 10%.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('99751b18-46fa-5b6c-876d-2e5ced7216ed', 'neet_ug', 'Physics', 'Current Electricity', 'A set of ''n'' equal resistors, of value ''R'' each, are connected in series to a battery of emf ''E'' and internal resistance ''R''. The current drawn is I. Now, the ''n'' resistors are connected in parallel to the same battery. Then the current drawn from battery becomes 10 I. The value of ''n'' is', '[{"id": "a", "text": "20"}, {"id": "b", "text": "11"}, {"id": "c", "text": "10"}, {"id": "d", "text": "9"}]'::jsonb, 'c', 'Series: I = E/[(n+1)R]; parallel: 10I = E/[R(1/n + 1)], so n = 10.', 'Dividing the two expressions: 10 = (n+1)R / [R(1+n)/n] = n. Hence n = 10.', '{"a": "20 would make the ratio of currents 20.", "b": "11 confuses n with n + 1.", "d": "9 would give a current ratio of 9."}'::jsonb, 'For n equal resistors, series equivalent is nR and parallel equivalent is R/n.', 'med', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('4d24663a-2813-5dda-9274-3508bce62232', 'neet_ug', 'Physics', 'Current Electricity', 'A battery consists of a variable number ''n'' of identical cells (having internal resistance ''r'' each) which are connected in series. The terminals of the battery are short-circuited and the current I is measured. Which of the graphs shows the correct relationship between I and n ?', '[{"id": "a", "text": "Option (1) in figure"}, {"id": "b", "text": "Option (2) in figure"}, {"id": "c", "text": "Option (3) in figure"}, {"id": "d", "text": "Option (4) in figure"}]'::jsonb, 'c', 'Short-circuit current I = nE/(nr) = E/r does not depend on n, so the graph is a horizontal line.', 'With n cells in series the emf is nE and the internal resistance is nr. With no external resistance, I = nE/nr = E/r, a constant, so the graph is horizontal.', '{"a": "A saturating curve would need an external resistance in the circuit.", "b": "A linear rise would need the resistance to stay fixed while the emf grows.", "d": "An accelerating rise has no basis here."}'::jsonb, 'Short-circuit current of identical cells in series equals E/r, whatever the number of cells.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', '/pyq/ug/2018/7.webp'),
('9864886c-49b3-586e-965a-ebaa8780399f', 'neet_ug', 'Physics', 'Wave Optics', 'Unpolarised light is incident from air on a plane surface of a material of refractive index ''μ''. At a particular angle of incidence ''i'', it is found that the reflected and refracted rays are perpendicular to each other. Which of the following options is correct for this situation ?', '[{"id": "a", "text": "i = sin⁻¹(1/μ)"}, {"id": "b", "text": "Reflected light is polarised with its electric vector perpendicular to the plane of incidence"}, {"id": "c", "text": "Reflected light is polarised with its electric vector parallel to the plane of incidence"}, {"id": "d", "text": "i = tan⁻¹(1/μ)"}]'::jsonb, 'b', 'At the Brewster angle the reflected light is completely polarised with E perpendicular to the plane of incidence.', 'When the reflected and refracted rays are perpendicular, i is the Brewster angle with tan i = μ. The reflected beam then carries only the component of E perpendicular to the plane of incidence.', '{"a": "sin⁻¹(1/μ) is the critical angle, not the Brewster angle.", "c": "The parallel component is fully transmitted at the Brewster angle, so it is absent from the reflected light.", "d": "Brewster''s law is tan i = μ, not 1/μ."}'::jsonb, 'Brewster''s law: tan i_B = μ; i_B + r = 90°.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('2da4c3d7-b0a0-5bba-ac9a-6af9b1d9292e', 'neet_ug', 'Physics', 'Wave Optics', 'In Young''s double slit experiment the separation d between the slits is 2 mm, the wavelength λ of the light used is 5896 Å and distance D between the screen and slits is 100 cm. It is found that the angular width of the fringes is 0·20°. To increase the fringe angular width to 0·21° (with same λ and D) the separation between the slits needs to be changed to', '[{"id": "a", "text": "2·1 mm"}, {"id": "b", "text": "1·9 mm"}, {"id": "c", "text": "1·8 mm"}, {"id": "d", "text": "1·7 mm"}]'::jsonb, 'b', 'Angular width θ = λ/d, so d'' = d × 0·20/0·21 ≈ 1·9 mm.', 'θ ∝ 1/d at fixed λ, so d'' = 2 mm × (0·20/0·21) = 1·905 mm ≈ 1·9 mm.', '{"a": "Increasing d would make the fringes narrower, not wider.", "c": "1·8 mm gives θ ≈ 0·222°.", "d": "1·7 mm gives θ ≈ 0·235°."}'::jsonb, 'Angular fringe width in YDSE is θ = λ/d and does not depend on D.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('a916ca83-a1c2-5697-8965-7ea72e825ca6', 'neet_ug', 'Physics', 'Ray Optics and Optical Instruments', 'An astronomical refracting telescope will have large angular magnification and high angular resolution, when it has an objective lens of', '[{"id": "a", "text": "large focal length and large diameter"}, {"id": "b", "text": "large focal length and small diameter"}, {"id": "c", "text": "small focal length and large diameter"}, {"id": "d", "text": "small focal length and small diameter"}]'::jsonb, 'a', 'M = f₀/fₑ needs a large f₀, and resolving power ∝ D/λ needs a large aperture.', 'Angular magnification of a telescope is f₀/fₑ, so the objective needs a long focal length. The limit of resolution is about 1·22λ/D, so a larger diameter resolves finer detail.', '{"b": "A small diameter lowers the resolving power.", "c": "A short objective focal length lowers the magnification.", "d": "This lowers both magnification and resolution."}'::jsonb, 'Telescope: M = f₀/fₑ (normal adjustment); resolving power = D/(1·22λ).', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('b39024fb-645b-509d-94f0-67ba6ab1ec9b', 'neet_ug', 'Physics', 'Atoms', 'The ratio of kinetic energy to the total energy of an electron in a Bohr orbit of the hydrogen atom, is', '[{"id": "a", "text": "2 : –1"}, {"id": "b", "text": "1 : –1"}, {"id": "c", "text": "1 : 1"}, {"id": "d", "text": "1 : –2"}]'::jsonb, 'b', 'In a Bohr orbit E = −K, so K : E = 1 : −1.', 'For an inverse-square force, U = −2K, so E = K + U = −K. The ratio K/E is therefore −1, written 1 : −1.', '{"a": "2 : −1 is the ratio of U to E (U = 2E).", "c": "Total energy is negative, so the ratio cannot be positive.", "d": "1 : −2 is K : U."}'::jsonb, 'Bohr orbit: K = −E, U = 2E.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('7a3d669c-546b-55ae-89de-53c9c15cd9e4', 'neet_ug', 'Physics', 'Dual Nature of Radiation and Matter', 'An electron of mass m with an initial velocity V⃗ = V₀ î (V₀ > 0) enters an electric field E⃗ = – E₀ î (E₀ = constant > 0) at t = 0. If λ₀ is its de-Broglie wavelength initially, then its de-Broglie wavelength at time t is', '[{"id": "a", "text": "λ₀ t"}, {"id": "b", "text": "λ₀ (1 + eE₀t/(mV₀))"}, {"id": "c", "text": "λ₀ / (1 + eE₀t/(mV₀))"}, {"id": "d", "text": "λ₀"}]'::jsonb, 'c', 'The force on the electron is +eE₀ î, so its speed grows to V₀ + eE₀t/m and λ falls in proportion.', 'F = −eE⃗ = +eE₀ î, along the velocity, so v = V₀ + (eE₀/m)t. Since λ = h/mv, λ = λ₀V₀/v = λ₀/(1 + eE₀t/(mV₀)).', '{"a": "λ₀t has the wrong dimensions.", "b": "This would be right only if the electron were slowing down linearly in 1/v, which it is not.", "d": "The speed changes, so λ cannot stay constant."}'::jsonb, 'de Broglie wavelength λ = h/p; a field along −x accelerates an electron along +x.', 'med', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('9a55c157-7141-5d42-9a48-aa7048853a80', 'neet_ug', 'Physics', 'Dual Nature of Radiation and Matter', 'When the light of frequency 2ν₀ (where ν₀ is threshold frequency), is incident on a metal plate, the maximum velocity of electrons emitted is v₁. When the frequency of the incident radiation is increased to 5ν₀, the maximum velocity of electrons emitted from the same plate is v₂. The ratio of v₁ to v₂ is', '[{"id": "a", "text": "4 : 1"}, {"id": "b", "text": "1 : 4"}, {"id": "c", "text": "1 : 2"}, {"id": "d", "text": "2 : 1"}]'::jsonb, 'c', 'K_max = h(ν − ν₀) gives hν₀ and 4hν₀, so v₁ : v₂ = √1 : √4 = 1 : 2.', '½mv₁² = h(2ν₀ − ν₀) = hν₀ and ½mv₂² = h(5ν₀ − ν₀) = 4hν₀. So v₁²/v₂² = 1/4 and v₁/v₂ = 1/2.', '{"a": "This inverts the ratio and takes the ratio of energies instead of speeds.", "b": "1 : 4 is the ratio of kinetic energies, not speeds.", "d": "The ratio is inverted; the higher frequency gives the faster electrons."}'::jsonb, 'Einstein''s photoelectric equation: ½mv²_max = hν − φ₀ = h(ν − ν₀).', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('92ff8d18-0e92-5c10-8afe-4f2b70c2b670', 'neet_ug', 'Physics', 'Semiconductor Electronics', 'In the circuit shown in the figure, the input voltage Vᵢ is 20 V, V_BE = 0 and V_CE = 0. The values of I_B, I_C and β are given by', '[{"id": "a", "text": "I_B = 20 μA, I_C = 5 mA, β = 250"}, {"id": "b", "text": "I_B = 25 μA, I_C = 5 mA, β = 200"}, {"id": "c", "text": "I_B = 40 μA, I_C = 10 mA, β = 250"}, {"id": "d", "text": "I_B = 40 μA, I_C = 5 mA, β = 125"}]'::jsonb, 'd', 'I_B = 20 V/500 kΩ = 40 μA, I_C = 20 V/4 kΩ = 5 mA, so β = 125.', 'With V_BE = 0, the whole 20 V drops across R_B: I_B = 20/(500×10³) = 40 μA. With V_CE = 0, all 20 V drops across R_C: I_C = 20/(4×10³) = 5 mA. β = I_C/I_B = 5 mA/40 μA = 125.', '{"a": "I_B is not 20 μA, since 20 V/500 kΩ = 40 μA.", "b": "I_B = 25 μA would need R_B = 800 kΩ.", "c": "I_C = 10 mA would need R_C = 2 kΩ."}'::jsonb, 'Current gain β = I_C/I_B for a transistor in the CE configuration.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', '/pyq/ug/2018/15.webp'),
('53c7549a-92ce-59cb-9c20-65d5ac2ac9c8', 'neet_ug', 'Physics', 'Semiconductor Electronics', 'In a p-n junction diode, change in temperature due to heating', '[{"id": "a", "text": "does not affect resistance of p-n junction"}, {"id": "b", "text": "affects only forward resistance"}, {"id": "c", "text": "affects only reverse resistance"}, {"id": "d", "text": "affects the overall V – I characteristics of p-n junction"}]'::jsonb, 'd', 'Heating changes carrier concentration, so both forward and reverse behaviour (the full V–I curve) change.', 'Raising the temperature generates more electron–hole pairs and increases the intrinsic carrier density. This raises the reverse saturation current and lowers the forward cut-in voltage, so the whole V–I characteristic shifts.', '{"a": "Semiconductor conductivity depends strongly on temperature.", "b": "The reverse (minority-carrier) current is also strongly affected.", "c": "Forward conduction also changes with temperature."}'::jsonb, 'The conductivity of a semiconductor increases with temperature because thermal generation creates more carriers.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('54f01501-2998-524a-bcc5-d3d2c40ff75a', 'neet_ug', 'Physics', 'Semiconductor Electronics', 'In the combination of the following gates the output Y can be written in terms of inputs A and B as', '[{"id": "a", "text": "(A·B)‾ + A·B"}, {"id": "b", "text": "A·B̄ + Ā·B"}, {"id": "c", "text": "(A·B)‾"}, {"id": "d", "text": "(A + B)‾"}]'::jsonb, 'b', 'The upper AND gives A·B̄, the lower gives Ā·B, and the OR combines them into XOR.', 'A goes directly to the upper AND while B reaches it through a NOT, giving A·B̄. B goes directly to the lower AND while A reaches it through a NOT, giving Ā·B. The OR gate outputs Y = A·B̄ + Ā·B (XOR).', '{"a": "This is XNOR-like logic that does not match the wiring.", "c": "This is NAND, which would need a single AND followed by NOT.", "d": "This is NOR, with no OR followed by NOT in the circuit."}'::jsonb, 'XOR: Y = A·B̄ + Ā·B is 1 only when the inputs differ.', 'med', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', '/pyq/ug/2018/17.webp'),
('f901d1fb-d716-57e2-a0e1-0b6b7029b3c9', 'neet_ug', 'Physics', 'Electromagnetic Waves', 'An em wave is propagating in a medium with a velocity V⃗ = V î. The instantaneous oscillating electric field of this em wave is along +y axis. Then the direction of oscillating magnetic field of the em wave will be along', '[{"id": "a", "text": "– y direction"}, {"id": "b", "text": "+ z direction"}, {"id": "c", "text": "– z direction"}, {"id": "d", "text": "– x direction"}]'::jsonb, 'b', 'E × B must point along the propagation direction: ĵ × k̂ = î, so B is along +z.', 'The direction of propagation is that of E⃗ × B⃗. With E along ĵ and propagation along î, B must be along k̂, since ĵ × k̂ = î.', '{"a": "B must be perpendicular to E, not along it.", "c": "ĵ × (−k̂) = −î, which would reverse the propagation.", "d": "B must be perpendicular to the propagation direction."}'::jsonb, 'In an EM wave E, B and the direction of propagation are mutually perpendicular, with propagation along E × B.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('42b1b5b4-a26f-5859-915b-da1e738194bd', 'neet_ug', 'Physics', 'Ray Optics and Optical Instruments', 'The refractive index of the material of a prism is √2 and the angle of the prism is 30°. One of the two refracting surfaces of the prism is made a mirror inwards, by silver coating. A beam of monochromatic light entering the prism from the other face will retrace its path (after reflection from the silvered surface) if its angle of incidence on the prism is', '[{"id": "a", "text": "30°"}, {"id": "b", "text": "45°"}, {"id": "c", "text": "60°"}, {"id": "d", "text": "zero"}]'::jsonb, 'b', 'To retrace, the ray must hit the silvered face normally, so r = A = 30°, giving sin i = √2 sin 30°, i = 45°.', 'For the ray to retrace its path it must strike the silvered face at 90°, which makes the refraction angle at the first face r = A = 30°. Snell''s law gives sin i = √2 × ½ = 1/√2, so i = 45°.', '{"a": "30° is the refraction angle inside, not the incidence angle.", "c": "60° gives sin r = 0·612, so r ≈ 37·8°, not 30°.", "d": "At zero incidence the ray would meet the silvered face at 30° and not retrace."}'::jsonb, 'In a prism, r₁ + r₂ = A; normal incidence on the second face means r₂ = 0.', 'med', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('61f36b43-e1dc-53e2-938e-2b0dc7cfcfbf', 'neet_ug', 'Physics', 'Ray Optics and Optical Instruments', 'An object is placed at a distance of 40 cm from a concave mirror of focal length 15 cm. If the object is displaced through a distance of 20 cm towards the mirror, the displacement of the image will be', '[{"id": "a", "text": "30 cm towards the mirror"}, {"id": "b", "text": "36 cm away from the mirror"}, {"id": "c", "text": "30 cm away from the mirror"}, {"id": "d", "text": "36 cm towards the mirror"}]'::jsonb, 'b', 'The image moves from 24 cm to 60 cm in front of the mirror, i.e. 36 cm away from it.', 'With u = −40 cm and f = −15 cm, 1/v = −1/15 + 1/40 gives v = −24 cm. With u = −20 cm, 1/v = −1/15 + 1/20 gives v = −60 cm. The image shifts 36 cm farther from the mirror.', '{"a": "Neither the distance nor the direction is right.", "c": "The shift is 60 − 24 = 36 cm, not 30 cm.", "d": "As the object approaches f, the real image moves away from the mirror."}'::jsonb, 'Mirror formula: 1/v + 1/u = 1/f, using the Cartesian sign convention.', 'med', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('8713c99d-2480-545e-b60b-2774c40095c7', 'neet_ug', 'Physics', 'Electromagnetic Induction', 'The magnetic potential energy stored in a certain inductor is 25 mJ, when the current in the inductor is 60 mA. This inductor is of inductance', '[{"id": "a", "text": "1·389 H"}, {"id": "b", "text": "138·88 H"}, {"id": "c", "text": "0·138 H"}, {"id": "d", "text": "13·89 H"}]'::jsonb, 'd', 'L = 2U/I² = 2 × 0·025/(0·06)² ≈ 13·89 H.', 'U = ½LI², so L = 2U/I² = 0·05/0·0036 = 13·89 H.', '{"a": "Off by a factor of 10.", "b": "Off by a factor of 10 the other way.", "c": "Off by a factor of 100."}'::jsonb, 'Energy stored in an inductor: U = ½LI².', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('6b597132-5c12-596c-8c02-728a7871cd9c', 'neet_ug', 'Physics', 'Electric Charges and Fields', 'An electron falls from rest through a vertical distance h in a uniform and vertically upward directed electric field E. The direction of electric field is now reversed, keeping its magnitude the same. A proton is allowed to fall from rest in it through the same vertical distance h. The time of fall of the electron, in comparison to the time of fall of the proton is', '[{"id": "a", "text": "10 times greater"}, {"id": "b", "text": "5 times greater"}, {"id": "c", "text": "smaller"}, {"id": "d", "text": "equal"}]'::jsonb, 'c', 'Both get the same force eE downward, but the electron''s far smaller mass gives a much larger acceleration, so it falls faster.', 'The electron in an upward field and the proton in a downward field both feel a downward force eE. The acceleration a = eE/m (gravity is negligible) is much larger for the electron, and since t = √(2h/a), the electron takes less time.', '{"a": "The lighter particle accelerates more, so its time is shorter, not longer.", "b": "Same reasoning; the electron''s time is smaller.", "d": "The masses differ, so the times cannot be equal."}'::jsonb, 'In a uniform field the acceleration a = qE/m, so lighter charges accelerate more.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('df02a0d4-1395-5379-8b48-a79d94e5e166', 'neet_ug', 'Physics', 'Electrostatic Potential and Capacitance', 'The electrostatic force between the metal plates of an isolated parallel plate capacitor C having a charge Q and area A, is', '[{"id": "a", "text": "proportional to the square root of the distance between the plates."}, {"id": "b", "text": "linearly proportional to the distance between the plates."}, {"id": "c", "text": "independent of the distance between the plates."}, {"id": "d", "text": "inversely proportional to the distance between the plates."}]'::jsonb, 'c', 'F = Q²/(2ε₀A) contains no plate separation.', 'Each plate sits in the field of the other, σ/2ε₀, so F = Q × Q/(2ε₀A) = Q²/(2ε₀A). For an isolated capacitor Q is fixed, so the force does not depend on d.', '{"a": "The force has no d dependence.", "b": "It is the energy stored that is proportional to d at constant Q, not the force.", "d": "The force has no d dependence."}'::jsonb, 'Force between capacitor plates F = Q²/(2ε₀A); energy U = Q²/2C.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('afb8c74a-c14f-5bbe-bf28-7834df9ac3ea', 'neet_ug', 'Physics', 'Waves', 'A tuning fork is used to produce resonance in a glass tube. The length of the air column in this tube can be adjusted by a variable piston. At room temperature of 27°C two successive resonances are produced at 20 cm and 73 cm of column length. If the frequency of the tuning fork is 320 Hz, the velocity of sound in air at 27°C is', '[{"id": "a", "text": "350 m/s"}, {"id": "b", "text": "339 m/s"}, {"id": "c", "text": "330 m/s"}, {"id": "d", "text": "300 m/s"}]'::jsonb, 'b', 'Successive resonances differ by λ/2, so λ = 2 × 53 cm = 1·06 m and v = 320 × 1·06 ≈ 339 m/s.', 'The difference between successive resonance lengths is λ/2 = 73 − 20 = 53 cm, so λ = 1·06 m. v = fλ = 320 × 1·06 = 339·2 m/s.', '{"a": "350 m/s would need λ ≈ 1·094 m.", "c": "330 m/s is the usual value at 0°C, not this measurement.", "d": "300 m/s would need λ ≈ 0·94 m."}'::jsonb, 'In a resonance tube l₂ − l₁ = λ/2, and the end correction cancels out.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('ab3e3c62-236e-5c13-b3d2-c4dd008d2f89', 'neet_ug', 'Physics', 'Oscillations', 'A pendulum is hung from the roof of a sufficiently high building and is moving freely to and fro like a simple harmonic oscillator. The acceleration of the bob of the pendulum is 20 m/s² at a distance of 5 m from the mean position. The time period of oscillation is', '[{"id": "a", "text": "2 s"}, {"id": "b", "text": "π s"}, {"id": "c", "text": "2π s"}, {"id": "d", "text": "1 s"}]'::jsonb, 'b', 'ω² = a/x = 4 s⁻², so ω = 2 rad/s and T = 2π/ω = π s.', 'In SHM |a| = ω²x, so ω² = 20/5 = 4 and ω = 2 rad/s. T = 2π/2 = π s.', '{"a": "2 s takes ω for T.", "c": "2π s would need ω = 1 rad/s.", "d": "1 s would need ω = 2π rad/s."}'::jsonb, 'SHM: a = −ω²x and T = 2π√(x/a).', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('776aecc3-1270-598c-b7e0-68b0986caa3c', 'neet_ug', 'Physics', 'Moving Charges and Magnetism', 'A metallic rod of mass per unit length 0·5 kg m⁻¹ is lying horizontally on a smooth inclined plane which makes an angle of 30° with the horizontal. The rod is not allowed to slide down by flowing a current through it when a magnetic field of induction 0·25 T is acting on it in the vertical direction. The current flowing in the rod to keep it stationary is', '[{"id": "a", "text": "14·76 A"}, {"id": "b", "text": "5·98 A"}, {"id": "c", "text": "7·14 A"}, {"id": "d", "text": "11·32 A"}]'::jsonb, 'd', 'Balance along the incline: BIl cos 30° = mg sin 30°, so I = (m/l)g tan 30°/B ≈ 11·32 A.', 'The vertical B gives a horizontal force BIl on the rod. Along the incline, BIl cos θ = mg sin θ, so I = (m/l)g tan θ/B = 0·5 × 9·8 × 0·577/0·25 ≈ 11·32 A.', '{"a": "Comes from using the wrong trigonometric ratio.", "b": "Comes from balancing against the sin component wrongly.", "c": "Comes from using cos instead of tan."}'::jsonb, 'Force on a current-carrying conductor: F = I l⃗ × B⃗, perpendicular to both.', 'med', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('64089fc6-bdad-5714-9a3b-67f03446cb01', 'neet_ug', 'Physics', 'Magnetism and Matter', 'A thin diamagnetic rod is placed vertically between the poles of an electromagnet. When the current in the electromagnet is switched on, then the diamagnetic rod is pushed up, out of the horizontal magnetic field. Hence the rod gains gravitational potential energy. The work required to do this comes from', '[{"id": "a", "text": "the lattice structure of the material of the rod"}, {"id": "b", "text": "the magnetic field"}, {"id": "c", "text": "the current source"}, {"id": "d", "text": "the induced electric field due to the changing magnetic field"}]'::jsonb, 'c', 'The energy ultimately comes from the source that drives current through the electromagnet.', 'A static magnetic field does no net work by itself; it only stores and transfers energy. When the rod moves, the field energy changes and the battery driving the electromagnet supplies the extra energy, so the gain in gravitational PE comes from the current source.', '{"a": "The lattice provides no energy for the lift.", "b": "The field only stores and transfers energy; it is not the ultimate source.", "d": "The induced field acts only briefly during switch-on and is driven by the source anyway."}'::jsonb, 'Diamagnetic materials are pushed from stronger to weaker regions of a magnetic field.', 'med', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('e7525e04-4d81-5819-a213-61b27c84f5b2', 'neet_ug', 'Physics', 'Alternating Current', 'An inductor 20 mH, a capacitor 100 μF and a resistor 50 Ω are connected in series across a source of emf, V = 10 sin 314 t. The power loss in the circuit is', '[{"id": "a", "text": "2·74 W"}, {"id": "b", "text": "0·43 W"}, {"id": "c", "text": "0·79 W"}, {"id": "d", "text": "1·13 W"}]'::jsonb, 'c', 'With Z ≈ 56·2 Ω, I_rms ≈ 0·126 A and P = I²R ≈ 0·79 W.', 'X_L = 314 × 0·02 = 6·28 Ω and X_C = 1/(314 × 10⁻⁴) = 31·85 Ω, so Z = √(50² + 25·57²) ≈ 56·2 Ω. I_rms = 7·07/56·2 ≈ 0·126 A, and P = I_rms²R ≈ 0·0159 × 50 ≈ 0·79 W.', '{"a": "Too large; it ignores the reactance or uses peak values.", "b": "Too small; it misapplies the power factor.", "d": "Close to V_rms²/R × cos φ worked with wrong numbers."}'::jsonb, 'Average power in an LCR circuit: P = V_rms I_rms cos φ = I_rms²R.', 'med', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('883a5532-9bbd-50b5-ba02-02a4f415078d', 'neet_ug', 'Physics', 'Moving Charges and Magnetism', 'Current sensitivity of a moving coil galvanometer is 5 div/mA and its voltage sensitivity (angular deflection per unit voltage applied) is 20 div/V. The resistance of the galvanometer is', '[{"id": "a", "text": "250 Ω"}, {"id": "b", "text": "25 Ω"}, {"id": "c", "text": "40 Ω"}, {"id": "d", "text": "500 Ω"}]'::jsonb, 'a', 'G = current sensitivity / voltage sensitivity = 5000 div/A ÷ 20 div/V = 250 Ω.', 'Voltage sensitivity = current sensitivity/G, so G = I_s/V_s = (5 div/mA = 5000 div/A)/(20 div/V) = 250 Ω.', '{"b": "Off by a factor of 10.", "c": "Inverts the ratio and makes a unit error.", "d": "Double the correct value."}'::jsonb, 'Voltage sensitivity = NAB/(kR) = current sensitivity/R.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('610aa50b-4e1d-5a09-af1f-602720332961', 'neet_ug', 'Physics', 'Work, Energy and Power', 'A body initially at rest and sliding along a frictionless track from a height h (as shown in the figure) just completes a vertical circle of diameter AB = D. The height h is equal to', '[{"id": "a", "text": "7/5 D"}, {"id": "b", "text": "D"}, {"id": "c", "text": "3/2 D"}, {"id": "d", "text": "5/4 D"}]'::jsonb, 'd', 'Just completing the loop needs v² = 5gR at the bottom, so h = 5R/2 = 5D/4.', 'To just complete the vertical circle, the speed at the lowest point must be √(5gR). Energy conservation gives mgh = ½m(5gR), so h = 5R/2 = 5D/4.', '{"a": "7/5 D mixes in the rolling factor for a sphere; the body here slides.", "b": "Height D gives too little speed to reach the top.", "c": "3/2 D is too high a requirement compared with 5D/4."}'::jsonb, 'To complete a vertical circle, v_bottom ≥ √(5gR) and v_top ≥ √(gR).', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', '/pyq/ug/2018/30.webp'),
('ccfc3b75-dc1b-57a5-859c-421d7d902324', 'neet_ug', 'Physics', 'System of Particles and Rotational Motion', 'Three objects, A : (a solid sphere), B : (a thin circular disk) and C : (a circular ring), each have the same mass M and radius R. They all spin with the same angular speed ω about their own symmetry axes. The amounts of work (W) required to bring them to rest, would satisfy the relation', '[{"id": "a", "text": "W_B > W_A > W_C"}, {"id": "b", "text": "W_A > W_B > W_C"}, {"id": "c", "text": "W_C > W_B > W_A"}, {"id": "d", "text": "W_A > W_C > W_B"}]'::jsonb, 'c', 'W = ½Iω², and I_ring (MR²) > I_disc (½MR²) > I_sphere (⅖MR²).', 'The work needed equals the rotational KE ½Iω². With equal M, R and ω, the ordering follows I: ring MR² > disc 0·5MR² > solid sphere 0·4MR². So W_C > W_B > W_A.', '{"a": "The sphere has the smallest moment of inertia, not the middle one.", "b": "This reverses the order.", "d": "The ring has the largest I, so it needs the most work."}'::jsonb, 'MI about the symmetry axis: ring MR², disc MR²/2, solid sphere 2MR²/5.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('bc38b5eb-96c8-5b1b-a934-320ea05b8af0', 'neet_ug', 'Physics', 'Work, Energy and Power', 'A moving block having mass m, collides with another stationary block having mass 4m. The lighter block comes to rest after collision. When the initial velocity of the lighter block is v, then the value of coefficient of restitution (e) will be', '[{"id": "a", "text": "0·8"}, {"id": "b", "text": "0·25"}, {"id": "c", "text": "0·5"}, {"id": "d", "text": "0·4"}]'::jsonb, 'b', 'Momentum gives the heavy block v/4, so e = (v/4)/v = 0·25.', 'mv = 4m v′, so v′ = v/4. e = (relative speed of separation)/(relative speed of approach) = (v/4 − 0)/v = 0·25.', '{"a": "0·8 does not follow from v′ = v/4.", "c": "0·5 would need v′ = v/2.", "d": "0·4 would need v′ = 0·4v."}'::jsonb, 'e = (v₂ − v₁)/(u₁ − u₂); e = 1 for an elastic collision and 0 for a perfectly inelastic one.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('e4fe2ec5-3b8b-5129-9622-3f0656bc4455', 'neet_ug', 'Physics', 'Laws of Motion', 'Which one of the following statements is incorrect ?', '[{"id": "a", "text": "Frictional force opposes the relative motion."}, {"id": "b", "text": "Limiting value of static friction is directly proportional to normal reaction."}, {"id": "c", "text": "Rolling friction is smaller than sliding friction."}, {"id": "d", "text": "Coefficient of sliding friction has dimensions of length."}]'::jsonb, 'd', 'μ is a ratio of two forces, so it is dimensionless.', 'μ_k = f_k/N is a ratio of two forces and has no dimensions. The other three statements are standard properties of friction, so statement (4) is the incorrect one.', '{"a": "This is correct: friction opposes relative motion.", "b": "This is correct: f_s,max = μ_sN.", "c": "This is correct: rolling friction is generally much smaller."}'::jsonb, 'The coefficient of friction μ = f/N is dimensionless.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('80281f3e-29e2-5d54-902a-2c8e5f940fa0', 'neet_ug', 'Physics', 'Motion in a Straight Line', 'A toy car with charge q moves on a frictionless horizontal plane surface under the influence of a uniform electric field E⃗. Due to the force qE⃗, its velocity increases from 0 to 6 m/s in one second duration. At that instant the direction of the field is reversed. The car continues to move for two more seconds under the influence of this field. The average velocity and the average speed of the toy car between 0 to 3 seconds are respectively', '[{"id": "a", "text": "1 m/s, 3·5 m/s"}, {"id": "b", "text": "1 m/s, 3 m/s"}, {"id": "c", "text": "2 m/s, 4 m/s"}, {"id": "d", "text": "1·5 m/s, 3 m/s"}]'::jsonb, 'b', 'With a = 6 m/s² the car goes +3, +3, −3 m in the three seconds: displacement 3 m, distance 9 m.', '0–1 s: it accelerates at 6 m/s² and covers 3 m. 1–2 s: it decelerates from 6 m/s to 0 and covers another 3 m. 2–3 s: it moves back 3 m. Displacement = 3 m and distance = 9 m, so the average velocity is 1 m/s and the average speed is 3 m/s.', '{"a": "The distance is 9 m, which gives 3 m/s, not 3·5 m/s.", "c": "This ignores the backward motion in the last second.", "d": "The displacement is 3 m, not 4·5 m."}'::jsonb, 'Average velocity = displacement/time; average speed = total path length/time.', 'med', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('7a052179-cdaf-5675-98e5-6fdca32a123e', 'neet_ug', 'Physics', 'Laws of Motion', 'A block of mass m is placed on a smooth inclined wedge ABC of inclination θ as shown in the figure. The wedge is given an acceleration ''a'' towards the right. The relation between a and θ for the block to remain stationary on the wedge is', '[{"id": "a", "text": "a = g cos θ"}, {"id": "b", "text": "a = g/sin θ"}, {"id": "c", "text": "a = g/cosec θ"}, {"id": "d", "text": "a = g tan θ"}]'::jsonb, 'd', 'In the wedge frame, the pseudo force ma cos θ up the slope balances mg sin θ, so a = g tan θ.', 'In the wedge frame a pseudo force ma acts on the block towards the left. Its component up the incline is ma cos θ, and gravity''s component down the incline is mg sin θ. Equating them gives a = g tan θ.', '{"a": "This uses the wrong components.", "b": "This exceeds g and does not balance the forces along the incline.", "c": "g/cosec θ = g sin θ, which does not balance the forces."}'::jsonb, 'In an accelerated frame, add a pseudo force −ma⃗ to apply Newton''s laws.', 'med', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', '/pyq/ug/2018/35.webp'),
('8a8ebcb4-11a8-509e-b4c8-1d758e6f54b8', 'neet_ug', 'Physics', 'System of Particles and Rotational Motion', 'The moment of the force, F⃗ = 4 î + 5 ĵ – 6 k̂ at (2, 0, – 3), about the point (2, – 2, – 2), is given by', '[{"id": "a", "text": "– 7 î – 8 ĵ – 4 k̂"}, {"id": "b", "text": "– 4 î – ĵ – 8 k̂"}, {"id": "c", "text": "– 8 î – 4 ĵ – 7 k̂"}, {"id": "d", "text": "– 7 î – 4 ĵ – 8 k̂"}]'::jsonb, 'd', 'r⃗ = (0, 2, −1); r⃗ × F⃗ = −7î − 4ĵ − 8k̂.', 'r⃗ = (2,0,−3) − (2,−2,−2) = 2ĵ − k̂. τ = r⃗ × F⃗: x = 2(−6) − (−1)(5) = −7; y = (−1)(4) − 0(−6) = −4; z = 0(5) − 2(4) = −8.', '{"a": "The ĵ and k̂ components are swapped.", "b": "The components are scrambled.", "c": "The components are scrambled."}'::jsonb, 'Torque τ⃗ = r⃗ × F⃗, where r⃗ runs from the reference point to the point of application.', 'med', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('687195e4-c00a-527d-ba3c-26aaa37ea1b5', 'neet_ug', 'Physics', 'Units and Measurements', 'A student measured the diameter of a small steel ball using a screw gauge of least count 0·001 cm. The main scale reading is 5 mm and zero of circular scale division coincides with 25 divisions above the reference level. If screw gauge has a zero error of – 0·004 cm, the correct diameter of the ball is', '[{"id": "a", "text": "0·053 cm"}, {"id": "b", "text": "0·525 cm"}, {"id": "c", "text": "0·521 cm"}, {"id": "d", "text": "0·529 cm"}]'::jsonb, 'd', 'Reading = 0·5 + 25 × 0·001 = 0·525 cm; correct = 0·525 − (−0·004) = 0·529 cm.', 'The observed reading is MSR + CSR × LC = 0·5 cm + 0·025 cm = 0·525 cm. True value = observed − zero error = 0·525 + 0·004 = 0·529 cm.', '{"a": "This drops the main scale reading.", "b": "This leaves out the zero-error correction.", "c": "This adds the zero error with the wrong sign."}'::jsonb, 'Correct reading = observed reading − zero error (with sign).', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('b537b098-4a61-54d0-ad23-cb01e03f6eea', 'neet_ug', 'Physics', 'System of Particles and Rotational Motion', 'A solid sphere is rotating freely about its symmetry axis in free space. The radius of the sphere is increased keeping its mass same. Which of the following physical quantities would remain constant for the sphere ?', '[{"id": "a", "text": "Rotational kinetic energy"}, {"id": "b", "text": "Moment of inertia"}, {"id": "c", "text": "Angular velocity"}, {"id": "d", "text": "Angular momentum"}]'::jsonb, 'd', 'No external torque acts, so angular momentum is conserved.', 'In free space there is no external torque, so L = Iω stays constant. As R grows, I rises and ω falls, and the KE L²/2I decreases.', '{"a": "KE = L²/2I falls as I increases.", "b": "I = (2/5)MR² increases with R.", "c": "ω falls to keep Iω constant."}'::jsonb, 'With zero external torque, angular momentum is conserved: I₁ω₁ = I₂ω₂.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('ae6328ae-0a4f-5735-856c-4a44ced76944', 'neet_ug', 'Physics', 'Gravitation', 'The kinetic energies of a planet in an elliptical orbit about the Sun, at positions A, B and C are K_A, K_B and K_C, respectively. AC is the major axis and SB is perpendicular to AC at the position of the Sun S as shown in the figure. Then', '[{"id": "a", "text": "K_B < K_A < K_C"}, {"id": "b", "text": "K_A > K_B > K_C"}, {"id": "c", "text": "K_A < K_B < K_C"}, {"id": "d", "text": "K_B > K_A > K_C"}]'::jsonb, 'b', 'A is nearest to the Sun (perihelion) and C farthest, so speed and KE fall from A to B to C.', 'By angular momentum conservation (Kepler''s second law), the planet moves fastest nearest the Sun. Here SA < SB < SC, so K_A > K_B > K_C.', '{"a": "A is the closest point, so K_A is the largest.", "c": "This reverses the order.", "d": "B is farther from the Sun than A, so K_B < K_A."}'::jsonb, 'A planet moves fastest at perihelion and slowest at aphelion (areal velocity is constant).', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', '/pyq/ug/2018/39.webp'),
('43b7282c-56e7-5003-af35-6733a941bde3', 'neet_ug', 'Physics', 'Gravitation', 'If the mass of the Sun were ten times smaller and the universal gravitational constant were ten times larger in magnitude, which of the following is not correct ?', '[{"id": "a", "text": "Time period of a simple pendulum on the Earth would decrease."}, {"id": "b", "text": "Walking on the ground would become more difficult."}, {"id": "c", "text": "Raindrops will fall faster."}, {"id": "d", "text": "''g'' on the Earth will not change."}]'::jsonb, 'd', 'g on Earth = GM_E/R_E² depends on Earth''s mass, not the Sun''s, so a 10× larger G makes g 10× larger.', 'Surface gravity g = GM_E/R² does not involve the Sun''s mass. Increasing G tenfold increases g tenfold, so statements (1)–(3) follow, and ''g will not change'' is false.', '{"a": "This is correct: T = 2π√(l/g) decreases when g increases.", "b": "This is correct: a larger weight makes walking harder.", "c": "This is correct: a larger g means faster falling (and a higher terminal speed)."}'::jsonb, 'Acceleration due to gravity g = GM/R² depends on the planet''s own mass.', 'med', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('827c499f-70b5-53f9-9529-7b62e527f112', 'neet_ug', 'Physics', 'System of Particles and Rotational Motion', 'A solid sphere is in rolling motion. In rolling motion a body possesses translational kinetic energy (K_t) as well as rotational kinetic energy (K_r) simultaneously. The ratio K_t : (K_t + K_r) for the sphere is', '[{"id": "a", "text": "10 : 7"}, {"id": "b", "text": "5 : 7"}, {"id": "c", "text": "7 : 10"}, {"id": "d", "text": "2 : 5"}]'::jsonb, 'b', 'K_r/K_t = k²/R² = 2/5, so K_t : K_total = 1 : 7/5 = 5 : 7.', 'K_t = ½mv² and K_r = ½(2/5 mR²)(v/R)² = (1/5)mv². The total is (7/10)mv², so K_t : K_total = (1/2) : (7/10) = 5 : 7.', '{"a": "This inverts the ratio.", "c": "7/10 is the total KE as a fraction of mv², not the ratio asked.", "d": "2 : 5 is K_r : K_t."}'::jsonb, 'For rolling, K_total = ½mv²(1 + k²/R²); for a solid sphere k²/R² = 2/5.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('425942a3-05c4-5f47-9848-778cce49de7b', 'neet_ug', 'Physics', 'Mechanical Properties of Fluids', 'A small sphere of radius ''r'' falls from rest in a viscous liquid. As a result, heat is produced due to viscous force. The rate of production of heat when the sphere attains its terminal velocity, is proportional to', '[{"id": "a", "text": "r⁵"}, {"id": "b", "text": "r²"}, {"id": "c", "text": "r³"}, {"id": "d", "text": "r⁴"}]'::jsonb, 'a', 'Power = F v_t = 6πηr v_t², and v_t ∝ r², so P ∝ r⁵.', 'At terminal velocity the heat produced per second equals the viscous power 6πηr v_t × v_t. Since v_t = 2r²(ρ − σ)g/9η ∝ r², P ∝ r × r⁴ = r⁵.', '{"b": "r² is how the terminal velocity scales, not the power.", "c": "r³ is how the weight scales.", "d": "r⁴ is v_t², without the factor of r from Stokes'' force."}'::jsonb, 'Stokes'' law F = 6πηrv; terminal velocity v_t ∝ r².', 'med', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('647e931f-a8d2-522d-91dd-6b22b925745e', 'neet_ug', 'Physics', 'Thermal Properties of Matter', 'The power radiated by a black body is P and it radiates maximum energy at wavelength, λ₀. If the temperature of the black body is now changed so that it radiates maximum energy at wavelength 3λ₀/4, the power radiated by it becomes nP. The value of n is', '[{"id": "a", "text": "256/81"}, {"id": "b", "text": "4/3"}, {"id": "c", "text": "3/4"}, {"id": "d", "text": "81/256"}]'::jsonb, 'a', 'Wien''s law gives T'' = 4T/3, and Stefan''s law gives P ∝ T⁴, so n = (4/3)⁴ = 256/81.', 'λ_m T is constant, so reducing λ_m to 3/4 raises T by a factor of 4/3. Radiated power ∝ T⁴, so n = (4/3)⁴ = 256/81.', '{"b": "4/3 is only the temperature ratio.", "c": "3/4 is the wavelength ratio.", "d": "This inverts the ratio; the power rises because T rises."}'::jsonb, 'Wien''s law: λ_m T = constant; Stefan–Boltzmann: P = σAT⁴.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('5fce2948-6c04-5792-8734-59286f877292', 'neet_ug', 'Physics', 'Mechanical Properties of Solids', 'Two wires are made of the same material and have the same volume. The first wire has cross-sectional area A and the second wire has cross-sectional area 3A. If the length of the first wire is increased by Δl on applying a force F, how much force is needed to stretch the second wire by the same amount ?', '[{"id": "a", "text": "4 F"}, {"id": "b", "text": "6 F"}, {"id": "c", "text": "9 F"}, {"id": "d", "text": "F"}]'::jsonb, 'c', 'Equal volume means L₂ = L/3; F = YAΔl/L, so F₂ = Y(3A)Δl/(L/3) = 9F.', 'F = YAΔl/L. For the second wire the area is 3A and the length is L/3 (same volume), so F₂ = Y × 3A × Δl × 3/L = 9F.', '{"a": "This adds the factors instead of multiplying them.", "b": "This miscounts one factor of 3.", "d": "This ignores the changes in area and length."}'::jsonb, 'Young''s modulus Y = (F/A)/(Δl/L); for wires of equal volume, F ∝ A².', 'med', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('30752286-3a66-53e8-94da-f1d78fc4873a', 'neet_ug', 'Physics', 'Thermodynamics', 'A sample of 0·1 g of water at 100°C and normal pressure (1·013 × 10⁵ N m⁻²) requires 54 cal of heat energy to convert to steam at 100°C. If the volume of the steam produced is 167·1 cc, the change in internal energy of the sample, is', '[{"id": "a", "text": "42·2 J"}, {"id": "b", "text": "208·7 J"}, {"id": "c", "text": "104·3 J"}, {"id": "d", "text": "84·5 J"}]'::jsonb, 'b', 'ΔU = Q − PΔV = 54 × 4·18 − 1·013×10⁵ × 167×10⁻⁶ ≈ 225·7 − 16·9 ≈ 208·8 J.', 'Q = 54 cal ≈ 225·7 J. The volume changes from 0·1 cc to 167·1 cc, so ΔV = 167 × 10⁻⁶ m³ and W = PΔV = 1·013×10⁵ × 1·67×10⁻⁴ ≈ 16·9 J. By the first law, ΔU = Q − W ≈ 208·7 J.', '{"a": "This is far too small; the heat supplied is about 226 J.", "c": "Roughly half the correct value.", "d": "This drops a large part of the supplied heat."}'::jsonb, 'First law: ΔQ = ΔU + PΔV; 1 cal ≈ 4·18 J.', 'med', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('ad947516-2bea-5d55-9ec5-d1c144d42b4b', 'neet_ug', 'Chemistry', 'Redox Reactions', 'The correct order of N-compounds in its decreasing order of oxidation states is', '[{"id": "a", "text": "HNO₃, NH₄Cl, NO, N₂"}, {"id": "b", "text": "HNO₃, NO, NH₄Cl, N₂"}, {"id": "c", "text": "HNO₃, NO, N₂, NH₄Cl"}, {"id": "d", "text": "NH₄Cl, N₂, NO, HNO₃"}]'::jsonb, 'c', 'Oxidation states of N: HNO₃ (+5) > NO (+2) > N₂ (0) > NH₄Cl (−3).', 'In HNO₃, N is +5 (1 + x − 6 = 0). In NO it is +2, in elemental N₂ it is 0, and in NH₄⁺ it is −3 (x + 4 = +1). The decreasing sequence is therefore HNO₃, NO, N₂, NH₄Cl.', '{"a": "Places NH₄Cl (−3) second, above NO and N₂.", "b": "Puts NH₄Cl (−3) above N₂ (0).", "d": "This is the increasing order, not decreasing."}'::jsonb, 'Nitrogen shows oxidation states from −3 (NH₃) to +5 (HNO₃, N₂O₅).', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('f046a0bf-c6b1-51fb-a88a-60a1bdd09b4f', 'neet_ug', 'Chemistry', 'The p-Block Elements (Group 13)', 'Which one of the following elements is unable to form MF₆³⁻ ion?', '[{"id": "a", "text": "B"}, {"id": "b", "text": "Al"}, {"id": "c", "text": "Ga"}, {"id": "d", "text": "In"}]'::jsonb, 'a', 'Boron has no d-orbitals, so its maximum covalency is 4 and it cannot form BF₆³⁻.', 'Boron, a second-period element, has only 2s and 2p orbitals, so it can hold at most four electron pairs (as in BF₄⁻). Al, Ga and In have vacant d-orbitals available, so they can expand their coordination to six and form ions such as AlF₆³⁻.', '{"b": "Al uses its 3d orbitals and forms AlF₆³⁻ (e.g. cryolite Na₃AlF₆).", "c": "Ga has d-orbitals and can show coordination number 6.", "d": "In can also expand its covalency to 6."}'::jsonb, 'Boron''s maximum covalency is 4 because it lacks d-orbitals.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('c92592df-1af1-5086-bfaa-f4059724dc42', 'neet_ug', 'Chemistry', 'The p-Block Elements (Group 13)', 'The correct order of atomic radii in group 13 elements is', '[{"id": "a", "text": "B < Ga < Al < Tl < In"}, {"id": "b", "text": "B < Al < Ga < In < Tl"}, {"id": "c", "text": "B < Al < In < Ga < Tl"}, {"id": "d", "text": "B < Ga < Al < In < Tl"}]'::jsonb, 'd', 'Ga is smaller than Al because of poor shielding by its 3d electrons, giving B < Ga < Al < In < Tl.', 'Radius normally increases down a group, but Ga follows the ten 3d electrons, which shield the nuclear charge poorly. The higher effective nuclear charge makes Ga (135 pm) slightly smaller than Al (143 pm). In (167 pm) and Tl (170 pm) then follow, so the order is B < Ga < Al < In < Tl.', '{"a": "Places Tl smaller than In; Tl is slightly larger.", "b": "Ignores the d-block contraction that makes Ga smaller than Al.", "c": "Places Ga after In, which is wrong."}'::jsonb, 'Atomic radius of Ga < Al because of the poor shielding of the intervening 3d electrons.', 'med', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('ce44bb77-c10b-5690-a30a-eb28b27068c2', 'neet_ug', 'Chemistry', 'Chemical Bonding and Molecular Structure', 'In the structure of ClF₃, the number of lone pairs of electrons on central atom ''Cl'' is', '[{"id": "a", "text": "four"}, {"id": "b", "text": "two"}, {"id": "c", "text": "one"}, {"id": "d", "text": "three"}]'::jsonb, 'b', 'Cl in ClF₃ has 7 valence electrons; 3 form bonds and the remaining 4 make two lone pairs.', 'Cl has 7 valence electrons; three are used in three Cl–F bonds, leaving 4 electrons, which are 2 lone pairs. The 5 electron pairs give sp³d hybridisation, and the two lone pairs occupy equatorial positions, giving a T-shaped molecule.', '{"a": "Four lone pairs would need 8 non-bonding electrons, which Cl does not have after bonding.", "c": "One lone pair would leave Cl with 6 bonding + 2 = 8 electrons, which is wrong for ClF₃.", "d": "Three lone pairs belong to XeF₂-type species, not ClF₃."}'::jsonb, 'ClF₃: sp³d, 3 bond pairs + 2 lone pairs, T-shaped.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('7faae7e0-8763-5e67-8c20-ded4a08b08d7', 'neet_ug', 'Chemistry', 'Alcohols, Phenols and Ethers', 'Identify the major products P, Q and R in the following sequence of reactions:
Benzene + CH₃CH₂CH₂Cl (anhydrous AlCl₃) → P
P (i) O₂, (ii) H₃O⁺/Δ → Q + R', '[{"id": "a", "text": "Option (1) in figure"}, {"id": "b", "text": "Option (2) in figure"}, {"id": "c", "text": "Option (3) in figure"}, {"id": "d", "text": "Option (4) in figure"}]'::jsonb, 'd', 'The n-propyl cation rearranges to the isopropyl cation, giving cumene (P), which forms phenol (Q) and acetone (R) by the cumene process.', 'In Friedel–Crafts alkylation, the 1° propyl carbocation undergoes a hydride shift to the more stable 2° isopropyl carbocation, so P is cumene, C₆H₅CH(CH₃)₂. Air oxidation gives cumene hydroperoxide, and acid hydrolysis of this splits it into phenol (Q) and acetone, CH₃COCH₃ (R).', '{"a": "P and Q are right, but the cumene process gives acetone, not propan-2-ol.", "b": "No rearrangement shown, and cumene oxidation does not give benzaldehyde or benzoic acid.", "c": "Ignores the carbocation rearrangement and gives wrong oxidation products."}'::jsonb, 'Cumene process: cumene + O₂ → cumene hydroperoxide → (H₃O⁺) phenol + acetone.', 'med', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', '/pyq/ug/2018/52.webp'),
('d7cf1f59-755e-5473-ae19-32cd288e8644', 'neet_ug', 'Chemistry', 'Biomolecules', 'Which of the following compounds can form a zwitterion?', '[{"id": "a", "text": "Benzoic acid"}, {"id": "b", "text": "Acetanilide"}, {"id": "c", "text": "Aniline"}, {"id": "d", "text": "Glycine"}]'::jsonb, 'd', 'Glycine has both –COOH and –NH₂, so it exists as the dipolar ion H₃N⁺–CH₂–COO⁻.', 'A zwitterion forms when one molecule has both an acidic and a basic group, so a proton moves internally from –COOH to –NH₂. Glycine (H₂N–CH₂–COOH) fits this, giving ⁺H₃N–CH₂–COO⁻. Benzoic acid has only an acidic group, aniline only a basic one, and the nitrogen in acetanilide is an amide that is barely basic.', '{"a": "Benzoic acid has no basic group to accept the proton.", "b": "The amide nitrogen of acetanilide is not basic enough, and there is no acid group.", "c": "Aniline has a basic –NH₂ but no acidic group."}'::jsonb, 'α-Amino acids exist as zwitterions in aqueous solution and in the solid state, which explains their high melting points.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('789c7fd3-1931-5ed7-92bf-fc63f08b4cb6', 'neet_ug', 'Chemistry', 'Amines', 'Nitration of aniline in strong acidic medium also gives m-nitroaniline because', '[{"id": "a", "text": "In absence of substituents nitro group always goes to m-position."}, {"id": "b", "text": "In electrophilic substitution reactions amino group is meta directive."}, {"id": "c", "text": "In spite of substituents nitro group always goes to only m-position."}, {"id": "d", "text": "In acidic (strong) medium aniline is present as anilinium ion."}]'::jsonb, 'd', 'In strong acid, –NH₂ is protonated to –NH₃⁺, which is deactivating and meta-directing.', 'Aniline is basic, so in the HNO₃/H₂SO₄ mixture a large fraction is converted to the anilinium ion, C₆H₅NH₃⁺. The –NH₃⁺ group has no lone pair to donate and withdraws electrons by its −I effect, so it directs the incoming nitronium ion to the meta position. This is why about 47% m-nitroaniline forms along with the o- and p-isomers.', '{"a": "Without a substituent there is no directing effect, so the statement is meaningless.", "b": "Free –NH₂ is a strong ortho/para director.", "c": "The position of nitration is governed by the substituent already present."}'::jsonb, 'Direct nitration of aniline gives p- (51%), m- (47%) and o- (2%) nitroaniline because of anilinium ion formation.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('55c2cd20-6e8b-5ab1-bfba-a65ad1b9ebae', 'neet_ug', 'Chemistry', 'Biomolecules', 'The difference between amylose and amylopectin is', '[{"id": "a", "text": "Amylopectin have 1 → 4 α-linkage and 1 → 6 β-linkage"}, {"id": "b", "text": "Amylose have 1 → 4 α-linkage and 1 → 6 β-linkage"}, {"id": "c", "text": "Amylopectin have 1 → 4 α-linkage and 1 → 6 α-linkage"}, {"id": "d", "text": "Amylose is made up of glucose and galactose"}]'::jsonb, 'c', 'Amylopectin is branched: its chain has C1→C4 α-glycosidic links and its branches have C1→C6 α-links.', 'Amylose is an unbranched chain of α-D-glucose joined only by C1–C4 α-glycosidic bonds. Amylopectin is branched: the main chain is C1–C4 α-linked, and the branch points are C1–C6 α-glycosidic linkages. Both are made only of α-D-glucose, and starch has no β-linkages.', '{"a": "The branch linkage in amylopectin is α, not β.", "b": "Amylose has no 1→6 branches, and starch has no β-links.", "d": "Amylose contains only α-D-glucose units."}'::jsonb, 'Starch = amylose (15–20%, water-soluble, linear) + amylopectin (80–85%, insoluble, branched).', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('436bca9f-fc7e-5947-9cb7-60ec04a7959e', 'neet_ug', 'Chemistry', 'Some Basic Concepts of Chemistry', 'A mixture of 2·3 g formic acid and 4·5 g oxalic acid is treated with conc. H₂SO₄. The evolved gaseous mixture is passed through KOH pellets. Weight (in g) of the remaining product at STP will be', '[{"id": "a", "text": "2·8"}, {"id": "b", "text": "3·0"}, {"id": "c", "text": "1·4"}, {"id": "d", "text": "4·4"}]'::jsonb, 'a', 'Only CO remains after KOH absorbs CO₂: 0·05 + 0·05 = 0·1 mol CO = 2·8 g.', 'Concentrated H₂SO₄ dehydrates HCOOH → CO + H₂O and H₂C₂O₄ → CO + CO₂ + H₂O. Formic acid: 2·3/46 = 0·05 mol, which gives 0·05 mol CO. Oxalic acid: 4·5/90 = 0·05 mol, which gives 0·05 mol CO and 0·05 mol CO₂. KOH absorbs CO₂ (and moisture), leaving 0·1 mol CO = 0·1 × 28 = 2·8 g.', '{"b": "Does not correspond to any real combination of the gases.", "c": "Counts the CO from only one of the acids.", "d": "This is the mass of 0·1 mol CO₂, but CO₂ is absorbed by KOH."}'::jsonb, 'Conc. H₂SO₄ dehydrates formic acid to CO and oxalic acid to CO + CO₂.', 'med', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('1fdd8a41-6dad-5afc-a55b-83d1f7a45829', 'neet_ug', 'Chemistry', 'Alcohols, Phenols and Ethers', 'The compound A on treatment with Na gives B, and with PCl₅ gives C. B and C react together to give diethyl ether. A, B and C are in the order', '[{"id": "a", "text": "C₂H₅Cl, C₂H₆, C₂H₅OH"}, {"id": "b", "text": "C₂H₅OH, C₂H₅Cl, C₂H₅ONa"}, {"id": "c", "text": "C₂H₅OH, C₂H₆, C₂H₅Cl"}, {"id": "d", "text": "C₂H₅OH, C₂H₅ONa, C₂H₅Cl"}]'::jsonb, 'd', 'Ethanol gives sodium ethoxide with Na and ethyl chloride with PCl₅, and these two form diethyl ether by Williamson synthesis.', 'A = C₂H₅OH. With Na it gives B = C₂H₅ONa (+ ½H₂), and with PCl₅ it gives C = C₂H₅Cl. In Williamson ether synthesis, C₂H₅ONa + C₂H₅Cl → C₂H₅OC₂H₅ + NaCl.', '{"a": "Ethyl chloride with Na gives butane (Wurtz), not ethane.", "b": "B and C are swapped: Na gives the alkoxide and PCl₅ the chloride.", "c": "Alcohol + Na gives an alkoxide, not ethane."}'::jsonb, 'Williamson synthesis: R–ONa + R′–X → R–O–R′ + NaX (best with a 1° alkyl halide).', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('3ae560db-ce15-50e4-b9da-5bf672476edd', 'neet_ug', 'Chemistry', 'Haloalkanes and Haloarenes', 'The compound C₇H₈ undergoes the following reactions:
C₇H₈ —(3 Cl₂/Δ)→ A —(Br₂/Fe)→ B —(Zn/HCl)→ C
The product ''C'' is', '[{"id": "a", "text": "3-bromo-2,4,6-trichlorotoluene"}, {"id": "b", "text": "o-bromotoluene"}, {"id": "c", "text": "m-bromotoluene"}, {"id": "d", "text": "p-bromotoluene"}]'::jsonb, 'c', 'Side-chain chlorination gives C₆H₅CCl₃, a meta director, so bromination goes meta, and reducing CCl₃ back to CH₃ gives m-bromotoluene.', 'Toluene with 3 Cl₂ under heat (free-radical side-chain substitution) gives benzotrichloride, C₆H₅CCl₃ (A). The –CCl₃ group is strongly electron-withdrawing and meta-directing, so Br₂/Fe gives m-bromobenzotrichloride (B). Zn/HCl reduces –CCl₃ to –CH₃, so C is m-bromotoluene.', '{"a": "Heating with Cl₂ chlorinates the side chain, not the ring.", "b": "o-Substitution would need CH₃ as the director, but at that stage the group is CCl₃.", "d": "p-Bromotoluene forms on brominating toluene directly, not via C₆H₅CCl₃."}'::jsonb, 'Halogenation in light/heat substitutes the side chain; with Fe/FeX₃ (Lewis acid) it substitutes the ring.', 'med', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('dca40195-80b4-5a8f-96b0-684b5ef42573', 'neet_ug', 'Chemistry', 'Hydrocarbons', 'Hydrocarbon (A) reacts with bromine by substitution to form an alkyl bromide which by Wurtz reaction is converted to gaseous hydrocarbon containing less than four carbon atoms. (A) is', '[{"id": "a", "text": "CH₃ – CH₃"}, {"id": "b", "text": "CH₂ = CH₂"}, {"id": "c", "text": "CH ≡ CH"}, {"id": "d", "text": "CH₄"}]'::jsonb, 'd', 'CH₄ → CH₃Br → (Wurtz) CH₃–CH₃, which has only two carbons.', 'Wurtz coupling doubles the carbon count of the alkyl group. Methane gives CH₃Br by substitution, and 2CH₃Br + 2Na → C₂H₆, a gas with fewer than four carbons. Ethane would give C₂H₅Br and then butane (4 C), while ethene and ethyne add bromine instead of substituting it.', '{"a": "Ethane would lead to butane, which has four carbon atoms.", "b": "Ethene undergoes addition, not substitution, with Br₂.", "c": "Ethyne undergoes addition with Br₂."}'::jsonb, 'Wurtz reaction: 2R–X + 2Na (dry ether) → R–R + 2NaX; it is not useful for methane synthesis.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('f92b1230-673b-5884-b434-f0d04be7d803', 'neet_ug', 'Chemistry', 'Organic Chemistry – Some Basic Principles and Techniques', 'Which of the following molecules represents the order of hybridisation sp², sp², sp, sp from left to right atoms?', '[{"id": "a", "text": "CH₂ = CH – CH = CH₂"}, {"id": "b", "text": "CH₂ = CH – C ≡ CH"}, {"id": "c", "text": "HC ≡ C – C ≡ CH"}, {"id": "d", "text": "CH₃ – CH = CH – CH₃"}]'::jsonb, 'b', 'In vinylacetylene, CH₂=CH– carbons are sp² and –C≡CH carbons are sp.', 'A doubly bonded carbon is sp² and a triply bonded carbon is sp. In CH₂=CH–C≡CH, C1 and C2 form the C=C bond (sp², sp²) and C3 and C4 form the C≡C bond (sp, sp). This matches the required sequence.', '{"a": "All four carbons are sp².", "c": "All four carbons are sp.", "d": "The order is sp³, sp², sp², sp³."}'::jsonb, 's-character: sp (50%) > sp² (33%) > sp³ (25%); higher s-character means a more electronegative carbon.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('93d69a17-e9a6-552b-ba76-a7b383c28762', 'neet_ug', 'Chemistry', 'Organic Chemistry – Some Basic Principles and Techniques', 'Which of the following carbocations is expected to be most stable?', '[{"id": "a", "text": "Option (1) in figure"}, {"id": "b", "text": "Option (2) in figure"}, {"id": "c", "text": "Option (3) in figure"}, {"id": "d", "text": "Option (4) in figure"}]'::jsonb, 'a', 'With NO₂ meta to the sp³ carbon, the positive charge never sits on the carbon bearing the electron-withdrawing NO₂.', 'In an arenium (σ-complex) ion the positive charge is delocalised onto the carbons ortho and para to the sp³ carbon. In (1), NO₂ is meta to the sp³ carbon, so no resonance form puts the + charge next to the –NO₂ group. In (2), (3) and (4), NO₂ is para or ortho, so one resonance structure puts the + on the carbon attached to NO₂, which is strongly destabilising.', '{"b": "NO₂ is directly on the positively charged carbon, which is highly destabilised.", "c": "NO₂ is para to the sp³ carbon, so a contributing structure puts + on the C–NO₂ carbon.", "d": "NO₂ is ortho to the sp³ carbon and carries the + charge, which is destabilised."}'::jsonb, '–NO₂ is a meta director because the meta σ-complex avoids a + charge on the ring carbon bearing NO₂.', 'hard', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', '/pyq/ug/2018/64.webp'),
('39c82c76-335b-5223-8625-55810c876621', 'neet_ug', 'Chemistry', 'Alcohols, Phenols and Ethers', 'In the reaction
Phenol + CHCl₃ + NaOH → sodium o-formylphenoxide (o-O⁻Na⁺–C₆H₄–CHO)
the electrophile involved is', '[{"id": "a", "text": "dichloromethyl anion (⁻CHCl₂)"}, {"id": "b", "text": "formyl cation (⁺CHO)"}, {"id": "c", "text": "dichloromethyl cation (⁺CHCl₂)"}, {"id": "d", "text": "dichlorocarbene (:CCl₂)"}]'::jsonb, 'd', 'In the Reimer–Tiemann reaction, base removes HCl from CHCl₃ to give the electron-deficient electrophile :CCl₂.', 'OH⁻ removes a proton from CHCl₃ to give ⁻CCl₃, which loses Cl⁻ to form dichlorocarbene, :CCl₂. This neutral species has only six electrons and attacks the electron-rich ortho position of the phenoxide ion. Hydrolysis of the –CHCl₂ intermediate then gives the –CHO group (salicylaldehyde after acidification).', '{"a": "An anion is a nucleophile and cannot attack the electron-rich ring.", "b": "The formyl cation is the electrophile in Gattermann–Koch formylation, not in Reimer–Tiemann.", "c": "⁺CHCl₂ is not generated in strongly basic medium."}'::jsonb, 'Reimer–Tiemann: phenol + CHCl₃ + aq. NaOH → salicylaldehyde via a dichlorocarbene electrophile.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', '/pyq/ug/2018/66.webp'),
('2f5b2a98-c329-5436-a24f-8a4b76e5dd21', 'neet_ug', 'Chemistry', 'Aldehydes, Ketones and Carboxylic Acids', 'Carboxylic acids have higher boiling points than aldehydes, ketones and even alcohols of comparable molecular mass. It is due to their', '[{"id": "a", "text": "more extensive association of carboxylic acid via van der Waals force of attraction"}, {"id": "b", "text": "formation of carboxylate ion"}, {"id": "c", "text": "formation of intramolecular H-bonding"}, {"id": "d", "text": "formation of intermolecular H-bonding"}]'::jsonb, 'd', 'Carboxylic acids form strong intermolecular H-bonded dimers, which persist even in the vapour phase.', 'Each –COOH group can act as both an H-bond donor (O–H) and acceptor (C=O), so two molecules pair into a cyclic dimer held by two hydrogen bonds. This intermolecular association is stronger and more extensive than in alcohols and is absent in aldehydes and ketones, so carboxylic acids have higher boiling points.', '{"a": "Van der Waals forces are similar for compounds of comparable mass, so they cannot explain the difference.", "b": "Carboxylic acids barely ionise in the pure liquid.", "c": "Intramolecular H-bonding would lower, not raise, the boiling point."}'::jsonb, 'Carboxylic acids exist as H-bonded dimers in the vapour phase and in aprotic solvents.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('c0e0eef3-0fc9-5b30-9641-f3c0ea65f291', 'neet_ug', 'Chemistry', 'Aldehydes, Ketones and Carboxylic Acids', 'Compound A, C₈H₁₀O, is found to react with NaOI (produced by reacting Y with NaOH) and yields a yellow precipitate with characteristic smell.
A and Y are respectively', '[{"id": "a", "text": "C₆H₅–CH(OH)–CH₃ and I₂"}, {"id": "b", "text": "C₆H₅–CH₂–CH₂–OH and I₂"}, {"id": "c", "text": "H₃C–C₆H₄–CH₂–OH (p-methylbenzyl alcohol) and I₂"}, {"id": "d", "text": "CH₃–C₆H₃(CH₃)–OH (2,4-dimethylphenol) and I₂"}]'::jsonb, 'a', '1-Phenylethanol has the CH₃CH(OH)– unit, so it gives the iodoform test with NaOI made from I₂ + NaOH.', 'The yellow precipitate with a characteristic smell is iodoform, CHI₃. NaOI is made from Y = I₂ and NaOH. Only compounds with a CH₃CO– or CH₃CH(OH)– group respond, and 1-phenylethanol, C₆H₅CH(OH)CH₃ (C₈H₁₀O), is first oxidised to acetophenone and then gives CHI₃.', '{"b": "2-Phenylethanol has no CH₃CH(OH)– group.", "c": "A benzylic 1° alcohol with no methyl carbinol group gives no iodoform.", "d": "A phenol does not give the iodoform test."}'::jsonb, 'Iodoform test is positive for CH₃CO–R, CH₃CH(OH)–R, ethanol and acetaldehyde.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('ef82ced9-ea82-5926-83b7-9953c4a00309', 'neet_ug', 'Chemistry', 'The d- and f-Block Elements', 'Match the metal ions given in Column I with the spin magnetic moments of the ions given in Column II and assign the correct code:
Column I | Column II
a. Co³⁺ | i. √8 B.M.
b. Cr³⁺ | ii. √35 B.M.
c. Fe³⁺ | iii. √3 B.M.
d. Ni²⁺ | iv. √24 B.M.
 | v. √15 B.M.', '[{"id": "a", "text": "a-iv, b-i, c-ii, d-iii"}, {"id": "b", "text": "a-i, b-ii, c-iii, d-iv"}, {"id": "c", "text": "a-iv, b-v, c-ii, d-i"}, {"id": "d", "text": "a-iii, b-v, c-i, d-ii"}]'::jsonb, 'c', 'μ = √[n(n+2)]: Co³⁺ (4 unpaired) √24, Cr³⁺ (3) √15, Fe³⁺ (5) √35, Ni²⁺ (2) √8.', 'As free ions: Co³⁺ is 3d⁶ with 4 unpaired electrons, so μ = √(4×6) = √24. Cr³⁺ is 3d³ with n = 3, so μ = √15. Fe³⁺ is 3d⁵ with n = 5, so μ = √35. Ni²⁺ is 3d⁸ with n = 2, so μ = √8. This gives a-iv, b-v, c-ii, d-i.', '{"a": "Gives Cr³⁺ √8 and Ni²⁺ √3, which do not match their unpaired electrons.", "b": "Simply pairs the lists in order, ignoring electron counts.", "d": "Assigns √3 (one unpaired electron) to Co³⁺, which has four."}'::jsonb, 'Spin-only magnetic moment μ = √[n(n+2)] B.M., where n = number of unpaired electrons.', 'med', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('f474a91d-e584-53d7-b44f-8e29d5873456', 'neet_ug', 'Chemistry', 'The d- and f-Block Elements', 'Which one of the following ions exhibits d-d transition and paramagnetism as well?', '[{"id": "a", "text": "MnO₄⁻"}, {"id": "b", "text": "Cr₂O₇²⁻"}, {"id": "c", "text": "CrO₄²⁻"}, {"id": "d", "text": "MnO₄²⁻"}]'::jsonb, 'd', 'In manganate, Mn is +6 (3d¹), so it has one unpaired d electron: it is paramagnetic and can show d-d transitions.', 'MnO₄⁻ (Mn +7), Cr₂O₇²⁻ and CrO₄²⁻ (Cr +6) are all d⁰, so they are diamagnetic, and their intense colours come from ligand-to-metal charge transfer rather than d-d transitions. In MnO₄²⁻, Mn is +6 with a 3d¹ configuration, so its single unpaired electron makes it paramagnetic and allows a d-d transition.', '{"a": "Mn(+7) is d⁰, diamagnetic, and coloured by charge transfer.", "b": "Cr(+6) is d⁰, so there is no d-d transition and it is diamagnetic.", "c": "Cr(+6) is d⁰, so there is no d-d transition and it is diamagnetic."}'::jsonb, 'Colour of d⁰ oxo-anions like MnO₄⁻ and CrO₄²⁻ is due to charge transfer, not d-d transitions.', 'med', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('cb13e3db-cc44-5461-adb1-db2714a0c859', 'neet_ug', 'Chemistry', 'Coordination Compounds', 'Iron carbonyl, Fe(CO)₅ is', '[{"id": "a", "text": "trinuclear"}, {"id": "b", "text": "mononuclear"}, {"id": "c", "text": "tetranuclear"}, {"id": "d", "text": "dinuclear"}]'::jsonb, 'b', 'Fe(CO)₅ contains a single Fe atom, so it is mononuclear.', 'The nuclearity of a carbonyl is the number of metal atoms in one molecule. Fe(CO)₅ has one iron centre surrounded by five CO ligands in a trigonal bipyramid. Fe₂(CO)₉ and Fe₃(CO)₁₂ are the dinuclear and trinuclear iron carbonyls.', '{"a": "Trinuclear is Fe₃(CO)₁₂.", "c": "Tetranuclear carbonyls (e.g. Co₄(CO)₁₂) have four metal atoms.", "d": "Dinuclear is Fe₂(CO)₉ or Co₂(CO)₈."}'::jsonb, 'Fe(CO)₅ is trigonal bipyramidal; Ni(CO)₄ is tetrahedral; Cr(CO)₆ is octahedral.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('8df6b36b-5df5-56c1-ba09-b4a7e3d8d5e8', 'neet_ug', 'Chemistry', 'Coordination Compounds', 'The type of isomerism shown by the complex [CoCl₂(en)₂] is', '[{"id": "a", "text": "Ionization isomerism"}, {"id": "b", "text": "Coordination isomerism"}, {"id": "c", "text": "Geometrical isomerism"}, {"id": "d", "text": "Linkage isomerism"}]'::jsonb, 'c', 'Octahedral [M(AA)₂B₂] complexes have cis and trans forms, which is geometrical isomerism.', 'In [CoCl₂(en)₂], the two Cl⁻ ligands can be adjacent (cis) or opposite (trans) in the octahedron, so it shows geometrical isomerism. The cis form is also optically active. There is no counter-ion to exchange, no ambidentate ligand and no complex cation–anion pair, so ionization, linkage and coordination isomerism are not possible.', '{"a": "Requires an exchangeable counter-ion outside the coordination sphere.", "b": "Needs both a cationic and an anionic complex in one salt.", "d": "Requires an ambidentate ligand such as NO₂⁻ or SCN⁻."}'::jsonb, 'cis-[CoCl₂(en)₂]⁺ is optically active; the trans isomer is optically inactive.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('31c8efd3-3731-5dcc-8325-5a9326d25341', 'neet_ug', 'Chemistry', 'Coordination Compounds', 'The geometry and magnetic behaviour of the complex [Ni(CO)₄] are', '[{"id": "a", "text": "square planar geometry and paramagnetic"}, {"id": "b", "text": "tetrahedral geometry and diamagnetic"}, {"id": "c", "text": "square planar geometry and diamagnetic"}, {"id": "d", "text": "tetrahedral geometry and paramagnetic"}]'::jsonb, 'b', 'Ni(0) is 3d¹⁰ in Ni(CO)₄; it is sp³ hybridised, so it is tetrahedral and diamagnetic.', 'Ni in Ni(CO)₄ is in the zero oxidation state (3d⁸4s²). The strong-field CO ligand pairs the electrons into 3d¹⁰, leaving 4s and 4p empty for sp³ hybridisation. The result is a tetrahedral complex with no unpaired electrons, so it is diamagnetic.', '{"a": "Square planar (dsp²) geometry is seen in d⁸ complexes like [Ni(CN)₄]²⁻, not in Ni(0) carbonyl.", "c": "The geometry is wrong; Ni(CO)₄ is tetrahedral.", "d": "Ni(CO)₄ has no unpaired electrons."}'::jsonb, '[Ni(CO)₄]: sp³, tetrahedral, diamagnetic; [NiCl₄]²⁻: sp³, paramagnetic; [Ni(CN)₄]²⁻: dsp², square planar, diamagnetic.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('e979ec46-cdda-5fe3-b4d9-4b6d1420c174', 'neet_ug', 'Chemistry', 'Equilibrium', 'Following solutions were prepared by mixing different volumes of NaOH and HCl of different concentrations:
a. 60 mL M/10 HCl + 40 mL M/10 NaOH
b. 55 mL M/10 HCl + 45 mL M/10 NaOH
c. 75 mL M/5 HCl + 25 mL M/5 NaOH
d. 100 mL M/10 HCl + 100 mL M/10 NaOH
pH of which one of them will be equal to 1?', '[{"id": "a", "text": "d"}, {"id": "b", "text": "a"}, {"id": "c", "text": "b"}, {"id": "d", "text": "c"}]'::jsonb, 'd', 'Only mixture c leaves 0·1 M excess H⁺: (15 − 5) mmol in 100 mL.', 'Calculate the excess HCl in mmol. a: 6 − 4 = 2 mmol/100 mL = 0·02 M, pH ≈ 1·7. b: 5·5 − 4·5 = 1 mmol/100 mL = 0·01 M, pH = 2. c: 75 × 0·2 − 25 × 0·2 = 15 − 5 = 10 mmol/100 mL = 0·1 M, pH = 1. d: neutral, pH = 7. So the answer is mixture c, option (4).', '{"a": "Mixture d is exactly neutralised (pH 7).", "b": "Mixture a gives [H⁺] = 0·02 M, pH ≈ 1·7.", "c": "Mixture b gives [H⁺] = 0·01 M, pH = 2."}'::jsonb, 'For a strong acid–strong base mixture, pH = −log[(excess mmol H⁺)/(total volume in mL)].', 'med', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('42a10430-623a-58fe-bf26-542fcd86c14e', 'neet_ug', 'Chemistry', 'Equilibrium', 'The solubility of BaSO₄ in water is 2·42 × 10⁻³ g L⁻¹ at 298 K. The value of its solubility product (Ksp) will be
(Given molar mass of BaSO₄ = 233 g mol⁻¹)', '[{"id": "a", "text": "1·08 × 10⁻¹⁴ mol² L⁻²"}, {"id": "b", "text": "1·08 × 10⁻¹² mol² L⁻²"}, {"id": "c", "text": "1·08 × 10⁻¹⁰ mol² L⁻²"}, {"id": "d", "text": "1·08 × 10⁻⁸ mol² L⁻²"}]'::jsonb, 'c', 's = 2·42 × 10⁻³/233 = 1·04 × 10⁻⁵ M, so Ksp = s² = 1·08 × 10⁻¹⁰.', 'Molar solubility s = 2·42 × 10⁻³ g L⁻¹ ÷ 233 g mol⁻¹ = 1·039 × 10⁻⁵ mol L⁻¹. For BaSO₄ ⇌ Ba²⁺ + SO₄²⁻, Ksp = s × s = (1·039 × 10⁻⁵)² = 1·08 × 10⁻¹⁰ mol² L⁻².', '{"a": "Off by 10⁻⁴; the exponent of s was handled wrongly.", "b": "Off by 10⁻²; the squaring of 10⁻⁵ was miscalculated.", "d": "Too large; it corresponds to s ≈ 10⁻⁴ M."}'::jsonb, 'For an AB-type salt, Ksp = s²; for AB₂, Ksp = 4s³.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('64b97a37-ffaf-51b3-8468-beee9dd4b8a6', 'neet_ug', 'Chemistry', 'Some Basic Concepts of Chemistry', 'In which case is the number of molecules of water maximum?', '[{"id": "a", "text": "0·00224 L of water vapours at 1 atm and 273 K"}, {"id": "b", "text": "0·18 g of water"}, {"id": "c", "text": "18 mL of water"}, {"id": "d", "text": "10⁻³ mol of water"}]'::jsonb, 'c', '18 mL of liquid water (density 1 g mL⁻¹) is 18 g = 1 mol, far more than the others.', '(1) 0·00224 L at STP = 0·00224/22·4 = 10⁻⁴ mol. (2) 0·18 g/18 = 10⁻² mol. (3) 18 mL × 1 g mL⁻¹ = 18 g = 1 mol. (4) 10⁻³ mol. The largest number of moles, and so of molecules, is in 18 mL of water (6·022 × 10²³ molecules).', '{"a": "Only 10⁻⁴ mol of molecules.", "b": "Only 10⁻² mol.", "d": "Only 10⁻³ mol."}'::jsonb, 'Number of molecules = moles × Nₐ; 1 mol of gas at STP occupies 22·4 L.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('ca569ad0-3173-57ee-bde7-ffbb51bd0e33', 'neet_ug', 'Chemistry', 'Chemical Kinetics', 'The correct difference between first- and second-order reactions is that', '[{"id": "a", "text": "a first-order reaction can be catalyzed; a second-order reaction cannot be catalyzed"}, {"id": "b", "text": "the half-life of a first-order reaction does not depend on [A]₀; the half-life of a second-order reaction does depend on [A]₀"}, {"id": "c", "text": "the rate of a first-order reaction does not depend on reactant concentrations; the rate of a second-order reaction does depend on reactant concentrations"}, {"id": "d", "text": "the rate of a first-order reaction does depend on reactant concentrations; the rate of a second-order reaction does not depend on reactant concentrations"}]'::jsonb, 'b', 'First-order t½ = 0·693/k is independent of [A]₀, while second-order t½ = 1/(k[A]₀) depends on it.', 'For first order, t½ = 0·693/k, which has no concentration term. For second order (rate = k[A]²), t½ = 1/(k[A]₀), so it changes with the initial concentration. The rates of both orders depend on concentration, and reactions of any order can be catalysed.', '{"a": "Catalysis is possible whatever the order.", "c": "A first-order rate is k[A], so it does depend on concentration.", "d": "A second-order rate depends on the square of concentration."}'::jsonb, 't½ ∝ [A]₀^(1−n) for an nth-order reaction.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('3b4e45b0-c15b-5ede-b58b-a2fd118cd967', 'neet_ug', 'Chemistry', 'Electrochemistry', 'Consider the change in oxidation state of Bromine corresponding to different emf values as shown in the diagram below:
BrO₄⁻ —(1·82 V)→ BrO₃⁻ —(1·5 V)→ HBrO —(1·595 V)→ Br₂ —(1·0652 V)→ Br⁻
Then the species undergoing disproportionation is', '[{"id": "a", "text": "Br₂"}, {"id": "b", "text": "BrO₄⁻"}, {"id": "c", "text": "BrO₃⁻"}, {"id": "d", "text": "HBrO"}]'::jsonb, 'd', 'HBrO disproportionates because E°(HBrO→Br₂) = 1·595 V is greater than E°(BrO₃⁻→HBrO) = 1·5 V, which gives a positive E°cell.', 'A species disproportionates when the reduction potential to its right is greater than the one to its left. For HBrO: E°cell = E°(HBrO/Br₂) − E°(BrO₃⁻/HBrO) = 1·595 − 1·5 = +0·095 V > 0, so ΔG° < 0 and the change is spontaneous. For Br₂: 1·0652 − 1·595 < 0, and for BrO₃⁻: 1·5 − 1·82 < 0, so neither disproportionates. BrO₄⁻ is the highest oxidation state and cannot be oxidised further.', '{"a": "E°cell = 1·0652 − 1·595 = −0·53 V, which is non-spontaneous.", "b": "Bromine in BrO₄⁻ is at +7, the maximum, so it cannot be oxidised.", "c": "E°cell = 1·5 − 1·82 = −0·32 V, which is non-spontaneous."}'::jsonb, 'In a Latimer diagram, a species disproportionates if E°(right) > E°(left).', 'med', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', '/pyq/ug/2018/81.webp'),
('0ecc6260-2a86-57a1-9e1f-a175e4a76707', 'neet_ug', 'Chemistry', 'Redox Reactions', 'For the redox reaction
MnO₄⁻ + C₂O₄²⁻ + H⁺ → Mn²⁺ + CO₂ + H₂O
the correct coefficients of the reactants for the balanced equation are
MnO₄⁻ | C₂O₄²⁻ | H⁺', '[{"id": "a", "text": "2, 16, 5"}, {"id": "b", "text": "2, 5, 16"}, {"id": "c", "text": "16, 5, 2"}, {"id": "d", "text": "5, 16, 2"}]'::jsonb, 'b', '2MnO₄⁻ + 5C₂O₄²⁻ + 16H⁺ → 2Mn²⁺ + 10CO₂ + 8H₂O.', 'Mn changes from +7 to +2, gaining 5e⁻ per MnO₄⁻. Each C₂O₄²⁻ goes to 2CO₂, losing 2e⁻. Equalising electrons (10) needs 2MnO₄⁻ and 5C₂O₄²⁻. Balancing O with H₂O (8 H₂O for 8 O lost from the permanganate) then needs 16 H⁺.', '{"a": "The oxalate and H⁺ coefficients are swapped.", "c": "Does not balance the electron transfer.", "d": "Neither electrons nor charge balance."}'::jsonb, 'In acidic medium KMnO₄ is a 5-electron oxidant (n-factor 5), and oxalate has n-factor 2.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('6a518f00-5987-5458-98e1-44e833b76c0d', 'neet_ug', 'Chemistry', 'Equilibrium', 'Which one of the following conditions will favour maximum formation of the product in the reaction,
A₂(g) + B₂(g) ⇌ X₂(g)  ΔrH = – X kJ?', '[{"id": "a", "text": "High temperature and high pressure"}, {"id": "b", "text": "Low temperature and low pressure"}, {"id": "c", "text": "Low temperature and high pressure"}, {"id": "d", "text": "High temperature and low pressure"}]'::jsonb, 'c', 'The forward reaction is exothermic and decreases gas moles (2 → 1), so low T and high P favour the product.', 'By Le Chatelier''s principle, lowering the temperature favours the exothermic forward reaction (ΔH < 0). Since 2 mol of gas give 1 mol, raising the pressure shifts the equilibrium towards fewer moles, i.e. towards X₂. So low temperature and high pressure maximise the product.', '{"a": "High temperature favours the endothermic backward reaction.", "b": "Low pressure favours the side with more gas moles (the reactants).", "d": "Both conditions favour the reactants."}'::jsonb, 'Le Chatelier: increasing pressure shifts the equilibrium towards fewer gaseous moles.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('08729a67-a79b-581c-963b-f91e6440d48b', 'neet_ug', 'Chemistry', 'Chemical Kinetics', 'When initial concentration of the reactant is doubled, the half-life period of a zero order reaction', '[{"id": "a", "text": "is tripled"}, {"id": "b", "text": "is doubled"}, {"id": "c", "text": "is halved"}, {"id": "d", "text": "remains unchanged"}]'::jsonb, 'b', 'For zero order, t½ = [A]₀/2k, so it is directly proportional to [A]₀.', 'The integrated zero-order law is [A] = [A]₀ − kt. Setting [A] = [A]₀/2 gives t½ = [A]₀/(2k). Doubling [A]₀ therefore doubles the half-life.', '{"a": "Half-life varies linearly, not threefold.", "c": "Halving happens for second order (t½ ∝ 1/[A]₀).", "d": "Unchanged half-life is characteristic of first order."}'::jsonb, 'Zero order: t½ ∝ [A]₀; first order: independent; second order: ∝ 1/[A]₀.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('59a48bf7-4a16-50b7-8fd9-5e8d78bcc51b', 'neet_ug', 'Chemistry', 'Thermodynamics', 'The bond dissociation energies of X₂, Y₂ and XY are in the ratio of 1 : 0·5 : 1. ΔH for the formation of XY is – 200 kJ mol⁻¹. The bond dissociation energy of X₂ will be', '[{"id": "a", "text": "800 kJ mol⁻¹"}, {"id": "b", "text": "100 kJ mol⁻¹"}, {"id": "c", "text": "200 kJ mol⁻¹"}, {"id": "d", "text": "400 kJ mol⁻¹"}]'::jsonb, 'a', '½X₂ + ½Y₂ → XY: −200 = ½a + ¼a − a = −a/4, so a = 800 kJ mol⁻¹.', 'Let BDE(X₂) = a, BDE(Y₂) = 0·5a and BDE(XY) = a. For ½X₂ + ½Y₂ → XY, ΔH = Σ(bonds broken) − Σ(bonds formed) = 0·5a + 0·25a − a = −0·25a. Setting −0·25a = −200 gives a = 800 kJ mol⁻¹.', '{"b": "Comes from wrongly multiplying instead of dividing by 0·25.", "c": "Takes ΔH itself as the BDE.", "d": "Forgets that formation uses only ½ mol of each diatomic, i.e. writes X₂ + Y₂ → 2XY with ΔH = −200."}'::jsonb, 'ΔH(reaction) = Σ BE(reactants) − Σ BE(products), always with the stoichiometry for 1 mol of product.', 'med', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('b4ced231-85a9-5cb4-83a3-1926cb0c4a46', 'neet_ug', 'Chemistry', 'Chemical Bonding and Molecular Structure', 'Consider the following species:
CN⁺, CN⁻, NO and CN
Which one of these will have the highest bond order?', '[{"id": "a", "text": "CN⁺"}, {"id": "b", "text": "CN⁻"}, {"id": "c", "text": "NO"}, {"id": "d", "text": "CN"}]'::jsonb, 'b', 'CN⁻ (14 electrons, isoelectronic with N₂) has bond order 3, the highest.', 'Using MO theory, bond order = (Nb − Na)/2. CN⁺ has 12 electrons, giving BO = 2. CN has 13 electrons, giving 2·5. NO has 15 electrons, giving 2·5 (the extra electron goes into π*). CN⁻ has 14 electrons, isoelectronic with N₂, giving BO = 3.', '{"a": "12 electrons, bond order 2.", "c": "15 electrons, bond order 2·5.", "d": "13 electrons, bond order 2·5."}'::jsonb, 'Species with 14 electrons (N₂, CO, CN⁻, NO⁺) have bond order 3.', 'med', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('b70d8b6e-a6d0-5819-b12c-f8400691f418', 'neet_ug', 'Chemistry', 'Classification of Elements and Periodicity in Properties', 'Magnesium reacts with an element (X) to form an ionic compound. If the ground state electronic configuration of (X) is 1s² 2s² 2p³, the simplest formula for this compound is', '[{"id": "a", "text": "Mg₂X"}, {"id": "b", "text": "MgX₂"}, {"id": "c", "text": "Mg₂X₃"}, {"id": "d", "text": "Mg₃X₂"}]'::jsonb, 'd', 'X is nitrogen (valency 3, forms N³⁻) and Mg forms Mg²⁺, giving Mg₃N₂.', '1s² 2s² 2p³ is nitrogen, which gains 3 electrons to become N³⁻. Magnesium loses 2 electrons to become Mg²⁺. Balancing the charges, 3 × (+2) = 2 × (−3), gives Mg₃X₂, i.e. magnesium nitride Mg₃N₂.', '{"a": "Would need X²⁻ (like oxide), not N³⁻.", "b": "Would need X⁻ (like halide).", "c": "Charges do not balance: 2(+2) ≠ 3(−3)."}'::jsonb, 'Mg burns in air to give MgO and Mg₃N₂; Mg₃N₂ reacts with water to release NH₃.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('e139c235-1b98-58e6-b439-5cdc5acdd758', 'neet_ug', 'Chemistry', 'Structure of Atom', 'Which one is a wrong statement?', '[{"id": "a", "text": "The electronic configuration of N atom is 1s² 2s² 2pₓ¹ 2p_y¹ 2p_z¹ (box diagram shown, with the 2p_z electron drawn with opposite spin)"}, {"id": "b", "text": "An orbital is designated by three quantum numbers while an electron in an atom is designated by four quantum numbers."}, {"id": "c", "text": "Total orbital angular momentum of electron in ''s'' orbital is equal to zero."}, {"id": "d", "text": "The value of m for d_z² is zero."}]'::jsonb, 'a', 'The box diagram for N shows one 2p electron with opposite spin, which violates Hund''s rule.', 'By Hund''s rule, the three unpaired electrons in degenerate 2p orbitals must all have parallel spins (↑ ↑ ↑) in the ground state. The diagram shows ↑ ↑ ↓, so it is wrong. An orbital needs n, l and mₗ, while an electron also needs mₛ. For an s electron l = 0, so the orbital angular momentum √[l(l+1)]ħ = 0, and d_z² corresponds to mₗ = 0.', '{"b": "Correct: orbitals use n, l, mₗ, and electrons also use mₛ.", "c": "Correct: l = 0 gives zero orbital angular momentum.", "d": "Correct: d_z² is the mₗ = 0 orbital."}'::jsonb, 'Hund''s rule: electrons occupy degenerate orbitals singly with parallel spins before pairing.', 'med', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', '/pyq/ug/2018/90.webp'),
('bc5f1b67-e572-5b6c-9e06-84bf52972681', 'neet_ug', 'Botany', 'Photosynthesis in Higher Plants', 'Oxygen is not produced during photosynthesis by', '[{"id": "a", "text": "Cycas"}, {"id": "b", "text": "Nostoc"}, {"id": "c", "text": "Green sulphur bacteria"}, {"id": "d", "text": "Chara"}]'::jsonb, 'c', 'Green sulphur bacteria carry out anoxygenic photosynthesis, using H₂S instead of water as the electron donor.', 'Oxygen comes from the splitting of water at photosystem II. Green sulphur bacteria lack PS II and use H₂S as the hydrogen donor, so they release sulphur instead of O₂. Cycas (a gymnosperm), Chara (a green alga) and Nostoc (a cyanobacterium) all split water and evolve oxygen.', '{"a": "Cycas is a gymnosperm with normal oxygenic photosynthesis.", "b": "Nostoc is a cyanobacterium with PS II, so it is oxygenic.", "d": "Chara is a green alga and evolves O₂."}'::jsonb, 'Van Niel''s work on purple and green sulphur bacteria showed that the O₂ evolved in photosynthesis comes from H₂O, not CO₂.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('4c460a4f-6917-5446-b7e8-09cfc4631cb4', 'neet_ug', 'Botany', 'Sexual Reproduction in Flowering Plants', 'Double fertilization is', '[{"id": "a", "text": "Fusion of two male gametes with one egg"}, {"id": "b", "text": "Fusion of one male gamete with two polar nuclei"}, {"id": "c", "text": "Fusion of two male gametes of a pollen tube with two different eggs"}, {"id": "d", "text": "Syngamy and triple fusion"}]'::jsonb, 'd', 'Double fertilisation is syngamy (male gamete + egg) together with triple fusion (male gamete + two polar nuclei) in the same embryo sac.', 'Each pollen tube releases two male gametes into the embryo sac. One fuses with the egg cell (syngamy) to form the diploid zygote, and the other fuses with the two polar nuclei (triple fusion) to form the triploid primary endosperm nucleus. Because two fusions happen, the process is called double fertilisation and is unique to angiosperms.', '{"a": "Only one male gamete fuses with the egg.", "b": "This describes only triple fusion, one half of the process.", "c": "An embryo sac has only one egg."}'::jsonb, 'Double fertilisation is unique to angiosperms; triple fusion produces the 3n PEN.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('c5c17184-fe54-5377-b310-fe1a74290a14', 'neet_ug', 'Botany', 'Sexual Reproduction in Flowering Plants', 'Which one of the following plants shows a very close relationship with a species of moth, where none of the two can complete its life cycle without the other?', '[{"id": "a", "text": "Banana"}, {"id": "b", "text": "Yucca"}, {"id": "c", "text": "Hydrilla"}, {"id": "d", "text": "Viola"}]'::jsonb, 'b', 'Yucca and the yucca moth (Tegeticula) are obligate mutualists: the moth pollinates the flower and its larvae feed on the developing seeds.', 'The female yucca moth deposits eggs in the ovary of Yucca and actively packs pollen onto the stigma. The plant cannot be pollinated without the moth, and the moth larvae depend on the developing seeds, so neither can complete its life cycle without the other. Banana is parthenocarpic, Hydrilla is water-pollinated and Viola is cleistogamous or bee-pollinated.', '{"a": "Banana produces seedless fruit by parthenocarpy and needs no specific moth.", "c": "Hydrilla is pollinated by water (hydrophily).", "d": "Viola has cleistogamous flowers that self-pollinate."}'::jsonb, 'Yucca–moth and fig–wasp are classic examples of obligate plant–insect mutualism.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('c6334392-4f8d-5621-ae0c-9c9851136291', 'neet_ug', 'Botany', 'Sexual Reproduction in Flowering Plants', 'Pollen grains can be stored for several years in liquid nitrogen having a temperature of', '[{"id": "a", "text": "– 196°C"}, {"id": "b", "text": "– 80°C"}, {"id": "c", "text": "– 120°C"}, {"id": "d", "text": "– 160°C"}]'::jsonb, 'a', 'Liquid nitrogen is at −196°C, which is used for cryopreservation of pollen in pollen banks.', 'Liquid nitrogen boils at about 77 K, which is −196°C. At this temperature metabolic activity stops, so pollen grains stay viable for years. This is the basis of pollen banks used in crop breeding programmes.', '{"b": "−80°C is a deep-freezer temperature, not liquid nitrogen.", "c": "This is not the boiling point of liquid nitrogen.", "d": "This is not the boiling point of liquid nitrogen."}'::jsonb, 'Pollen grains can be cryopreserved in liquid nitrogen (−196°C) in pollen banks.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('372682c0-e3dd-5783-922d-ab7f63ea6aed', 'neet_ug', 'Botany', 'Respiration in Plants', 'What is the role of NAD⁺ in cellular respiration?', '[{"id": "a", "text": "It is a nucleotide source for ATP synthesis."}, {"id": "b", "text": "It functions as an electron carrier."}, {"id": "c", "text": "It functions as an enzyme."}, {"id": "d", "text": "It is the final electron acceptor for anaerobic respiration."}]'::jsonb, 'b', 'NAD⁺ is a coenzyme that accepts electrons and protons (forming NADH) in glycolysis and the Krebs cycle and passes them to the ETS.', 'During oxidation of substrates in glycolysis, link reaction and the TCA cycle, dehydrogenases transfer hydrogen to NAD⁺, reducing it to NADH + H⁺. NADH then hands these electrons to complex I of the electron transport system, where ATP is made by oxidative phosphorylation. So NAD⁺ acts as an electron (hydrogen) carrier, not as an enzyme or a source of ATP nucleotides.', '{"a": "ATP is made from ADP + Pi, not from NAD⁺ nucleotides.", "c": "NAD⁺ is a coenzyme, not an enzyme itself.", "d": "In fermentation, NADH is re-oxidised by pyruvate or acetaldehyde, which act as the final acceptors."}'::jsonb, 'Oxidation of one NADH in the ETS yields about 3 ATP; one FADH₂ yields about 2 ATP.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('572df3a8-4406-58e2-868f-4e229efd477a', 'neet_ug', 'Zoology', 'Biotechnology: Principles and Processes', 'Which of the following is commonly used as a vector for introducing a DNA fragment in human lymphocytes ?', '[{"id": "a", "text": "λ phage"}, {"id": "b", "text": "Ti plasmid"}, {"id": "c", "text": "Retrovirus"}, {"id": "d", "text": "pBR 322"}]'::jsonb, 'c', 'Disarmed retroviruses are the standard vectors for delivering genes into human (animal) cells such as lymphocytes.', 'Retroviruses integrate their genome into the host chromosome, so a disarmed retrovirus carrying the desired gene can stably insert it into human lymphocytes. This was used in the first gene therapy (ADA deficiency), where the functional ADA cDNA was introduced into lymphocytes. The other options are vectors for bacteria or plants.', '{"a": "λ phage infects E. coli, not human cells.", "b": "Ti plasmid of Agrobacterium is a plant vector.", "d": "pBR322 is an E. coli cloning plasmid."}'::jsonb, 'In ADA-deficiency gene therapy, functional ADA cDNA is delivered into lymphocytes using a retroviral vector.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('2e8b0263-f898-5bcc-90cd-ab2c5938e9ae', 'neet_ug', 'Zoology', 'Biotechnology and its Applications', 'Use of bioresources by multinational companies and organisations without authorisation from the concerned country and its people is called', '[{"id": "a", "text": "Biodegradation"}, {"id": "b", "text": "Biopiracy"}, {"id": "c", "text": "Bio-infringement"}, {"id": "d", "text": "Bioexploitation"}]'::jsonb, 'b', 'Exploiting a nation''s bioresources without authorisation or compensation is biopiracy.', 'When multinational companies use the biological resources or traditional knowledge of a country without permission or fair payment, NCERT calls it biopiracy. Basmati rice and turmeric patents are classic examples.', '{"a": "Biodegradation is breakdown of matter by microbes.", "c": "Bio-infringement is not the NCERT term for this.", "d": "Bioexploitation is a loose word, not the defined term."}'::jsonb, 'Biopiracy: unauthorised use of bioresources/traditional knowledge without compensatory payment.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('e8e8eb86-8c84-5491-b786-34a6d0f17b83', 'neet_ug', 'Zoology', 'Biotechnology and its Applications', 'In India, the organisation responsible for assessing the safety of introducing genetically modified organisms for public use is', '[{"id": "a", "text": "Research Committee on Genetic Manipulation (RCGM)"}, {"id": "b", "text": "Council for Scientific and Industrial Research (CSIR)"}, {"id": "c", "text": "Indian Council of Medical Research (ICMR)"}, {"id": "d", "text": "Genetic Engineering Appraisal Committee (GEAC)"}]'::jsonb, 'd', 'GEAC decides on the validity of GM research and the safety of releasing GM organisms for public use.', 'The Indian Government set up GEAC to judge the validity of GM research and the safety of introducing GM organisms for public services. RCGM oversees research-stage biosafety, while CSIR and ICMR are research councils.', '{"a": "RCGM reviews research-stage projects, not public release.", "b": "CSIR is an industrial research council.", "c": "ICMR funds and conducts medical research."}'::jsonb, 'GEAC = Genetic Engineering Appraisal Committee, the regulator for GM release in India.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('01a70c8e-68cc-5a4d-990c-001d1f93a46a', 'neet_ug', 'Zoology', 'Biotechnology: Principles and Processes', 'The correct order of steps in Polymerase Chain Reaction (PCR) is', '[{"id": "a", "text": "Denaturation, Extension, Annealing"}, {"id": "b", "text": "Annealing, Extension, Denaturation"}, {"id": "c", "text": "Extension, Denaturation, Annealing"}, {"id": "d", "text": "Denaturation, Annealing, Extension"}]'::jsonb, 'd', 'Each PCR cycle is denaturation, then primer annealing, then extension by Taq polymerase.', 'The double-stranded template is first denatured at high temperature, then cooled so that primers anneal to the single strands, and finally Taq polymerase extends the primers. Repeating the cycle amplifies the DNA exponentially.', '{"a": "Extension cannot occur before primers anneal.", "b": "The cycle must start with denaturation to separate strands.", "c": "Extension needs a primed single strand first."}'::jsonb, 'PCR cycle: denaturation → annealing → extension, using thermostable Taq polymerase.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('94196a71-a18c-5bbe-aa2a-3732b855ae45', 'neet_ug', 'Botany', 'Molecular Basis of Inheritance', 'Select the correct match :
(1) T.H. Morgan – Transduction
(2) F₂ × Recessive parent – Dihybrid cross
(3) Ribozyme – Nucleic acid
(4) G. Mendel – Transformation', '[{"id": "a", "text": "T.H. Morgan – Transduction"}, {"id": "b", "text": "F₂ × Recessive parent – Dihybrid cross"}, {"id": "c", "text": "Ribozyme – Nucleic acid"}, {"id": "d", "text": "G. Mendel – Transformation"}]'::jsonb, 'c', 'A ribozyme is a catalytic RNA, so it is a nucleic acid.', 'Ribozymes are RNA molecules with enzymatic activity (e.g. the 23S rRNA peptidyl transferase), so ''Ribozyme – Nucleic acid'' is correct. Morgan worked on linkage, a cross of F₁ with the recessive parent is a test cross, and transformation was discovered by Griffith.', '{"a": "Morgan is known for linkage; transduction was found by Zinder and Lederberg.", "b": "Crossing with the recessive parent is a test cross.", "d": "Transformation was discovered by Griffith."}'::jsonb, 'Ribozyme = catalytic RNA; peptidyl transferase activity of 23S rRNA is a ribozyme.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('71942911-cdd4-56a4-a87e-ceb0271158ae', 'neet_ug', 'Zoology', 'Biotechnology and its Applications', 'A ''new'' variety of rice was patented by a foreign company, though such varieties have been present in India for a long time. This is related to', '[{"id": "a", "text": "Lerma Rojo"}, {"id": "b", "text": "Sharbati Sonora"}, {"id": "c", "text": "Co-667"}, {"id": "d", "text": "Basmati"}]'::jsonb, 'd', 'The US patent on a Basmati-derived rice variety is the classic biopiracy case.', 'In 1997 an American company obtained a patent on Basmati rice lines derived from Indian farmers'' varieties, although Basmati has been grown in India for centuries. Lerma Rojo and Sharbati Sonora are wheat varieties and Co-667 is a sugarcane variety.', '{"a": "Lerma Rojo is a semi-dwarf wheat variety.", "b": "Sharbati Sonora is a wheat variety.", "c": "Co-667 is a sugarcane variety."}'::jsonb, 'India has about 200,000 rice varieties, of which about 27 are Basmati.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('6db4a70c-5999-542c-bb6a-cfbe0f86d3b6', 'neet_ug', 'Botany', 'Principles of Inheritance and Variation', 'Which of the following pairs is wrongly matched ?', '[{"id": "a", "text": "XO type sex determination : Grasshopper"}, {"id": "b", "text": "ABO blood grouping : Co-dominance"}, {"id": "c", "text": "Starch synthesis in pea : Multiple alleles"}, {"id": "d", "text": "T.H. Morgan : Linkage"}]'::jsonb, 'c', 'Starch synthesis in pea is an example of pleiotropy/incomplete dominance, not multiple alleles.', 'In pea, a single gene controls starch synthesis and seed shape; at the level of starch-grain size it shows incomplete dominance, and it illustrates pleiotropy. Multiple alleles is exemplified by the ABO gene (I). Grasshopper has XO sex determination and Morgan discovered linkage, so those pairs are correct.', '{"a": "Grasshopper males are XO, so this is correct.", "b": "Iᴬ and Iᴮ are co-dominant, so this is correct.", "d": "Morgan coined linkage, so this is correct."}'::jsonb, 'Starch grain size in pea (gene B) shows incomplete dominance; ABO shows both co-dominance and multiple alleles.', 'med', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('9b7cb4f4-53ea-5a94-ab23-4396e6c72e6b', 'neet_ug', 'Botany', 'Principles of Inheritance and Variation', 'Select the correct statement :', '[{"id": "a", "text": "Spliceosomes take part in translation."}, {"id": "b", "text": "Punnett square was developed by a British scientist."}, {"id": "c", "text": "Franklin Stahl coined the term \"linkage\"."}, {"id": "d", "text": "Transduction was discovered by S. Altman."}]'::jsonb, 'b', 'The Punnett square is named after the British geneticist Reginald C. Punnett.', 'Reginald Punnett, a British geneticist, devised the checkerboard to work out offspring genotypes. Spliceosomes act in RNA splicing (post-transcriptional processing), linkage was coined by Morgan, and transduction was discovered by Zinder and Lederberg.', '{"a": "Spliceosomes splice hnRNA, not translate.", "c": "Morgan coined ''linkage''.", "d": "Altman is associated with ribozymes, not transduction."}'::jsonb, 'Punnett square: graphic representation of all possible gametic combinations, by R.C. Punnett.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('2fe03e32-88a4-59bd-9b49-4a4f9248f7f1', 'neet_ug', 'Botany', 'Molecular Basis of Inheritance', 'The experimental proof for semiconservative replication of DNA was first shown in a', '[{"id": "a", "text": "Plant"}, {"id": "b", "text": "Bacterium"}, {"id": "c", "text": "Fungus"}, {"id": "d", "text": "Virus"}]'::jsonb, 'b', 'Meselson and Stahl first proved semiconservative replication in the bacterium E. coli.', 'In 1958 Meselson and Stahl grew E. coli in ¹⁵N medium, shifted it to ¹⁴N, and used CsCl density-gradient centrifugation to show hybrid DNA after one generation. Taylor later showed the same in Vicia faba (a plant) using radioactive thymidine.', '{"a": "Taylor''s Vicia faba work came later.", "c": "No fungus was used for the first proof.", "d": "Viruses were not used for this experiment."}'::jsonb, 'Meselson–Stahl: E. coli, ¹⁵NH₄Cl, CsCl density gradient; one generation gives hybrid DNA.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('3bf9f95b-715f-5ae2-8b62-e045c14af17a', 'neet_ug', 'Botany', 'Molecular Basis of Inheritance', 'Select the correct match :', '[{"id": "a", "text": "Matthew Meselson and F. Stahl – Pisum sativum"}, {"id": "b", "text": "Alfred Hershey and Martha Chase – TMV"}, {"id": "c", "text": "Alec Jeffreys – Streptococcus pneumoniae"}, {"id": "d", "text": "Francois Jacob and Jacques Monod – Lac operon"}]'::jsonb, 'd', 'Jacob and Monod proposed the lac operon model of gene regulation.', 'Jacob and Monod first described a transcriptionally regulated system, the lac operon of E. coli. Meselson and Stahl used E. coli, Hershey and Chase used bacteriophage T2, and Alec Jeffreys developed DNA fingerprinting; Streptococcus pneumoniae was Griffith''s organism.', '{"a": "Meselson and Stahl used E. coli.", "b": "Hershey and Chase used T2 bacteriophage.", "c": "Jeffreys devised DNA fingerprinting; S. pneumoniae was used by Griffith."}'::jsonb, 'Lac operon: i (repressor), p, o, and structural genes z, y, a; lactose is the inducer.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('f596ff18-546b-5611-8571-e6aabed1e1bf', 'neet_ug', 'Botany', 'Sexual Reproduction in Flowering Plants', 'Which of the following has proved helpful in preserving pollen as fossils ?', '[{"id": "a", "text": "Oil content"}, {"id": "b", "text": "Cellulosic intine"}, {"id": "c", "text": "Pollenkitt"}, {"id": "d", "text": "Sporopollenin"}]'::jsonb, 'd', 'Sporopollenin in the exine resists decay, so pollen is well preserved as fossils.', 'The exine of pollen is made of sporopollenin, one of the most resistant organic materials known; it withstands high temperature, strong acids and alkalis, and no enzyme degrades it. This is why pollen grains survive as fossils.', '{"a": "Oil content is not a resistant wall material.", "b": "The intine is thin and cellulosic-pectic, and decays easily.", "c": "Pollenkitt is an oily coat that helps insect pollination."}'::jsonb, 'Germ pores in exine lack sporopollenin; intine is made of cellulose and pectin.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('45c1efab-c83f-5cfb-9a10-48f6c57050d8', 'neet_ug', 'Botany', 'Organisms and Populations', 'Natality refers to', '[{"id": "a", "text": "Number of individuals leaving the habitat"}, {"id": "b", "text": "Birth rate"}, {"id": "c", "text": "Death rate"}, {"id": "d", "text": "Number of individuals entering a habitat"}]'::jsonb, 'b', 'Natality is the number of births in a population over a given period.', 'Population density rises through natality (births) and immigration and falls through mortality (deaths) and emigration. Individuals leaving are emigrants and those entering are immigrants.', '{"a": "That is emigration.", "c": "That is mortality.", "d": "That is immigration."}'::jsonb, 'Nₜ₊₁ = Nₜ + [(B + I) − (D + E)].', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('6f6ae0eb-8e81-5f8f-a0f5-87ead66582ce', 'neet_ug', 'Botany', 'Organisms and Populations', 'Niche is', '[{"id": "a", "text": "the range of temperature that the organism needs to live"}, {"id": "b", "text": "the physical space where an organism lives"}, {"id": "c", "text": "all the biological factors in the organism''s environment"}, {"id": "d", "text": "the functional role played by the organism where it lives"}]'::jsonb, 'd', 'A niche is the functional role of a species in its habitat.', 'Each organism has a range of conditions it can tolerate, resources it uses and a distinct functional role in the ecological system; together these make up its niche. The physical space is the habitat, and temperature range alone is only one dimension.', '{"a": "Temperature range is just one aspect of the niche.", "b": "The physical space is the habitat.", "c": "Biotic factors are part of the environment, not the niche itself."}'::jsonb, 'Habitat is the ''address''; niche is the ''profession'' of an organism.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('d8bd3af5-00bb-5f44-8652-c34b85ec0786', 'neet_ug', 'Botany', 'Ecosystem', 'What type of ecological pyramid would be obtained with the following data ?
Secondary consumer : 120 g
Primary consumer : 60 g
Primary producer : 10 g', '[{"id": "a", "text": "Upright pyramid of numbers"}, {"id": "b", "text": "Pyramid of energy"}, {"id": "c", "text": "Inverted pyramid of biomass"}, {"id": "d", "text": "Upright pyramid of biomass"}]'::jsonb, 'c', 'Biomass increases from producer to secondary consumer, so the biomass pyramid is inverted.', 'The data are in grams, so they describe standing biomass. The producer level has the least biomass (10 g) and the top level the most (120 g), giving an inverted pyramid of biomass, as seen in the sea where small phytoplankton support larger fish biomass.', '{"a": "The data are masses, not numbers of organisms.", "b": "A pyramid of energy is always upright and measured in energy units.", "d": "An upright pyramid would need producers to have the largest biomass."}'::jsonb, 'Pyramid of biomass is inverted in the sea; pyramid of energy is always upright.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('b2367c93-3690-577a-b6f1-49480ca24481', 'neet_ug', 'Zoology', 'Biomolecules', 'The two functional groups characteristic of sugars are', '[{"id": "a", "text": "carbonyl and phosphate"}, {"id": "b", "text": "carbonyl and methyl"}, {"id": "c", "text": "hydroxyl and methyl"}, {"id": "d", "text": "carbonyl and hydroxyl"}]'::jsonb, 'd', 'Sugars are polyhydroxy aldehydes or ketones, so they carry carbonyl and hydroxyl groups.', 'A monosaccharide such as glucose has an aldehyde (or a ketone in fructose) carbonyl group plus several –OH groups. Phosphate and methyl groups are not defining features of sugars.', '{"a": "Phosphate is found in sugar phosphates, not all sugars.", "b": "Methyl is not characteristic of sugars.", "c": "Methyl is not characteristic of sugars."}'::jsonb, 'Carbohydrates are polyhydroxy aldehydes or ketones; glucose is an aldohexose, fructose a ketohexose.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('83c0cf7a-7077-5891-ae42-08377dd2d2c7', 'neet_ug', 'Botany', 'Biological Classification', 'Which among the following is not a prokaryote ?', '[{"id": "a", "text": "Nostoc"}, {"id": "b", "text": "Mycobacterium"}, {"id": "c", "text": "Saccharomyces"}, {"id": "d", "text": "Oscillatoria"}]'::jsonb, 'c', 'Saccharomyces (yeast) is a eukaryotic fungus.', 'Saccharomyces is a unicellular ascomycete fungus with a true nucleus, so it is eukaryotic. Nostoc and Oscillatoria are cyanobacteria and Mycobacterium is a bacterium, all prokaryotes.', '{"a": "Nostoc is a cyanobacterium.", "b": "Mycobacterium is a bacterium.", "d": "Oscillatoria is a cyanobacterium."}'::jsonb, 'Yeast (Saccharomyces) is a unicellular sac fungus (Ascomycetes).', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('191a0c54-fe1a-5603-9bbb-07e97720d47c', 'neet_ug', 'Botany', 'Cell: The Unit of Life', 'The Golgi complex participates in', '[{"id": "a", "text": "Respiration in bacteria"}, {"id": "b", "text": "Formation of secretory vesicles"}, {"id": "c", "text": "Fatty acid breakdown"}, {"id": "d", "text": "Activation of amino acid"}]'::jsonb, 'b', 'The Golgi apparatus packages materials and buds off secretory vesicles.', 'Materials from the ER reach the cis face of the Golgi, are modified, and leave the trans face as secretory vesicles. Bacterial respiration happens at the plasma membrane (mesosomes), fatty acid breakdown in mitochondria and peroxisomes, and amino acid activation in the cytoplasm.', '{"a": "Bacteria lack a Golgi complex.", "c": "β-oxidation occurs in mitochondria/peroxisomes.", "d": "Amino acids are activated by aminoacyl-tRNA synthetases in the cytosol."}'::jsonb, 'Golgi is the site of glycoprotein and glycolipid formation; cis face = forming, trans face = maturing.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('cc5ba39e-fc8d-50f1-bfff-166294653b13', 'neet_ug', 'Botany', 'Photosynthesis in Higher Plants', 'Which of the following is not a product of light reaction of photosynthesis ?', '[{"id": "a", "text": "NADPH"}, {"id": "b", "text": "NADH"}, {"id": "c", "text": "ATP"}, {"id": "d", "text": "Oxygen"}]'::jsonb, 'b', 'Light reactions make ATP, NADPH and O₂, not NADH.', 'Photolysis of water releases O₂, the electron transport chain reduces NADP⁺ to NADPH, and photophosphorylation yields ATP. NADH is produced in respiration, not in the light reaction.', '{"a": "NADPH is made at the end of PS I.", "c": "ATP is made by photophosphorylation.", "d": "O₂ comes from splitting of water."}'::jsonb, 'Light reaction products: ATP, NADPH and O₂; the ATP and NADPH drive the Calvin cycle.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('c738b335-979f-5b17-812c-af9315da19c9', 'neet_ug', 'Botany', 'Cell: The Unit of Life', 'Which of the following is true for nucleolus ?', '[{"id": "a", "text": "It takes part in spindle formation."}, {"id": "b", "text": "It is a membrane-bound structure."}, {"id": "c", "text": "Larger nucleoli are present in dividing cells."}, {"id": "d", "text": "It is a site for active ribosomal RNA synthesis."}]'::jsonb, 'd', 'The nucleolus is where rRNA is actively synthesised.', 'The nucleolus is a non-membrane-bound body in the nucleus and is the site of active rRNA synthesis. Larger and more numerous nucleoli occur in cells actively making proteins, and the spindle forms from centrioles/microtubules.', '{"a": "The spindle is formed by microtubules organised by centrioles.", "b": "The nucleolus has no membrane.", "c": "Large nucleoli mark cells active in protein synthesis, not dividing cells."}'::jsonb, 'Nucleolus: non-membranous; site of rRNA synthesis; disappears in prophase.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('091ecbb5-e5e0-5815-9f64-6535b5d0884a', 'neet_ug', 'Botany', 'Cell Cycle and Cell Division', 'The stage during which separation of the paired homologous chromosomes begins is', '[{"id": "a", "text": "Diakinesis"}, {"id": "b", "text": "Diplotene"}, {"id": "c", "text": "Pachytene"}, {"id": "d", "text": "Zygotene"}]'::jsonb, 'b', 'In diplotene the synaptonemal complex dissolves and homologues begin to separate, staying joined only at chiasmata.', 'Pairing (synapsis) happens in zygotene and crossing over in pachytene. In diplotene the synaptonemal complex dissolves and homologous chromosomes start moving apart except at the chiasmata. Diakinesis follows with terminalisation of chiasmata.', '{"a": "Diakinesis shows terminalisation of chiasmata after separation has begun.", "c": "Pachytene is the stage of crossing over.", "d": "Zygotene is when homologues pair."}'::jsonb, 'Prophase I order: leptotene, zygotene, pachytene, diplotene, diakinesis.', 'med', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('4d4e5a42-744e-5b39-bebf-fa729d411e99', 'neet_ug', 'Botany', 'Anatomy of Flowering Plants', 'Stomata in grass leaf are', '[{"id": "a", "text": "Rectangular"}, {"id": "b", "text": "Kidney shaped"}, {"id": "c", "text": "Dumb-bell shaped"}, {"id": "d", "text": "Barrel shaped"}]'::jsonb, 'c', 'Grasses have dumb-bell shaped guard cells.', 'In dicots the guard cells are bean (kidney) shaped, but in grasses (monocots) the guard cells are dumb-bell shaped. Their walls are thickened in the middle and thin at the ends.', '{"a": "No guard cells are rectangular.", "b": "Kidney-shaped guard cells occur in dicots.", "d": "Barrel-shaped is not a guard-cell form."}'::jsonb, 'Stomatal apparatus = stomatal pore + guard cells + subsidiary cells.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('770c0f2d-ae57-5d79-a494-1307688b8f20', 'neet_ug', 'Botany', 'Anatomy of Flowering Plants', 'Secondary xylem and phloem in dicot stem are produced by', '[{"id": "a", "text": "Phellogen"}, {"id": "b", "text": "Vascular cambium"}, {"id": "c", "text": "Apical meristems"}, {"id": "d", "text": "Axillary meristems"}]'::jsonb, 'b', 'Vascular cambium cuts off secondary xylem inward and secondary phloem outward.', 'During secondary growth the vascular cambium ring divides to form secondary xylem towards the pith and secondary phloem towards the periphery. Phellogen (cork cambium) makes cork and secondary cortex, while apical and axillary meristems give primary growth.', '{"a": "Phellogen forms periderm.", "c": "Apical meristems give primary growth in length.", "d": "Axillary meristems form branches."}'::jsonb, 'Cambium is more active on the inner side, so more secondary xylem than phloem forms.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('cb72c770-0f11-5ac4-997f-d387afe245d9', 'neet_ug', 'Botany', 'Morphology of Flowering Plants', 'Pneumatophores occur in', '[{"id": "a", "text": "Carnivorous plants"}, {"id": "b", "text": "Free-floating hydrophytes"}, {"id": "c", "text": "Halophytes"}, {"id": "d", "text": "Submerged hydrophytes"}]'::jsonb, 'c', 'Mangrove halophytes such as Rhizophora have pneumatophores.', 'Plants in swampy, saline areas like Rhizophora have roots that grow vertically upward to get oxygen for respiration; these are pneumatophores. Hydrophytes and carnivorous plants do not have them.', '{"a": "Carnivorous plants have modified leaves, not pneumatophores.", "b": "Free-floating hydrophytes get air directly.", "d": "Submerged hydrophytes have aerenchyma instead."}'::jsonb, 'Pneumatophores (respiratory roots) occur in Rhizophora, a mangrove.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('f03c8e48-cc8e-54b2-9237-c1d84159ba9f', 'neet_ug', 'Botany', 'Anatomy of Flowering Plants', 'Casparian strips occur in', '[{"id": "a", "text": "Cortex"}, {"id": "b", "text": "Pericycle"}, {"id": "c", "text": "Epidermis"}, {"id": "d", "text": "Endodermis"}]'::jsonb, 'd', 'Casparian strips are suberin bands on the walls of endodermal cells.', 'The innermost layer of the cortex, the endodermis, has a deposit of water-impermeable waxy suberin on its tangential and radial walls in the form of casparian strips. It is most prominent in roots.', '{"a": "Cortex cells are thin-walled parenchyma.", "b": "Pericycle lies inside the endodermis and lacks casparian strips.", "c": "Epidermis has no casparian strips."}'::jsonb, 'Casparian strips are made of suberin on radial and tangential walls of the endodermis.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('ac436051-ff8b-572c-a858-e42c6d8a2a15', 'neet_ug', 'Botany', 'Anatomy of Flowering Plants', 'Plants having little or no secondary growth are', '[{"id": "a", "text": "Conifers"}, {"id": "b", "text": "Deciduous angiosperms"}, {"id": "c", "text": "Grasses"}, {"id": "d", "text": "Cycads"}]'::jsonb, 'c', 'Grasses are monocots and lack vascular cambium, so they show little or no secondary growth.', 'Monocots like grasses have closed vascular bundles without cambium, so they generally do not undergo secondary growth. Conifers, cycads and dicot trees all have cambium and grow in girth.', '{"a": "Conifers form wood by secondary growth.", "b": "Deciduous dicot trees have prominent secondary growth.", "d": "Cycads show secondary growth."}'::jsonb, 'Monocot vascular bundles are closed (no cambium); dicot bundles are open.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('0d2b215a-0a68-5322-816a-7be1de979161', 'neet_ug', 'Botany', 'Morphology of Flowering Plants', 'Sweet potato is a modified', '[{"id": "a", "text": "Tap root"}, {"id": "b", "text": "Adventitious root"}, {"id": "c", "text": "Stem"}, {"id": "d", "text": "Rhizome"}]'::jsonb, 'b', 'Sweet potato is a swollen adventitious root that stores food.', 'The storage organ of sweet potato develops from adventitious roots, unlike carrot or turnip which are modified tap roots. Potato, by contrast, is a stem tuber.', '{"a": "Carrot and turnip are tap-root modifications.", "c": "Potato is the stem tuber, not sweet potato.", "d": "Ginger is a rhizome."}'::jsonb, 'Adventitious food-storage roots: sweet potato; tap-root storage: carrot, turnip.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('47b2c738-f4eb-574e-b21e-4655d59f6383', 'neet_ug', 'Botany', 'Plant Kingdom', 'Which of the following statements is correct ?', '[{"id": "a", "text": "Horsetails are gymnosperms."}, {"id": "b", "text": "Selaginella is heterosporous, while Salvinia is homosporous."}, {"id": "c", "text": "Ovules are not enclosed by ovary wall in gymnosperms."}, {"id": "d", "text": "Stems are usually unbranched in both Cycas and Cedrus."}]'::jsonb, 'c', 'Gymnosperms have naked ovules, not enclosed in an ovary.', 'Gymnosperms bear ovules that are exposed, before and after fertilisation, because there is no ovary wall. Horsetails (Equisetum) are pteridophytes, both Selaginella and Salvinia are heterosporous, and only Cycas has an unbranched stem while Cedrus is branched.', '{"a": "Horsetails are pteridophytes.", "b": "Salvinia is also heterosporous.", "d": "Cedrus has a branched stem."}'::jsonb, 'Heterosporous pteridophytes: Selaginella and Salvinia.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('d6228128-7e4b-588e-b10a-76f1cf254afb', 'neet_ug', 'Botany', 'Biological Classification', 'Select the wrong statement :', '[{"id": "a", "text": "Pseudopodia are locomotory and feeding structures in Sporozoans."}, {"id": "b", "text": "Mushrooms belong to Basidiomycetes."}, {"id": "c", "text": "Cell wall is present in members of Fungi and Plantae."}, {"id": "d", "text": "Mitochondria are the powerhouse of the cell in all kingdoms except Monera."}]'::jsonb, 'a', 'Pseudopodia occur in amoeboid protozoans (sarcodines), not in sporozoans.', 'Amoeboid protozoans like Amoeba use pseudopodia to move and capture prey. Sporozoans such as Plasmodium have an infectious spore-like stage and lack locomotory organelles. The other statements are true: mushrooms are basidiomycetes, fungi and plants have cell walls, and Monera lacks mitochondria.', '{"b": "Agaricus (mushroom) is a basidiomycete, so this is true.", "c": "Fungi have chitin walls and plants cellulose walls, so this is true.", "d": "Prokaryotes lack mitochondria, so this is true."}'::jsonb, 'Sporozoans (e.g. Plasmodium) have no locomotory structures.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('cf166886-2c6a-57b0-82f0-3fb13e6b7b00', 'neet_ug', 'Botany', 'Biological Classification', 'After karyogamy followed by meiosis, spores are produced exogenously in', '[{"id": "a", "text": "Agaricus"}, {"id": "b", "text": "Alternaria"}, {"id": "c", "text": "Neurospora"}, {"id": "d", "text": "Saccharomyces"}]'::jsonb, 'a', 'Basidiomycetes like Agaricus form basidiospores exogenously on the basidium after karyogamy and meiosis.', 'In basidiomycetes, karyogamy and meiosis occur in the basidium and four basidiospores are borne externally on it. Ascomycetes such as Neurospora and Saccharomyces form ascospores endogenously in asci, and Alternaria is a deuteromycete with no known sexual stage.', '{"b": "Alternaria (Deuteromycetes) has no sexual phase.", "c": "Neurospora forms ascospores inside asci.", "d": "Saccharomyces forms ascospores inside asci."}'::jsonb, 'Basidiospores are exogenous; ascospores are endogenous.', 'med', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('5145c149-ce22-5b9d-a278-eb3cf944de6b', 'neet_ug', 'Botany', 'The Living World', 'Match the items given in Column I with those in Column II and select the correct option given below :
Column I | Column II
a. Herbarium | i. It is a place having a collection of preserved plants and animals.
b. Key | ii. A list that enumerates methodically all the species found in an area with brief description aiding identification.
c. Museum | iii. Is a place where dried and pressed plant specimens mounted on sheets are kept.
d. Catalogue | iv. A booklet containing a list of characters and their alternates which are helpful in identification of various taxa.', '[{"id": "a", "text": "a-ii, b-iv, c-iii, d-i"}, {"id": "b", "text": "a-iii, b-ii, c-i, d-iv"}, {"id": "c", "text": "a-i, b-iv, c-iii, d-ii"}, {"id": "d", "text": "a-iii, b-iv, c-i, d-ii"}]'::jsonb, 'd', 'Herbarium–pressed sheets, Key–paired characters, Museum–preserved plants and animals, Catalogue–methodical species list.', 'A herbarium stores dried, pressed specimens on sheets (iii). A key is based on contrasting characters (couplets) for identification (iv). A museum houses preserved plants and animals (i), and a catalogue lists species methodically with brief descriptions (ii).', '{"a": "Herbarium is not a species list.", "b": "A key is not a methodical species list.", "c": "A herbarium stores only plant sheets, not animals."}'::jsonb, 'Taxonomic keys use couplets of contrasting characters.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('c2f27ca2-1c03-5b79-96f0-15c11a1df333', 'neet_ug', 'Botany', 'Plant Kingdom', 'Winged pollen grains are present in', '[{"id": "a", "text": "Mango"}, {"id": "b", "text": "Cycas"}, {"id": "c", "text": "Mustard"}, {"id": "d", "text": "Pinus"}]'::jsonb, 'd', 'Pinus pollen has two air sacs (wings) that aid wind dispersal.', 'Pinus pollen grains carry two lateral air-filled wings that help in wind pollination. Cycas pollen is not winged, and mango and mustard are insect-pollinated angiosperms.', '{"a": "Mango pollen is not winged.", "b": "Cycas pollen lacks wings.", "c": "Mustard pollen is not winged."}'::jsonb, 'Pinus is monoecious; its winged pollen suits anemophily.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('f563ced5-ac98-5305-8632-456e917a68b7', 'neet_ug', 'Botany', 'Plant Kingdom', 'Which one is wrongly matched ?', '[{"id": "a", "text": "Gemma cups – Marchantia"}, {"id": "b", "text": "Biflagellate zoospores – Brown algae"}, {"id": "c", "text": "Uniflagellate gametes – Polysiphonia"}, {"id": "d", "text": "Unicellular organism – Chlorella"}]'::jsonb, 'c', 'Polysiphonia is a red alga, and red algae have no flagellated stages.', 'Rhodophyceae such as Polysiphonia have non-motile gametes; flagella are absent at every stage. Marchantia forms gemmae in gemma cups, brown algae have biflagellate zoospores with laterally inserted flagella, and Chlorella is unicellular.', '{"a": "Marchantia has gemma cups, so this is correct.", "b": "Brown algae have pear-shaped biflagellate zoospores, so this is correct.", "d": "Chlorella is a unicellular green alga, so this is correct."}'::jsonb, 'Red algae: floridean starch, r-phycoerythrin, non-motile gametes.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('89af628a-d706-5576-8ad9-f4442e77abb8', 'neet_ug', 'Zoology', 'Breathing and Exchange of Gases', 'Which of the following options correctly represents the lung conditions in asthma and emphysema, respectively ?', '[{"id": "a", "text": "Increased respiratory surface; Inflammation of bronchioles"}, {"id": "b", "text": "Increased number of bronchioles; Increased respiratory surface"}, {"id": "c", "text": "Inflammation of bronchioles; Decreased respiratory surface"}, {"id": "d", "text": "Decreased respiratory surface; Inflammation of bronchioles"}]'::jsonb, 'c', 'Asthma inflames the bronchi/bronchioles; emphysema damages alveolar walls and cuts the respiratory surface.', 'Asthma causes inflammation of bronchi and bronchioles, leading to wheezing and difficult breathing. In emphysema, chronic damage to alveolar walls lowers the respiratory surface area, often due to smoking.', '{"a": "Neither disease increases respiratory surface, and the order is reversed.", "b": "Neither condition increases bronchioles or surface area.", "d": "The order is reversed."}'::jsonb, 'Emphysema is a chronic disorder in which alveolar walls are damaged; cigarette smoking is a major cause.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('485d69d5-dd50-52ae-941e-d6e10b1dd508', 'neet_ug', 'Zoology', 'Body Fluids and Circulation', 'Match the items given in Column I with those in Column II and select the correct option given below :
Column I | Column II
a. Tricuspid valve | i. Between left atrium and left ventricle
b. Bicuspid valve | ii. Between right ventricle and pulmonary artery
c. Semilunar valve | iii. Between right atrium and right ventricle', '[{"id": "a", "text": "a-i, b-ii, c-iii"}, {"id": "b", "text": "a-i, b-iii, c-ii"}, {"id": "c", "text": "a-iii, b-i, c-ii"}, {"id": "d", "text": "a-ii, b-i, c-iii"}]'::jsonb, 'c', 'Tricuspid: RA–RV; bicuspid (mitral): LA–LV; semilunar: at the exit of the ventricles into the pulmonary artery/aorta.', 'The tricuspid valve guards the right atrioventricular opening, the bicuspid (mitral) valve guards the left one, and semilunar valves lie at the openings of the pulmonary artery and aorta. So the match is a-iii, b-i, c-ii.', '{"a": "The tricuspid valve is on the right side.", "b": "The tricuspid valve is on the right side.", "d": "The tricuspid valve is not at the pulmonary artery."}'::jsonb, 'Valves allow one-way flow: atria → ventricles → great arteries.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('25725303-e7ff-5014-8f22-9d1e0ac00bf2', 'neet_ug', 'Zoology', 'Breathing and Exchange of Gases', 'Match the items given in Column I with those in Column II and select the correct option given below :
Column I | Column II
a. Tidal volume | i. 2500 – 3000 mL
b. Inspiratory Reserve volume | ii. 1100 – 1200 mL
c. Expiratory Reserve volume | iii. 500 – 550 mL
d. Residual volume | iv. 1000 – 1100 mL', '[{"id": "a", "text": "a-i, b-iv, c-ii, d-iii"}, {"id": "b", "text": "a-iii, b-i, c-iv, d-ii"}, {"id": "c", "text": "a-iii, b-ii, c-i, d-iv"}, {"id": "d", "text": "a-iv, b-iii, c-ii, d-i"}]'::jsonb, 'b', 'TV ≈ 500 mL, IRV ≈ 2500–3000 mL, ERV ≈ 1000–1100 mL, RV ≈ 1100–1200 mL.', 'NCERT values for a healthy adult are tidal volume 500–550 mL, IRV 2500–3000 mL, ERV 1000–1100 mL and residual volume 1100–1200 mL. That gives a-iii, b-i, c-iv, d-ii.', '{"a": "Tidal volume is not 2500–3000 mL.", "c": "IRV is not 1100–1200 mL.", "d": "Tidal volume is not 1000–1100 mL."}'::jsonb, 'Vital capacity = ERV + TV + IRV; total lung capacity = VC + RV.', 'med', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('0d4b8fa9-1a71-500f-8ec9-55c2f0e435b6', 'neet_ug', 'Zoology', 'Neural Control and Coordination', 'The transparent lens in the human eye is held in its place by', '[{"id": "a", "text": "smooth muscles attached to the iris"}, {"id": "b", "text": "ligaments attached to the iris"}, {"id": "c", "text": "ligaments attached to the ciliary body"}, {"id": "d", "text": "smooth muscles attached to the ciliary body"}]'::jsonb, 'c', 'Suspensory ligaments attached to the ciliary body hold the lens.', 'NCERT states that a transparent crystalline lens is held in position by ligaments attached to the ciliary body. The ciliary muscles change the tension on these ligaments to adjust lens curvature, while the iris only controls pupil size.', '{"a": "Iris muscles change pupil diameter, not lens position.", "b": "The ligaments attach to the ciliary body, not the iris.", "d": "The lens is held by ligaments, not directly by muscles."}'::jsonb, 'Ciliary body continues forward as the pigmented iris; the lens divides the eye into aqueous and vitreous chambers.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('82b66034-1949-52a5-9d9a-d00c5677052f', 'neet_ug', 'Zoology', 'Chemical Coordination and Integration', 'Which of the following is an amino acid derived hormone ?', '[{"id": "a", "text": "Estradiol"}, {"id": "b", "text": "Ecdysone"}, {"id": "c", "text": "Epinephrine"}, {"id": "d", "text": "Estriol"}]'::jsonb, 'c', 'Epinephrine is derived from the amino acid tyrosine.', 'Catecholamines such as epinephrine and norepinephrine, and thyroxine, are amino-acid (tyrosine) derivatives. Estradiol, estriol and the insect moulting hormone ecdysone are steroids.', '{"a": "Estradiol is a steroid.", "b": "Ecdysone is a steroid insect hormone.", "d": "Estriol is a steroid."}'::jsonb, 'Hormone classes: peptide (insulin), steroid (cortisol, estradiol), iodothyronine (T₄), amino-acid derived (epinephrine).', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('a7065dea-00ab-5407-9810-dd9a4893563b', 'neet_ug', 'Zoology', 'Locomotion and Movement', 'Which of the following hormones can play a significant role in osteoporosis ?', '[{"id": "a", "text": "Estrogen and Parathyroid hormone"}, {"id": "b", "text": "Progesterone and Aldosterone"}, {"id": "c", "text": "Aldosterone and Prolactin"}, {"id": "d", "text": "Parathyroid hormone and Prolactin"}]'::jsonb, 'a', 'Low estrogen and excess parathyroid hormone both cause bone loss leading to osteoporosis.', 'Osteoporosis is an age-related loss of bone mass; decreased estrogen after menopause is a common cause. Parathyroid hormone raises blood Ca²⁺ by bone resorption, so it also contributes. Aldosterone and prolactin do not regulate bone mass significantly.', '{"b": "Progesterone and aldosterone are not key bone regulators.", "c": "Aldosterone and prolactin do not drive osteoporosis.", "d": "Prolactin has no major role in bone loss."}'::jsonb, 'Osteoporosis: decreased bone mass, increased fractures; low estrogen is a common cause.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('3d1bd753-63a6-5a92-a2a2-5ff17414bb3a', 'neet_ug', 'Zoology', 'Neural Control and Coordination', 'Which of the following structures or regions is incorrectly paired with its function ?', '[{"id": "a", "text": "Hypothalamus : production of releasing hormones and regulation of temperature, hunger and thirst."}, {"id": "b", "text": "Limbic system : consists of fibre tracts that interconnect different regions of brain; controls movement."}, {"id": "c", "text": "Medulla oblongata : controls respiration and cardiovascular reflexes."}, {"id": "d", "text": "Corpus callosum : band of fibers connecting left and right cerebral hemispheres."}]'::jsonb, 'b', 'The limbic system governs emotion, sexual behaviour and motivation, not movement.', 'The limbic system (amygdala, hippocampus and related structures with the hypothalamus) regulates sexual behaviour, expression of emotional reactions and motivation. Coordination of movement is a cerebellum function. The other pairs are correct.', '{"a": "The hypothalamus does all of these, so this is correct.", "c": "The medulla contains respiratory and cardiovascular centres, so this is correct.", "d": "The corpus callosum joins the hemispheres, so this is correct."}'::jsonb, 'Limbic system = inner cerebral parts (amygdala, hippocampus) + hypothalamus; controls emotion and motivation.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('34b9f0ef-d149-5a13-a29f-e46d2ac1ade8', 'neet_ug', 'Zoology', 'Human Reproduction', 'The amnion of mammalian embryo is derived from', '[{"id": "a", "text": "mesoderm and trophoblast"}, {"id": "b", "text": "endoderm and mesoderm"}, {"id": "c", "text": "ectoderm and mesoderm"}, {"id": "d", "text": "ectoderm and endoderm"}]'::jsonb, 'c', 'The amnion is formed from ectoderm on the inside and somatic mesoderm on the outside.', 'Extra-embryonic membranes arise from germ layers: the amnion and chorion develop from ectoderm with somatic mesoderm (somatopleure), while the yolk sac and allantois develop from endoderm with splanchnic mesoderm.', '{"a": "The trophoblast forms the chorion and placenta, not the amnion.", "b": "Endoderm + mesoderm form the yolk sac/allantois.", "d": "There is no ectoderm–endoderm membrane like this."}'::jsonb, 'Amnion and chorion come from somatopleure; yolk sac and allantois from splanchnopleure.', 'med', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('a954a6e1-439d-5f29-8305-34278133d726', 'neet_ug', 'Zoology', 'Human Reproduction', 'Hormones secreted by the placenta to maintain pregnancy are', '[{"id": "a", "text": "hCG, hPL, progestogens, estrogens"}, {"id": "b", "text": "hCG, hPL, estrogens, relaxin, oxytocin"}, {"id": "c", "text": "hCG, hPL, progestogens, prolactin"}, {"id": "d", "text": "hCG, progestogens, estrogens, glucocorticoids"}]'::jsonb, 'a', 'The placenta secretes hCG, hPL, estrogens and progestogens to maintain pregnancy.', 'NCERT lists hCG, hPL, estrogens and progestogens as placental hormones. Relaxin is secreted by the ovary late in pregnancy, oxytocin by the posterior pituitary, prolactin by the anterior pituitary, and glucocorticoids by the adrenal cortex.', '{"b": "Oxytocin is from the pituitary and relaxin from the ovary.", "c": "Prolactin is from the anterior pituitary.", "d": "Glucocorticoids are from the adrenal cortex."}'::jsonb, 'hCG, hPL and relaxin are produced in women only during pregnancy.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('b2498638-b7cf-5930-88ff-e4c33caaf93f', 'neet_ug', 'Zoology', 'Human Reproduction', 'The difference between spermiogenesis and spermiation is', '[{"id": "a", "text": "In spermiogenesis spermatozoa from sertoli cells are released into the cavity of seminiferous tubules, while in spermiation spermatozoa are formed."}, {"id": "b", "text": "In spermiogenesis spermatozoa are formed, while in spermiation spermatids are formed."}, {"id": "c", "text": "In spermiogenesis spermatids are formed, while in spermiation spermatozoa are formed."}, {"id": "d", "text": "In spermiogenesis spermatozoa are formed, while in spermiation spermatozoa are released from sertoli cells into the cavity of seminiferous tubules."}]'::jsonb, 'd', 'Spermiogenesis turns spermatids into sperms; spermiation releases those sperms into the lumen.', 'Spermatids change into spermatozoa by spermiogenesis while embedded in Sertoli cells. Release of the sperm heads from Sertoli cells into the lumen of the seminiferous tubule is called spermiation.', '{"a": "This swaps the two processes.", "b": "Spermatids form from meiosis II, not spermiation.", "c": "Spermatids form by meiosis; spermiogenesis forms spermatozoa."}'::jsonb, 'Spermatogenesis → spermiogenesis → spermiation.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('1f9b69cd-1616-5776-bd05-6d6c5d85ae46', 'neet_ug', 'Zoology', 'Reproductive Health', 'The contraceptive ''SAHELI''', '[{"id": "a", "text": "is an IUD."}, {"id": "b", "text": "increases the concentration of estrogen and prevents ovulation in females."}, {"id": "c", "text": "blocks estrogen receptors in the uterus, preventing eggs from getting implanted."}, {"id": "d", "text": "is a post-coital contraceptive."}]'::jsonb, 'c', 'Saheli is a once-a-week non-steroidal pill that acts as an anti-estrogen on the uterus.', 'Saheli (centchroman), developed by CDRI Lucknow, is a non-steroidal selective estrogen receptor modulator; it blocks estrogen receptors in the uterus so the endometrium is unsuitable for implantation. It is an oral pill taken once a week, not an IUD, it does not raise estrogen, and it is not an emergency post-coital pill.', '{"a": "It is an oral pill, not an IUD.", "b": "It is non-steroidal and does not raise estrogen.", "d": "It is taken weekly as a regular pill, not after coitus."}'::jsonb, 'Saheli: once-a-week non-steroidal oral pill from CDRI Lucknow.', 'med', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('5c3dffe5-4da8-549f-bda7-ee48ba639c22', 'neet_ug', 'Botany', 'Biological Classification', 'Ciliates differ from all other protozoans in', '[{"id": "a", "text": "using pseudopodia for capturing prey"}, {"id": "b", "text": "having a contractile vacuole for removing excess water"}, {"id": "c", "text": "using flagella for locomotion"}, {"id": "d", "text": "having two types of nuclei"}]'::jsonb, 'd', 'Ciliates like Paramecium uniquely have a macronucleus and a micronucleus.', 'Ciliates have nuclear dimorphism, with a large macronucleus for metabolism and a small micronucleus for reproduction; no other protozoan group has this. Pseudopodia are in amoeboids, flagella in flagellates, and contractile vacuoles occur in several freshwater protozoans.', '{"a": "Pseudopodia are typical of amoeboid protozoans.", "b": "Contractile vacuoles also occur in Amoeba and others.", "c": "Flagella are used by flagellated protozoans."}'::jsonb, 'Paramecium has a gullet; cilia move water laden with food into it.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('3c07e871-9b3b-53ef-8606-392a65abbdbc', 'neet_ug', 'Zoology', 'Animal Kingdom', 'Identify the vertebrate group of animals characterized by crop and gizzard in its digestive system.', '[{"id": "a", "text": "Aves"}, {"id": "b", "text": "Reptilia"}, {"id": "c", "text": "Amphibia"}, {"id": "d", "text": "Osteichthyes"}]'::jsonb, 'a', 'Birds have a crop and a gizzard as extra chambers of the alimentary canal.', 'NCERT lists the presence of crop and gizzard as a characteristic of Aves; the crop stores food and the muscular gizzard grinds it. Reptiles, amphibians and bony fishes are not characterised by these.', '{"b": "Reptiles are not defined by crop and gizzard.", "c": "Amphibians lack these chambers.", "d": "Bony fishes lack these chambers."}'::jsonb, 'Aves: pneumatic bones, crop and gizzard, feathers, forelimbs modified into wings.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('7dcd09c3-51ba-57b0-b67b-33a74ae710a4', 'neet_ug', 'Zoology', 'Structural Organisation in Animals', 'Which of the following features is used to identify a male cockroach from a female cockroach ?', '[{"id": "a", "text": "Forewings with darker tegmina"}, {"id": "b", "text": "Presence of caudal styles"}, {"id": "c", "text": "Presence of a boat shaped sternum on the 9th abdominal segment"}, {"id": "d", "text": "Presence of anal cerci"}]'::jsonb, 'b', 'Only male cockroaches have a pair of short, thread-like anal (caudal) styles.', 'In males the 9th sternum bears a pair of short anal styles, which are absent in females. Both sexes have anal cerci and tegmina, and the boat-shaped 7th sternum (with genital pouch) belongs to the female.', '{"a": "Both sexes have tegmina.", "c": "The boat-shaped sternum is the 7th in females.", "d": "Anal cerci occur in both sexes."}'::jsonb, 'In female cockroach, the 7th sternum is boat shaped and forms a genital pouch.', 'med', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('176730c8-148e-595a-a614-017c439fedb1', 'neet_ug', 'Zoology', 'Animal Kingdom', 'Which one of these animals is not a homeotherm ?', '[{"id": "a", "text": "Camelus"}, {"id": "b", "text": "Chelone"}, {"id": "c", "text": "Macropus"}, {"id": "d", "text": "Psittacula"}]'::jsonb, 'b', 'Chelone (turtle) is a reptile and therefore cold-blooded.', 'Birds and mammals are homeothermic. Camelus (camel) and Macropus (kangaroo) are mammals and Psittacula (parrot) is a bird, while Chelone is a turtle, a poikilothermic reptile.', '{"a": "Camel is a mammal and homeothermic.", "c": "Kangaroo is a mammal and homeothermic.", "d": "Parrot is a bird and homeothermic."}'::jsonb, 'Reptiles are poikilotherms; birds and mammals are homeotherms.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('32eb0e13-d94b-5120-b59c-fd628d9e2ba4', 'neet_ug', 'Zoology', 'Animal Kingdom', 'Which of the following animals does not undergo metamorphosis ?', '[{"id": "a", "text": "Moth"}, {"id": "b", "text": "Tunicate"}, {"id": "c", "text": "Earthworm"}, {"id": "d", "text": "Starfish"}]'::jsonb, 'c', 'Earthworm has direct development with no larval stage.', 'Earthworms lay cocoons from which young worms hatch directly, so development is direct. Moths (insects), tunicates (tadpole larva) and starfish (bipinnaria larva) all pass through larval stages and metamorphosis.', '{"a": "Moths have complete metamorphosis.", "b": "Tunicates have a free-swimming tadpole larva.", "d": "Starfish have a bilaterally symmetrical larva."}'::jsonb, 'Echinoderm larvae are bilaterally symmetrical while adults are radially symmetrical.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('12e4e910-819e-5a51-8efb-6e85316c208a', 'neet_ug', 'Botany', 'Biological Classification', 'Which of the following organisms are known as chief producers in the oceans ?', '[{"id": "a", "text": "Cyanobacteria"}, {"id": "b", "text": "Diatoms"}, {"id": "c", "text": "Dinoflagellates"}, {"id": "d", "text": "Euglenoids"}]'::jsonb, 'b', 'Diatoms are the chief producers in the oceans.', 'NCERT describes diatoms (chrysophytes) as the chief producers in the oceans; their silica walls also form diatomaceous earth. Dinoflagellates and cyanobacteria are also photosynthetic but are not given this title.', '{"a": "Cyanobacteria are important but not called chief ocean producers.", "c": "Dinoflagellates are mostly marine but not the chief producers.", "d": "Euglenoids are mostly freshwater."}'::jsonb, 'Diatoms have silica walls; their deposits form diatomaceous earth.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('4964872a-0a73-57e8-baaa-57a6957592f7', 'neet_ug', 'Botany', 'Organisms and Populations', 'Which one of the following population interactions is widely used in medical science for the production of antibiotics ?', '[{"id": "a", "text": "Parasitism"}, {"id": "b", "text": "Mutualism"}, {"id": "c", "text": "Commensalism"}, {"id": "d", "text": "Amensalism"}]'::jsonb, 'd', 'Antibiotic production depends on amensalism: one microbe secretes a substance that harms another, unaffected itself.', 'In amensalism one species is harmed while the other is unaffected (–, 0). Penicillium secreting penicillin that kills bacteria is the classic example, and this antibiosis is exploited to make antibiotics.', '{"a": "Parasitism benefits one and harms the other; it is not the basis of antibiotics.", "b": "Mutualism benefits both.", "c": "Commensalism benefits one and does not affect the other."}'::jsonb, 'Amensalism: one species harmed (–), the other unaffected (0).', 'med', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('5e211c9b-43fa-5b8c-b151-b775b6c3369b', 'neet_ug', 'Botany', 'Biodiversity and Conservation', 'All of the following are included in ''Ex-situ conservation'' except', '[{"id": "a", "text": "Botanical gardens"}, {"id": "b", "text": "Sacred groves"}, {"id": "c", "text": "Wildlife safari parks"}, {"id": "d", "text": "Seed banks"}]'::jsonb, 'b', 'Sacred groves protect species in their natural habitat, so they are in-situ conservation.', 'Ex-situ conservation removes organisms from their habitat to places like botanical gardens, zoos, wildlife safari parks and seed banks. Sacred groves are forest patches protected in place by tradition, making them in-situ.', '{"a": "Botanical gardens are ex-situ.", "c": "Wildlife safari parks are ex-situ.", "d": "Seed banks are ex-situ."}'::jsonb, 'Sacred groves: Khasi and Jaintia hills (Meghalaya), Aravalli hills, Western Ghats, Bastar.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('0fdc6ddf-3758-5dc9-bbc5-d256e4ea665d', 'neet_ug', 'Botany', 'Organisms and Populations', 'In a growing population of a country,', '[{"id": "a", "text": "reproductive and pre-reproductive individuals are equal in number."}, {"id": "b", "text": "reproductive individuals are less than the post-reproductive individuals."}, {"id": "c", "text": "pre-reproductive individuals are more than the reproductive individuals."}, {"id": "d", "text": "pre-reproductive individuals are less than the reproductive individuals."}]'::jsonb, 'c', 'A growing population has a broad base: more pre-reproductive than reproductive individuals.', 'In a triangular (expanding) age pyramid the pre-reproductive group forms the widest base. Equal pre-reproductive and reproductive groups give a stable (bell-shaped) pyramid, and fewer pre-reproductive individuals give a declining (urn-shaped) one.', '{"a": "That describes a stable population.", "b": "That is not a growing pattern.", "d": "That describes a declining population."}'::jsonb, 'Age pyramids: triangular = expanding, bell = stable, urn = declining.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('e1c87b2d-c6bf-5c96-8791-8234de4f3ea7', 'neet_ug', 'Zoology', 'Human Health and Disease', 'Which part of poppy plant is used to obtain the drug "Smack" ?', '[{"id": "a", "text": "Roots"}, {"id": "b", "text": "Latex"}, {"id": "c", "text": "Flowers"}, {"id": "d", "text": "Leaves"}]'::jsonb, 'b', 'Smack (heroin) is made from morphine, which is extracted from the latex of poppy.', 'Heroin, commonly called smack, is diacetylmorphine obtained by acetylation of morphine. Morphine is extracted from the latex of the unripe capsules of Papaver somniferum.', '{"a": "Roots are not the source of opioids.", "c": "Flowers are not used.", "d": "Leaves are not used."}'::jsonb, 'Heroin (smack) is a depressant that slows body functions.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('b4776558-24ef-5f7d-adeb-33df115d0a48', 'neet_ug', 'Botany', 'Molecular Basis of Inheritance', 'All of the following are part of an operon except', '[{"id": "a", "text": "an enhancer"}, {"id": "b", "text": "structural genes"}, {"id": "c", "text": "an operator"}, {"id": "d", "text": "a promoter"}]'::jsonb, 'a', 'Enhancers are eukaryotic regulatory elements, not part of the prokaryotic operon.', 'A bacterial operon has a promoter, an operator and structural genes transcribed together (the regulator gene may lie nearby). Enhancers are sequences that boost transcription in eukaryotes and are not components of an operon.', '{"b": "Structural genes (z, y, a) are part of the lac operon.", "c": "The operator binds the repressor.", "d": "The promoter binds RNA polymerase."}'::jsonb, 'Polycistronic structural genes of an operon share one promoter and operator.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('0ab1e8a0-816c-5df4-84a0-dea53956f3f9', 'neet_ug', 'Botany', 'Principles of Inheritance and Variation', 'A woman has an X-linked condition on one of her X chromosomes. This chromosome can be inherited by', '[{"id": "a", "text": "Only grandchildren"}, {"id": "b", "text": "Only sons"}, {"id": "c", "text": "Only daughters"}, {"id": "d", "text": "Both sons and daughters"}]'::jsonb, 'd', 'A mother passes one X to every child, so either son or daughter can receive that X.', 'Every child, male or female, gets one X chromosome from the mother. So the affected X has a 50% chance of going to any son or daughter.', '{"a": "It can reach her children directly.", "b": "Daughters also receive a maternal X.", "c": "Sons receive their only X from the mother."}'::jsonb, 'Sons get the X only from the mother; criss-cross inheritance in X-linked traits.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('e0ed0095-5c31-5c0d-ac5f-29128d3b1c07', 'neet_ug', 'Zoology', 'Evolution', 'According to Hugo de Vries, the mechanism of evolution is', '[{"id": "a", "text": "Phenotypic variations"}, {"id": "b", "text": "Saltation"}, {"id": "c", "text": "Multiple step mutations"}, {"id": "d", "text": "Minor mutations"}]'::jsonb, 'b', 'De Vries proposed that large single-step mutations (saltation) cause speciation.', 'Working on evening primrose, Hugo de Vries suggested that mutations are large, sudden and random and can cause speciation in a single step, which he called saltation. Darwin, in contrast, emphasised small gradual variations.', '{"a": "Darwin emphasised small phenotypic variations.", "c": "De Vries proposed single-step, not multiple-step changes.", "d": "He stressed large, not minor, mutations."}'::jsonb, 'De Vries worked on Oenothera lamarckiana (evening primrose).', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('3aa3f35c-ba52-5b97-86fc-6fa9da81693b', 'neet_ug', 'Botany', 'Molecular Basis of Inheritance', 'AGGTATCGCAT is a sequence from the coding strand of a gene. What will be the corresponding sequence of the transcribed mRNA ?', '[{"id": "a", "text": "ACCUAUGCGAU"}, {"id": "b", "text": "UGGTUTCGCAT"}, {"id": "c", "text": "AGGUAUCGCAU"}, {"id": "d", "text": "UCCAUAGCGUA"}]'::jsonb, 'c', 'mRNA has the same sequence as the coding strand, with U in place of T.', 'The template strand is complementary to the coding strand, and mRNA is complementary to the template, so mRNA matches the coding strand. Replacing every T with U in AGGTATCGCAT gives AGGUAUCGCAU.', '{"a": "This is not the coding sequence with T→U.", "b": "mRNA cannot contain T.", "d": "This is complementary to the coding strand (template-like)."}'::jsonb, 'Coding strand = sense strand; it has the same sequence as mRNA (T replaced by U).', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('f046e2ff-d99b-539c-a316-cdf27a0e59d3', 'neet_ug', 'Zoology', 'Human Reproduction', 'Match the items given in Column I with those in Column II and select the correct option given below :
Column I | Column II
a. Proliferative Phase | i. Breakdown of endometrial lining
b. Secretory Phase | ii. Follicular Phase
c. Menstruation | iii. Luteal Phase', '[{"id": "a", "text": "a-ii, b-iii, c-i"}, {"id": "b", "text": "a-i, b-iii, c-ii"}, {"id": "c", "text": "a-iii, b-ii, c-i"}, {"id": "d", "text": "a-iii, b-i, c-ii"}]'::jsonb, 'a', 'Proliferative = follicular, secretory = luteal, menstruation = breakdown of endometrium.', 'In the follicular phase rising estrogen makes the endometrium proliferate, so it is also called the proliferative phase. In the luteal phase progesterone from the corpus luteum makes it secretory. Menstruation is the shedding of the endometrial lining.', '{"b": "Proliferative phase is not endometrial breakdown.", "c": "Proliferative phase is not the luteal phase.", "d": "Proliferative phase is not the luteal phase."}'::jsonb, 'Corpus luteum secretes progesterone, essential to maintain the endometrium.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('766e9d44-0103-5f0d-95dd-f69235343351', 'neet_ug', 'Zoology', 'Excretory Products and their Elimination', 'Match the items given in Column I with those in Column II and select the correct option given below :
Column I | Column II
a. Glycosuria | i. Accumulation of uric acid in joints
b. Gout | ii. Mass of crystallised salts within the kidney
c. Renal calculi | iii. Inflammation in glomeruli
d. Glomerular nephritis | iv. Presence of glucose in urine', '[{"id": "a", "text": "a-ii, b-iii, c-i, d-iv"}, {"id": "b", "text": "a-i, b-ii, c-iii, d-iv"}, {"id": "c", "text": "a-iii, b-ii, c-iv, d-i"}, {"id": "d", "text": "a-iv, b-i, c-ii, d-iii"}]'::jsonb, 'd', 'Glycosuria = glucose in urine, gout = uric acid in joints, renal calculi = kidney stones, glomerulonephritis = inflamed glomeruli.', 'Glycosuria literally means sugar (glucose) in urine (iv). Gout is caused by deposition of uric acid crystals in joints (i). Renal calculi are stones or masses of crystallised salts (oxalates etc.) formed in the kidney (ii). Glomerulonephritis is inflammation of the glomeruli (iii). So a-iv, b-i, c-ii, d-iii.', '{"a": "Glycosuria is not about crystallised salts and gout is not glomerular inflammation.", "b": "Shifts every term by one; glycosuria is not uric acid accumulation.", "c": "Glycosuria is not glomerular inflammation and renal calculi do not mean glucose in urine."}'::jsonb, 'Presence of glucose (glycosuria) and ketone bodies (ketonuria) in urine indicates diabetes mellitus.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('83b715e9-f7d0-59dc-a562-a13cf58fa2b3', 'neet_ug', 'Zoology', 'Excretory Products and their Elimination', 'Match the items given in Column I with those in Column II and select the correct option given below :
Column I (Function) | Column II (Part of Excretory System)
a. Ultrafiltration | i. Henle''s loop
b. Concentration of urine | ii. Ureter
c. Transport of urine | iii. Urinary bladder
d. Storage of urine | iv. Malpighian corpuscle
 | v. Proximal convoluted tubule', '[{"id": "a", "text": "a-v, b-iv, c-i, d-ii"}, {"id": "b", "text": "a-iv, b-i, c-ii, d-iii"}, {"id": "c", "text": "a-iv, b-v, c-ii, d-iii"}, {"id": "d", "text": "a-v, b-iv, c-i, d-iii"}]'::jsonb, 'b', 'Ultrafiltration occurs in the Malpighian corpuscle, concentration in Henle''s loop, transport through the ureter and storage in the urinary bladder.', 'Glomerular (ultra)filtration takes place across the glomerulus–Bowman''s capsule, i.e. the Malpighian corpuscle (iv). The loop of Henle, via the counter-current mechanism, is chiefly responsible for concentrating urine (i). Ureters carry urine from kidney to bladder (ii), and the urinary bladder stores it (iii).', '{"a": "PCT is the main site of reabsorption, not ultrafiltration; the ureter does not store urine.", "c": "PCT reabsorbs solutes but the main concentrating segment is Henle''s loop.", "d": "Ultrafiltration is not in the PCT, and Henle''s loop does not transport urine to the bladder."}'::jsonb, 'The Malpighian body (renal corpuscle) = glomerulus + Bowman''s capsule; GFR in a healthy adult is about 125 mL/min.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('c3a68d29-8eaf-5b89-865e-05e68e922082', 'neet_ug', 'Zoology', 'Body Fluids and Circulation', 'Match the items given in Column I with those in Column II and select the correct option given below :
Column I | Column II
a. Fibrinogen | i. Osmotic balance
b. Globulin | ii. Blood clotting
c. Albumin | iii. Defence mechanism', '[{"id": "a", "text": "a-i, b-iii, c-ii"}, {"id": "b", "text": "a-i, b-ii, c-iii"}, {"id": "c", "text": "a-iii, b-ii, c-i"}, {"id": "d", "text": "a-ii, b-iii, c-i"}]'::jsonb, 'd', 'Fibrinogen clots blood, globulins defend the body and albumin maintains osmotic balance.', 'Fibrinogen is converted to fibrin during coagulation (ii). Globulins (including immunoglobulins) are mainly involved in the defence mechanisms of the body (iii). Albumin, the most abundant plasma protein, maintains colloidal osmotic pressure (i).', '{"a": "Fibrinogen has no role in osmotic balance; albumin does not clot blood.", "b": "Globulin is not a clotting factor and albumin is not the main defence protein.", "c": "Fibrinogen is not a defence protein and globulin does not clot blood."}'::jsonb, 'Plasma proteins form 6–8% of plasma; fibrinogen, globulins and albumins are the major ones.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('8bfb50b5-7e5b-5664-815c-e762c6160638', 'neet_ug', 'Zoology', 'Breathing and Exchange of Gases', 'Which of the following is an occupational respiratory disorder ?', '[{"id": "a", "text": "Botulism"}, {"id": "b", "text": "Silicosis"}, {"id": "c", "text": "Anthracis"}, {"id": "d", "text": "Emphysema"}]'::jsonb, 'b', 'Silicosis results from long-term inhalation of silica dust in stone-grinding and mining industries.', 'Occupational respiratory disorders arise from chronic exposure to dust at the workplace; silica dust causes silicosis and asbestos causes asbestosis, leading to lung fibrosis. Botulism is food poisoning by Clostridium botulinum toxin, anthrax is a bacterial infection, and emphysema is mainly caused by cigarette smoking.', '{"a": "Botulism is a food-borne neuroparalytic toxin illness, not a respiratory occupational disorder.", "c": "Anthrax is an infectious disease caused by Bacillus anthracis, not the dust-induced disorder NCERT lists.", "d": "Emphysema is a chronic disorder mainly due to smoking, with damaged alveolar walls."}'::jsonb, 'Silicosis and asbestosis cause inflammation and fibrosis of lung tissue; workers should wear protective masks.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('cac49c86-875f-588a-acec-73d9add56c8f', 'neet_ug', 'Zoology', 'Locomotion and Movement', 'Calcium is important in skeletal muscle contraction because it', '[{"id": "a", "text": "detaches the myosin head from the actin filament."}, {"id": "b", "text": "activates the myosin ATPase by binding to it."}, {"id": "c", "text": "binds to troponin to remove the masking of active sites on actin for myosin."}, {"id": "d", "text": "prevents the formation of bonds between the myosin cross bridges and the actin filament."}]'::jsonb, 'c', 'Ca²⁺ binds troponin, shifting tropomyosin and exposing myosin-binding sites on actin.', 'A neural signal releases Ca²⁺ from the sarcoplasmic reticulum. Ca²⁺ binds to the troponin subunit on the thin filament, which moves tropomyosin and unmasks the active sites on actin. Myosin heads can then bind to form cross bridges and pull actin, causing contraction.', '{"a": "Detachment of the myosin head is caused by binding of a new ATP, not calcium.", "b": "Myosin head itself has ATPase activity; Ca²⁺ does not bind myosin to activate it.", "d": "Calcium promotes, not prevents, cross-bridge formation."}'::jsonb, 'In resting muscle, troponin–tropomyosin masks the myosin-binding sites on actin; Ca²⁺ removes this masking.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('7fd2564e-7540-5ca7-b683-555a99a7929c', 'neet_ug', 'Zoology', 'Neural Control and Coordination', 'Nissl bodies are mainly composed of', '[{"id": "a", "text": "Nucleic acids and SER"}, {"id": "b", "text": "DNA and RNA"}, {"id": "c", "text": "Proteins and lipids"}, {"id": "d", "text": "Free ribosomes and RER"}]'::jsonb, 'd', 'Nissl granules in the neuron cell body are clusters of free ribosomes and rough ER.', 'The cyton of a neuron contains granular bodies called Nissl''s granules, which are aggregates of rough endoplasmic reticulum and free ribosomes. They reflect the high protein-synthesising activity of neurons.', '{"a": "SER is not a component of Nissl bodies.", "b": "Nissl bodies are not made of DNA; they contain rRNA within ribosomes.", "c": "Proteins and lipids describe membranes in general, not the specific make-up of Nissl bodies."}'::jsonb, 'Nissl''s granules are present in the cell body and dendrites but absent from the axon.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('60453500-d276-59f0-886c-ddb476638a22', 'neet_ug', 'Botany', 'Respiration in Plants', 'Which of these statements is incorrect ?', '[{"id": "a", "text": "Glycolysis operates as long as it is supplied with NAD that can pick up hydrogen atoms."}, {"id": "b", "text": "Glycolysis occurs in cytosol."}, {"id": "c", "text": "Enzymes of TCA cycle are present in mitochondrial matrix."}, {"id": "d", "text": "Oxidative phosphorylation takes place in outer mitochondrial membrane."}]'::jsonb, 'd', 'Oxidative phosphorylation occurs on the inner mitochondrial membrane, not the outer one.', 'The electron transport chain complexes and ATP synthase (F₀–F₁) are located in the inner mitochondrial membrane, so oxidative phosphorylation happens there. Glycolysis takes place in the cytosol and needs NAD⁺ to accept hydrogen; TCA cycle enzymes lie in the matrix (except succinate dehydrogenase, bound to the inner membrane).', '{"a": "True: glycolysis stalls if NAD⁺ is not regenerated.", "b": "True: glycolysis is a cytoplasmic pathway.", "c": "True: Krebs cycle enzymes are located in the mitochondrial matrix."}'::jsonb, 'ETS and ATP synthase are located in the inner mitochondrial membrane; F₁ head projects into the matrix.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('c30ff194-4c9b-5860-9552-cea42d1c7e85', 'neet_ug', 'Botany', 'Cell: The Unit of Life', 'Select the incorrect match :', '[{"id": "a", "text": "Submetacentric chromosomes – L-shaped chromosomes"}, {"id": "b", "text": "Allosomes – Sex chromosomes"}, {"id": "c", "text": "Lampbrush chromosomes – Diplotene bivalents"}, {"id": "d", "text": "Polytene chromosomes – Oocytes of amphibians"}]'::jsonb, 'd', 'Polytene chromosomes occur in insect salivary glands; amphibian oocytes have lampbrush chromosomes.', 'Polytene chromosomes arise from repeated DNA replication without cell division and are typical of salivary glands of Drosophila and other dipteran larvae. Lampbrush chromosomes are seen in diplotene bivalents of amphibian oocytes. Submetacentric chromosomes, with unequal arms, appear L-shaped at anaphase, and allosomes are sex chromosomes.', '{"a": "Correct match: the centromere slightly off-centre gives an L shape.", "b": "Correct match: allosomes are sex chromosomes, as opposed to autosomes.", "c": "Correct match: lampbrush chromosomes are diplotene bivalents in oocytes."}'::jsonb, 'Based on centromere position, chromosomes are metacentric, submetacentric, acrocentric and telocentric.', 'med', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('bffbd856-38d4-59d1-b807-c74b17ed4930', 'neet_ug', 'Botany', 'Cell: The Unit of Life', 'Which of the following events does not occur in rough endoplasmic reticulum ?', '[{"id": "a", "text": "Cleavage of signal peptide"}, {"id": "b", "text": "Protein glycosylation"}, {"id": "c", "text": "Protein folding"}, {"id": "d", "text": "Phospholipid synthesis"}]'::jsonb, 'd', 'Lipids, including phospholipids, are synthesised in the smooth ER, not the rough ER.', 'RER is studded with ribosomes and handles synthesis and early processing of secretory and membrane proteins: removal of the signal peptide by signal peptidase, initial (N-linked) glycosylation and folding by chaperones. The smooth ER is the major site of lipid synthesis, including phospholipids and steroids.', '{"a": "Signal peptide is cleaved in the RER lumen as the polypeptide enters.", "b": "N-linked glycosylation of proteins begins in the RER.", "c": "Newly made proteins fold in the RER with the help of chaperones."}'::jsonb, 'SER is the major site of lipid synthesis; in animal cells it makes steroidal hormones.', 'med', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('751925d7-5b95-5da2-93a0-905a5d5f15ea', 'neet_ug', 'Botany', 'Molecular Basis of Inheritance', 'Many ribosomes may associate with a single mRNA to form multiple copies of a polypeptide simultaneously. Such strings of ribosomes are termed as', '[{"id": "a", "text": "Plastidome"}, {"id": "b", "text": "Polyhedral bodies"}, {"id": "c", "text": "Polysome"}, {"id": "d", "text": "Nucleosome"}]'::jsonb, 'c', 'Several ribosomes translating one mRNA together form a polysome (polyribosome).', 'A single mRNA can be read by many ribosomes at once, each producing its own copy of the polypeptide; this chain is called a polysome or polyribosome. A nucleosome is a DNA–histone unit, and a plastidome is the total plastids of a cell.', '{"a": "Plastidome refers to all plastids of a cell.", "b": "Polyhedral bodies are unrelated (e.g. viral inclusion or carboxysome-like structures).", "d": "Nucleosome is histone octamer wrapped by DNA, part of chromatin."}'::jsonb, 'Polysomes increase the rate of protein synthesis from one mRNA.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('4317323f-59b1-5cb5-b50f-290bcbf5a2c5', 'neet_ug', 'Zoology', 'Human Health and Disease', 'In which disease does mosquito transmitted pathogen cause chronic inflammation of lymphatic vessels ?', '[{"id": "a", "text": "Ringworm disease"}, {"id": "b", "text": "Ascariasis"}, {"id": "c", "text": "Elephantiasis"}, {"id": "d", "text": "Amoebiasis"}]'::jsonb, 'c', 'Filariasis (elephantiasis) is caused by Wuchereria, spread by Culex mosquito, and inflames lymphatic vessels.', 'Wuchereria bancrofti and W. malayi, transmitted by the bite of female mosquitoes, live in the lymphatic vessels of the lower limbs, causing slowly developing chronic inflammation and gross swelling called elephantiasis or filariasis.', '{"a": "Ringworm is a fungal skin infection spread by contact.", "b": "Ascariasis spreads through contaminated food and water, not mosquitoes.", "d": "Amoebiasis is spread by houseflies carrying Entamoeba cysts to food."}'::jsonb, 'Filarial worms (Wuchereria) are transmitted by female Culex mosquitoes and can also deform genital organs.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('c81966e8-e0f5-5353-b464-f3790b82780e', 'neet_ug', 'Zoology', 'Human Health and Disease', 'Which of the following is not an autoimmune disease ?', '[{"id": "a", "text": "Alzheimer''s disease"}, {"id": "b", "text": "Rheumatoid arthritis"}, {"id": "c", "text": "Psoriasis"}, {"id": "d", "text": "Vitiligo"}]'::jsonb, 'a', 'Alzheimer''s is a neurodegenerative disorder, not an autoimmune disease.', 'In autoimmune diseases the immune system attacks self-cells: rheumatoid arthritis (joint synovium), psoriasis (skin) and vitiligo (melanocytes) are all examples. Alzheimer''s disease is a progressive neurodegenerative disease linked to amyloid plaques and reduced acetylcholine, not to an autoimmune attack.', '{"b": "Rheumatoid arthritis is the classic NCERT example of autoimmunity.", "c": "Psoriasis involves T-cell-mediated attack on skin cells.", "d": "Vitiligo results from immune destruction of melanocytes."}'::jsonb, 'NCERT cites rheumatoid arthritis as an example of autoimmune disease.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('d19844e6-423c-50fa-b779-5e8ff277b034', 'neet_ug', 'Zoology', 'Evolution', 'Among the following sets of examples for divergent evolution, select the incorrect option :', '[{"id": "a", "text": "Brain of bat, man and cheetah"}, {"id": "b", "text": "Heart of bat, man and cheetah"}, {"id": "c", "text": "Forelimbs of man, bat and cheetah"}, {"id": "d", "text": "Eye of octopus, bat and man"}]'::jsonb, 'd', 'Eyes of octopus and mammals are analogous, a case of convergent, not divergent, evolution.', 'Divergent evolution produces homologous structures sharing common ancestry, such as the forelimbs, hearts and brains of mammals like bat, man and cheetah. The eye of the octopus (mollusc) and of mammals are similar in function but differ in origin, so they are analogous structures arising by convergent evolution.', '{"a": "Mammalian brains are homologous, so this is valid divergent evolution.", "b": "Vertebrate hearts are homologous structures.", "c": "Forelimbs of mammals are the standard NCERT example of homology."}'::jsonb, 'Homology indicates divergent evolution; analogy (e.g. eyes of octopus and mammals) indicates convergent evolution.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('56e22cb7-3b5d-526c-bfed-ab0e9efe9840', 'neet_ug', 'Botany', 'Microbes in Human Welfare', 'Conversion of milk to curd improves its nutritional value by increasing the amount of', '[{"id": "a", "text": "Vitamin B₁₂"}, {"id": "b", "text": "Vitamin A"}, {"id": "c", "text": "Vitamin D"}, {"id": "d", "text": "Vitamin E"}]'::jsonb, 'a', 'Lactic acid bacteria in curd increase its vitamin B₁₂ content.', 'Lactobacillus and other lactic acid bacteria convert milk to curd by producing acids that coagulate and partially digest milk proteins. NCERT notes that LAB also improve nutritional quality by increasing vitamin B₁₂, and they check disease-causing microbes in the stomach.', '{"b": "Vitamin A content is not increased by lactic acid fermentation.", "c": "Vitamin D is not synthesised by LAB.", "d": "Vitamin E is not produced by curd-forming bacteria."}'::jsonb, 'LAB (Lactobacillus) improve nutritional quality of curd by increasing vitamin B₁₂.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('79b662ee-56e4-55f1-a31b-9c44bc5262dc', 'neet_ug', 'Zoology', 'Evolution', 'The similarity of bone structure in the forelimbs of many vertebrates is an example of', '[{"id": "a", "text": "Convergent evolution"}, {"id": "b", "text": "Analogy"}, {"id": "c", "text": "Homology"}, {"id": "d", "text": "Adaptive radiation"}]'::jsonb, 'c', 'Vertebrate forelimbs share the same basic bone plan despite different functions, which is homology.', 'Whales, bats, cheetahs and humans have forelimbs with the same arrangement of humerus, radius, ulna, carpals, metacarpals and phalanges, though they perform different functions. Structures with common origin and anatomy but different functions are homologous, reflecting common ancestry.', '{"a": "Convergent evolution gives analogous, not homologous, structures.", "b": "Analogous organs have different structure but similar function, the opposite case.", "d": "Adaptive radiation is the diversification of a lineage into many forms; forelimb similarity is evidence of homology itself."}'::jsonb, 'Homologous organs: same structure, different function (divergent evolution); e.g. thorns of Bougainvillea and tendrils of Cucurbita.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('2040be88-3ee4-5542-85c3-0c2447cbc17c', 'neet_ug', 'Botany', 'Principles of Inheritance and Variation', 'Which of the following characteristics represent ''Inheritance of blood groups'' in humans ?
a. Dominance
b. Co-dominance
c. Multiple allele
d. Incomplete dominance
e. Polygenic inheritance', '[{"id": "a", "text": "b, d and e"}, {"id": "b", "text": "a, b and c"}, {"id": "c", "text": "b, c and e"}, {"id": "d", "text": "a, c and e"}]'::jsonb, 'b', 'ABO blood groups show dominance, co-dominance and multiple alleles.', 'The ABO gene I has three alleles (Iᴬ, Iᴮ, i), so it shows multiple allelism. Iᴬ and Iᴮ are each completely dominant over i (dominance), while Iᴬ and Iᴮ together express both antigens in AB individuals (co-dominance). A single gene controls it, so it is not polygenic, and there is no incomplete dominance.', '{"a": "No incomplete dominance and no polygenic control in ABO inheritance.", "c": "ABO blood group is controlled by a single gene, not polygenes.", "d": "Polygenic inheritance does not apply; it omits co-dominance."}'::jsonb, 'Six genotypes and four phenotypes are possible for the human ABO blood group.', 'easy', true, 2018, NULL, 'NEET UG 2018 (NTA) · answer verified by UG Prep', NULL),
('9d4dac88-7a23-52d2-8df7-a71cfb10b30b', 'neet_ug', 'Chemistry', 'Thermodynamics', 'Under isothermal condition, a gas at 300 K expands from 0.1 L to 0.25 L against a constant external pressure of 2 bar. The work done by the gas is :-
[Given that 1 L bar = 100 J]', '[{"id": "a", "text": "–30 J"}, {"id": "b", "text": "5 kJ"}, {"id": "c", "text": "25 J"}, {"id": "d", "text": "30 J"}]'::jsonb, 'a', 'For irreversible expansion against constant pressure, w = –pₑₓΔV = –2 × 0.15 L bar = –30 J.', 'ΔV = 0.25 – 0.10 = 0.15 L. w = –pₑₓΔV = –2 bar × 0.15 L = –0.30 L bar = –30 J. Under the IUPAC sign convention used by NCERT, the negative sign shows that the system does work on the surroundings.', '{"b": "Wrong magnitude: 0.3 L bar is 30 J, not 5 kJ.", "c": "Wrong product: pΔV here is 0.3 L bar = 30 J, not 25 J.", "d": "Correct magnitude but wrong sign under the convention w = –pₑₓΔV for expansion."}'::jsonb, 'Work of irreversible expansion against constant external pressure: w = –pₑₓ(V_f – V_i).', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('55950359-efb8-5ea3-85f7-083d4299a6b0', 'neet_ug', 'Chemistry', 'Equilibrium', 'pH of a saturated solution of Ca(OH)₂ is 9. The solubility product (Ksp) of Ca(OH)₂ is :-', '[{"id": "a", "text": "0.5 × 10⁻¹⁵"}, {"id": "b", "text": "0.25 × 10⁻¹⁰"}, {"id": "c", "text": "0.125 × 10⁻¹⁵"}, {"id": "d", "text": "0.5 × 10⁻¹⁰"}]'::jsonb, 'a', 'pOH = 5 gives [OH⁻] = 10⁻⁵ M, so Ksp = [Ca²⁺][OH⁻]² = (0.5 × 10⁻⁵)(10⁻⁵)² = 0.5 × 10⁻¹⁵.', 'pH 9 means pOH = 5, so [OH⁻] = 1 × 10⁻⁵ M. Each Ca(OH)₂ gives 2 OH⁻, so [Ca²⁺] = 0.5 × 10⁻⁵ M. Ksp = [Ca²⁺][OH⁻]² = 0.5 × 10⁻⁵ × 10⁻¹⁰ = 0.5 × 10⁻¹⁵.', '{"b": "Comes from squaring 0.5 × 10⁻⁵ instead of using [OH⁻]².", "c": "Uses 4s³ with s taken as 0.5 × 10⁻⁵ applied wrongly (counts the factor of 2 twice).", "d": "Off by 10⁵; treats [OH⁻] as 10⁻² or misreads pOH."}'::jsonb, 'For a 1:2 salt AB₂ with solubility s, Ksp = 4s³ = [A²⁺][B⁻]².', 'med', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('b629cd63-fbf9-5e1c-964a-7177acfd81dd', 'neet_ug', 'Chemistry', 'Some Basic Concepts of Chemistry', 'The number of moles of hydrogen molecules required to produce 20 moles of ammonia through Haber''s process is :-', '[{"id": "a", "text": "10"}, {"id": "b", "text": "20"}, {"id": "c", "text": "30"}, {"id": "d", "text": "40"}]'::jsonb, 'c', 'N₂ + 3H₂ → 2NH₃, so 20 mol NH₃ needs (3/2) × 20 = 30 mol H₂.', 'The balanced equation N₂ + 3H₂ → 2NH₃ gives a H₂ : NH₃ mole ratio of 3 : 2. For 20 mol NH₃, H₂ = 20 × 3/2 = 30 mol.', '{"a": "This is the moles of N₂ required, not H₂.", "b": "Assumes a 1:1 ratio between H₂ and NH₃.", "d": "Uses a 2:1 ratio instead of 3:2."}'::jsonb, 'Haber process: N₂(g) + 3H₂(g) ⇌ 2NH₃(g), ΔH < 0, Fe catalyst with Mo promoter.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('d8f04444-b5f8-5334-903d-19d9b49c704d', 'neet_ug', 'Chemistry', 'Solutions', 'For an ideal solution, the correct option is :-', '[{"id": "a", "text": "Δ_mix S = 0 at constant T and P"}, {"id": "b", "text": "Δ_mix V ≠ 0 at constant T and P"}, {"id": "c", "text": "Δ_mix H = 0 at constant T and P"}, {"id": "d", "text": "Δ_mix G = 0 at constant T and P"}]'::jsonb, 'c', 'An ideal solution forms with no heat change and no volume change: Δ_mix H = 0 and Δ_mix V = 0.', 'In an ideal solution the A–B interactions equal the A–A and B–B interactions, so no heat is absorbed or released (Δ_mix H = 0) and volumes are additive (Δ_mix V = 0). Mixing still increases disorder, so Δ_mix S > 0 and Δ_mix G < 0.', '{"a": "Mixing always increases entropy, so Δ_mix S > 0.", "b": "For an ideal solution Δ_mix V = 0.", "d": "Mixing is spontaneous, so Δ_mix G < 0."}'::jsonb, 'Ideal solutions obey Raoult''s law over the whole range, with Δ_mix H = 0 and Δ_mix V = 0.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('0571bf3b-4272-5ae3-bb3f-a0404fca0271', 'neet_ug', 'Chemistry', 'Electrochemistry', 'For a cell involving one electron E°cell = 0.59 V at 298 K, the equilibrium constant for the cell reaction is :-
[Given that 2.303RT/F = 0.059 V at T = 298 K]', '[{"id": "a", "text": "1.0 × 10²"}, {"id": "b", "text": "1.0 × 10⁵"}, {"id": "c", "text": "1.0 × 10¹⁰"}, {"id": "d", "text": "1.0 × 10³⁰"}]'::jsonb, 'c', 'log K = nE°/0.059 = 1 × 0.59/0.059 = 10, so K = 10¹⁰.', 'At equilibrium E_cell = 0, so E° = (0.059/n) log K. With n = 1, log K = 0.59/0.059 = 10, giving K = 1.0 × 10¹⁰.', '{"a": "Would need E° = 0.118 V.", "b": "Would need E° = 0.295 V or n = 1/2.", "d": "Would correspond to n = 3."}'::jsonb, 'E°cell = (0.059/n) log K at 298 K; ΔG° = –nFE° = –RT ln K.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('40f09973-2047-5972-81e5-1c3b60dec18f', 'neet_ug', 'Chemistry', 'Organic Chemistry – Some Basic Principles and Techniques', 'The number of sigma (σ) and pi (π) bonds in pent-2-en-4-yne is :-', '[{"id": "a", "text": "10 σ bonds and 3π bonds"}, {"id": "b", "text": "8 σ bonds and 5π bonds"}, {"id": "c", "text": "11 σ bonds and 2π bonds"}, {"id": "d", "text": "13 σ bonds and no π bond"}]'::jsonb, 'a', 'CH₃–CH=CH–C≡CH has 4 C–C σ + 6 C–H σ = 10 σ, and 1 + 2 = 3 π bonds.', 'The structure is CH₃–CH=CH–C≡CH. There are 4 carbon–carbon σ bonds and 6 C–H bonds (3 + 1 + 1 + 1), giving 10 σ. The C=C contributes 1 π and the C≡C contributes 2 π, giving 3 π.', '{"b": "Undercounts C–H σ bonds and overcounts π bonds.", "c": "Counts the triple bond as having only one π bond.", "d": "Treats the molecule as saturated."}'::jsonb, 'Every single bond is σ; a double bond is 1σ + 1π; a triple bond is 1σ + 2π.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('cd6fc685-6283-585e-b896-dcc1153a66a1', 'neet_ug', 'Chemistry', 'Chemical Bonding and Molecular Structure', 'Which of the following diatomic molecular species has only π bonds according to Molecular Orbital Theory ?', '[{"id": "a", "text": "O₂"}, {"id": "b", "text": "N₂"}, {"id": "c", "text": "C₂"}, {"id": "d", "text": "Be₂"}]'::jsonb, 'c', 'In C₂ (KK σ2s² σ*2s² π2p⁴) the bond order of 2 comes entirely from the two π2p bonding pairs.', 'C₂ has 12 electrons: σ1s² σ*1s² σ2s² σ*2s² (π2pₓ² = π2p_y²). The σ2s and σ*2s cancel, so the bond order of 2 comes only from the filled π orbitals, with σ2p empty. O₂ and N₂ contain a σ2p bond, and Be₂ has bond order zero.', '{"a": "O₂ has a σ2p bond plus net π bonding.", "b": "N₂ has one σ2p and two π bonds.", "d": "Be₂ has bond order 0 and does not exist as a stable molecule."}'::jsonb, 'C₂ is diamagnetic with bond order 2, and both bonds are π bonds.', 'med', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('cb16d2ab-242c-5f88-b964-11a455ee36c3', 'neet_ug', 'Chemistry', 'Redox Reactions', 'Which of the following reactions are disproportionation reaction ?
(a) 2Cu⁺ → Cu²⁺ + Cu⁰
(b) 3MnO₄²⁻ + 4H⁺ → 2MnO₄⁻ + MnO₂ + 2H₂O
(c) 2KMnO₄ –Δ→ K₂MnO₄ + MnO₂ + O₂
(d) 2MnO₄⁻ + 3Mn²⁺ + 2H₂O → 5MnO₂ + 4H⁺
Select the correct option from the following :-', '[{"id": "a", "text": "(a) and (b) only"}, {"id": "b", "text": "(a), (b) and (c)"}, {"id": "c", "text": "(a), (c) and (d)"}, {"id": "d", "text": "(a) and (d) only"}]'::jsonb, 'a', 'Only (a) and (b) have one species in one oxidation state being both oxidised and reduced.', '(a) Cu(+1) goes to +2 and 0, and (b) Mn(+6) goes to +7 and +4, so both are disproportionation. In (c), Mn(+7) is only reduced (to +6 and +4) while oxygen is oxidised, so it is an ordinary intramolecular redox reaction. (d) is the reverse case (comproportionation): Mn(+7) and Mn(+2) combine to give Mn(+4).', '{"b": "Includes (c), where a different element (O) is oxidised.", "c": "Includes (c) and (d), neither of which is disproportionation.", "d": "(d) is comproportionation and it leaves out (b)."}'::jsonb, 'Disproportionation: the same element in one oxidation state is simultaneously oxidised and reduced.', 'med', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('b383afcf-b49c-5120-ba30-7c8f64028af7', 'neet_ug', 'Chemistry', 'Amines', 'The correct order of the basic strength of methyl substituted amines in aqueous solution is :-', '[{"id": "a", "text": "(CH₃)₂NH > CH₃NH₂ > (CH₃)₃N"}, {"id": "b", "text": "(CH₃)₃N > CH₃NH₂ > (CH₃)₂NH"}, {"id": "c", "text": "(CH₃)₃N > (CH₃)₂NH > CH₃NH₂"}, {"id": "d", "text": "CH₃NH₂ > (CH₃)₂NH > (CH₃)₃N"}]'::jsonb, 'a', 'In water, methylamines follow 2° > 1° > 3° because of the balance of +I effect, H-bond solvation and steric hindrance.', 'The +I effect of methyl groups raises basicity, but in water the protonated ammonium ion is also stabilised by H-bonding, which is strongest for ions with more N–H. Tertiary ammonium has only one N–H and is crowded, so (CH₃)₃N falls below CH₃NH₂. The net order is (CH₃)₂NH > CH₃NH₂ > (CH₃)₃N.', '{"b": "Puts the tertiary amine first; that is not the order in water.", "c": "This is the gas-phase order based on the inductive effect alone.", "d": "Ignores the +I effect, which makes the secondary amine strongest."}'::jsonb, 'Aqueous basicity: methyl amines 2° > 1° > 3° > NH₃; ethyl amines 2° > 3° > 1° > NH₃.', 'med', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('5ed80cc8-49c0-556d-8599-960b7c58a2fe', 'neet_ug', 'Chemistry', 'Equilibrium', 'Conjugate base for Bronsted acids H₂O and HF are :-', '[{"id": "a", "text": "OH⁻ and H₂F⁺ respectively"}, {"id": "b", "text": "H₃O⁺ and F⁻, respectively"}, {"id": "c", "text": "OH⁻ and F⁻, respectively"}, {"id": "d", "text": "H₃O⁺ and H₂F⁺, respectively"}]'::jsonb, 'c', 'Removing one H⁺ from H₂O gives OH⁻ and from HF gives F⁻.', 'A conjugate base is what remains after a Brønsted acid loses one proton. H₂O – H⁺ = OH⁻ and HF – H⁺ = F⁻. H₃O⁺ and H₂F⁺ are formed by gaining a proton, so they are conjugate acids.', '{"a": "H₂F⁺ is the conjugate acid of HF.", "b": "H₃O⁺ is the conjugate acid of H₂O.", "d": "Both are conjugate acids, not bases."}'::jsonb, 'Conjugate acid–base pairs differ by exactly one proton.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('ecbc2008-5176-5200-8852-b8b642af5fea', 'neet_ug', 'Chemistry', 'Equilibrium', 'Which will make basic buffer ?', '[{"id": "a", "text": "50 mL of 0.1 M NaOH + 25 mL of 0.1 M CH₃COOH"}, {"id": "b", "text": "100 mL of 0.1 M CH₃COOH + 100 mL of 0.1 M NaOH"}, {"id": "c", "text": "100 mL of 0.1 M HCl + 200 mL of 0.1 M NH₄OH"}, {"id": "d", "text": "100 mL of 0.1 M HCl + 100 mL of 0.1 M NaOH"}]'::jsonb, 'c', '10 mmol HCl neutralises half of the 20 mmol NH₄OH, leaving 10 mmol NH₄OH + 10 mmol NH₄Cl, which is a basic buffer.', '(3): HCl = 10 mmol and NH₄OH = 20 mmol. After reaction, 10 mmol NH₄OH remains along with 10 mmol NH₄Cl, a weak base plus its salt with a strong acid, which is a basic buffer. (1) leaves excess strong NaOH, (2) is exact neutralisation giving only CH₃COONa, and (4) gives only NaCl.', '{"a": "Leaves excess strong base (NaOH), which is not a buffer.", "b": "Complete neutralisation leaves only the salt CH₃COONa (hydrolysis, no buffer).", "d": "Strong acid + strong base gives neutral NaCl."}'::jsonb, 'Basic buffer = weak base + its salt with a strong acid (e.g. NH₄OH + NH₄Cl).', 'med', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('574e14fd-6e53-5dcd-8274-ebfbd0bb3be8', 'neet_ug', 'Chemistry', 'Alcohols, Phenols and Ethers', 'The compound that is most difficult to protonate is :-', '[{"id": "a", "text": "H–O–H"}, {"id": "b", "text": "H₃C–O–H"}, {"id": "c", "text": "H₃C–O–CH₃"}, {"id": "d", "text": "Ph–O–H"}]'::jsonb, 'd', 'In phenol the oxygen lone pair is delocalised into the ring, so it is least available to accept a proton.', 'Protonation needs an available lone pair on oxygen. In Ph–OH the lone pair takes part in resonance with the benzene ring, which lowers its electron density, and the sp² carbon is also electron-withdrawing. Methyl groups in methanol and dimethyl ether push electron density onto O (+I), making them easier to protonate than water and phenol.', '{"a": "Water''s lone pairs are localised and readily accept H⁺.", "b": "The +I effect of CH₃ makes oxygen more basic.", "c": "Two CH₃ groups make the ether oxygen readily protonated."}'::jsonb, 'Resonance of the O lone pair with the ring makes phenol a weaker base and a stronger acid than alcohols.', 'med', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('9fb3a464-6fe1-5b86-8a6f-cadbeb3b31c6', 'neet_ug', 'Chemistry', 'Hydrocarbons', 'The most suitable reagent for the following conversion is :-
H₃C–C≡C–CH₃ → cis-2-butene', '[{"id": "a", "text": "Na/liquid NH₃"}, {"id": "b", "text": "H₂, Pd/C, quinoline"}, {"id": "c", "text": "Zn/HCl"}, {"id": "d", "text": "Hg²⁺/H⁺, H₂O"}]'::jsonb, 'b', 'Lindlar''s catalyst (Pd poisoned with quinoline) gives syn addition of H₂, so the alkyne becomes a cis-alkene.', 'Partial hydrogenation over Pd/C poisoned with quinoline stops at the alkene stage. Both H atoms add from the same face (syn addition), giving cis-2-butene. Na in liquid NH₃ instead gives the trans alkene by anti addition.', '{"a": "Birch-type dissolving-metal reduction gives trans-2-butene.", "c": "Zn/HCl does not reduce a non-conjugated alkyne cleanly to a cis-alkene.", "d": "Hg²⁺/H⁺ hydrates the alkyne to a ketone (butan-2-one)."}'::jsonb, 'Lindlar''s catalyst gives a cis-alkene; Na/liq. NH₃ gives a trans-alkene.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('ec70073b-cabe-5297-b795-a0ba10b6f08c', 'neet_ug', 'Chemistry', 'The p-Block Elements', 'Which of the following species is not stable ?', '[{"id": "a", "text": "[SiF₆]²⁻"}, {"id": "b", "text": "[GeCl₆]²⁻"}, {"id": "c", "text": "[Sn(OH)₆]²⁻"}, {"id": "d", "text": "[SiCl₆]²⁻"}]'::jsonb, 'd', 'Six large Cl atoms cannot fit around the small Si atom, and Cl lone pairs interact poorly with Si, so [SiCl₆]²⁻ does not exist.', 'Si can expand its coordination to six only with small, highly electronegative ligands like F⁻. Cl⁻ is too large for six to fit around small Si (steric crowding), and its lone pairs interact poorly with Si. Larger Ge and Sn can accommodate six Cl or OH groups.', '{"a": "[SiF₆]²⁻ is a well-known stable ion; F is small.", "b": "Larger Ge can hold six Cl atoms.", "c": "Large Sn readily forms the hexahydroxostannate ion."}'::jsonb, 'SiF₆²⁻ exists but SiCl₆²⁻ does not, because six large Cl atoms cannot fit around Si.', 'med', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('ac7721f0-89fc-5916-83c6-9002c222218a', 'neet_ug', 'Chemistry', 'Alcohols, Phenols and Ethers', 'The structure of intermediate A in the following reaction is :-
Cumene (isopropylbenzene) —O₂→ A —H⁺/H₂O→ Phenol + Acetone (see figure)', '[{"id": "a", "text": "Option (1) in figure"}, {"id": "b", "text": "Option (2) in figure"}, {"id": "c", "text": "Option (3) in figure"}, {"id": "d", "text": "Option (4) in figure"}]'::jsonb, 'b', 'Air oxidation of cumene gives cumene hydroperoxide, C₆H₅C(CH₃)₂–O–O–H, which is option (2).', 'O₂ abstracts the tertiary benzylic H of cumene and forms cumene hydroperoxide, C₆H₅–C(CH₃)₂–OOH. In acid this undergoes rearrangement with phenyl migration to oxygen, then hydrolysis, to give phenol and acetone.', '{"a": "Isopropyl phenyl ether is not an oxidation product and would not give acetone on hydrolysis.", "c": "The O–O group is not inserted between the ring and the isopropyl group.", "d": "The hydroperoxide forms at the tertiary benzylic carbon, not at a primary CH₃."}'::jsonb, 'Cumene process: cumene → cumene hydroperoxide → phenol + acetone (industrial phenol).', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', '/pyq/ug/2019/20.webp'),
('6ede885d-bfa2-5858-abb4-e003517c9f32', 'neet_ug', 'Chemistry', 'The d- and f-Block Elements', 'The manganate and permanganate ions are tetrahedral, due to', '[{"id": "a", "text": "The π-bonding involves overlap of p-orbitals of oxygen with d-orbitals of manganese"}, {"id": "b", "text": "There is no π-bonding"}, {"id": "c", "text": "The π-bonding involves overlap of p-orbitals of oxygen with p-orbitals of manganese"}, {"id": "d", "text": "The π-bonding involves overlap of d-orbitals of oxygen with d-orbitals of manganese"}]'::jsonb, 'a', 'Mn uses sp³-type σ bonds plus dπ–pπ bonding between filled O 2p and vacant Mn 3d orbitals.', 'In MnO₄²⁻ and MnO₄⁻, Mn forms four σ bonds in a tetrahedral arrangement. π-bonding arises from overlap of oxygen 2p orbitals with manganese 3d orbitals (dπ–pπ). Oxygen has no low-lying d orbitals, and Mn p orbitals are used for σ bonding.', '{"b": "Mn–O bonds have significant π character, shown by their short bond lengths.", "c": "Mn 4p orbitals are not used for π-bonding here.", "d": "Oxygen has no available d orbitals."}'::jsonb, 'Green K₂MnO₄ is paramagnetic and purple KMnO₄ is diamagnetic; both are tetrahedral with dπ–pπ bonding.', 'med', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('f0ad0df7-6bb2-5dfc-927f-9ffef600adee', 'neet_ug', 'Chemistry', 'Classification of Elements and Periodicity in Properties', 'For the second period elements the correct increasing order of first ionisation enthalpy is :-', '[{"id": "a", "text": "Li < Be < B < C < N < O < F < Ne"}, {"id": "b", "text": "Li < B < Be < C < O < N < F < Ne"}, {"id": "c", "text": "Li < B < Be < C < N < O < F < Ne"}, {"id": "d", "text": "Li < Be < B < C < O < N < F < Ne"}]'::jsonb, 'b', 'Be > B (filled 2s vs a lone 2p electron) and N > O (half-filled 2p), giving Li < B < Be < C < O < N < F < Ne.', 'IE rises across the period with exceptions. B''s 2p electron is shielded by 2s and is easier to remove than Be''s 2s electron, so B < Be. O has one paired 2p electron with repulsion, while N has a stable half-filled 2p³, so O < N.', '{"a": "Ignores both the Be/B and N/O anomalies.", "c": "Misses the N > O anomaly.", "d": "Misses the Be > B anomaly."}'::jsonb, 'Period 2 IE anomalies: Be > B and N > O.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('b821903e-b9ef-5073-9113-84e8144b0d7a', 'neet_ug', 'Chemistry', 'Chemical Kinetics', 'If the rate constant for a first order reaction is k, the time (t) required for the completion of 99% of the reaction is given by :-', '[{"id": "a", "text": "t = 0.693/k"}, {"id": "b", "text": "t = 6.909/k"}, {"id": "c", "text": "t = 4.606/k"}, {"id": "d", "text": "t = 2.303/k"}]'::jsonb, 'c', 't = (2.303/k) log(100/1) = 2 × 2.303/k = 4.606/k.', 'For first-order kinetics t = (2.303/k) log([A]₀/[A]). After 99% completion [A] = [A]₀/100, so log 100 = 2 and t = 4.606/k.', '{"a": "This is the half-life (50% completion).", "b": "Corresponds to 99.9% completion (log 1000 = 3).", "d": "Corresponds to 90% completion (log 10 = 1)."}'::jsonb, 'First order: t₉₉% = 2 × t₉₀% and t₉₉.₉% ≈ 10 × t½.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('b97196ea-1dc9-5fcf-ae18-5ccde92222cb', 'neet_ug', 'Chemistry', 'Chemical Bonding and Molecular Structure', 'Identify the incorrect statement related to PCl₅ from the following :-', '[{"id": "a", "text": "Three equatorial P–Cl bonds make an angle of 120° with each other"}, {"id": "b", "text": "Two axial P–Cl bonds make an angle of 180° with each other"}, {"id": "c", "text": "Axial P–Cl bonds are longer than equatorial P–Cl bonds"}, {"id": "d", "text": "PCl₅ molecule is non-reactive"}]'::jsonb, 'd', 'PCl₅ is quite reactive because its longer, weaker axial bonds break easily.', 'PCl₅ is trigonal bipyramidal (sp³d): equatorial bonds are 120° apart, and the axial bonds are 180° apart and at 90° to the equatorial plane. The axial bonds suffer more repulsion and are longer and weaker, which makes PCl₅ reactive (it readily gives PCl₃ + Cl₂ and acts as a chlorinating agent).', '{"a": "True: the equatorial bonds are trigonal planar at 120°.", "b": "True: the axial bonds are linear.", "c": "True: the axial bonds face greater bond-pair repulsion and are longer."}'::jsonb, 'In PCl₅ the axial bonds (≈240 pm) are longer than the equatorial bonds (≈202 pm).', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('50e18c15-780a-5817-8467-6c457ebffc87', 'neet_ug', 'Chemistry', 'Structure of Atom', '4d, 5p, 5f and 6p orbitals are arranged in the order of decreasing energy. The correct option is :-', '[{"id": "a", "text": "5f > 6p > 5p > 4d"}, {"id": "b", "text": "6p > 5f > 5p > 4d"}, {"id": "c", "text": "6p > 5f > 4d > 5p"}, {"id": "d", "text": "5f > 6p > 4d > 5p"}]'::jsonb, 'a', 'By the (n + l) rule: 5f = 8, 6p = 7, 5p = 6, 4d = 6 (lower n first), so 5f > 6p > 5p > 4d.', 'Higher n + l means higher energy, and for equal n + l the higher n is higher. 5f (8) > 6p (7). 5p and 4d both have n + l = 6, so 5p (n = 5) > 4d (n = 4).', '{"b": "6p (n+l = 7) is lower than 5f (n+l = 8).", "c": "Gets both pairs reversed.", "d": "Places 4d above 5p, but for equal n+l the higher n is higher."}'::jsonb, 'Aufbau (n + l) rule: lower n + l fills first; for a tie, lower n fills first.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('3dca6bff-ec10-5036-9c39-99686d6cfc31', 'neet_ug', 'Chemistry', 'The p-Block Elements', 'Match the Xenon compounds in Column-I with its structure in Column-II and assign the correct code :-
Column-I | Column-II
(a) XeF₄ | (i) pyramidal
(b) XeF₆ | (ii) square planar
(c) XeOF₄ | (iii) distorted octahedral
(d) XeO₃ | (iv) square pyramidal', '[{"id": "a", "text": "(a)-(i), (b)-(ii), (c)-(iii), (d)-(iv)"}, {"id": "b", "text": "(a)-(ii), (b)-(iii), (c)-(iv), (d)-(i)"}, {"id": "c", "text": "(a)-(ii), (b)-(iii), (c)-(i), (d)-(iv)"}, {"id": "d", "text": "(a)-(iii), (b)-(iv), (c)-(i), (d)-(ii)"}]'::jsonb, 'b', 'XeF₄ is square planar, XeF₆ distorted octahedral, XeOF₄ square pyramidal and XeO₃ pyramidal.', 'XeF₄: 4 bond pairs + 2 lone pairs (sp³d²) gives square planar. XeF₆: 6 bond pairs + 1 lone pair gives distorted octahedral. XeOF₄: 5 σ bond pairs + 1 lone pair gives square pyramidal. XeO₃: 3 σ bond pairs + 1 lone pair gives trigonal pyramidal.', '{"a": "Mismatches all four.", "c": "Swaps XeOF₄ (square pyramidal) and XeO₃ (pyramidal).", "d": "XeF₄ is square planar, not distorted octahedral."}'::jsonb, 'Xe compound shapes from VSEPR: XeF₂ linear, XeF₄ square planar, XeF₆ distorted octahedral, XeO₃ pyramidal, XeOF₄ square pyramidal.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('08074fad-6b00-5037-a35a-bc95ddc4e111', 'neet_ug', 'Chemistry', 'The p-Block Elements', 'Which is the correct thermal stability order for H₂E (E = O, S, Se, Te and Po) ?', '[{"id": "a", "text": "H₂S < H₂O < H₂Se < H₂Te < H₂Po"}, {"id": "b", "text": "H₂O < H₂S < H₂Se < H₂Te < H₂Po"}, {"id": "c", "text": "H₂Po < H₂Te < H₂Se < H₂S < H₂O"}, {"id": "d", "text": "H₂Se < H₂Te < H₂Po < H₂O < H₂S"}]'::jsonb, 'c', 'The E–H bond weakens down group 16, so thermal stability falls from H₂O to H₂Po.', 'As the size of E increases down the group, the E–H bond becomes longer and its dissociation enthalpy falls. So thermal stability decreases: H₂O > H₂S > H₂Se > H₂Te > H₂Po. The same trend makes acidic character increase down the group.', '{"a": "Puts H₂S below H₂O and then has stability increasing down the group.", "b": "Reverses the order; that is the trend for acidic strength.", "d": "Has no consistent trend."}'::jsonb, 'Down group 16: thermal stability of H₂E decreases and acidic strength increases.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('aef8e17f-ee4b-585b-be10-be24eaf259bd', 'neet_ug', 'Chemistry', 'The p-Block Elements', 'The correct structure of tribromooctaoxide is :- (see figure)', '[{"id": "a", "text": "Option (1) in figure"}, {"id": "b", "text": "Option (2) in figure"}, {"id": "c", "text": "Option (3) in figure"}, {"id": "d", "text": "Option (4) in figure"}]'::jsonb, 'a', 'Br₃O₈ is neutral, so its structure has only Br=O and Br–Br bonds with no formal charges, as in option (1).', 'Br₃O₈ is a neutral molecule, so the correct structure must carry no formal charges. Option (1) shows a Br–Br–Br chain where each terminal Br carries three Br=O bonds and the central Br carries two, using all 8 O atoms in neutral Br=O bonds. Options (2)–(4) carry negative charges on oxygen, which would make the species anionic.', '{"b": "Shows O⁻ groups, giving an anion and not neutral Br₃O₈.", "c": "Several O⁻ groups give a charged species.", "d": "Contains O⁻ groups, so it is not a neutral molecule."}'::jsonb, 'Bromine oxides such as Br₂O, BrO₂ and BrO₃ are unstable and powerful oxidising agents at low temperature.', 'hard', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', '/pyq/ug/2019/29.webp'),
('d1860415-ef40-5ee1-b5dd-6894dbdb95b8', 'neet_ug', 'Chemistry', 'Hydrocarbons', 'An alkene "A" on reaction with O₃ and Zn–H₂O gives propanone and ethanal in equimolar ratio. Addition of HCl to alkene "A" gives "B" as the major product. The structure of product "B" is :-', '[{"id": "a", "text": "Cl–CH₂–CH₂–CH(CH₃)–CH₃"}, {"id": "b", "text": "H₃C–CH₂–CH(CH₂Cl)–CH₃"}, {"id": "c", "text": "H₃C–CH₂–C(CH₃)(Cl)–CH₃"}, {"id": "d", "text": "H₃C–CH(Cl)–CH(CH₃)–CH₃"}]'::jsonb, 'c', 'A is (CH₃)₂C=CH–CH₃; Markovnikov addition of HCl puts Cl on the tertiary carbon, giving 2-chloro-2-methylbutane.', 'Joining the carbonyl carbons of (CH₃)₂C=O and CH₃CHO gives A = 2-methylbut-2-ene, (CH₃)₂C=CHCH₃. H⁺ adds to the CH carbon to give the more stable tertiary carbocation (CH₃)₂C⁺–CH₂CH₃, which Cl⁻ then traps. B = (CH₃)₂CCl–CH₂CH₃.', '{"a": "A primary chloride would need an anti-Markovnikov route and a different skeleton.", "b": "Would come from a different alkene, and Cl would not end up on a primary carbon.", "d": "The secondary chloride comes from the less stable carbocation, so it is the minor product."}'::jsonb, 'Reductive ozonolysis cleaves C=C into two carbonyls; reconnect the C=O carbons to find the alkene.', 'med', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('ccbf8e82-d7c5-5199-8480-0d5f63e7ae53', 'neet_ug', 'Chemistry', 'Structure of Atom', 'Which of the following series of transitions in the spectrum of hydrogen atom falls in visible region ?', '[{"id": "a", "text": "Lyman series"}, {"id": "b", "text": "Balmer series"}, {"id": "c", "text": "Paschen series"}, {"id": "d", "text": "Brackett series"}]'::jsonb, 'b', 'Transitions ending at n = 2 (Balmer) emit visible light.', 'Lyman lines (n_f = 1) lie in the ultraviolet. Balmer lines (n_f = 2) lie in the visible region (e.g. Hα at 656 nm). Paschen (n_f = 3), Brackett (n_f = 4) and Pfund (n_f = 5) lie in the infrared.', '{"a": "Lyman is in the ultraviolet.", "c": "Paschen is in the infrared.", "d": "Brackett is in the infrared."}'::jsonb, '1/λ = R_H(1/n₁² – 1/n₂²); Balmer n₁ = 2 is the only visible series.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('5ac56272-7e0b-57a4-bda9-36f26ecad8dc', 'neet_ug', 'Chemistry', 'Solutions', 'The mixture that forms maximum boiling azeotrope is :', '[{"id": "a", "text": "Water + Nitric acid"}, {"id": "b", "text": "Ethanol + Water"}, {"id": "c", "text": "Acetone + Carbon disulphide"}, {"id": "d", "text": "Heptane + Octane"}]'::jsonb, 'a', 'HNO₃–water shows a large negative deviation from Raoult''s law, so it forms a maximum boiling azeotrope (≈68% HNO₃).', 'A maximum boiling azeotrope forms when A–B attractions are stronger than A–A and B–B attractions (negative deviation), which lowers the vapour pressure. Nitric acid and water interact strongly, giving an azeotrope at about 68% HNO₃ that boils near 393 K.', '{"b": "Ethanol–water shows positive deviation, giving a minimum boiling azeotrope (95% ethanol).", "c": "Acetone–CS₂ shows positive deviation.", "d": "Heptane–octane is a nearly ideal solution."}'::jsonb, 'Positive deviation gives a minimum boiling azeotrope; negative deviation gives a maximum boiling azeotrope.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('c53d5d88-2340-5050-9111-c25a78020c7e', 'neet_ug', 'Chemistry', 'Electrochemistry', 'For the cell reaction
2Fe³⁺(aq) + 2I⁻(aq) → 2Fe²⁺(aq) + I₂(aq)
E°cell = 0.24 V at 298 K. The standard Gibbs energy (ΔrG°) of the cell reaction is :
[Given that Faraday constant F = 96500 C mol⁻¹]', '[{"id": "a", "text": "–46.32 kJ mol⁻¹"}, {"id": "b", "text": "–23.16 kJ mol⁻¹"}, {"id": "c", "text": "46.32 kJ mol⁻¹"}, {"id": "d", "text": "23.16 kJ mol⁻¹"}]'::jsonb, 'a', 'ΔrG° = –nFE° = –2 × 96500 × 0.24 = –46320 J = –46.32 kJ mol⁻¹.', 'Two electrons are transferred (2Fe³⁺ → 2Fe²⁺, 2I⁻ → I₂), so n = 2. ΔrG° = –nFE° = –2 × 96500 × 0.24 J mol⁻¹ = –46 320 J mol⁻¹ = –46.32 kJ mol⁻¹. It is negative because E° > 0, so the reaction is spontaneous.', '{"b": "Uses n = 1.", "c": "Correct magnitude but wrong sign; a positive E° means negative ΔG°.", "d": "Uses n = 1 and the wrong sign."}'::jsonb, 'ΔrG° = –nFE°cell; a positive E° means a spontaneous cell reaction.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('3ca97f4b-a538-5c00-a833-bd68406cc34f', 'neet_ug', 'Chemistry', 'Thermodynamics', 'In which case change in entropy is negative ?', '[{"id": "a", "text": "Evaporation of water"}, {"id": "b", "text": "Expansion of a gas at constant temperature"}, {"id": "c", "text": "Sublimation of solid to gas"}, {"id": "d", "text": "2H(g) → H₂(g)"}]'::jsonb, 'd', 'Two gaseous atoms combining into one molecule reduces the number of particles, so ΔS < 0.', 'Entropy falls when the number of gaseous particles decreases or the system becomes more ordered. In 2H(g) → H₂(g), two moles of gas become one, so ΔS is negative. Evaporation, isothermal expansion and sublimation all increase disorder.', '{"a": "Liquid → gas increases entropy.", "b": "A larger volume gives more microstates, so ΔS > 0.", "c": "Solid → gas gives a large entropy increase."}'::jsonb, 'ΔS < 0 when Δn_gas < 0 or when a phase becomes more ordered (gas → liquid → solid).', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('55bc8bde-7bc5-59cc-a4e3-8f8e86d455d4', 'neet_ug', 'Chemistry', 'The p-Block Elements', 'Match the following :
(a) Pure nitrogen | (i) Chlorine
(b) Haber process | (ii) Sulphuric acid
(c) Contact process | (iii) Ammonia
(d) Deacon''s process | (iv) Sodium azide or Barium azide
Which of the following is the correct option ?', '[{"id": "a", "text": "(a)-(i), (b)-(ii), (c)-(iii), (d)-(iv)"}, {"id": "b", "text": "(a)-(ii), (b)-(iv), (c)-(i), (d)-(iii)"}, {"id": "c", "text": "(a)-(iii), (b)-(iv), (c)-(ii), (d)-(i)"}, {"id": "d", "text": "(a)-(iv), (b)-(iii), (c)-(ii), (d)-(i)"}]'::jsonb, 'd', 'Pure N₂ comes from heating azides, Haber gives NH₃, Contact gives H₂SO₄ and Deacon gives Cl₂.', 'Very pure N₂ is made by thermal decomposition of NaN₃ or Ba(N₃)₂. The Haber process makes NH₃ from N₂ and H₂. The Contact process makes H₂SO₄ via catalytic oxidation of SO₂ (V₂O₅). Deacon''s process oxidises HCl with O₂ over CuCl₂ to give Cl₂.', '{"a": "Matches none correctly.", "b": "Mismatches all four.", "c": "Pure nitrogen does not come from the ammonia process, and Haber does not involve azides."}'::jsonb, 'Ba(N₃)₂ → Ba + 3N₂ gives very pure N₂; Deacon: 4HCl + O₂ → 2Cl₂ + 2H₂O (CuCl₂, 723 K).', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('855d707d-7d2f-54c2-b56b-2d2cb2ade6e9', 'neet_ug', 'Chemistry', 'The p-Block Elements', 'Which of the following is incorrect statement ?', '[{"id": "a", "text": "PbF₄ is covalent in nature"}, {"id": "b", "text": "SiCl₄ is easily hydrolysed"}, {"id": "c", "text": "GeX₄ (X = F, Cl, Br, I) is more stable than GeX₂"}, {"id": "d", "text": "SnF₄ is ionic in nature"}]'::jsonb, 'a', 'PbF₄ and SnF₄ are ionic in nature, so calling PbF₄ covalent is incorrect.', 'Most group 14 tetrahalides are covalent, but SnF₄ and PbF₄ are exceptions that are ionic, because F⁻ is small and the metal cations are large. SiCl₄ hydrolyses readily, since Si has vacant d orbitals that accept a lone pair from water. For Ge the +4 state is more stable than +2 (the inert pair effect is weak), so GeX₄ is more stable than GeX₂.', '{"b": "True: SiCl₄ + 4H₂O → Si(OH)₄ + 4HCl.", "c": "True: Ge favours the +4 oxidation state.", "d": "True: SnF₄ is ionic, as stated in NCERT."}'::jsonb, 'Group 14 tetrahalides are covalent except SnF₄ and PbF₄, which are ionic.', 'med', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('6a8e2613-1ae2-58fd-8dd2-57d160e9163d', 'neet_ug', 'Chemistry', 'Biomolecules', 'The non-essential amino acid among the following is :', '[{"id": "a", "text": "valine"}, {"id": "b", "text": "leucine"}, {"id": "c", "text": "alanine"}, {"id": "d", "text": "lysine"}]'::jsonb, 'c', 'Alanine is synthesised in the body, so it is non-essential.', 'Essential amino acids cannot be made by the body and must come from the diet; they include valine, leucine, isoleucine, lysine, threonine, methionine, phenylalanine, tryptophan, histidine and arginine. Alanine is made in the body (e.g. by transamination of pyruvate), so it is non-essential.', '{"a": "Valine is an essential branched-chain amino acid.", "b": "Leucine is essential.", "d": "Lysine is essential."}'::jsonb, 'Essential amino acids (10, per NCERT): valine, leucine, isoleucine, phenylalanine, tryptophan, threonine, methionine, lysine, arginine and histidine.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('6adf952b-8b26-53bf-a284-3dafea45a8f6', 'neet_ug', 'Chemistry', 'Haloalkanes and Haloarenes', 'Among the following, the reaction that proceeds through an electrophilic substitution is :', '[{"id": "a", "text": "C₆H₅N₂⁺Cl⁻ —Cu₂Cl₂→ C₆H₅Cl + N₂"}, {"id": "b", "text": "C₆H₆ + Cl₂ —AlCl₃→ C₆H₅Cl + HCl"}, {"id": "c", "text": "C₆H₆ + Cl₂ —UV light→ C₆H₆Cl₆ (hexachlorocyclohexane)"}, {"id": "d", "text": "C₆H₅CH₂OH + HCl —heat→ C₆H₅CH₂Cl + H₂O"}]'::jsonb, 'b', 'AlCl₃ produces Cl⁺, which attacks the benzene ring in an electrophilic aromatic substitution.', 'AlCl₃ (a Lewis acid) polarises Cl₂ to give the Cl⁺ electrophile, which forms a σ-complex with benzene and then loses H⁺ to give chlorobenzene. The Sandmeyer reaction (1) goes through aryl radicals, UV chlorination (3) is free-radical addition, and (4) is nucleophilic substitution of a protonated alcohol.', '{"a": "Sandmeyer reaction: a radical (or nucleophilic) replacement of N₂, not electrophilic substitution.", "c": "Free-radical addition that gives BHC (gammaxene).", "d": "Nucleophilic substitution (S_N1/S_N2) at the benzylic carbon."}'::jsonb, 'Electrophilic aromatic substitution needs an electrophile, e.g. Cl⁺ generated by AlCl₃/FeCl₃.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('134314f8-36b0-56fd-9045-7a47b24262b9', 'neet_ug', 'Chemistry', 'Aldehydes, Ketones and Carboxylic Acids', 'The major product of the following reaction is :
Phthalic acid (benzene-1,2-dicarboxylic acid) + NH₃ —strong heating→ ? (see figure)', '[{"id": "a", "text": "Option (1) in figure"}, {"id": "b", "text": "Option (2) in figure"}, {"id": "c", "text": "Option (3) in figure"}, {"id": "d", "text": "Option (4) in figure"}]'::jsonb, 'b', 'Strong heating converts ammonium phthalate to the amide and then cyclises it to phthalimide, option (2).', 'Phthalic acid and NH₃ first form ammonium phthalate. On strong heating, water is lost to give the amide (phthalamic acid), and further loss of water closes the ring to the cyclic imide, phthalimide. Option (2) shows this imide structure.', '{"a": "Phthalamic acid is only the intermediate; strong heating dehydrates it further.", "c": "Anthranilic acid would need a Hofmann degradation (Br₂/NaOH), not just heat.", "d": "Replacing both COOH groups with NH₂ is not possible by heating with NH₃."}'::jsonb, 'Phthalimide (from phthalic acid + NH₃ with heat) is the starting material for the Gabriel synthesis of primary amines.', 'med', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', '/pyq/ug/2019/42.webp'),
('f174849c-fba6-5cfd-b5f5-98fd0684d484', 'neet_ug', 'Chemistry', 'Chemical Kinetics', 'For the chemical reaction
N₂(g) + 3H₂(g) ⇌ 2NH₃(g)
the correct option is :', '[{"id": "a", "text": "–(1/3) d[H₂]/dt = –(1/2) d[NH₃]/dt"}, {"id": "b", "text": "–d[N₂]/dt = 2 d[NH₃]/dt"}, {"id": "c", "text": "–d[N₂]/dt = (1/2) d[NH₃]/dt"}, {"id": "d", "text": "3 d[H₂]/dt = 2 d[NH₃]/dt"}]'::jsonb, 'c', 'Rate = –d[N₂]/dt = –(1/3)d[H₂]/dt = +(1/2)d[NH₃]/dt.', 'Divide each rate of change by its stoichiometric coefficient, with a negative sign for reactants. This gives –d[N₂]/dt = –(1/3) d[H₂]/dt = (1/2) d[NH₃]/dt, which matches option (3).', '{"a": "The sign on the NH₃ term is wrong, because product concentration increases.", "b": "The coefficient is inverted; it should be 1/2, not 2.", "d": "Both the signs and the factors are wrong; the correct relation is –(1/3)d[H₂]/dt = (1/2)d[NH₃]/dt."}'::jsonb, 'Rate = –(1/a)d[A]/dt = (1/c)d[C]/dt for aA → cC.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('ec3a1912-e6e5-5aa4-be74-9da26e7017cd', 'neet_ug', 'Chemistry', 'Coordination Compounds', 'What is the correct electronic configuration of the central atom in K₄[Fe(CN)₆] based on crystal field theory ?', '[{"id": "a", "text": "t₂g⁴ e_g²"}, {"id": "b", "text": "t₂g⁶ e_g⁰"}, {"id": "c", "text": "e³ t₂³"}, {"id": "d", "text": "e⁴ t₂²"}]'::jsonb, 'b', 'Fe²⁺ (d⁶) with strong-field CN⁻ ligands pairs up fully in t₂g, giving t₂g⁶e_g⁰ (low spin, diamagnetic).', 'In K₄[Fe(CN)₆], Fe is +2 (3d⁶). CN⁻ is a strong-field ligand, so in the octahedral field Δₒ > P and all six electrons pair in t₂g. The configuration is t₂g⁶e_g⁰, which is diamagnetic. The e/t₂ labels belong to tetrahedral splitting and do not apply here.', '{"a": "High-spin configuration, which occurs with weak-field ligands such as H₂O or F⁻.", "c": "Tetrahedral labels and wrong electron count.", "d": "Tetrahedral splitting; this complex is octahedral."}'::jsonb, '[Fe(CN)₆]⁴⁻ is low spin and diamagnetic, while [Fe(CN)₆]³⁻ has one unpaired electron.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('7f5e5bd9-a6bf-5b91-9e0f-dbbda0d3e68e', 'neet_ug', 'Physics', 'Thermodynamics', 'In which of the following processes, heat is neither absorbed nor released by a system ?', '[{"id": "a", "text": "isothermal"}, {"id": "b", "text": "adiabatic"}, {"id": "c", "text": "isobaric"}, {"id": "d", "text": "isochoric"}]'::jsonb, 'b', 'An adiabatic process is defined by zero heat exchange (Q = 0).', 'In an adiabatic process the system is thermally insulated, so Q = 0 and any work done comes entirely from the change in internal energy (ΔU = −W). All other listed processes involve heat flow.', '{"a": "Isothermal processes need heat exchange to keep T constant while work is done.", "c": "Isobaric processes absorb/release heat (Q = nCₚΔT).", "d": "Isochoric processes exchange heat as Q = nCᵥΔT."}'::jsonb, 'Adiabatic: Q = 0, PVᵞ = constant.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('3d3a0bc4-e85c-5f01-933f-556c6bdd2e36', 'neet_ug', 'Physics', 'Kinetic Theory', 'Increase in temperature of a gas filled in a container would lead to :', '[{"id": "a", "text": "increase in its mass"}, {"id": "b", "text": "increase in its kinetic energy"}, {"id": "c", "text": "decrease in its pressure"}, {"id": "d", "text": "decrease in intermolecular distance"}]'::jsonb, 'b', 'Average kinetic energy of gas molecules is proportional to absolute temperature.', 'From kinetic theory, average KE per molecule = (3/2)k_BT, so raising T raises the kinetic energy. In a closed rigid container mass and intermolecular distance stay the same and pressure increases, not decreases.', '{"a": "Mass of gas in a closed container is fixed.", "c": "At constant volume pressure rises with temperature.", "d": "Volume is fixed, so average spacing does not change."}'::jsonb, 'Average KE of a molecule = (3/2)k_BT.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('84f67ca7-a60a-55dd-a123-91fdbe53ee4b', 'neet_ug', 'Physics', 'Atoms', 'The total energy of an electron in an atom in an orbit is –3.4 eV. Its kinetic and potential energies are, respectively :', '[{"id": "a", "text": "–3.4 eV, –3.4 eV"}, {"id": "b", "text": "–3.4 eV, –6.8 eV"}, {"id": "c", "text": "3.4 eV, –6.8 eV"}, {"id": "d", "text": "3.4 eV, 3.4 eV"}]'::jsonb, 'c', 'In Bohr orbits KE = −E and PE = 2E.', 'For a Bohr orbit, KE = −E = +3.4 eV and PE = 2E = −6.8 eV; check: 3.4 + (−6.8) = −3.4 eV.', '{"a": "Kinetic energy can never be negative.", "b": "Kinetic energy can never be negative.", "d": "PE of a bound electron is negative and the sum must give −3.4 eV."}'::jsonb, 'Bohr model: KE = −TE, PE = −2KE.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('23d8b811-946d-5a55-af93-8fbbe0da66c2', 'neet_ug', 'Physics', 'Semiconductor Electronics: Materials, Devices and Simple Circuits', 'The correct Boolean operation represented by the circuit diagram drawn is :', '[{"id": "a", "text": "AND"}, {"id": "b", "text": "OR"}, {"id": "c", "text": "NAND"}, {"id": "d", "text": "NOR"}]'::jsonb, 'c', 'Two series switches shorting the LED to ground make the LED go off only when both are 1 — NAND.', 'The LED sits at the junction of a resistor divider from +6 V. Switches A and B are in series between this junction and ground, so only when A = 1 and B = 1 is the LED shorted and off (Y = 0). For every other input combination the LED glows (Y = 1), which is the NAND truth table.', '{"a": "AND would give Y = 1 only when both inputs are 1; here that is the only case where Y = 0.", "b": "OR would give Y = 0 only for A = B = 0.", "d": "NOR would need parallel switches, giving Y = 1 only for A = B = 0."}'::jsonb, 'NAND: Y = (A·B)̄, output 0 only when all inputs are 1.', 'med', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', '/pyq/ug/2019/49.webp'),
('ec1df56c-c683-56de-a3ff-3abb84977754', 'neet_ug', 'Physics', 'Laws of Motion', 'A block of mass 10 kg is in contact against the inner wall of a hollow cylindrical drum of radius 1 m. The coefficient of friction between the block and the inner wall of the cylinder is 0.1. The minimum angular velocity needed for the cylinder to keep the block stationary when the cylinder is vertical and rotating about its axis, will be : (g = 10 m/s²)', '[{"id": "a", "text": "√10 rad/s"}, {"id": "b", "text": "10/(2π) rad/s"}, {"id": "c", "text": "10 rad/s"}, {"id": "d", "text": "10π rad/s"}]'::jsonb, 'c', 'Friction μmω²r must balance weight mg, so ω = √(g/μr).', 'The normal reaction supplies the centripetal force: N = mω²r. Friction μN must hold the weight: μmω²r ≥ mg, so ω_min = √(g/(μr)) = √(10/(0.1 × 1)) = √100 = 10 rad/s.', '{"a": "√10 forgets to divide by μ.", "b": "Wrongly mixes rad/s with rev/s.", "d": "Spurious factor of π."}'::jsonb, 'Rotor (drum) problem: ω_min = √(g/μr), independent of mass.', 'med', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('7f446b44-616d-5270-a2fc-39dc42cd2493', 'neet_ug', 'Physics', 'Work, Energy and Power', 'Body A of mass 4m moving with speed u collides with another body B of mass 2m, at rest. The collision is head on and elastic in nature. After the collision the fraction of energy lost by the colliding body A is :', '[{"id": "a", "text": "1/9"}, {"id": "b", "text": "8/9"}, {"id": "c", "text": "4/9"}, {"id": "d", "text": "5/9"}]'::jsonb, 'b', 'Fraction of KE transferred in a 1-D elastic collision = 4m₁m₂/(m₁+m₂)².', 'A''s final speed v₁ = (m₁−m₂)u/(m₁+m₂) = (2m/6m)u = u/3, so A keeps (1/3)² = 1/9 of its KE and loses 8/9. Equivalently 4(4m)(2m)/(6m)² = 32/36 = 8/9.', '{"a": "1/9 is the fraction A retains, not loses.", "c": "Arithmetic slip in the transfer formula.", "d": "Arithmetic slip; does not follow from momentum and energy conservation."}'::jsonb, 'Elastic head-on collision: v₁ = (m₁−m₂)u/(m₁+m₂), v₂ = 2m₁u/(m₁+m₂).', 'med', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('94ad9e55-e4b7-5a21-a6d0-9f38b2811145', 'neet_ug', 'Physics', 'Motion in a Plane', 'The speed of a swimmer in still water is 20 m/s. The speed of river water is 10 m/s and is flowing due east. If he is standing on the south bank and wishes to cross the river along the shortest path, the angle at which he should make his strokes w.r.t. north is given by :', '[{"id": "a", "text": "30° west"}, {"id": "b", "text": "0°"}, {"id": "c", "text": "60° west"}, {"id": "d", "text": "45° west"}]'::jsonb, 'a', 'For the shortest path, sin θ = v_river/v_swimmer upstream of the normal.', 'To go straight across, the westward component of his velocity must cancel the river: 20 sin θ = 10, so sin θ = 1/2 and θ = 30° west of north.', '{"b": "Heading due north lets the current carry him east, so the path is not the shortest.", "c": "60° comes from using cos θ = 1/2 instead of sin θ.", "d": "45° does not cancel the current exactly."}'::jsonb, 'Shortest path across a river: sin θ = v_r/v_s (needs v_s > v_r).', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('b47f13ec-600f-5e6e-828f-4cc258662558', 'neet_ug', 'Physics', 'Work, Energy and Power', 'A mass m is attached to a thin wire and whirled in a vertical circle. The wire is most likely to break when :', '[{"id": "a", "text": "the mass is at the highest point"}, {"id": "b", "text": "the wire is horizontal"}, {"id": "c", "text": "the mass is at the lowest point"}, {"id": "d", "text": "inclined at an angle of 60° from vertical"}]'::jsonb, 'c', 'Tension is maximum at the lowest point, T = mv²/r + mg.', 'At the lowest point both speed and the need to support weight are greatest: T = mv²/r + mg. At the top T = mv²/r − mg is the smallest, so the wire breaks most likely at the bottom.', '{"a": "Tension is minimum at the top.", "b": "At horizontal position T = mv²/r only, smaller than at the bottom.", "d": "Intermediate tension, still less than at the lowest point."}'::jsonb, 'Vertical circle: T_bottom − T_top = 6mg for a string.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('48840c37-f11f-5458-9591-3f470cad7464', 'neet_ug', 'Physics', 'Oscillations', 'The displacement of a particle executing simple harmonic motion is given by
y = A₀ + A sinωt + B cosωt.
Then the amplitude of its oscillation is given by :', '[{"id": "a", "text": "A₀ + √(A² + B²)"}, {"id": "b", "text": "√(A² + B²)"}, {"id": "c", "text": "√(A₀² + (A + B)²)"}, {"id": "d", "text": "A + B"}]'::jsonb, 'b', 'A₀ only shifts the mean position; amplitude is √(A² + B²).', 'A sinωt + B cosωt combine into R sin(ωt + φ) with R = √(A² + B²). The constant A₀ simply moves the mean position to y = A₀ and does not change the amplitude.', '{"a": "Adds the mean-position offset to the amplitude.", "c": "Wrongly treats A₀ and (A+B) as perpendicular components.", "d": "Sine and cosine terms are 90° out of phase, so they add in quadrature, not linearly."}'::jsonb, 'a sinωt + b cosωt = √(a²+b²) sin(ωt+φ).', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('573b7123-45f2-5db4-8ffd-875b513142f1', 'neet_ug', 'Physics', 'Electromagnetic Induction', 'A 800 turn coil of effective area 0.05 m² is kept perpendicular to a magnetic field 5 × 10⁻⁵ T. When the plane of the coil is rotated by 90° around any of its coplanar axis in 0.1 s, the emf induced in the coil will be :', '[{"id": "a", "text": "2 V"}, {"id": "b", "text": "0.2 V"}, {"id": "c", "text": "2 × 10⁻³ V"}, {"id": "d", "text": "0.02 V"}]'::jsonb, 'd', 'Average emf = NΔΦ/Δt with flux going from BA to zero.', 'Initial flux per turn = BA = 5×10⁻⁵ × 0.05 = 2.5×10⁻⁶ Wb, final = 0. emf = NΔΦ/Δt = 800 × 2.5×10⁻⁶ / 0.1 = 0.02 V.', '{"a": "Off by a factor of 100.", "b": "Off by a factor of 10.", "c": "Forgets one factor (e.g. divides wrongly by time)."}'::jsonb, 'Faraday''s law: ε = −N dΦ/dt.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('08c807cb-05ed-52bf-8d83-c643ed80012d', 'neet_ug', 'Physics', 'Oscillations', 'Average velocity of a particle executing SHM in one complete vibration is :', '[{"id": "a", "text": "Aω/2"}, {"id": "b", "text": "Aω"}, {"id": "c", "text": "Aω²/2"}, {"id": "d", "text": "Zero"}]'::jsonb, 'd', 'Net displacement over a full cycle is zero, so average velocity is zero.', 'After one complete oscillation the particle returns to its starting point, so displacement is zero and average velocity = displacement/time = 0. (Average speed is 2Aω/π, not zero.)', '{"a": "Not the average of a vector over a full cycle.", "b": "Aω is the maximum speed.", "c": "Aω² is related to maximum acceleration, wrong dimensions for velocity."}'::jsonb, 'SHM: v_max = Aω, a_max = Aω².', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('1e216ad3-d3d5-54ce-a1b6-7221af28e924', 'neet_ug', 'Physics', 'Mechanical Properties of Fluids', 'A soap bubble, having radius of 1 mm, is blown from a detergent solution having a surface tension of 2.5 × 10⁻² N/m. The pressure inside the bubble equals at a point Z₀ below the free surface of water in a container. Taking g = 10 m/s², density of water = 10³ kg/m³, the value of Z₀ is :-', '[{"id": "a", "text": "100 cm"}, {"id": "b", "text": "10 cm"}, {"id": "c", "text": "1 cm"}, {"id": "d", "text": "0.5 cm"}]'::jsonb, 'c', 'Excess pressure in a soap bubble 4T/r equals ρgZ₀.', 'Excess pressure = 4T/r = 4 × 2.5×10⁻² / 10⁻³ = 100 Pa. Setting ρgZ₀ = 100 gives Z₀ = 100/(10³ × 10) = 0.01 m = 1 cm.', '{"a": "Off by a factor of 100.", "b": "Off by a factor of 10.", "d": "Uses 2T/r (single surface) instead of 4T/r."}'::jsonb, 'Soap bubble (two surfaces): ΔP = 4T/r; liquid drop: ΔP = 2T/r.', 'med', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('d0c095cc-f340-545a-8266-bd8d451c5687', 'neet_ug', 'Physics', 'Thermal Properties of Matter', 'A copper rod of 88 cm and an aluminum rod of unknown length have their increase in length independent of increase in temperature. The length of aluminum rod is : (α_Cu = 1.7 × 10⁻⁵ K⁻¹ and α_Al = 2.2 × 10⁻⁵ K⁻¹)', '[{"id": "a", "text": "6.8 cm"}, {"id": "b", "text": "113.9 cm"}, {"id": "c", "text": "88 cm"}, {"id": "d", "text": "68 cm"}]'::jsonb, 'd', 'Equal expansions need L_Cu α_Cu = L_Al α_Al.', 'For the difference in length to stay fixed, both rods must expand by the same amount: 88 × 1.7×10⁻⁵ = L_Al × 2.2×10⁻⁵, so L_Al = 88 × 1.7/2.2 = 68 cm.', '{"a": "Decimal error.", "b": "Inverts the ratio (88 × 2.2/1.7).", "c": "Equal lengths would expand unequally."}'::jsonb, 'Linear expansion: ΔL = Lα ΔT.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('21a2b709-787e-5a9b-9f34-e4449c54cecb', 'neet_ug', 'Physics', 'Thermal Properties of Matter', 'The unit of thermal conductivity is :', '[{"id": "a", "text": "J m K⁻¹"}, {"id": "b", "text": "J m⁻¹ K⁻¹"}, {"id": "c", "text": "W m K⁻¹"}, {"id": "d", "text": "W m⁻¹ K⁻¹"}]'::jsonb, 'd', 'From H = KAΔT/L, K = HL/(AΔT) has unit W m⁻¹ K⁻¹.', 'Rate of heat flow H = KA(ΔT)/L, so K = H·L/(A·ΔT) → W·m/(m²·K) = W m⁻¹ K⁻¹.', '{"a": "Missing the per-second (power) and wrong power of metre.", "b": "Uses energy instead of power.", "c": "Wrong power of metre."}'::jsonb, 'Thermal conductivity K: W m⁻¹ K⁻¹.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('4d610884-7410-54b1-8b42-1d952ec50714', 'neet_ug', 'Physics', 'Mechanical Properties of Solids', 'When a block of mass M is suspended by a long wire of length L, the length of the wire become (L + l). The elastic potential energy stored in the extended wire is :-', '[{"id": "a", "text": "Mgl"}, {"id": "b", "text": "MgL"}, {"id": "c", "text": "(1/2) Mgl"}, {"id": "d", "text": "(1/2) MgL"}]'::jsonb, 'c', 'Elastic energy = ½ × load × extension.', 'Strain energy U = ½ F × extension = ½ Mg l. The other half of the gravitational PE lost (Mgl) is dissipated during the extension.', '{"a": "Mgl is the loss in gravitational PE, not stored elastic energy.", "b": "Uses original length instead of extension.", "d": "Uses original length instead of extension."}'::jsonb, 'Elastic PE = ½ × stress × strain × volume = ½Fx.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('c59b1bc6-e217-597d-b769-ecb71e33e129', 'neet_ug', 'Physics', 'System of Particles and Rotational Motion', 'A disc of radius 2m and mass 100 kg rolls on a horizontal floor. Its centre of mass has speed of 20 cm/s. How much work is needed to stop it ?', '[{"id": "a", "text": "3 J"}, {"id": "b", "text": "30 kJ"}, {"id": "c", "text": "2 J"}, {"id": "d", "text": "1 J"}]'::jsonb, 'a', 'Rolling disc KE = (3/4)Mv².', 'KE = ½Mv² + ½Iω² = ½Mv²(1 + ½) = (3/4) × 100 × (0.2)² = 3 J. Work needed to stop it equals this KE.', '{"b": "Uses v = 20 instead of 0.2 m/s.", "c": "Counts only translational KE (½Mv² = 2 J).", "d": "Counts only rotational KE (1 J)."}'::jsonb, 'Rolling KE = ½Mv²(1 + k²/R²).', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('b566d908-959b-55d8-9fc1-d99b473a3117', 'neet_ug', 'Physics', 'Units and Measurements', 'In an experiment, the percentage of error occurred in the measurment of physical quantities A, B, C and D are 1%, 2%, 3% and 4% respectively. Then the maximum percentage of error in the measurement X, where X = A²B^(1/2)/(C^(1/3)D³), will be :', '[{"id": "a", "text": "(3/13)%"}, {"id": "b", "text": "16%"}, {"id": "c", "text": "–10%"}, {"id": "d", "text": "10%"}]'::jsonb, 'b', 'Maximum relative error adds powers × individual errors.', 'ΔX/X = 2(1) + ½(2) + ⅓(3) + 3(4) = 2 + 1 + 1 + 12 = 16%.', '{"a": "Not the result of the error-propagation rule.", "c": "Errors always add; maximum error is never negative.", "d": "Subtracts the denominator errors instead of adding."}'::jsonb, 'For X = AᵃBᵇ/Cᶜ, ΔX/X = aΔA/A + bΔB/B + cΔC/C.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('215fa42d-aed5-52ef-99f4-33227a85dee1', 'neet_ug', 'Physics', 'Gravitation', 'A body weighs 200 N on the surface of the earth. How much will it weigh half way down to the centre of the earth ?', '[{"id": "a", "text": "150 N"}, {"id": "b", "text": "200 N"}, {"id": "c", "text": "250 N"}, {"id": "d", "text": "100 N"}]'::jsonb, 'd', 'Below the surface g'' = g(1 − d/R).', 'At depth d = R/2, g'' = g(1 − 1/2) = g/2, so weight = 200/2 = 100 N.', '{"a": "Not consistent with linear decrease of g with depth.", "b": "g decreases with depth.", "c": "g never increases inside the earth."}'::jsonb, 'g at depth d: g(1 − d/R); zero at centre.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('da03df3b-792e-5bca-a322-8b0f3ab89b58', 'neet_ug', 'Physics', 'Ray Optics and Optical Instruments', 'Which colour of the light has the longest wavelength ?', '[{"id": "a", "text": "red"}, {"id": "b", "text": "blue"}, {"id": "c", "text": "green"}, {"id": "d", "text": "violet"}]'::jsonb, 'a', 'Red is at the long-wavelength end of the visible spectrum (~700 nm).', 'Visible light runs from violet (~400 nm) to red (~700 nm), so red has the longest wavelength among the options.', '{"b": "Blue is about 450–490 nm.", "c": "Green is about 500–560 nm.", "d": "Violet has the shortest visible wavelength."}'::jsonb, 'VIBGYOR: wavelength increases from violet to red.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('3c1ba2ea-26ba-53e3-9f88-7a0f25e67792', 'neet_ug', 'Physics', 'System of Particles and Rotational Motion', 'A solid cylinder of mass 2 kg and radius 4 cm is rotating about its axis at the rate of 3 rpm. The torque required to stop after 2π revolutions is :', '[{"id": "a", "text": "2 × 10⁻⁶ N m"}, {"id": "b", "text": "2 × 10⁻³ N m"}, {"id": "c", "text": "12 × 10⁻⁴ N m"}, {"id": "d", "text": "2 × 10⁶ N m"}]'::jsonb, 'a', 'Use ω² = 2αθ with θ = 2π rev = 4π² rad, then τ = Iα.', 'ω = 3 × 2π/60 = π/10 rad/s; θ = 2π × 2π = 4π² rad. α = ω²/(2θ) = (π²/100)/(8π²) = 1/800 rad/s². I = ½MR² = ½ × 2 × (0.04)² = 1.6×10⁻³ kg m², so τ = 1.6×10⁻³/800 = 2×10⁻⁶ N m.', '{"b": "Off by 10³; likely radius not converted correctly.", "c": "Arithmetic error.", "d": "Absurdly large; inverted powers."}'::jsonb, 'Rotational kinematics: ω² = ω₀² + 2αθ; τ = Iα.', 'hard', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('5b759062-7fb8-5b98-afed-879a74fd6cd6', 'neet_ug', 'Physics', 'Oscillations', 'The radius of circle the period of revolution initial position and sense of revolution are indicated in the fig.
y-projection of the radius vector of rotating particle P is :', '[{"id": "a", "text": "y(t) = –3cos2πt, where y in m"}, {"id": "b", "text": "y(t) = 4 sin(πt/2), where y in m"}, {"id": "c", "text": "y(t) = 3 cos(3πt/2), where y in m"}, {"id": "d", "text": "y(t) = 3 cos(πt/2), where y in m"}]'::jsonb, 'd', 'Starting at the top (y = +3 m) with ω = 2π/4 = π/2 gives y = 3cos(πt/2).', 'Radius = 3 m and T = 4 s, so ω = 2π/T = π/2 rad/s. At t = 0, P is on the +y axis, so y(0) = +3 m, giving y = 3 cos(πt/2) regardless of the sense of rotation.', '{"a": "Wrong sign and wrong ω.", "b": "Wrong amplitude and gives y(0) = 0.", "c": "Wrong angular frequency."}'::jsonb, 'Projection of uniform circular motion on a diameter is SHM.', 'med', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', '/pyq/ug/2019/66.webp'),
('15c1956f-cb5d-567e-988c-a5e3caaedb98', 'neet_ug', 'Physics', 'Electric Charges and Fields', 'A hollow metal sphere of radius R is uniformly charged. The electric field due to the sphere at a distance r from the centre :', '[{"id": "a", "text": "increases as r increases for r < R and for r > R"}, {"id": "b", "text": "zero as r increases for r < R, decreases as r increases for r > R"}, {"id": "c", "text": "zero as r increases for r < R, increases as r increases for r > R"}, {"id": "d", "text": "decreases as r increases for r < R and for r > R"}]'::jsonb, 'b', 'Field is zero inside a charged shell and falls as 1/r² outside.', 'By Gauss''s law, no charge is enclosed for r < R, so E = 0. For r > R the shell acts like a point charge, E = kQ/r², which decreases with r.', '{"a": "Field inside a conducting shell is zero.", "c": "Outside, E falls as 1/r².", "d": "Inside, E is zero, not decreasing."}'::jsonb, 'Charged shell: E = 0 inside, kQ/r² outside.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('e2ed8c36-5f55-5518-a545-fc7f73290b2b', 'neet_ug', 'Physics', 'Electromagnetic Induction', 'In which of the following devices, the eddy current effect is not used ?', '[{"id": "a", "text": "induction furnace"}, {"id": "b", "text": "magnetic braking in train"}, {"id": "c", "text": "electromagnet"}, {"id": "d", "text": "electric heater"}]'::jsonb, 'd', 'An ordinary electric heater works on Joule heating, not eddy currents.', 'Induction furnaces heat metal by eddy currents and magnetic brakes use eddy-current damping. An electric heater simply passes current through a resistive coil (I²R heating), with no eddy currents involved.', '{"a": "Induction furnace uses eddy currents to heat metals.", "b": "Electromagnetic braking relies on eddy currents.", "c": "Intended as an eddy-current-related device in the key; the heater is the clear non-eddy device."}'::jsonb, 'Applications of eddy currents: magnetic braking, electromagnetic damping, induction furnace, energy meters.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('a21a873d-950d-5106-a00f-8f30c59e7d83', 'neet_ug', 'Physics', 'Current Electricity', 'Six similar bulbs are connected as shown in the figure with a DC source of emf E, and zero internal resistance.
The ratio of power consumption by the bulbs when (i) all are glowing and (ii) in the situation when two from section A and one from section B are glowing, will be :', '[{"id": "a", "text": "4 : 9"}, {"id": "b", "text": "9 : 4"}, {"id": "c", "text": "1 : 2"}, {"id": "d", "text": "2 : 1"}]'::jsonb, 'b', 'Sections A and B are each three bulbs in parallel, joined in series; P = E²/R_eq.', 'All glowing: R_eq = R/3 + R/3 = 2R/3, P₁ = 3E²/2R. With two in A and one in B: R_eq = R/2 + R = 3R/2, P₂ = 2E²/3R. P₁ : P₂ = (3/2) : (2/3) = 9 : 4.', '{"a": "Inverted ratio.", "c": "Does not match the equivalent resistances.", "d": "Does not match the equivalent resistances."}'::jsonb, 'At constant emf, P = E²/R_eq: lower resistance gives more power.', 'med', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', '/pyq/ug/2019/69.webp'),
('320eae6e-f941-578a-b221-2e7be8321da2', 'neet_ug', 'Physics', 'Work, Energy and Power', 'A force F = 20 + 10y acts on a particle in y-direction where F is in newton and y in meter. Work done by this force to move the particle from y = 0 to y = 1 m is :', '[{"id": "a", "text": "30 J"}, {"id": "b", "text": "5 J"}, {"id": "c", "text": "25 J"}, {"id": "d", "text": "20 J"}]'::jsonb, 'c', 'Work = ∫F dy for a variable force.', 'W = ∫₀¹ (20 + 10y) dy = [20y + 5y²]₀¹ = 20 + 5 = 25 J.', '{"a": "Uses F at y = 1 (30 N) × 1 m.", "b": "Only the 10y term''s integral.", "d": "Only the constant term."}'::jsonb, 'Work by a variable force = area under F–x graph.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('6e67dea6-ef82-578d-a545-fadbc33893b4', 'neet_ug', 'Physics', 'Ray Optics and Optical Instruments', 'Pick the wrong answer in the context with rainbow.', '[{"id": "a", "text": "When the light rays undergo two internal reflections in a water drop, a secondary rainbow is formed."}, {"id": "b", "text": "The order of colours is reversed in the secondary rainbow."}, {"id": "c", "text": "An observer can see a rainbow when his front is towards the sun."}, {"id": "d", "text": "Rainbow is a combined effect of dispersion refraction and reflection sunlight."}]'::jsonb, 'c', 'A rainbow is seen with the sun behind the observer.', 'Rainbows form from sunlight refracted, dispersed and internally reflected in droplets in front of the observer, with the sun at the observer''s back. So facing the sun is wrong. Secondary rainbows involve two internal reflections and have reversed colours.', '{"a": "Correct: secondary rainbow needs two total internal reflections.", "b": "Correct: colours are reversed in the secondary bow.", "d": "Correct: rainbow involves dispersion, refraction and internal reflection."}'::jsonb, 'Primary rainbow: one internal reflection; secondary: two, with reversed colours.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('c974c97b-3c3e-502a-b1ac-4dbf067c6c75', 'neet_ug', 'Physics', 'Moving Charges and Magnetism', 'A cylindrical conductor of radius R is carrying a constant current. The plot of the magnitude of the magnetic field, B with the distance d, from the centre of the conductor, is correctly represented by the figure :', '[{"id": "a", "text": "Option (1) in figure"}, {"id": "b", "text": "Option (2) in figure"}, {"id": "c", "text": "Option (3) in figure"}, {"id": "d", "text": "Option (4) in figure"}]'::jsonb, 'c', 'B rises linearly inside the wire and falls as 1/d outside.', 'By Ampère''s law, inside a uniformly carrying conductor B = μ₀Id/(2πR²), increasing linearly with d to a maximum at d = R. Outside, B = μ₀I/(2πd), falling off as 1/d. Graph (3) shows exactly this.', '{"a": "B is not constant inside the conductor.", "b": "B is not zero inside; it grows linearly.", "d": "B decreases outside, it does not stay constant."}'::jsonb, 'Long straight wire: B_in ∝ r, B_out ∝ 1/r, max at surface.', 'med', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', '/pyq/ug/2019/73.webp'),
('eedee01e-445f-513d-877f-b9b31aba9cd1', 'neet_ug', 'Physics', 'Motion in a Plane', 'Two particles A and B are moving in uniform circular motion in concentric circles of radius r_A and r_B with speed υ_A and υ_B respectively. The time period of rotation is the same. The ratio of angular speed of A to that of B will be :', '[{"id": "a", "text": "r_A : r_B"}, {"id": "b", "text": "υ_A : υ_B"}, {"id": "c", "text": "r_B : r_A"}, {"id": "d", "text": "1 : 1"}]'::jsonb, 'd', 'ω = 2π/T, so equal periods mean equal angular speeds.', 'Angular speed depends only on period: ω = 2π/T. With equal T, ω_A = ω_B, ratio 1 : 1. Linear speeds differ (υ = ωr) but angular speeds do not.', '{"a": "This is the ratio of linear speeds.", "b": "Equals r_A : r_B, not the ω ratio.", "c": "Inverse ratio has no basis."}'::jsonb, 'ω = 2π/T = υ/r.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('dc0e3fa4-a97a-57e3-afc3-2a7b8f0a42ab', 'neet_ug', 'Physics', 'Ray Optics and Optical Instruments', 'Two similar thin equi-convex lenses, of focal length f each, are kept coaxially in contact with each other such that the focal length of the combination is F₁. When the space between the two lenses is filled with glycerin (which has the same refractive index (μ = 1.5) as that of glass) then the equivalent focal length is F₂. The ratio F₁ : F₂ will be :', '[{"id": "a", "text": "2 : 1"}, {"id": "b", "text": "1 : 2"}, {"id": "c", "text": "2 : 3"}, {"id": "d", "text": "3 : 4"}]'::jsonb, 'b', 'The glycerin forms a concave lens of focal length −f between the two convex lenses.', 'Air gap: 1/F₁ = 1/f + 1/f, so F₁ = f/2. With μ = 1.5 and radius R, each glass lens has 1/f = 0.5(2/R) = 1/R. The glycerin fills an equi-concave lens with 1/f_g = 0.5(−2/R) = −1/f. Then 1/F₂ = 2/f − 1/f = 1/f, F₂ = f, so F₁ : F₂ = 1 : 2.', '{"a": "Inverted ratio.", "c": "Does not follow from the lens-maker''s formula.", "d": "Does not follow from the lens-maker''s formula."}'::jsonb, 'Lens maker: 1/f = (μ − 1)(1/R₁ − 1/R₂); in contact 1/F = Σ1/fᵢ.', 'hard', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('b1e32f18-b733-5b9b-9fdc-115d57774fba', 'neet_ug', 'Physics', 'Ray Optics and Optical Instruments', 'In total internal reflection when the angle of incidence is equal to the critical angle for the pair of media in contact, what will be angle of refraction?', '[{"id": "a", "text": "180°"}, {"id": "b", "text": "0°"}, {"id": "c", "text": "equal to angle of incidence"}, {"id": "d", "text": "90°"}]'::jsonb, 'd', 'At the critical angle the refracted ray grazes the surface, r = 90°.', 'The critical angle is defined as the angle of incidence in the denser medium for which the angle of refraction in the rarer medium is 90°, since sin C = μ_rarer/μ_denser = sin 90° × μ₂/μ₁.', '{"a": "Not a meaningful refraction angle.", "b": "0° corresponds to normal incidence.", "c": "Refraction angle exceeds incidence when going denser → rarer."}'::jsonb, 'sin C = 1/μ (denser medium to air).', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('f91e81b0-41f4-50a7-b76f-5e1d3dee52bd', 'neet_ug', 'Physics', 'Electric Charges and Fields', 'Two parallel infinite line charges with linear charge densities +λ C/m and −λ C/m are placed at a distance of 2R in free space. What is the electric field mid-way between the two line charges?', '[{"id": "a", "text": "zero"}, {"id": "b", "text": "2λ/(πε₀R) N/C"}, {"id": "c", "text": "λ/(πε₀R) N/C"}, {"id": "d", "text": "λ/(2πε₀R) N/C"}]'::jsonb, 'c', 'Fields of opposite line charges add at the midpoint.', 'Each line gives E = λ/(2πε₀R) at distance R. At the midpoint, the field of +λ points away from it and that of −λ points toward −λ, so both are in the same direction: E = 2 × λ/(2πε₀R) = λ/(πε₀R).', '{"a": "Fields would cancel only for like charges.", "b": "Double counts the factor of 2.", "d": "Field of only one line charge."}'::jsonb, 'Infinite line charge: E = λ/(2πε₀r).', 'med', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('d14da8cc-f089-53b5-a8a8-6c2a601d5422', 'neet_ug', 'Physics', 'Semiconductor Electronics: Materials, Devices and Simple Circuits', 'For a p-type semiconductor which of the following statements is true ?', '[{"id": "a", "text": "Electrons are the majority carriers and trivalent atoms are the dopants."}, {"id": "b", "text": "Holes are the majority carriers and trivalent atoms are the dopants."}, {"id": "c", "text": "Holes are the majority carriers and pentavalent atoms are the dopants."}, {"id": "d", "text": "Electrons are the majority carriers and pentavalent atoms are the dopants."}]'::jsonb, 'b', 'p-type: trivalent (acceptor) dopants, holes as majority carriers.', 'Doping Si/Ge with trivalent atoms like B, Al or In leaves one bond incomplete, creating a hole per dopant. These acceptor holes make holes the majority carriers in p-type material.', '{"a": "In p-type, electrons are minority carriers.", "c": "Pentavalent dopants make n-type.", "d": "This describes n-type semiconductor."}'::jsonb, 'p-type: acceptor (group 13) dopant, n_h ≫ n_e.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('fcd8e2d6-f0dc-55b6-a6cf-b9f3ce4de7a0', 'neet_ug', 'Physics', 'Current Electricity', 'Which of the following acts as a circuit protection device?', '[{"id": "a", "text": "conductor"}, {"id": "b", "text": "inductor"}, {"id": "c", "text": "switch"}, {"id": "d", "text": "fuse"}]'::jsonb, 'd', 'A fuse melts and breaks the circuit when current exceeds a safe limit.', 'A fuse wire has a low melting point; excess current heats it (I²R) until it melts and opens the circuit, protecting appliances. Conductors, inductors and switches do not protect automatically against overcurrent.', '{"a": "Simply carries current.", "b": "Opposes change in current but does not protect against overload.", "c": "Manually controls the circuit; no automatic protection."}'::jsonb, 'Fuse: low melting point, high resistivity alloy wire in series.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('6236094b-5398-5284-8693-58cc4fcc93fc', 'neet_ug', 'Physics', 'Electromagnetic Waves', 'A parallel plate capacitor of capacitance 20 μF is being charged by a voltage source whose potential is changing at the rate of 3 V/s. The conduction current through the connecting wires, and the displacement current through the plates of the capacitor, would be, respectively :', '[{"id": "a", "text": "zero, 60 μA"}, {"id": "b", "text": "60 μA, 60 μA"}, {"id": "c", "text": "60 μA, zero"}, {"id": "d", "text": "zero, zero"}]'::jsonb, 'b', 'Conduction current in the wires equals displacement current between the plates, C dV/dt.', 'i = C dV/dt = 20×10⁻⁶ × 3 = 60 μA flows in the wires. Between the plates the displacement current ε₀ dΦ_E/dt equals the same 60 μA, keeping current continuous.', '{"a": "Conduction current in the wires is not zero while charging.", "c": "Displacement current exists between the plates while charging.", "d": "Both are non-zero while V changes."}'::jsonb, 'Displacement current i_d = ε₀ dΦ_E/dt = conduction current.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('7b3ea139-c6e2-5b8c-b05a-281cabe1d1d6', 'neet_ug', 'Physics', 'Current Electricity', 'In the circuits shown below, the readings of the voltmeters and the ammeters will be :', '[{"id": "a", "text": "V₂ > V₁ and i₁ = i₂"}, {"id": "b", "text": "V₁ = V₂ and i₁ > i₂"}, {"id": "c", "text": "V₁ = V₂ and i₁ = i₂"}, {"id": "d", "text": "V₂ > V₁ and i₁ > i₂"}]'::jsonb, 'c', 'Ideal voltmeters draw no current, so both circuits are just 10 V across 10 Ω.', 'Circuit 1: V₁ is across the 10 Ω resistor, i₁ = 10/10 = 1 A, V₁ = 10 V. Circuit 2: an ideal voltmeter in series with 10 Ω carries no current, so no drop across that resistor and V₂ reads the 10 V across the other 10 Ω; i₂ = 1 A. Hence V₁ = V₂ and i₁ = i₂.', '{"a": "V₂ is not larger; the series 10 Ω has no drop.", "b": "Currents are equal because the voltmeter branch carries no current.", "d": "Neither reading differs for ideal meters."}'::jsonb, 'Ideal voltmeter: infinite resistance; ideal ammeter: zero resistance.', 'med', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', '/pyq/ug/2019/81.webp'),
('d7b69e56-5eff-586c-a733-b76ed167b115', 'neet_ug', 'Physics', 'Nuclei', 'α-particle consists of :', '[{"id": "a", "text": "2 protons and 2 neutrons only"}, {"id": "b", "text": "2 electrons, 2 protons and 2 neutrons"}, {"id": "c", "text": "2 electrons and 4 protons only"}, {"id": "d", "text": "2 protons only"}]'::jsonb, 'a', 'An α-particle is a helium-4 nucleus: 2p + 2n.', 'The α-particle is the nucleus of ⁴He, carrying charge +2e and mass number 4, so it has 2 protons and 2 neutrons and no electrons.', '{"b": "That would be a neutral helium atom.", "c": "Wrong composition and charge.", "d": "Mass number would be 2, not 4."}'::jsonb, 'α = ⁴₂He²⁺ nucleus.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('4f810723-17aa-5ed7-8d09-61698cb9174a', 'neet_ug', 'Physics', 'Dual Nature of Radiation and Matter', 'An electron is accelerated through a potential difference of 10,000 V. Its de Broglie wavelength is, (nearly) : (mₑ = 9 × 10⁻³¹ kg)', '[{"id": "a", "text": "12.2 × 10⁻¹³ m"}, {"id": "b", "text": "12.2 × 10⁻¹² m"}, {"id": "c", "text": "12.2 × 10⁻¹⁴ m"}, {"id": "d", "text": "12.2 nm"}]'::jsonb, 'b', 'λ = 1.227/√V nm for electrons.', 'λ = h/√(2meV) = 1.227/√V nm = 1.227/100 nm = 0.01227 nm = 12.2 × 10⁻¹² m.', '{"a": "Off by a factor of 10.", "c": "Off by a factor of 100.", "d": "Off by a factor of 1000."}'::jsonb, 'Electron de Broglie wavelength: λ = 1.227/√V nm.', 'med', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('4512989e-f3af-588c-803f-c9f8da95943b', 'neet_ug', 'Physics', 'Motion in a Straight Line', 'When an object is shot from the bottom of a long smooth inclined plane kept at an angle 60° with horizontal, it can travel a distance x₁ along the plane. But when the inclination is decreased to 30° and the same object the shot with the same velocity, it can travel x₂ distance. Then x₁ : x₂ will be', '[{"id": "a", "text": "1 : √2"}, {"id": "b", "text": "√2 : 1"}, {"id": "c", "text": "1 : √3"}, {"id": "d", "text": "1 : 2√3"}]'::jsonb, 'c', 'Deceleration along a smooth incline is g sinθ, so x ∝ 1/sinθ.', 'x = u²/(2g sinθ). So x₁/x₂ = sin30°/sin60° = (1/2)/(√3/2) = 1/√3.', '{"a": "Uses a wrong trigonometric ratio.", "b": "Uses a wrong trigonometric ratio.", "d": "Arithmetic error."}'::jsonb, 'Smooth incline: a = g sinθ along the plane.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('395fb714-8ffb-547b-aabb-6151a146f274', 'neet_ug', 'Physics', 'Mechanical Properties of Fluids', 'A small hole of area of cross-section 2 mm² is present near the bottom of a fully filled open tank of height 2 m. Taking g = 10 m/s², the rate of flow of water through the open hole would be nearly :', '[{"id": "a", "text": "12.6 × 10⁻⁶ m³/s"}, {"id": "b", "text": "8.9 × 10⁻⁶ m³/s"}, {"id": "c", "text": "2.23 × 10⁻⁶ m³/s"}, {"id": "d", "text": "6.4 × 10⁻⁶ m³/s"}]'::jsonb, 'a', 'Torricelli: v = √(2gh), flow rate = Av.', 'v = √(2 × 10 × 2) = √40 ≈ 6.32 m/s. Q = Av = 2×10⁻⁶ × 6.32 ≈ 12.6×10⁻⁶ m³/s.', '{"b": "Would correspond to a smaller efflux speed (≈4.5 m/s), i.e. using √(gh) instead of √(2gh).", "c": "Too small by a factor of about 6; misses the speed factor.", "d": "Takes the speed (√40 ≈ 6.3) without multiplying by the 2 mm² area properly."}'::jsonb, 'Torricelli''s law: efflux speed v = √(2gh).', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('d984e6f0-5436-50f9-bf03-7d0462dfa2df', 'neet_ug', 'Physics', 'Electric Charges and Fields', 'Two point charges A and B, having charges +Q and −Q respectively, are placed at certain distance apart and force acting between them is F. If 25% charge of A is transferred to B, then force between the charges becomes :', '[{"id": "a", "text": "F"}, {"id": "b", "text": "9F/16"}, {"id": "c", "text": "16F/9"}, {"id": "d", "text": "4F/3"}]'::jsonb, 'b', 'After transfer the charges are +3Q/4 and −3Q/4.', 'A loses Q/4 → +3Q/4; B gains +Q/4 → −Q + Q/4 = −3Q/4. Force ∝ product: (3/4)² = 9/16, so F'' = 9F/16.', '{"a": "Product of charges changes.", "c": "Inverted ratio.", "d": "Arithmetic error."}'::jsonb, 'Coulomb''s law: F ∝ q₁q₂/r².', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('1efc6316-c7ee-5a16-a0d7-81a62597b27e', 'neet_ug', 'Physics', 'Moving Charges and Magnetism', 'Ionized hydrogen atoms and α-particles with same momenta enters perpendicular to a constant magnetic field B. The ratio of their radii of their paths r_H : r_α will be', '[{"id": "a", "text": "2 : 1"}, {"id": "b", "text": "1 : 2"}, {"id": "c", "text": "4 : 1"}, {"id": "d", "text": "1 : 4"}]'::jsonb, 'a', 'r = p/(qB): same p, so r ∝ 1/q.', 'r = mv/(qB) = p/(qB). With equal p and B, r_H/r_α = q_α/q_H = 2e/e = 2 : 1.', '{"b": "Inverted ratio.", "c": "Uses mass/charge ratio as if speeds were equal.", "d": "Inverted and squared."}'::jsonb, 'Charge in magnetic field: r = mv/qB = p/qB.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('749612d3-4de0-5597-b83e-2482bba296a6', 'neet_ug', 'Physics', 'Laws of Motion', 'A particle moving with velocity V⃗ is acted by three forces shown by the vector triangle PQR. The velocity of the particle will :', '[{"id": "a", "text": "increase"}, {"id": "b", "text": "decrease"}, {"id": "c", "text": "remain constant"}, {"id": "d", "text": "change according to the smallest force QR⃗"}]'::jsonb, 'c', 'Forces forming a closed triangle sum to zero, so velocity stays constant.', 'The three forces are represented in order by the sides of a closed triangle PQR, so their resultant is zero. With zero net force, acceleration is zero and the particle keeps moving with constant velocity (Newton''s first law).', '{"a": "Needs a net force along the motion.", "b": "Needs a net force opposite to the motion.", "d": "Individual forces do not matter once the resultant is zero."}'::jsonb, 'Triangle law: forces represented by sides of a closed triangle taken in order are in equilibrium.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', '/pyq/ug/2019/88.webp'),
('b9a9474d-4b3a-5d1f-ad73-2bb383e289ff', 'neet_ug', 'Physics', 'Gravitation', 'The work done to raise a mass m from the surface of the earth to a height h, which is equal to the radius of the earth, is :', '[{"id": "a", "text": "mgR"}, {"id": "b", "text": "2 mgR"}, {"id": "c", "text": "(1/2) mgR"}, {"id": "d", "text": "(3/2) mgR"}]'::jsonb, 'c', 'ΔU = mgh/(1 + h/R) = mgR/2 for h = R.', 'W = GMm/R − GMm/2R = GMm/2R = mgR/2, using GM = gR².', '{"a": "Assumes g constant up to height R.", "b": "Overestimate; ignores weakening of g.", "d": "No basis in the energy difference."}'::jsonb, 'Gravitational PE: U = −GMm/r.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('916fb0de-bee2-58db-b727-1386cac49e96', 'neet_ug', 'Physics', 'Wave Optics', 'In a double slit experiment, when light of wavelength 400 nm was used, the angular width of the first minima formed on a screen placed 1m away, was found to be 0.2°. What will be the angular width of the first minima, if the entire experimental apparatus is immersed in water (μ_water = 4/3)', '[{"id": "a", "text": "0.266°"}, {"id": "b", "text": "0.15°"}, {"id": "c", "text": "0.05°"}, {"id": "d", "text": "0.1°"}]'::jsonb, 'b', 'Wavelength in water is λ/μ, so angular width scales as 1/μ.', 'Angular width θ = λ/d. In water λ'' = λ/μ, so θ'' = θ/μ = 0.2°/(4/3) = 0.15°.', '{"a": "Multiplies by μ instead of dividing.", "c": "Arithmetic error.", "d": "Halves instead of dividing by 4/3."}'::jsonb, 'In a medium, λ'' = λ/μ; fringe width shrinks by μ.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('b5715a34-743f-52dd-8a27-52cd3a2cb01d', 'neet_ug', 'Botany', 'Biological Classification', 'Which of the following statements is incorrect ?', '[{"id": "a", "text": "Viroids lack a protein coat"}, {"id": "b", "text": "Viruses are obligate parasites"}, {"id": "c", "text": "Infective constituent in viruses is the protein coat"}, {"id": "d", "text": "Prions consist of abnormally folded proteins"}]'::jsonb, 'c', 'The infective part of a virus is its nucleic acid, not the protein coat.', 'A virus is a nucleoprotein particle in which the genetic material (RNA or DNA) carries the infectivity; the protein capsid only protects it and helps attachment. Viroids are naked infectious RNA, viruses can multiply only inside living host cells, and prions are misfolded proteins, so statement (3) is the wrong one.', '{"a": "True: viroids are free RNA without a capsid.", "b": "True: viruses reproduce only inside living cells.", "d": "True: prions are abnormally folded proteins (e.g., causing BSE)."}'::jsonb, 'Viroids (discovered by T.O. Diener) are free low-molecular-weight RNA causing potato spindle tuber disease.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('2c25af8f-8388-50ef-b8cc-3e2fe7d8a3c0', 'neet_ug', 'Botany', 'Biomolecules', 'Purines found both in DNA and RNA are :-', '[{"id": "a", "text": "Adenine and thymine"}, {"id": "b", "text": "Adenine and guanine"}, {"id": "c", "text": "Guanine and cytosine"}, {"id": "d", "text": "Cytosine and thymine"}]'::jsonb, 'b', 'Adenine and guanine are the purines common to DNA and RNA.', 'Purines have a fused double-ring structure; the two purines in nucleic acids are adenine and guanine, and both occur in DNA as well as RNA. Cytosine, thymine and uracil are single-ring pyrimidines.', '{"a": "Thymine is a pyrimidine and is absent from RNA.", "c": "Cytosine is a pyrimidine.", "d": "Both are pyrimidines; thymine is DNA-specific."}'::jsonb, 'Uracil replaces thymine in RNA; both are pyrimidines.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('53c2c531-d9bf-5469-bc02-3aaf225ad2d4', 'neet_ug', 'Zoology', 'Chemical Coordination and Integration', 'Which of the following glucose transporters is insulin-dependent ?', '[{"id": "a", "text": "GLUT I"}, {"id": "b", "text": "GLUT II"}, {"id": "c", "text": "GLUT III"}, {"id": "d", "text": "GLUT IV"}]'::jsonb, 'd', 'GLUT-4 is the insulin-regulated glucose transporter of muscle and adipose tissue.', 'Insulin promotes glucose uptake into skeletal muscle and adipocytes by moving GLUT-4 transporters from intracellular vesicles to the plasma membrane. GLUT-1 (RBCs, brain), GLUT-2 (liver, pancreatic β-cells) and GLUT-3 (neurons) work without insulin.', '{"a": "GLUT-1 provides basal, insulin-independent uptake.", "b": "GLUT-2 in liver and β-cells is insulin-independent.", "c": "GLUT-3 in neurons is insulin-independent."}'::jsonb, 'Insulin is a hypoglycaemic hormone that enhances cellular glucose uptake and glycogenesis.', 'med', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('85d58d91-ab57-5af4-a085-0a0c33b50fd3', 'neet_ug', 'Zoology', 'Structural Organisation in Animals', 'Identify the cells whose secretion protects the lining of gastro-intestinal tract from various enzymes :-', '[{"id": "a", "text": "Chief Cells"}, {"id": "b", "text": "Goblet Cells"}, {"id": "c", "text": "Oxyntic Cells"}, {"id": "d", "text": "Duodenal Cells"}]'::jsonb, 'b', 'Goblet cells secrete mucus that shields the gut lining from digestive enzymes and acid.', 'Goblet cells are unicellular glands in the columnar epithelium of the alimentary canal that secrete mucus. The mucus coats the mucosa and protects it from self-digestion by enzymes and HCl. Chief cells secrete pepsinogen and oxyntic cells secrete HCl, which are the agents the lining needs protecting from.', '{"a": "Chief (peptic) cells secrete pepsinogen, a digestive enzyme precursor.", "c": "Oxyntic (parietal) cells secrete HCl and intrinsic factor.", "d": "Not a specific mucus-secreting cell type named for protection."}'::jsonb, 'Goblet cells are unicellular glandular epithelial cells of the alimentary canal lining.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('a0fe9d67-3cfc-5581-9a66-43648ac321d3', 'neet_ug', 'Zoology', 'Biotechnology: Principles and Processes', 'Which one of the following equipments is essentially required for growing microbes on a large scale, for industrial production of enzymes ?', '[{"id": "a", "text": "BOD incubator"}, {"id": "b", "text": "Sludge digester"}, {"id": "c", "text": "Industrial oven"}, {"id": "d", "text": "Bioreactor"}]'::jsonb, 'd', 'Bioreactors are vessels for large-volume culture of microbes to make products like enzymes.', 'Large-scale production of a desired product requires culturing cells in large volumes (100–1000 L) under optimal temperature, pH, aeration and nutrient supply, which is done in bioreactors such as the stirred-tank type. A BOD incubator is for small tests, a sludge digester is for anaerobic sewage treatment, and an oven is for heating.', '{"a": "Used for measuring BOD of small samples, not industrial culture.", "b": "Anaerobic digester for sewage sludge producing biogas.", "c": "An oven sterilises/heats; it cannot culture microbes."}'::jsonb, 'A stirred-tank bioreactor has an agitator, oxygen delivery, foam control, temperature and pH control systems.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('ca697e18-4817-5fce-b91f-0429a9ac68c6', 'neet_ug', 'Zoology', 'Biotechnology and its Applications', 'Which of the following is true for Golden rice ?', '[{"id": "a", "text": "It is Vitamin A enriched, with a gene from daffodil"}, {"id": "b", "text": "It is pest resistant, with a gene from Bacillus thuringiensis"}, {"id": "c", "text": "It is drought tolerant, developed using Agrobacterium vector"}, {"id": "d", "text": "It has yellow grains, because of a gene introduced from a primitive variety of rice"}]'::jsonb, 'a', 'Golden rice is a β-carotene (pro-vitamin A) enriched transgenic rice made using a daffodil gene.', 'Golden rice was engineered to synthesise β-carotene in the endosperm by introducing the phytoene synthase gene from daffodil along with a bacterial gene. Its yellow colour comes from β-carotene, not from a primitive rice gene, and it was not designed for pest resistance or drought tolerance.', '{"b": "Bt genes give pest resistance in Bt cotton/brinjal, not golden rice.", "c": "Golden rice was not made for drought tolerance.", "d": "The yellow colour is due to transgenic β-carotene synthesis, not a gene from primitive rice."}'::jsonb, 'Golden rice targets vitamin A deficiency; β-carotene is the precursor of vitamin A.', 'med', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('eacf074d-092d-5dd8-ae5e-fb2479263e1b', 'neet_ug', 'Botany', 'Biodiversity and Conservation', 'Which one of the following is not a method of in situ conservation of biodiversity ?', '[{"id": "a", "text": "Biosphere Reserve"}, {"id": "b", "text": "Wildlife Sanctuary"}, {"id": "c", "text": "Botanical Garden"}, {"id": "d", "text": "Sacred Grove"}]'::jsonb, 'c', 'Botanical gardens conserve plants away from their natural habitat, so they are ex situ.', 'In situ conservation protects species within their natural habitat, as in biosphere reserves, national parks, wildlife sanctuaries and sacred groves. Botanical gardens, zoos, seed banks and cryopreservation keep organisms outside their habitat and are ex situ methods.', '{"a": "Biosphere reserves protect ecosystems in place.", "b": "Sanctuaries protect wildlife in their habitat.", "d": "Sacred groves are community-protected forest patches, an in situ method."}'::jsonb, 'India''s territory covers parts of 3 of the world''s 34 biodiversity hotspots: Western Ghats–Sri Lanka, Indo-Burma and Himalaya.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('bcb316ca-4ea7-553f-b506-4a21fe5efc9b', 'neet_ug', 'Botany', 'Molecular Basis of Inheritance', 'Under which of the following conditions will there be no change in the reading frame of following mRNA ?
5''AACAGCGGUGCUAUU3''', '[{"id": "a", "text": "Insertion of G at 5th position"}, {"id": "b", "text": "Deletion of G from 5th position"}, {"id": "c", "text": "Insertion of A at G at 4th and 5th positions respectively"}, {"id": "d", "text": "Deletion of GGU from 7th, 8th and 9th positions"}]'::jsonb, 'd', 'Removing three consecutive bases (one whole codon) keeps the downstream reading frame intact.', 'Reading in triplets: AAC AGC GGU GCU AUU. Deleting G-G-U at positions 7–9 removes exactly one codon, leaving AAC AGC GCU AUU with the same frame. Inserting or deleting one base, or inserting two bases, shifts every codon after that point (frameshift).', '{"a": "A single insertion causes a frameshift.", "b": "A single deletion causes a frameshift.", "c": "Two insertions shift the frame by two bases."}'::jsonb, 'Insertion or deletion of 3 or multiples of 3 bases adds/removes codons without a frameshift.', 'med', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('aea2b27d-4014-5da7-b036-64a73e4bf7eb', 'neet_ug', 'Botany', 'Microbes in Human Welfare', 'Match the following organisms with the products they produce :-
(a) Lactobacillus | (i) Cheese
(b) Saccharomyces cerevisiae | (ii) Curd
(c) Aspergillus niger | (iii) Citric Acid
(d) Acetobacter aceti | (iv) Bread
 | (v) Acetic Acid
Select the correct option.', '[{"id": "a", "text": "(a)-ii, (b)-iv, (c)-v, (d)-iii"}, {"id": "b", "text": "(a)-ii, (b)-iv, (c)-iii, (d)-v"}, {"id": "c", "text": "(a)-iii, (b)-iv, (c)-v, (d)-i"}, {"id": "d", "text": "(a)-ii, (b)-i, (c)-iii, (d)-v"}]'::jsonb, 'b', 'Lactobacillus–curd, baker''s yeast–bread, A. niger–citric acid, Acetobacter aceti–acetic acid.', 'Lactobacillus (LAB) converts milk to curd; Saccharomyces cerevisiae ferments dough to make bread; the fungus Aspergillus niger produces citric acid; and the bacterium Acetobacter aceti produces acetic acid. Only option (2) gives this combination.', '{"a": "Swaps citric acid and acetic acid producers.", "c": "Lactobacillus makes curd, not citric acid; Acetobacter does not make cheese.", "d": "S. cerevisiae is used for bread (and alcohol), not cheese."}'::jsonb, 'Clostridium butylicum → butyric acid; Lactobacillus → lactic acid; Aspergillus niger → citric acid; Acetobacter aceti → acetic acid.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('e866952d-a759-5d58-9aed-8a1b4c78cd0a', 'neet_ug', 'Botany', 'Principles of Inheritance and Variation', 'What map unit (Centimorgan) is adopted in the construction of genetic maps ?', '[{"id": "a", "text": "A unit of distance between two expressed genes, representing 10% cross over"}, {"id": "b", "text": "A unit of distance between two expressed genes, representing 100% cross over"}, {"id": "c", "text": "A unit of distance between genes on chromosomes, representing 1% cross over"}, {"id": "d", "text": "A unit of distance between genes on chromosomes, representing 50% cross over"}]'::jsonb, 'c', 'One centimorgan equals 1% recombination (crossing over) between two linked genes.', 'Sturtevant used recombination frequency between linked genes on a chromosome as a measure of their distance. A map unit (centimorgan) is defined as the distance giving 1% recombinant progeny. It refers to gene loci on chromosomes, not specifically to expressed genes.', '{"a": "10% recombination equals 10 cM, not one unit.", "b": "Recombination frequency cannot exceed 50%; 100% is meaningless.", "d": "50% recombination indicates independent assortment, i.e., 50 cM or unlinked genes."}'::jsonb, 'Recombination frequency is higher for genes farther apart and lower for tightly linked genes.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('dc753c02-95aa-5871-8a90-e1af550dedb2', 'neet_ug', 'Zoology', 'Reproductive Health', 'Select the hormone-releasing Intra-Uterine Devices?', '[{"id": "a", "text": "Vaults, LNG-20"}, {"id": "b", "text": "Multiload 375, Progestasert"}, {"id": "c", "text": "Progestasert, LNG-20"}, {"id": "d", "text": "Lippes Loop, Multiload 375"}]'::jsonb, 'c', 'Progestasert and LNG-20 are hormone-releasing IUDs.', 'IUDs are classified as non-medicated (Lippes loop), copper-releasing (CuT, Cu7, Multiload 375) and hormone-releasing (Progestasert, LNG-20). Hormone-releasing IUDs make the uterus unsuitable for implantation and the cervix hostile to sperm. Vaults are barrier devices, not IUDs.', '{"a": "Vaults are barrier contraceptives.", "b": "Multiload 375 is copper-releasing.", "d": "Lippes loop is non-medicated and Multiload 375 is copper-releasing."}'::jsonb, 'Copper ions released from Cu-IUDs suppress sperm motility and fertilising capacity.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('1f536f7a-4d03-55d6-a269-2fc6358b0b43', 'neet_ug', 'Botany', 'Microbes in Human Welfare', 'Which of the following can be used as a biocontrol agent in the treatment of plant disease ?', '[{"id": "a", "text": "Trichoderma"}, {"id": "b", "text": "Chlorella"}, {"id": "c", "text": "Anabaena"}, {"id": "d", "text": "Lactobacillus"}]'::jsonb, 'a', 'Trichoderma is a free-living fungus used as a biocontrol agent against plant pathogens.', 'Trichoderma species are free-living fungi common in root ecosystems that act against several plant pathogens, so they are used for biological control of plant diseases. Chlorella is a protein-rich alga (SCP), Anabaena is a nitrogen-fixing cyanobacterium (biofertiliser) and Lactobacillus forms curd.', '{"b": "Chlorella is used as single-cell protein, not biocontrol.", "c": "Anabaena is a biofertiliser fixing nitrogen.", "d": "Lactobacillus is used in curd formation."}'::jsonb, 'Baculoviruses (genus Nucleopolyhedrovirus) are species-specific biocontrol agents of insects.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('8a8ee29d-4afc-5ad9-a253-33411e4cc5b4', 'neet_ug', 'Botany', 'Molecular Basis of Inheritance', 'Expressed Sequence Tags (ESTs) refers to :-', '[{"id": "a", "text": "Genes expressed as RNA"}, {"id": "b", "text": "Polypeptide expression"}, {"id": "c", "text": "DNA polymorphism"}, {"id": "d", "text": "Novel DNA sequences"}]'::jsonb, 'a', 'ESTs identify all genes that are expressed as RNA.', 'The Human Genome Project used two approaches: sequence annotation (sequencing the whole genome) and Expressed Sequence Tags, which focus on identifying all the genes expressed as RNA. ESTs are short cDNA sequences from mRNA, so they mark transcribed genes.', '{"b": "ESTs come from RNA (cDNA), not proteins.", "c": "DNA polymorphism refers to variation such as VNTRs/SNPs.", "d": "ESTs are not defined as novel sequences."}'::jsonb, 'Sequence annotation sequences the whole genome including coding and non-coding regions.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('adf08521-b52a-5380-959f-23f1afb67bc9', 'neet_ug', 'Zoology', 'Human Health and Disease', 'Colostrum, the yellowish fluid, secreted by mother during the initial days of lactation is very essential to impart immunity to the newborn infants because it contains :-', '[{"id": "a", "text": "Natural killer cells"}, {"id": "b", "text": "Monocytes"}, {"id": "c", "text": "Macrophages"}, {"id": "d", "text": "Immunoglobulin A"}]'::jsonb, 'd', 'Colostrum is rich in IgA antibodies that give the newborn passive immunity.', 'Colostrum, secreted in the first few days of lactation, contains abundant IgA antibodies. These ready-made antibodies protect the infant''s gut and give passive immunity until its own immune system matures. NK cells, monocytes and macrophages are not the immunity-providing component of colostrum.', '{"a": "NK cells are part of innate cellular defence, not transferred via colostrum.", "b": "Monocytes are blood phagocytes, not the key colostrum factor.", "c": "Macrophages are tissue phagocytes; colostrum''s protective role is from IgA."}'::jsonb, 'Transfer of antibodies from mother to foetus via placenta (IgG) is also passive immunity.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('2e47fc3b-fc90-5e35-ba43-a78af06c10cf', 'neet_ug', 'Zoology', 'Human Reproduction', 'Select the correct sequence of transport of sperm cells in male reproductive system :-', '[{"id": "a", "text": "Testis → Epididymis → Vasa efferentia → Rete testis → Inguinal canal → Urethra"}, {"id": "b", "text": "Seminiferous tubules → Rete testis → Vasa efferentia → Epididymis → Vas deferens → Ejaculatory duct → Urethra → Urethral meatus"}, {"id": "c", "text": "Seminiferous tubules → Vasa efferentia → Epididymis → Inguinal canal → Urethra"}, {"id": "d", "text": "Testis → Epididymis → Vasa efferentia → Vas deferens → Ejaculatory duct → Inguinal canal → Urethra → Urethral meatus"}]'::jsonb, 'b', 'Sperms pass from seminiferous tubules to rete testis, vasa efferentia, epididymis, vas deferens, ejaculatory duct and urethra.', 'Sperms formed in seminiferous tubules move into the rete testis, then via vasa efferentia to the epididymis where they mature. From there the vas deferens carries them, joining the seminal vesicle duct to form the ejaculatory duct, which opens into the urethra and out through the urethral meatus. The inguinal canal is only a passage for the spermatic cord, not a duct for sperm.', '{"a": "Rete testis lies before vasa efferentia, and the inguinal canal is not a sperm duct.", "c": "Skips rete testis, vas deferens and ejaculatory duct.", "d": "Wrong order of epididymis and vasa efferentia; inguinal canal is not in the pathway."}'::jsonb, 'Male accessory glands: paired seminal vesicles, a prostate and paired bulbourethral glands.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('9de3f2d3-b855-5d11-a717-87e771b06810', 'neet_ug', 'Zoology', 'Evolution', 'A gene locus has two alleles A, a. If the frequency of dominant allele A is 0.4 then what will be the frequency of homozygous dominant, heterozygous and homozygous recessive individuals in the population ?', '[{"id": "a", "text": "0.36 (AA); 0.48 (Aa); 0.16 (aa)"}, {"id": "b", "text": "0.16 (AA); 0.24 (Aa); 0.36 (aa)"}, {"id": "c", "text": "0.16 (AA); 0.48 (Aa); 0.36 (aa)"}, {"id": "d", "text": "0.16 (AA); 0.36 (Aa); 0.48 (aa)"}]'::jsonb, 'c', 'With p = 0.4 and q = 0.6, p² = 0.16, 2pq = 0.48, q² = 0.36.', 'In Hardy–Weinberg equilibrium p + q = 1, so q = 1 − 0.4 = 0.6. Genotype frequencies are AA = p² = 0.16, Aa = 2pq = 2 × 0.4 × 0.6 = 0.48 and aa = q² = 0.36, which add up to 1.', '{"a": "Uses q for A, i.e., swaps the allele frequencies.", "b": "2pq is 0.48, not 0.24 (forgot the factor 2).", "d": "Swaps the heterozygous and recessive frequencies."}'::jsonb, 'Hardy–Weinberg: p² + 2pq + q² = 1; disturbed by gene migration, genetic drift, mutation, recombination and natural selection.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('fa8f142a-0f53-51e5-b5e3-1dfb9a121b0c', 'neet_ug', 'Zoology', 'Animal Kingdom', 'Match the following organisms with their respective characteristics :-
(a) Pila | (i) Flame cells
(b) Bombyx | (ii) Comb plates
(c) Pleurobrachia | (iii) Radula
(d) Taenia | (iv) Malpighian tubules
Select the correct option from the following', '[{"id": "a", "text": "(a)-(iii), (b)-(ii), (c)-(i), (d)-(iv)"}, {"id": "b", "text": "(a)-(iii), (b)-(iv), (c)-(ii), (d)-(i)"}, {"id": "c", "text": "(a)-(ii), (b)-(iv), (c)-(iii), (d)-(i)"}, {"id": "d", "text": "(a)-(iii), (b)-(ii), (c)-(iv), (d)-(i)"}]'::jsonb, 'b', 'Pila–radula, Bombyx–Malpighian tubules, Pleurobrachia–comb plates, Taenia–flame cells.', 'Pila is a mollusc with a rasping radula; Bombyx (silkworm) is an arthropod excreting through Malpighian tubules; Pleurobrachia is a ctenophore with eight rows of comb plates for locomotion; Taenia is a flatworm using flame cells for osmoregulation and excretion. This matches option (2).', '{"a": "Comb plates belong to Pleurobrachia, not Bombyx.", "c": "Radula belongs to Pila, not Pleurobrachia.", "d": "Malpighian tubules belong to Bombyx, not Pleurobrachia."}'::jsonb, 'Ctenophores show bioluminescence; comb plates are their locomotory structures.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('1a3e8834-c4d8-53c6-90c7-0ddf1ba75224', 'neet_ug', 'Botany', 'Cell: The Unit of Life', 'The shorter and longer arms of a submetacentric chromosome are referred to as :-', '[{"id": "a", "text": "s-arm and l-arm respectively"}, {"id": "b", "text": "p-arm and q-arm respectively"}, {"id": "c", "text": "q-arm and p-arm respectively"}, {"id": "d", "text": "m-arm and n-arm respectively"}]'::jsonb, 'b', 'The short arm is called p and the long arm q.', 'In a submetacentric chromosome the centromere lies slightly away from the middle, giving one short and one long arm. By convention the short arm is designated p (petite) and the long arm q.', '{"a": "s and l are not the standard designations.", "c": "Reverses the convention.", "d": "m and n are not used for chromosome arms."}'::jsonb, 'Metacentric: centromere in middle; acrocentric: near the end; telocentric: terminal centromere.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('6434d261-0a73-5373-9c2c-8074bd531b0c', 'neet_ug', 'Zoology', 'Neural Control and Coordination', 'Which part of the brain is responsible for thermoregulation ?', '[{"id": "a", "text": "Cerebrum"}, {"id": "b", "text": "Hypothalamus"}, {"id": "c", "text": "Corpus callosum"}, {"id": "d", "text": "Medulla oblongata"}]'::jsonb, 'b', 'The hypothalamus contains the centres that regulate body temperature.', 'The hypothalamus, at the base of the thalamus, has centres controlling body temperature, hunger and thirst, and it also secretes neurohormones. The cerebrum handles higher functions, the corpus callosum connects the hemispheres, and the medulla controls respiration, heart rate and gastric secretions.', '{"a": "Cerebrum is for thinking, memory, sensory and motor functions.", "c": "Corpus callosum only joins the two cerebral hemispheres.", "d": "Medulla controls respiration, cardiovascular reflexes and gastric secretion."}'::jsonb, 'Hypothalamus releases releasing and inhibiting hormones that regulate the anterior pituitary.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('3a2a8ad3-00a8-551c-a7c5-a41ff3168174', 'neet_ug', 'Botany', 'Cell: The Unit of Life', 'Which of the following pair of organelles does not contain DNA :-', '[{"id": "a", "text": "Mitochondria and Lysosomes"}, {"id": "b", "text": "Chloroplast and Vacuoles"}, {"id": "c", "text": "Lysosomes and Vacuoles"}, {"id": "d", "text": "Nuclear envelope and Mitochondria"}]'::jsonb, 'c', 'Lysosomes and vacuoles lack DNA; mitochondria and chloroplasts have their own DNA.', 'Mitochondria and chloroplasts are semi-autonomous organelles with their own circular DNA and 70S ribosomes. Lysosomes (hydrolytic-enzyme vesicles) and vacuoles (sap-filled tonoplast-bound spaces) have no DNA, so the pair in option (3) is correct.', '{"a": "Mitochondria contain DNA.", "b": "Chloroplasts contain DNA.", "d": "Mitochondria contain DNA; the nuclear envelope encloses nuclear DNA."}'::jsonb, 'Mitochondria and plastids are semi-autonomous: they have DNA, RNA and 70S ribosomes.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('36f06fba-2c5b-5e64-a8ad-93b8f8cf7dca', 'neet_ug', 'Botany', 'Principles of Inheritance and Variation', 'What is the genetic disorder in which an individual has an overall masculine development, gynaecomastia, and is sterile ?', '[{"id": "a", "text": "Turner''s syndrome"}, {"id": "b", "text": "Klinefelter''s syndrome"}, {"id": "c", "text": "Edward syndrome"}, {"id": "d", "text": "Down''s syndrome"}]'::jsonb, 'b', 'Klinefelter''s syndrome (47, XXY) gives a sterile male with gynaecomastia.', 'Klinefelter''s syndrome results from an extra X chromosome in a male (XXY). Such individuals have overall masculine development but show feminine traits like breast development (gynaecomastia) and are sterile. Turner''s syndrome is 45, X0 in females.', '{"a": "Turner''s syndrome (X0) affects females with rudimentary ovaries.", "c": "Edward syndrome is trisomy 18 with severe malformations.", "d": "Down''s syndrome is trisomy 21 with mental retardation and a furrowed tongue."}'::jsonb, 'Aneuploidy arises from failure of chromatid segregation during cell division.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('ceb138a9-32b6-590a-9b5d-56c6f8d82aba', 'neet_ug', 'Zoology', 'Reproductive Health', 'Which of the following sexually transmitted diseases is not completely curable ?', '[{"id": "a", "text": "Gonorrhoea"}, {"id": "b", "text": "Genital warts"}, {"id": "c", "text": "Genital herpes"}, {"id": "d", "text": "Chlamydiasis"}]'::jsonb, 'c', 'Genital herpes (viral) cannot be completely cured.', 'Except for hepatitis-B, genital herpes and HIV infection, the other STIs are completely curable if detected early and treated properly. Gonorrhoea and chlamydiasis are bacterial and curable with antibiotics, so genital herpes is the answer.', '{"a": "Bacterial (Neisseria) infection, curable with antibiotics.", "b": "NCERT treats genital warts as curable; only hepatitis-B, genital herpes and HIV are excepted.", "d": "Bacterial (Chlamydia) infection, curable with antibiotics."}'::jsonb, 'STIs that are not completely curable: hepatitis-B, genital herpes and HIV.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('ed0be153-eb41-5358-bdde-aedb363b557d', 'neet_ug', 'Zoology', 'Human Health and Disease', 'Which of the following immune responses is responsible for rejection of kidney graft?', '[{"id": "a", "text": "Auto-immune response"}, {"id": "b", "text": "Humoral immune response"}, {"id": "c", "text": "Inflammatory immune response"}, {"id": "d", "text": "Cell-mediated immune response"}]'::jsonb, 'd', 'Graft rejection is due to cell-mediated immunity by T-lymphocytes.', 'The body distinguishes ''self'' from ''non-self'' and T-lymphocytes mount a cell-mediated immune response against grafted tissue. That is why tissue and blood-group matching is done and transplant patients take immunosuppressants. Humoral immunity is antibody-mediated by B-cells.', '{"a": "Autoimmunity is an attack on self tissues.", "b": "Antibody (B-cell) response is not the main cause of graft rejection.", "c": "Inflammation is a non-specific innate response."}'::jsonb, 'CMI is mediated by T-lymphocytes; humoral immunity by antibodies from B-lymphocytes.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('2f0680de-b0ef-5bbd-8736-0fd9d1d80a82', 'neet_ug', 'Zoology', 'Excretory Products and their Elimination', 'Which of the following factors is responsible for the formation of concentrated urine?', '[{"id": "a", "text": "Low levels of antidiuretic hormone."}, {"id": "b", "text": "Maintaining hyperosmolarity towards inner medullary interstitium in the kidneys."}, {"id": "c", "text": "Secretion of erythropoietin by juxtaglomerular complex."}, {"id": "d", "text": "Hydrostatic pressure during glomerular filtration."}]'::jsonb, 'b', 'An increasing medullary osmotic gradient lets water leave the collecting duct, concentrating urine.', 'The counter-current mechanism of Henle''s loop and vasa recta, helped by NaCl and urea, maintains a gradient from 300 to about 1200 mOsmol/L towards the inner medulla. Water is drawn out of the collecting duct along this gradient, producing concentrated urine. Low ADH would instead cause dilute urine.', '{"a": "Low ADH reduces water reabsorption, giving dilute urine.", "c": "Erythropoietin regulates RBC production, not urine concentration.", "d": "Glomerular hydrostatic pressure drives filtration, not concentration."}'::jsonb, 'Human kidneys can make urine nearly four times as concentrated as the initial filtrate.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('c3611cad-1034-5146-8431-f36da9c8434e', 'neet_ug', 'Botany', 'Molecular Basis of Inheritance', 'Which of the following features of genetic code does allow bacteria to produce human insulin by recombinant DNA technology?', '[{"id": "a", "text": "Genetic code is not ambiguous"}, {"id": "b", "text": "Genetic code is redundant"}, {"id": "c", "text": "Genetic code is nearly universal"}, {"id": "d", "text": "Genetic code is specific"}]'::jsonb, 'c', 'Because the code is nearly universal, a human gene is read correctly by bacteria.', 'A codon specifies the same amino acid in bacteria and humans (with minor exceptions in mitochondria and some protozoa). So the human insulin gene inserted into E. coli is translated into the same polypeptide sequence. Unambiguity and degeneracy are real properties but do not explain cross-species expression.', '{"a": "Unambiguity means one codon codes one amino acid; it does not enable cross-species expression by itself.", "b": "Degeneracy (redundancy) means many codons per amino acid.", "d": "Specificity alone does not explain that bacteria read human codons the same way."}'::jsonb, 'UUU codes phenylalanine in bacteria as well as humans — evidence for universality.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('02f359ce-b402-56a0-a103-5675f8b21c6a', 'neet_ug', 'Botany', 'Cell: The Unit of Life', 'Which of the following statements is not correct?', '[{"id": "a", "text": "Lysosomes have numerous hydrolytic enzymes."}, {"id": "b", "text": "The hydrolytic enzymes of lysosomes are active under acidic pH."}, {"id": "c", "text": "Lysosomes are membrane bound structures."}, {"id": "d", "text": "Lysosomes are formed by the process of packaging in the endoplasmic reticulum."}]'::jsonb, 'd', 'Lysosomes are formed by packaging in the Golgi apparatus, not the ER.', 'Lysosomes are membrane-bound vesicles formed by the packaging process in the Golgi apparatus. They contain hydrolases (lipases, proteases, carbohydrases) that work optimally at acidic pH. Hence statement (4) is incorrect.', '{"a": "True: lysosomes are rich in hydrolytic enzymes.", "b": "True: lysosomal enzymes are optimally active at acidic pH.", "c": "True: lysosomes are bounded by a single membrane."}'::jsonb, 'The Golgi apparatus is the main site of glycoprotein and glycolipid formation.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('07670bf0-41fc-52c5-8a74-e3275ebb232c', 'neet_ug', 'Botany', 'Cell: The Unit of Life', 'The concept of "Omnis cellula-e cellula" regarding cell division was first proposed by:', '[{"id": "a", "text": "Rudolf Virchow"}, {"id": "b", "text": "Theodore Schwann"}, {"id": "c", "text": "Schleiden"}, {"id": "d", "text": "Aristotle"}]'::jsonb, 'a', 'Rudolf Virchow (1855) stated that new cells arise from pre-existing cells.', 'Schleiden and Schwann proposed the cell theory but did not explain how new cells form. In 1855 Rudolf Virchow explained that cells divide and new cells arise from pre-existing cells (Omnis cellula-e cellula), giving the cell theory its final shape.', '{"b": "Schwann co-proposed that animals and plants are made of cells.", "c": "Schleiden showed plants are made of cells.", "d": "Aristotle predates cell biology."}'::jsonb, 'Schwann proposed that the plasma membrane is a distinctive feature of animal cells.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('def390c1-45a3-5dab-8088-2197b70e7cb5', 'neet_ug', 'Zoology', 'Excretory Products and their Elimination', 'Use of an artificial kidney during hemodialysis may result in :
(a) Nitrogenous waste build-up in the body
(b) Non-elimination of excess potassium ions
(c) Reduced absorption of calcium ions from gastro-intestinal tract
(d) Reduced RBC production
Which of the following options is the most appropriate?', '[{"id": "a", "text": "(a) and (b) are correct"}, {"id": "b", "text": "(b) and (c) are correct"}, {"id": "c", "text": "(c) and (d) are correct"}, {"id": "d", "text": "(a) and (d) are correct"}]'::jsonb, 'c', 'Dialysis removes urea and K⁺ but cannot replace the kidney''s endocrine roles (vitamin D activation, erythropoietin).', 'The dialysing fluid lacks nitrogenous wastes and its ion levels are controlled, so urea and excess K⁺ are removed — (a) and (b) are false. However, an artificial kidney cannot make active vitamin D (calcitriol), needed for intestinal Ca²⁺ absorption, nor secrete erythropoietin, needed for RBC formation. So (c) and (d) can occur.', '{"a": "Dialysis does remove nitrogenous wastes and excess K⁺.", "b": "Excess K⁺ is removed by dialysis, so (b) is wrong.", "d": "Nitrogenous wastes are cleared by dialysis, so (a) is wrong."}'::jsonb, 'JG cells of the kidney release erythropoietin, which stimulates RBC formation.', 'hard', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('cc5806f9-0dc1-500a-b63b-f9e74714055e', 'neet_ug', 'Zoology', 'Locomotion and Movement', 'Which of the following muscular disorders is inherited ?', '[{"id": "a", "text": "Tetany"}, {"id": "b", "text": "Muscular dystrophy"}, {"id": "c", "text": "Myasthenia gravis"}, {"id": "d", "text": "Botulism"}]'::jsonb, 'b', 'Muscular dystrophy is a genetic disorder causing progressive muscle degeneration.', 'Muscular dystrophy is the progressive degeneration of skeletal muscle, mostly due to a genetic disorder. Tetany arises from low Ca²⁺ in body fluid, myasthenia gravis is an autoimmune disorder of the neuromuscular junction, and botulism is a toxin-caused food poisoning.', '{"a": "Tetany is due to low blood Ca²⁺, not inheritance.", "c": "Myasthenia gravis is autoimmune.", "d": "Botulism is caused by Clostridium botulinum toxin."}'::jsonb, 'Myasthenia gravis causes fatigue, weakening and paralysis of skeletal muscle.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('81e6d7cc-a426-5a1e-8d64-94e57e35d95f', 'neet_ug', 'Zoology', 'Animal Kingdom', 'Consider following features:
(a) Organ system level of organisation
(b) Bilateral symmetry
(c) True coelomates with segmentation of body
Select the correct option of animal groups which possess all the above characteristics.', '[{"id": "a", "text": "Annelida, Arthropoda and Chordata"}, {"id": "b", "text": "Annelida, Arthropoda and Mollusca"}, {"id": "c", "text": "Arthropoda, Mollusca and Chordata"}, {"id": "d", "text": "Annelida, Mollusca and Chordata"}]'::jsonb, 'a', 'Annelids, arthropods and chordates are bilateral, segmented, coelomate animals with organ systems.', 'All three features are shared by Annelida (metameric segmentation), Arthropoda (segmented body) and Chordata (segmentation seen in somites/vertebrae). Molluscs are coelomate and bilateral but unsegmented, which rules out every option containing Mollusca.', '{"b": "Mollusca are unsegmented.", "c": "Mollusca are unsegmented.", "d": "Mollusca are unsegmented."}'::jsonb, 'Metameric segmentation is characteristic of Annelida, e.g., Nereis, Pheretima, Hirudinaria.', 'med', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('ce1bf3c3-48e0-5328-90ce-e19141096b91', 'neet_ug', 'Botany', 'Principles of Inheritance and Variation', 'The frequency of recombination between gene pairs on the same chromosome as a measure of the distance between genes was explained by :', '[{"id": "a", "text": "T.H. Morgan"}, {"id": "b", "text": "Gregor J. Mendel"}, {"id": "c", "text": "Alfred Sturtevant"}, {"id": "d", "text": "Sutton Boveri"}]'::jsonb, 'c', 'Sturtevant used recombination frequency to map gene distances.', 'Morgan''s student Alfred Sturtevant used the frequency of recombination between gene pairs on the same chromosome as a measure of distance between them and constructed the first genetic maps. Morgan discovered linkage and coined ''recombination'', while Sutton and Boveri proposed the chromosomal theory.', '{"a": "Morgan described linkage and recombination in Drosophila.", "b": "Mendel gave the laws of inheritance.", "d": "Sutton and Boveri gave the chromosomal theory of inheritance."}'::jsonb, 'Genetic maps are used as a starting point in sequencing whole genomes.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('6423d00d-69cc-5f52-8200-9860117c441e', 'neet_ug', 'Zoology', 'Biotechnology: Principles and Processes', 'Following statements describe the characteristics of the enzyme Restriction endonuclease. Identify the incorrect statement.', '[{"id": "a", "text": "The enzyme cuts DNA molecule at identified position within the DNA"}, {"id": "b", "text": "The enzyme binds DNA at specific sites and cuts only one of the two strands."}, {"id": "c", "text": "The enzyme cuts the sugar-phosphate backbone at specific sites on each strand."}, {"id": "d", "text": "The enzyme recognizes a specific palindromic nucleotide sequence in the DNA"}]'::jsonb, 'b', 'Restriction endonucleases cut both strands of DNA, not just one.', 'A restriction endonuclease scans DNA, binds its specific palindromic recognition sequence and cuts each of the two strands at specific points in the sugar-phosphate backbone. Cutting both strands (often a little away from the centre) produces sticky ends. Hence the claim that it cuts only one strand is wrong.', '{"a": "True: endonucleases cut at specific positions within DNA.", "c": "True: both strands'' phosphodiester backbones are cut at specific sites.", "d": "True: recognition sequences are palindromic."}'::jsonb, 'EcoRI recognises 5''-GAATTC-3'' and cuts between G and A on both strands.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('c7eb6891-c9ff-5bb6-949e-ce30f3cb3bb9', 'neet_ug', 'Botany', 'Biological Classification', 'Which of the following statements is incorrect?', '[{"id": "a", "text": "Morels and truffles are edible delicacies."}, {"id": "b", "text": "Claviceps is a source of many alkaloids and LSD."}, {"id": "c", "text": "Conidia are produced exogenously and ascospores endogenously."}, {"id": "d", "text": "Yeasts have filamentous bodies with long thread-like hyphae."}]'::jsonb, 'd', 'Yeasts are unicellular fungi, not filamentous.', 'Yeasts are unicellular members of the fungi, while most other fungi have filamentous hyphae. Among Ascomycetes, morels and truffles are edible, Claviceps yields alkaloids and LSD, and conidia form exogenously on conidiophores while ascospores form endogenously in asci.', '{"a": "True: morels and truffles are edible ascomycetes.", "b": "True: Claviceps (ergot) yields alkaloids and LSD.", "c": "True: conidia are exogenous, ascospores are endogenous."}'::jsonb, 'Ascospores are produced endogenously in sac-like asci arranged in ascocarps.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('37ce1efe-ce76-5a05-98e4-4e18174fa81b', 'neet_ug', 'Botany', 'Morphology of Flowering Plants', 'Placentation, in which ovules develop on the inner wall of the ovary or in peripheral part, is :', '[{"id": "a", "text": "Basal"}, {"id": "b", "text": "Axile"}, {"id": "c", "text": "Parietal"}, {"id": "d", "text": "Free central"}]'::jsonb, 'c', 'In parietal placentation ovules develop on the inner wall or periphery of the ovary.', 'In parietal placentation the ovules arise on the inner wall of the ovary or its peripheral part, and the ovary is one-chambered though it may become two-chambered by a false septum (e.g., mustard, Argemone). Axile has ovules on a central axis in a multilocular ovary, free central on a central axis without septa, and basal at the base with one ovule.', '{"a": "Basal: placenta at the ovary base with a single ovule (sunflower).", "b": "Axile: ovules on central axis of a multilocular ovary (china rose, tomato).", "d": "Free central: ovules on a central axis without septa (Dianthus, Primrose)."}'::jsonb, 'Mustard and Argemone show parietal placentation; the false septum is called replum.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('6c639c83-ea55-599c-8c2d-e7b4606dfdc7', 'neet_ug', 'Botany', 'Biodiversity and Conservation', 'Which of the following is the most important causes for animals and plants being driven to extinction?', '[{"id": "a", "text": "Habitat loss and fragmentation"}, {"id": "b", "text": "Drought and floods"}, {"id": "c", "text": "Economic exploitation"}, {"id": "d", "text": "Alien species invasion"}]'::jsonb, 'a', 'Habitat loss and fragmentation is the most important cause of extinction.', 'Among the ''evil quartet'' (habitat loss and fragmentation, over-exploitation, alien species invasions and co-extinctions), habitat loss and fragmentation is the most important cause. Destruction of tropical rain forests, for example, has driven many species to extinction.', '{"b": "Natural calamities are not listed as the main cause.", "c": "Over-exploitation is important but secondary to habitat loss.", "d": "Alien invasions are significant but not the most important cause."}'::jsonb, 'The Amazon rain forest, called the ''lungs of the planet'', is being cut for soybean cultivation and grasslands.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('c6524f88-a7db-5bfb-90e8-ed837374c627', 'neet_ug', 'Zoology', 'Evolution', 'Variations caused by mutation, as proposed by Hugo de Vries, are', '[{"id": "a", "text": "random and directional"}, {"id": "b", "text": "random and directionless"}, {"id": "c", "text": "small and directional"}, {"id": "d", "text": "small and directionless"}]'::jsonb, 'b', 'De Vries'' mutations are sudden, large, random and directionless.', 'Working on evening primrose, Hugo de Vries proposed that evolution is caused by mutations, which are random and directionless and appear suddenly (saltation). Darwin''s variations, in contrast, were small and directional.', '{"a": "Mutations are not directional.", "c": "Small and directional describes Darwinian variations.", "d": "Mutations are large (saltation), not small."}'::jsonb, 'De Vries called the single-step large mutation ''saltation''.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('10be3ef2-2593-54d4-b790-e6c5474aa89a', 'neet_ug', 'Botany', 'Respiration in Plants', 'Respiratory Quotient (RQ) value of tripalmitin is :', '[{"id": "a", "text": "0.9"}, {"id": "b", "text": "0.7"}, {"id": "c", "text": "0.07"}, {"id": "d", "text": "0.09"}]'::jsonb, 'b', 'RQ of tripalmitin = 102 CO₂ / 145 O₂ ≈ 0.7.', 'Tripalmitin oxidation: 2(C₅₁H₉₈O₆) + 145 O₂ → 102 CO₂ + 98 H₂O + energy. RQ = volume of CO₂ evolved / volume of O₂ consumed = 102/145 ≈ 0.7. Fats need more oxygen per carbon, so their RQ is below 1.', '{"a": "0.9 is roughly that of proteins.", "c": "Off by a factor of ten.", "d": "Off by a factor of ten and below any normal substrate."}'::jsonb, 'RQ of carbohydrates = 1, fats < 1 (about 0.7), proteins ≈ 0.9.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('c1846c84-51dd-51fa-9d6b-03c6fe4807ea', 'neet_ug', 'Botany', 'Principles of Inheritance and Variation', 'In Antirrhinum (Snapdragon), a red flower was crossed with a white flower and in F₁ generation, pink flowers were obtained. When pink flowers were selfed, the F₂ generation showed white, red and pink flowers. Choose the incorrect statement from the following :', '[{"id": "a", "text": "This experiment does not follow the Principle of Dominance"}, {"id": "b", "text": "Pink colour in F₁ is due to incomplete dominance."}, {"id": "c", "text": "Ratio of F₂ is 1/4 (Red) : 2/4 (Pink) : 1/4 (White)"}, {"id": "d", "text": "Law of Segregation does not apply in this experiment."}]'::jsonb, 'd', 'Incomplete dominance still obeys the law of segregation.', 'The pink F₁ (Rr) shows incomplete dominance, so the principle of dominance is not followed. Yet the alleles R and r still separate during gamete formation, giving F₂ genotypes 1 RR (red) : 2 Rr (pink) : 1 rr (white). Thus segregation clearly applies and statement (4) is incorrect.', '{"a": "True: neither allele is completely dominant.", "b": "True: pink is an intermediate phenotype from incomplete dominance.", "c": "True: phenotypic and genotypic F₂ ratio is 1:2:1."}'::jsonb, 'The law of segregation is universal; dominance is not.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('bb00d0fa-9bcf-5061-9a78-d357f475efc5', 'neet_ug', 'Botany', 'Principles of Inheritance and Variation', 'Select the incorrect statement.', '[{"id": "a", "text": "Male fruit fly is heterogametic."}, {"id": "b", "text": "In male grasshoppers, 50% of sperms have no sex-chromosome."}, {"id": "c", "text": "In domesticated fowls sex of progeny depends on the type of sperm rather than egg."}, {"id": "d", "text": "Human males have one of their sex-chromosome much shorter than the other."}]'::jsonb, 'c', 'In birds the female (ZW) is heterogametic, so the egg decides the sex of progeny.', 'Birds follow ZW–ZZ sex determination: females produce Z- or W-bearing eggs while males (ZZ) produce identical sperms, so the egg determines the sex. Drosophila males are XY (heterogametic), grasshopper males are XO so half the sperms lack an X, and the human Y is much shorter than X.', '{"a": "True: Drosophila males are XY.", "b": "True: XO males produce 50% sperms without a sex chromosome.", "d": "True: the Y chromosome is much smaller than the X."}'::jsonb, 'XO type: grasshopper; XY type: humans, Drosophila; ZW type: birds.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('3f84f353-cb37-5fbc-8b8f-0ac163a1a74a', 'neet_ug', 'Botany', 'Cell Cycle and Cell Division', 'The correct sequence of phases of cell cycle is :', '[{"id": "a", "text": "M → G₁ → G₂ → S"}, {"id": "b", "text": "G₁ → G₂ → S → M"}, {"id": "c", "text": "S → G₁ → G₂ → M"}, {"id": "d", "text": "G₁ → S → G₂ → M"}]'::jsonb, 'd', 'Cell cycle order: G₁ → S → G₂ → M.', 'Interphase comprises G₁ (growth before DNA synthesis), S (DNA replication) and G₂ (preparation for division), after which the M phase (karyokinesis and cytokinesis) follows. So the correct sequence is G₁ → S → G₂ → M.', '{"a": "S must precede G₂.", "b": "S phase comes between G₁ and G₂.", "c": "G₁ comes before S."}'::jsonb, 'In S phase DNA doubles (2C → 4C) but chromosome number stays the same.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('0cbb9e16-af8f-5b5e-a72f-617eddc914b7', 'neet_ug', 'Botany', 'Plant Kingdom', 'From evolutionary point of view, retention of the female gametophyte with developing young embryo on the parent sporophyte for some time, is first observed in :', '[{"id": "a", "text": "Liverworts"}, {"id": "b", "text": "Mosses"}, {"id": "c", "text": "Pteridophytes"}, {"id": "d", "text": "Gymnosperms"}]'::jsonb, 'c', 'Heterosporous pteridophytes first retain the female gametophyte and young embryo on the parent sporophyte.', 'In heterosporous pteridophytes such as Selaginella and Salvinia, the megaspore develops into a female gametophyte that is retained on the parent sporophyte for variable periods, and the zygote develops into a young embryo within it. This event is a precursor to the seed habit, which is completed in gymnosperms.', '{"a": "In liverworts the gametophyte is the dominant independent phase.", "b": "Mosses have a dominant free-living gametophyte.", "d": "Gymnosperms show the full seed habit, which appeared later; retention first appears in pteridophytes."}'::jsonb, 'Heterospory in Selaginella and Salvinia is considered a precursor to the seed habit.', 'med', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('71b51411-c3f4-5e67-b3e9-1e76024572ac', 'neet_ug', 'Zoology', 'Locomotion and Movement', 'Select the correct option.', '[{"id": "a", "text": "8th, 9th and 10th pairs of ribs articulate directly with the sternum."}, {"id": "b", "text": "11th and 12th pairs of ribs are connected to the sternum with the help of hyaline cartilage."}, {"id": "c", "text": "Each rib is a flat thin bone and all the ribs are connected dorsally to the thoracic vertebrae and ventrally to the sternum."}, {"id": "d", "text": "There are seven pairs of vertebrosternal, three pairs of vertebrochondral and two pairs of vertebral ribs."}]'::jsonb, 'd', 'Ribs: 7 true (vertebrosternal), 3 false (vertebrochondral), 2 floating (vertebral) pairs.', 'Humans have 12 pairs of ribs. The first seven pairs attach directly to the sternum (true ribs); the 8th, 9th and 10th join the 7th rib''s hyaline cartilage instead of the sternum (vertebrochondral); the 11th and 12th are free ventrally (floating ribs). All ribs articulate dorsally with thoracic vertebrae, but not all reach the sternum.', '{"a": "8th–10th pairs attach indirectly via the 7th rib''s cartilage.", "b": "11th and 12th pairs are floating, not joined to the sternum.", "c": "Floating and false ribs do not attach ventrally to the sternum."}'::jsonb, 'Thoracic vertebrae, ribs and sternum together form the rib cage.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('53bbe47b-1967-5e4a-808a-12fff27d4ce3', 'neet_ug', 'Botany', 'Biomolecules', 'Concanavalin A is :', '[{"id": "a", "text": "an alkaloid"}, {"id": "b", "text": "an essential oil"}, {"id": "c", "text": "a lectin"}, {"id": "d", "text": "a pigment"}]'::jsonb, 'c', 'Concanavalin A is a lectin, a plant secondary metabolite.', 'NCERT''s list of secondary metabolites places Concanavalin A under lectins, which are carbohydrate-binding proteins (from jack bean). Morphine and codeine are alkaloids, lemon grass oil is an essential oil, and carotenoids and anthocyanins are pigments.', '{"a": "Alkaloids include morphine and codeine.", "b": "Essential oils include lemon grass oil.", "d": "Pigments include carotenoids and anthocyanins."}'::jsonb, 'Secondary metabolites: abrin and ricin are toxins; vinblastine and curcumin are drugs.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('4a3290aa-56f4-5bbe-8880-167c9135ee5a', 'neet_ug', 'Zoology', 'Human Reproduction', 'Extrusion of second polar body from egg nucleus occurs :', '[{"id": "a", "text": "after entry of sperm but before fertilization"}, {"id": "b", "text": "after fertilization"}, {"id": "c", "text": "before entry of sperm into ovum"}, {"id": "d", "text": "simultaneously with first cleavage"}]'::jsonb, 'a', 'Sperm entry triggers completion of meiosis II and release of the second polar body before nuclear fusion.', 'The secondary oocyte is arrested in meiosis II; entry of the sperm induces it to complete the division, releasing the second polar body and forming the haploid ovum (ootid). Only then do the haploid sperm and ovum nuclei fuse to complete fertilisation and form the zygote.', '{"b": "Polar body is extruded before nuclear fusion (fertilisation).", "c": "Meiosis II completes only after sperm entry.", "d": "Cleavage begins after the zygote has formed."}'::jsonb, 'Ovulation releases a secondary oocyte; meiosis II completes only on sperm entry.', 'med', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('323793e4-71c8-5438-a4bb-c38eda447f93', 'neet_ug', 'Botany', 'Plant Kingdom', 'Pinus seed cannot germinate and establish without fungal association. This is because :', '[{"id": "a", "text": "its embryo is immature"}, {"id": "b", "text": "it has obligate association with mycorrhizae."}, {"id": "c", "text": "it has very hard seed coat."}, {"id": "d", "text": "its seeds contain inhibitors that prevent germination."}]'::jsonb, 'b', 'Pinus has an obligate mycorrhizal association, without which seedlings cannot establish.', 'Roots of Pinus are associated with mycorrhizal fungi that help absorb water and minerals (especially phosphorus). This association is obligate for Pinus, so seeds fail to establish where the fungus is absent. Immaturity, hard coat or inhibitors are not the reason.', '{"a": "Pinus seeds have a well-developed embryo.", "c": "Seed coat hardness is not the cause of fungal dependence.", "d": "Germination inhibitors are unrelated to fungal association."}'::jsonb, 'Gymnosperm roots: Pinus has mycorrhiza; Cycas has coralloid roots with N₂-fixing cyanobacteria.', 'med', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('2974b616-23d5-5fb9-886d-c39ea0c3608a', 'neet_ug', 'Botany', 'Biodiversity and Conservation', 'The Earth Summit held in Rio de Janeiro in 1992 was called :', '[{"id": "a", "text": "to reduce CO₂ emissions and global warming."}, {"id": "b", "text": "for conservation of biodiversity and sustainable utilization of its benefits."}, {"id": "c", "text": "to assess threat posed to native species by invasive weed species."}, {"id": "d", "text": "for immediate steps to discontinue use of CFCs that were damaging the ozone layer."}]'::jsonb, 'b', 'The 1992 Rio Earth Summit called on nations to conserve biodiversity and use its benefits sustainably.', 'The Convention on Biological Diversity at the Earth Summit (Rio de Janeiro, 1992) called upon all nations to take measures for conservation of biodiversity and sustainable utilisation of its benefits. The follow-up World Summit on Sustainable Development (Johannesburg, 2002) pledged to reduce the rate of biodiversity loss by 2010.', '{"a": "CO₂ reduction is the aim of the Kyoto Protocol.", "c": "Invasive species were not the purpose of the summit.", "d": "CFC phase-out was the aim of the Montreal Protocol."}'::jsonb, 'World Summit on Sustainable Development, Johannesburg 2002: 190 countries pledged to reduce biodiversity loss by 2010.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('b8c7f3e6-eaed-5047-8e14-503f9a94eeb3', 'neet_ug', 'Zoology', 'Biotechnology: Principles and Processes', 'DNA precipitation out of a mixture of biomolecules can be achieved by treatment with :', '[{"id": "a", "text": "Isopropanol"}, {"id": "b", "text": "Chilled ethanol"}, {"id": "c", "text": "Methanol at room temperature"}, {"id": "d", "text": "Chilled chloroform"}]'::jsonb, 'b', 'Purified DNA comes out of solution as fine threads when chilled ethanol is added.', 'After cell lysis and enzymatic removal of RNA and proteins, DNA is precipitated by adding chilled ethanol, which lowers its solubility. The precipitated DNA appears as a collection of fine threads in suspension that can be spooled out. NCERT specifically names chilled ethanol for this step.', '{"a": "Isopropanol is used in some lab protocols but is not the NCERT-stated reagent.", "c": "Room-temperature methanol is not used to precipitate DNA.", "d": "Chloroform is used to remove proteins during phenol–chloroform extraction, not to precipitate DNA."}'::jsonb, 'Isolation of DNA: lysozyme/cellulase/chitinase lyse cells, RNase and protease remove contaminants, chilled ethanol precipitates DNA.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('d3102563-661e-53cf-82cc-6a3d4fc7d565', 'neet_ug', 'Botany', 'Anatomy of Flowering Plants', 'Grass leaves curl inwards during very dry weather. Select the most appropriate reason from the following :', '[{"id": "a", "text": "Closure of stomata"}, {"id": "b", "text": "Flaccidity of bulliform cells"}, {"id": "c", "text": "Shrinkage of air spaces in spongy mesophyll"}, {"id": "d", "text": "Tyloses in vessels"}]'::jsonb, 'b', 'Bulliform cells lose water and become flaccid, so grass leaves roll inward.', 'In the adaxial epidermis of grass leaves, large empty colourless bulliform cells lie along the veins. When turgid they keep the leaf blade spread open; under water stress they lose turgor and become flaccid, so the lamina curls inward, cutting down transpiration.', '{"a": "Stomatal closure reduces water loss but does not fold the leaf.", "c": "Grass (monocot) leaves have no distinct spongy mesophyll.", "d": "Tyloses block old xylem vessels in heartwood and have nothing to do with leaf rolling."}'::jsonb, 'Bulliform (motor) cells occur in the upper epidermis of grass leaves and cause leaf rolling in drought.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('670ff724-755f-5acd-ad90-a37d09aa43a2', 'neet_ug', 'Zoology', 'Chemical Coordination and Integration', 'Match the following hormones with the respective disease :
(a) Insulin | (i) Addison''s disease
(b) Thyroxin | (ii) Diabetes insipidus
(c) Corticoids | (iii) Acromegaly
(d) Growth Hormone | (iv) Goitre
 | (v) Diabetes mellitus
Select the correct option.', '[{"id": "a", "text": "(a)-(v), (b)-(i), (c)-(ii), (d)-(iii)"}, {"id": "b", "text": "(a)-(ii), (b)-(iv), (c)-(iii), (d)-(i)"}, {"id": "c", "text": "(a)-(v), (b)-(iv), (c)-(i), (d)-(iii)"}, {"id": "d", "text": "(a)-(ii), (b)-(iv), (c)-(i), (d)-(iii)"}]'::jsonb, 'c', 'Insulin–diabetes mellitus, thyroxin–goitre, corticoids–Addison''s, GH–acromegaly.', 'Lack of insulin causes diabetes mellitus. Thyroid hormone disorders (from iodine deficiency) cause goitre. Underproduction of adrenal corticoids causes Addison''s disease, and excess growth hormone in adults causes acromegaly. That gives (a)-(v), (b)-(iv), (c)-(i), (d)-(iii).', '{"a": "Thyroxin is not linked to Addison''s disease, and corticoids are not linked to diabetes insipidus.", "b": "Diabetes insipidus is caused by ADH deficiency, not insulin deficiency.", "d": "Insulin deficiency causes diabetes mellitus, not diabetes insipidus (an ADH disorder)."}'::jsonb, 'Diabetes insipidus comes from ADH (vasopressin) deficiency; diabetes mellitus from insulin deficiency.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('50289fee-9d01-58ca-ab15-30ec1bd6cd27', 'neet_ug', 'Zoology', 'Reproductive Health', 'Which of the following contraceptive methods do involve a role of hormone ?', '[{"id": "a", "text": "Lactational amenorrhea, Pills, Emergency contraceptives"}, {"id": "b", "text": "Barrier method, Lactational amenorrhea, Pills"}, {"id": "c", "text": "CuT, Pills, Emergency contraceptives"}, {"id": "d", "text": "Pills, Emergency contraceptives, Barrier methods"}]'::jsonb, 'a', 'LAM (prolactin-mediated anovulation), pills and emergency contraceptives all depend on hormones.', 'Pills and emergency contraceptives contain progestogens or progestogen–estrogen combinations. Lactational amenorrhea works because the high prolactin of intense breastfeeding suppresses ovulation, so it also has a hormonal basis. Barrier methods and copper-releasing IUDs (CuT) act without any hormone.', '{"b": "Barrier methods only stop sperm from physically meeting the ovum.", "c": "CuT works through Cu ions that reduce sperm motility, not hormones.", "d": "Barrier methods are non-hormonal."}'::jsonb, 'Hormone-releasing IUDs are Progestasert and LNG-20; CuT, Cu7 and Multiload 375 are copper-releasing IUDs.', 'med', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('9ca99e49-20d5-5166-80b8-aa3a4c74444a', 'neet_ug', 'Zoology', 'Human Health and Disease', 'Drug called ''Heroin'' is synthesized by :', '[{"id": "a", "text": "methylation of morphine"}, {"id": "b", "text": "acetylation of morphine"}, {"id": "c", "text": "glycosylation of morphine"}, {"id": "d", "text": "nitration of morphine"}]'::jsonb, 'b', 'Heroin (smack) is diacetylmorphine, made by acetylating morphine.', 'Morphine is extracted from the latex of the poppy Papaver somniferum. Acetylating its two –OH groups gives diacetylmorphine, i.e. heroin, a white odourless bitter crystalline compound that acts as a depressant.', '{"a": "Methylation of morphine gives codeine (methylmorphine), not heroin.", "c": "Glycosylation is not the route to heroin.", "d": "Nitration is not involved in making heroin."}'::jsonb, 'Heroin is chemically diacetylmorphine; opioids bind specific opioid receptors in the CNS and GI tract.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('147db888-7121-59f4-b9c1-d5d9b2b3725f', 'neet_ug', 'Zoology', 'Evolution', 'In a species, the weight of newborn ranges from 2 to 5 kg. 97% of the newborn with an average weight between 3 to 3.3 kg survive whereas 99% of the infants born with weights from 2 to 2.5 kg or 4.5 to 5 kg die. Which type of selection process is taking place ?', '[{"id": "a", "text": "Directional Selection"}, {"id": "b", "text": "Stabilizing Selection"}, {"id": "c", "text": "Disruptive Selection"}, {"id": "d", "text": "Cyclical Selection"}]'::jsonb, 'b', 'Intermediate-weight newborns are favoured and both extremes are eliminated, which is stabilising selection.', 'Survival is highest at the mean value (3–3.3 kg), and both tails of the distribution (very light and very heavy babies) are selected against. This narrows the variation around the mean, which is stabilising selection.', '{"a": "Directional selection favours one extreme and shifts the mean.", "c": "Disruptive selection favours both extremes over the mean.", "d": "''Cyclical selection'' is not one of the three NCERT types of natural selection."}'::jsonb, 'The three modes of natural selection are stabilising (mean favoured), directional (one extreme favoured) and disruptive (both extremes favoured).', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('d3c4e0ac-7a68-576f-aba7-cab342fd6e7c', 'neet_ug', 'Botany', 'Respiration in Plants', 'Conversion of glucose to glucose-6-phosphate, the first irreversible reaction of glycolysis, is catalyzed by :', '[{"id": "a", "text": "Aldolase"}, {"id": "b", "text": "Hexokinase"}, {"id": "c", "text": "Enolase"}, {"id": "d", "text": "Phosphofructokinase"}]'::jsonb, 'b', 'Hexokinase phosphorylates glucose to glucose-6-phosphate using ATP.', 'In the first step of glycolysis, glucose is phosphorylated at C-6 by ATP. The enzyme that catalyses this is hexokinase, and the reaction is effectively irreversible in the cell.', '{"a": "Aldolase splits fructose-1,6-bisphosphate into DHAP and PGAL.", "c": "Enolase converts 2-phosphoglycerate to PEP.", "d": "PFK phosphorylates fructose-6-phosphate to fructose-1,6-bisphosphate, the second ATP-using step."}'::jsonb, 'Glycolysis uses 2 ATP (hexokinase and PFK steps) and yields 4 ATP plus 2 NADH per glucose.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('a114a213-e83c-54c1-b646-38204bc9c19e', 'neet_ug', 'Botany', 'Ecosystem', 'Which of the following ecological pyramids is generally inverted ?', '[{"id": "a", "text": "Pyramid of numbers in grassland"}, {"id": "b", "text": "Pyramid of energy"}, {"id": "c", "text": "Pyramid of biomass in a forest"}, {"id": "d", "text": "Pyramid of biomass in a sea"}]'::jsonb, 'd', 'In the sea, the small standing biomass of phytoplankton supports a larger fish biomass, so the pyramid of biomass is inverted.', 'Phytoplankton have a very small standing crop but turn over rapidly, whereas the fish that feed on them build up a large standing biomass. So the pyramid of biomass in a sea is generally inverted. Energy pyramids can never be inverted.', '{"a": "The grassland pyramid of numbers is upright.", "b": "The pyramid of energy is always upright because energy is lost at each transfer.", "c": "Forest biomass is dominated by trees, so the pyramid is upright."}'::jsonb, 'The pyramid of numbers in a tree ecosystem can be inverted, but the pyramid of energy is always upright.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('2a2af72d-d444-5386-8ae3-94bdce5ae73c', 'neet_ug', 'Zoology', 'Breathing and Exchange of Gases', 'Due to increasing air-borne allergens and pollutants, many people in urban areas are suffering from respiratory disorder causing wheezing due to :', '[{"id": "a", "text": "benign growth on mucous lining of nasal cavity."}, {"id": "b", "text": "inflammation of bronchi and bronchioles."}, {"id": "c", "text": "proliferation of fibrous tissues and damage of the alveolar walls."}, {"id": "d", "text": "reduction in the secretion of surfactants by pneumocytes."}]'::jsonb, 'b', 'Asthma causes wheezing through inflammation of the bronchi and bronchioles.', 'Asthma is an allergic reaction in which the bronchi and bronchioles become inflamed and constricted, so breathing is difficult and wheezing results. Allergens and urban pollutants are typical triggers.', '{"a": "A nasal polyp is a benign growth that blocks the nose; it is not the cause of wheezing in asthma.", "c": "Alveolar wall damage describes emphysema (and fibrosis describes occupational lung disease).", "d": "Reduced surfactant causes respiratory distress, mainly in premature newborns."}'::jsonb, 'Emphysema is a chronic disorder in which alveolar walls are damaged, reducing the respiratory surface; cigarette smoking is a major cause.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('7a622dbe-187e-5b91-82d2-a1e33aba893d', 'neet_ug', 'Botany', 'Sexual Reproduction in Flowering Plants', 'Which one of the following statements regarding post-fertilization development in flowering plants is incorrect ?', '[{"id": "a", "text": "Ovary develops into fruit"}, {"id": "b", "text": "Zygote develops into embryo"}, {"id": "c", "text": "Central cell develops into endosperm"}, {"id": "d", "text": "Ovules develop into embryo sac"}]'::jsonb, 'd', 'After fertilisation the ovules become seeds, not embryo sacs.', 'After double fertilisation, the zygote forms the embryo, the primary endosperm cell (from the central cell) forms the endosperm, the ovules mature into seeds and the ovary becomes the fruit. The embryo sac forms inside the ovule before fertilisation, so (4) is the incorrect statement.', '{"a": "Correct: the ovary wall becomes the pericarp of the fruit.", "b": "Correct: the zygote divides to form the embryo.", "c": "Correct: the triploid PEN of the central cell forms the endosperm."}'::jsonb, 'Integuments become the seed coats, the micropyle remains as a pore, and the ovary wall becomes the pericarp.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('c3b013e4-3b4a-5eac-b4ee-92d80b704b9b', 'neet_ug', 'Botany', 'Anatomy of Flowering Plants', 'Phloem in gymnosperms lacks :', '[{"id": "a", "text": "Albuminous cells and sieve cells"}, {"id": "b", "text": "Sieve tubes only"}, {"id": "c", "text": "Companion cells only"}, {"id": "d", "text": "Both sieve tubes and companion cells"}]'::jsonb, 'd', 'Gymnosperm phloem has albuminous cells and sieve cells instead of sieve tubes and companion cells.', 'Angiosperm phloem has sieve tube elements, companion cells, phloem parenchyma and fibres. Gymnosperms have neither sieve tubes nor companion cells; sieve cells and albuminous cells do those jobs instead.', '{"a": "These are exactly what gymnosperm phloem does have.", "b": "Companion cells are also absent, so ''only'' is wrong.", "c": "Sieve tubes are also absent, so ''only'' is wrong."}'::jsonb, 'Gymnosperms also lack vessels in their xylem; vessels are characteristic of angiosperms.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('80eacc32-3d63-57c7-a498-5dc324b2f025', 'neet_ug', 'Botany', 'Plant Growth and Development', 'It takes very long time for pineapple plants to produce flowers. Which combination of hormones can be applied to artificially induce flowering in pineapple plants throughout the year to increase yield?', '[{"id": "a", "text": "Auxin and Ethylene"}, {"id": "b", "text": "Gibberellin and Cytokinin"}, {"id": "c", "text": "Gibberellin and Abscisic acid"}, {"id": "d", "text": "Cytokinin and Abscisic acid"}]'::jsonb, 'a', 'Both auxin and ethylene induce synchronised flowering in pineapple.', 'NCERT states that auxins induce flowering in pineapples, and that ethylene (supplied as ethephon) initiates flowering and synchronises fruit set in pineapples. Applying these two lets growers get flowering all year.', '{"b": "Gibberellins and cytokinins are not used to induce flowering in pineapple.", "c": "ABA is a growth inhibitor and promotes dormancy.", "d": "ABA inhibits growth, and cytokinin does not induce pineapple flowering."}'::jsonb, 'Ethephon is the most widely used source of ethylene; it hastens fruit ripening and induces flowering in mango and pineapple.', 'med', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('e287d625-3d67-5676-80bb-8b8eb93c0c01', 'neet_ug', 'Botany', 'Sexual Reproduction in Flowering Plants', 'Persistent nucellus in the seed is known as :', '[{"id": "a", "text": "Chalaza"}, {"id": "b", "text": "Perisperm"}, {"id": "c", "text": "Hilum"}, {"id": "d", "text": "Tegmen"}]'::jsonb, 'b', 'Nucellus that remains in a mature seed is called perisperm.', 'In most seeds the nucellus is used up during development. In a few seeds, such as black pepper and beet, it persists as a residual tissue called the perisperm.', '{"a": "The chalaza is the basal end of the ovule, opposite the micropyle.", "c": "The hilum is the scar where the seed was attached to the funicle.", "d": "The tegmen is the inner seed coat formed from the inner integument."}'::jsonb, 'Perisperm is found in black pepper and beet; endosperm is absent in exalbuminous seeds such as pea and groundnut.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('ba84a76b-d092-55d8-81c7-7203d1ab6495', 'neet_ug', 'Botany', 'Cell Cycle and Cell Division', 'Cells in G₀ phase:', '[{"id": "a", "text": "exit the cell cycle"}, {"id": "b", "text": "enter the cell cycle"}, {"id": "c", "text": "suspend the cell cycle"}, {"id": "d", "text": "terminate the cell cycle"}]'::jsonb, 'a', 'G₀ (quiescent stage) cells have left the cell cycle but stay metabolically active.', 'Some cells, such as many adult heart cells, do not divide further. They exit G₁ into an inactive stage called the quiescent stage (G₀), where they remain metabolically active but stop proliferating unless called on to divide.', '{"b": "Cells in G₀ have left the cycle, not entered it.", "c": "NCERT describes G₀ as exiting the cycle, not as a suspended phase of it.", "d": "The cell does not die or end permanently; it can re-enter the cycle when needed."}'::jsonb, 'Interphase = G₁ + S + G₂; DNA content doubles in S phase while chromosome number stays the same.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('581b7857-cd0f-576f-ba11-3c2e657837e5', 'neet_ug', 'Botany', 'Biological Classification', 'Match Column - I with Column - II.
Column - I | Column - II
(a) Saprophyte | (i) Symbiotic association of fungi with plant roots
(b) Parasite | (ii) Decomposition of dead organic materials
(c) Lichens | (iii) Living on living plants or animals
(d) Mycorrhiza | (iv) Symbiotic association of algae and fungi
Choose the correct answer from the options given below :', '[{"id": "a", "text": "(a)-(i), (b)-(ii), (c)-(iii), (d)-(iv)"}, {"id": "b", "text": "(a)-(iii), (b)-(ii), (c)-(i), (d)-(iv)"}, {"id": "c", "text": "(a)-(ii), (b)-(i), (c)-(iii), (d)-(iv)"}, {"id": "d", "text": "(a)-(ii), (b)-(iii), (c)-(iv), (d)-(i)"}]'::jsonb, 'd', 'Saprophyte–decomposition, parasite–living on hosts, lichen–alga+fungus, mycorrhiza–fungus+root.', 'Saprophytes absorb nutrients by decomposing dead organic matter. Parasites live on living plants or animals. Lichens are symbiotic associations of algae and fungi, and mycorrhizae are symbiotic associations of fungi with roots of higher plants. That gives (a)-(ii), (b)-(iii), (c)-(iv), (d)-(i).', '{"a": "This swaps every pairing; saprophytes are not root symbionts.", "b": "Parasites do not decompose dead matter, and lichens are not root associations.", "c": "Parasites are not root symbionts, and lichens do not live on living hosts."}'::jsonb, 'Lichens are pollution indicators and do not grow in polluted areas; the algal partner is the phycobiont and the fungal partner the mycobiont.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('74579a9d-569f-5768-849a-0548738b4e95', 'neet_ug', 'Zoology', 'Body Fluids and Circulation', 'Which would be the heart rate of a person if the cardiac output is 5L, blood volume in the ventricles at the end of diastole is 100 mL and at the end of ventricular systole is 50 mL?', '[{"id": "a", "text": "50 beats per minute"}, {"id": "b", "text": "75 beats per minute"}, {"id": "c", "text": "100 beats per minute"}, {"id": "d", "text": "125 beats per minute"}]'::jsonb, 'c', 'Stroke volume = 100 − 50 = 50 mL, so heart rate = 5000/50 = 100 per minute.', 'Stroke volume = end-diastolic volume − end-systolic volume = 100 − 50 = 50 mL. Cardiac output = stroke volume × heart rate, so heart rate = 5000 mL ÷ 50 mL = 100 beats per minute.', '{"a": "This would need a stroke volume of 100 mL.", "b": "This would need a stroke volume of about 67 mL.", "d": "This would need a stroke volume of 40 mL."}'::jsonb, 'Cardiac output in a healthy adult is about 70 mL × 72 beats ≈ 5 L per minute.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('1d7d6aa2-7ab1-5606-81aa-2ebf46b88d22', 'neet_ug', 'Zoology', 'Biotechnology and its Applications', 'What triggers activation of protoxin to active Bt toxin of Bacillus thuringiensis in boll worm?', '[{"id": "a", "text": "Body temperature"}, {"id": "b", "text": "Moist surface of midgut"}, {"id": "c", "text": "Alkaline pH of gut"}, {"id": "d", "text": "Acidic pH of stomach"}]'::jsonb, 'c', 'The alkaline pH of the insect gut dissolves the crystals and activates the Bt protoxin.', 'Bt toxin is stored as inactive protoxin crystals in the bacterium. When the insect eats them, the alkaline pH of its gut solubilises the crystals and converts the protoxin into active toxin. The active toxin binds midgut epithelial cells and creates pores, so the cells swell, lyse and the insect dies.', '{"a": "Temperature is not the activating factor.", "b": "Moisture alone does not activate the protoxin.", "d": "The insect gut is alkaline, not acidic; acidic conditions would not activate the toxin."}'::jsonb, 'cryIAc and cryIIAb genes target cotton bollworms, and cryIAb targets the corn borer.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('c709a405-8073-5026-8a10-cc6460f0e7c5', 'neet_ug', 'Zoology', 'Structural Organisation in Animals', 'The ciliated epithelial cells are required to move particles or mucus in a specific direction. In humans, these cells are mainly present in :', '[{"id": "a", "text": "Bile duct and Bronchioles"}, {"id": "b", "text": "Fallopian tubes and Pancreatic duct"}, {"id": "c", "text": "Eustachian tube and Salivary duct"}, {"id": "d", "text": "Bronchioles and Fallopian tubes"}]'::jsonb, 'd', 'Ciliated epithelium lines hollow organs like bronchioles and fallopian tubes.', 'Ciliated columnar or cuboidal epithelium moves mucus or particles in one direction. NCERT names the inner surface of hollow organs such as bronchioles and fallopian tubes as its main locations: in the bronchioles it moves mucus, and in the fallopian tubes it moves the ovum.', '{"a": "The bile duct is lined by non-ciliated epithelium.", "b": "The pancreatic duct is not lined by ciliated epithelium.", "c": "Salivary ducts are not ciliated."}'::jsonb, 'Compound epithelium lines the moist surfaces of the buccal cavity, pharynx and inner lining of the ducts of salivary glands and pancreatic ducts.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('35eed8d3-fddc-5b9a-85a3-832cdddb67fd', 'neet_ug', 'Botany', 'Anatomy of Flowering Plants', 'Which of the statements given below is not true about formation of Annual Rings in trees?', '[{"id": "a", "text": "Annual ring is a combination of spring wood and autumn wood produced in a year."}, {"id": "b", "text": "Differential activity of cambium causes light and dark bands of tissue - early and late wood respectively"}, {"id": "c", "text": "Activity of cambium depends upon variation in climate."}, {"id": "d", "text": "Annual rings are not prominent in trees of temperate region."}]'::jsonb, 'd', 'Annual rings are distinct in temperate trees because of marked seasonal changes.', 'In temperate regions, the cambium is very active in spring (light early wood with wide vessels) and less active in autumn (dark late wood with narrow vessels). Together these form one annual ring per year. Because the seasons are sharply marked there, rings are prominent in temperate trees; they are indistinct in tropical trees.', '{"a": "True: one spring wood band plus one autumn wood band make one annual ring.", "b": "True: early wood is light and late wood is dark.", "c": "True: cambial activity changes with climate."}'::jsonb, 'Counting annual rings gives a tree''s age (dendrochronology).', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('aeaaae71-0b5c-528a-92bd-3929f35823e7', 'neet_ug', 'Botany', 'Sexual Reproduction in Flowering Plants', 'What is the fate of the male gametes discharged in the synergid?', '[{"id": "a", "text": "One fuses with the egg, other(s) degenerate(s) in the synergid."}, {"id": "b", "text": "All fuse with the egg."}, {"id": "c", "text": "One fuses with the egg, other(s) fuse(s) with synergid nucleus."}, {"id": "d", "text": "One fuses with the egg and other fuses with central cell nuclei."}]'::jsonb, 'd', 'In double fertilisation one male gamete fuses with the egg (syngamy) and the other with the two polar nuclei (triple fusion).', 'The pollen tube releases two male gametes into a synergid. One fuses with the egg nucleus to form the diploid zygote. The other fuses with the two polar nuclei of the central cell to form the triploid primary endosperm nucleus.', '{"a": "The second male gamete does not degenerate; it takes part in triple fusion.", "b": "Only one male gamete fuses with the egg, which prevents polyspermy.", "c": "The synergid nucleus degenerates and does not fuse with a male gamete."}'::jsonb, 'Syngamy plus triple fusion together make up double fertilisation, which is unique to angiosperms.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('d34806a2-e938-5201-b393-f35cce0f87a6', 'neet_ug', 'Botany', 'Molecular Basis of Inheritance', 'Match the following genes of the Lac operon with their respective products.
(a) i gene | (i) β-galactosidase
(b) z gene | (ii) Permease
(c) a gene | (iii) Repressor
(d) y gene | (iv) Transacetylase
Select the correct option.', '[{"id": "a", "text": "(a)-(i), (b)-(iii), (c)-(ii), (d)-(iv)"}, {"id": "b", "text": "(a)-(iii), (b)-(i), (c)-(ii), (d)-(iv)"}, {"id": "c", "text": "(a)-(iii), (b)-(i), (c)-(iv), (d)-(ii)"}, {"id": "d", "text": "(a)-(iii), (b)-(iv), (c)-(i), (d)-(ii)"}]'::jsonb, 'c', 'i → repressor, z → β-galactosidase, a → transacetylase, y → permease.', 'The regulatory i gene codes for the repressor. The structural genes are z (β-galactosidase, which hydrolyses lactose into glucose and galactose), y (permease, which makes the cell permeable to β-galactosides) and a (transacetylase). That gives (a)-(iii), (b)-(i), (c)-(iv), (d)-(ii).', '{"a": "The i gene codes for the repressor, not β-galactosidase.", "b": "This swaps the a and y gene products.", "d": "The z gene codes for β-galactosidase, not transacetylase."}'::jsonb, 'Lactose (allolactose) acts as the inducer by inactivating the repressor; the lac operon is under negative regulation.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('1b19c3ea-b4c3-5406-a1ac-1b37ae02c395', 'neet_ug', 'Zoology', 'Structural Organisation in Animals', 'Select the correct sequence of organs in the alimentary canal of cockroach starting from mouth:', '[{"id": "a", "text": "Pharynx → Oesophagus → Crop → Gizzard → Ileum → Colon → Rectum"}, {"id": "b", "text": "Pharynx → Oesophagus → Gizzard → Crop → Ileum → Colon → Rectum"}, {"id": "c", "text": "Pharynx → Oesophagus → Gizzard → Ileum → Crop → Colon → Rectum"}, {"id": "d", "text": "Pharynx → Oesophagus → Ileum → Crop → Gizzard → Colon → Rectum"}]'::jsonb, 'a', 'In the cockroach, food passes from pharynx and oesophagus to the crop, then the gizzard, then the midgut and hindgut.', 'The foregut of the cockroach is pharynx → oesophagus → crop (food storage) → gizzard (proventriculus, for grinding). This is followed by the midgut and then the hindgut, made of ileum, colon and rectum, which opens out through the anus.', '{"b": "The crop comes before the gizzard, not after it.", "c": "The crop is part of the foregut and cannot come after the ileum.", "d": "The ileum is part of the hindgut and comes after the crop and gizzard."}'::jsonb, 'Malpighian tubules (excretory) open at the junction of the midgut and hindgut, and hepatic caecae at the junction of the foregut and midgut.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('0bc95e27-fd84-54d5-a998-9a1c655bcb95', 'neet_ug', 'Zoology', 'Human Health and Disease', 'Identify the correct pair representing the causative agent of typhoid fever and the confirmatory test for typhoid.', '[{"id": "a", "text": "Plasmodium vivax/UTI test."}, {"id": "b", "text": "Streptococcus pneumoniae/Widal test"}, {"id": "c", "text": "Salmonella typhi/Anthrone test"}, {"id": "d", "text": "Salmonella typhi/Widal test"}]'::jsonb, 'd', 'Typhoid is caused by Salmonella typhi and confirmed by the Widal test.', 'Salmonella typhi enters through contaminated food and water, infects the small intestine and spreads through the blood. The Widal test, which detects antibodies against Salmonella antigens, is used to confirm typhoid.', '{"a": "Plasmodium vivax causes malaria.", "b": "Streptococcus pneumoniae causes pneumonia.", "c": "The anthrone test detects carbohydrates, not typhoid."}'::jsonb, 'Mary Mallon (''Typhoid Mary'') was a carrier who spread typhoid through the food she cooked.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('f4067c4f-b17b-5a1e-ae89-b709536cd57f', 'neet_ug', 'Zoology', 'Chemical Coordination and Integration', 'How does steroid hormone influence the cellular activities?', '[{"id": "a", "text": "Changing the permeability of the cell membrane."}, {"id": "b", "text": "Binding to DNA and forming a gene-hormone complex."}, {"id": "c", "text": "Activating cyclic AMP located on the cell membrane."}, {"id": "d", "text": "Using aquaporin channels as second messenger."}]'::jsonb, 'b', 'Steroid hormones act inside the cell, where the hormone–receptor complex binds DNA and changes gene expression.', 'Steroid hormones are lipid soluble, so they cross the plasma membrane and bind intracellular (nuclear) receptors. The hormone–receptor complex binds the genome and regulates gene expression, which changes the cell''s physiology. Of the options, (2) describes this mechanism.', '{"a": "Steroids do not act mainly by changing membrane permeability.", "c": "The cAMP second-messenger route is used by protein/peptide hormones acting on membrane receptors.", "d": "Aquaporins are water channels, not second messengers."}'::jsonb, 'Steroid hormones (cortisol, testosterone, estradiol, progesterone) and iodothyronines act through intracellular receptors.', 'med', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('b36d3f8a-afa8-5934-bf04-69204cdde541', 'neet_ug', 'Zoology', 'Breathing and Exchange of Gases', 'Tidal Volume and Expiratory Reserve Volume of an athlete is 500 mL and 1000 mL respectively. What will be his Expiratory Capacity if the Residual Volume is 1200 mL?', '[{"id": "a", "text": "1500 mL"}, {"id": "b", "text": "1700 mL"}, {"id": "c", "text": "2200 mL"}, {"id": "d", "text": "2700 mL"}]'::jsonb, 'a', 'Expiratory capacity = TV + ERV = 500 + 1000 = 1500 mL.', 'Expiratory capacity is the total volume a person can expire after a normal inspiration, which is TV + ERV = 500 + 1000 = 1500 mL. Residual volume cannot be expired, so it is not included (it is a distractor here).', '{"b": "This adds RV to TV (500 + 1200), which is meaningless.", "c": "This is ERV + RV = functional residual capacity.", "d": "This adds TV + ERV + RV, wrongly including residual volume."}'::jsonb, 'Functional residual capacity = ERV + RV; vital capacity = ERV + TV + IRV.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('187e3db7-feb6-523c-a24e-71bd40f17c5a', 'neet_ug', 'Botany', 'Microbes in Human Welfare', 'Which of the following is a commercial blood cholesterol lowering agent?', '[{"id": "a", "text": "Cyclosporin A"}, {"id": "b", "text": "statin"}, {"id": "c", "text": "Streptokinase"}, {"id": "d", "text": "Lipases"}]'::jsonb, 'b', 'Statins from the yeast Monascus purpureus lower blood cholesterol.', 'Statins produced by Monascus purpureus competitively inhibit the enzyme responsible for cholesterol synthesis, so they are used commercially to lower blood cholesterol.', '{"a": "Cyclosporin A (from Trichoderma polysporum) is an immunosuppressant used in organ transplants.", "c": "Streptokinase is a clot buster used to dissolve blood clots.", "d": "Lipases are used in detergents to remove oily stains."}'::jsonb, 'Streptokinase is produced by Streptococcus and modified by genetic engineering for use as a clot buster.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('999407f1-0e94-58e4-a422-bfa22c24a539', 'neet_ug', 'Botany', 'Cell: The Unit of Life', 'Which of the following statements regarding mitochondria is incorrect?', '[{"id": "a", "text": "Outer membrane is permeable to monomers of carbohydrates fats and proteins."}, {"id": "b", "text": "Enzymes of electron transport are embedded in outer membrane."}, {"id": "c", "text": "Inner membrane is convoluted with infoldings."}, {"id": "d", "text": "Mitochondrial matrix contains single circular DNA molecule and ribosomes."}]'::jsonb, 'b', 'ETS enzymes are in the inner mitochondrial membrane, not the outer one.', 'The electron transport chain complexes and ATP synthase are located in the inner mitochondrial membrane, which is folded into cristae to increase surface area. The outer membrane is smooth and relatively permeable to small molecules, and the matrix holds circular DNA, 70S ribosomes and Krebs cycle enzymes.', '{"a": "Correct: the porin-rich outer membrane lets small monomers pass.", "c": "Correct: the infoldings of the inner membrane are called cristae.", "d": "Correct: the matrix has a single circular DNA, a few RNA molecules and 70S ribosomes."}'::jsonb, 'Mitochondria are semi-autonomous organelles and divide by fission.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('de58df17-e2b9-5a6e-a39e-4558e57cc01a', 'neet_ug', 'Zoology', 'Body Fluids and Circulation', 'Match the Column - I with Column -II
Column - I | Column - II
(a) P-wave | (i) Depolarisation of ventricles
(b) QRS complex | (ii) Repolarisation of ventricles
(c) T-wave | (iii) Coronary ischemia
(d) Reduction in the size of T-wave | (iv) Depolarisation of atria
 | (v) Repolarisation of atria
Select the correct option-', '[{"id": "a", "text": "(a)-(iv), (b)-(i), (c)-(ii), (d)-(iii)"}, {"id": "b", "text": "(a)-(iv), (b)-(i), (c)-(ii), (d)-(v)"}, {"id": "c", "text": "(a)-(ii), (b)-(i), (c)-(v), (d)-(iii)"}, {"id": "d", "text": "(a)-(ii), (b)-(iii), (c)-(v), (d)-(iv)"}]'::jsonb, 'a', 'P = atrial depolarisation, QRS = ventricular depolarisation, T = ventricular repolarisation; a small T-wave suggests coronary ischemia.', 'The P-wave reflects excitation (depolarisation) of the atria. The QRS complex marks ventricular depolarisation, and the T-wave marks ventricular repolarisation. A reduced T-wave points to insufficient oxygen supply to heart muscle, i.e. coronary ischemia. That gives (a)-(iv), (b)-(i), (c)-(ii), (d)-(iii).', '{"b": "A reduced T-wave is not atrial repolarisation, which is hidden in the QRS complex.", "c": "The P-wave is atrial depolarisation, not ventricular repolarisation.", "d": "QRS is ventricular depolarisation, not ischemia."}'::jsonb, 'Counting QRS complexes per minute gives the heart rate; the end of the T-wave marks the end of systole.', 'med', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('6185eb76-4158-56eb-a5f7-c37b3c069efa', 'neet_ug', 'Botany', 'Microbes in Human Welfare', 'Select the correct group of biocontrol agents.', '[{"id": "a", "text": "Bacillus thuringiensis, Tobacco mosaic virus, Aphids"}, {"id": "b", "text": "Trichoderma, Baculovirus, Bacillus thuringiensis"}, {"id": "c", "text": "Oscillatoria, Rhizobium, Trichoderma"}, {"id": "d", "text": "Nostoc, Azospirillium, Nucleopolyhedrovirus"}]'::jsonb, 'b', 'Trichoderma, baculoviruses and Bt are all biocontrol agents.', 'Bacillus thuringiensis kills insect larvae such as butterfly caterpillars. Trichoderma species control many plant fungal pathogens, and baculoviruses (genus Nucleopolyhedrovirus) are species-specific insecticides. All three in option (2) are used in biological control.', '{"a": "TMV is a plant pathogen and aphids are pests, not biocontrol agents.", "c": "Oscillatoria and Rhizobium are used as biofertilisers, not biocontrol agents.", "d": "Nostoc and Azospirillum are biofertilisers."}'::jsonb, 'Ladybird beetles control aphids and dragonflies control mosquitoes, which are classic biocontrol examples.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL),
('9a53400c-13d3-50dc-8144-2382ba29fcab', 'neet_ug', 'Botany', 'The Living World', 'Select correctly written scientific name of Mango which was first described by Carolus Linnaeus:', '[{"id": "a", "text": "Mangifera indica Car. Linn."}, {"id": "b", "text": "Mangifera indica Linn."}, {"id": "c", "text": "Mangifera indica"}, {"id": "d", "text": "Mangifera Indica"}]'::jsonb, 'b', 'The author citation goes after the specific epithet in abbreviated form: Mangifera indica Linn.', 'In binomial nomenclature the genus name starts with a capital letter and the specific epithet with a small letter, and the name of the author who first described the species is written in abbreviated form after it. So the mango is written Mangifera indica Linn.', '{"a": "''Car. Linn.'' is not the standard abbreviation of Linnaeus.", "c": "This is a valid binomial but leaves out the author citation the question asks for.", "d": "The specific epithet must begin with a small letter."}'::jsonb, 'Binomial names are written in italics when printed and underlined separately when handwritten.', 'easy', true, 2019, NULL, 'NEET UG 2019 (NTA) · answer verified by UG Prep', NULL)
ON CONFLICT (id) DO NOTHING;
